INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f733bde5-9177-4c6f-8795-f196ae4a4206', '詠懷', '詠懷', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["桑榆汾水北，煙火濁河東。","未必尋歸路，居然息轉蓬。","故鄉行處（《全唐詩》作「雲」）是，虛室坐間同。","日落西山暮，方知天下空。","（按：《韻詩陽秋》卷十一、《全唐詩》卷三七收後四句。","）。"]', '["桑榆汾水北，煙火濁河东。","未必尋归路，居然息轉蓬。","故乡行处（《全唐诗》作「云」）是，虛室坐间同。","日落西山暮，方知天下空。","（按：《韻诗陽秋》卷十一、《全唐诗》卷三七收後四句。","）。"]', '诗', 'shi', '', NULL, '詠懷 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea804dba-2478-4a46-8180-f796017a0c40', '山夜', '山夜', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["仲尼初返魯，藏史欲辭周。","脫落四方事，棲遑萬里遊。","影來徒自責，心盡更何求？","禮樂存三代，煙霞主一丘。","長歌明月在，獨坐白雲浮。","物情勞倚伏，生涯任去留。","百年一如此，世事方悠悠。"]', '["仲尼初返魯，藏史欲辞周。","脫落四方事，棲遑万里游。","影来徒自責，心尽更何求？","禮乐存三代，煙霞主一丘。","长歌明月在，独坐白云浮。","物情勞倚伏，生涯任去留。","百年一如此，世事方悠悠。"]', '诗', 'shi', '', NULL, '山夜 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc53aac-76f2-497a-a5da-affdf0db499d', '遊山贈仲長先生子光', '游山贈仲长先生子光', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["試出南河曲，還起北山期。","連峰無蹔斷，絕嶺互相疑。","結[藤]（滕）標往路，刻樹記來時。","沙場聊憩路，石壁旋題詩。","葉秋紅稍下，苔寒綠更滋。","幽尋多樂處，勿怪往還遲。"]', '["試出南河曲，還起北山期。","連峰無蹔斷，絕嶺互相疑。","結[藤]（滕）標往路，刻樹記来时。","沙場聊憩路，石壁旋題诗。","葉秋紅稍下，苔寒綠更滋。","幽尋多乐处，勿怪往還遲。"]', '诗', 'shi', '', NULL, '遊山贈仲長先生子光 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12594f4b-875d-47bf-9af0-f73ca2ab0b99', '春晚園林', '春晚园林', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["不道嫌朝隱，無情受陸沉。","忽逢今旦樂，還遂少時心。","捲書藏篋笥，移榻就園林。","老妻能勸酒，少子解彈琴。","落花隨處下，春鳥自須吟。","兀然成一醉，誰知懷抱深？","（按：《客野叢書》卷十九錄「老妻能勸酒，少子解彈琴」二句。","）。"]', '["不道嫌朝隐，無情受陸沉。","忽逢今旦乐，還遂少时心。","捲书藏篋笥，移榻就园林。","老妻能勸酒，少子解彈琴。","落花隨处下，春鸟自須吟。","兀然成一醉，誰知懷抱深？","（按：《客野叢书》卷十九錄「老妻能勸酒，少子解彈琴」二句。","）。"]', '诗', 'shi', '', NULL, '春晚園林 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a572e50f-8787-40f2-81f1-66b3e66f4038', '贈薛學士方士', '贈薛学士方士', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["昔歲尋周孔，今春訪老莊。","途經丹水岸，路出白雲鄉。","窈窕開皇道，深沉指太方。","物情爭逐鹿，人事各亡羊。","月明看桂樹，日下覓扶桑。","寄語悠悠者，誰知此路長。","。"]', '["昔歲尋周孔，今春訪老莊。","途經丹水岸，路出白云乡。","窈窕开皇道，深沉指太方。","物情爭逐鹿，人事各亡羊。","月明看桂樹，日下覓扶桑。","寄語悠悠者，誰知此路长。","。"]', '诗', 'shi', '', NULL, '贈薛學士方士 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('067009c1-ca78-4816-9f35-0b8e6b12a60b', '春莊走筆', '春莊走笔', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["野客元圖靜，田家本惡諠。","枕山通箘閣，臨磵創茅軒。","約略栽新柳，隨宜作小園。","草依三徑合，花接四隣繁。","野婦調中饋，山朋促上樽。","曉羹猶未糝，春酒不須溫。","賣藥開東鋪，租田向北村。","夢中逢櫟社，醉裏覓桃源。","猪肝時入饌，犢鼻即裁褌。","自覺勳名薄，方知道義尊。","所嗟同志少，無處可忘言。"]', '["野客元圖静，田家本惡諠。","枕山通箘閣，臨磵創茅軒。","約略栽新柳，隨宜作小园。","草依三徑合，花接四隣繁。","野婦調中饋，山朋促上樽。","晓羹猶未糝，春酒不須溫。","賣藥开东鋪，租田向北村。","梦中逢櫟社，醉裏覓桃源。","猪肝时入饌，犢鼻即裁褌。","自覺勳名薄，方知道義尊。","所嗟同志少，無处可忘言。"]', '诗', 'shi', '', NULL, '春莊走筆 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('975399c8-5411-43d7-a187-46a25b4cb3e0', '泛船河上', '泛船河上', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["初晴何以慰？薄暮理輕舟。","白雲銷向盡，黃河曲復流。","隨風依北岸，逐浪向南洲。","波瀾浩淼淼，懷抱直悠悠。","自覺生如寄，方知世若浮。","蓬萊何處在？坐使百年秋。"]', '["初晴何以慰？薄暮理轻舟。","白云銷向尽，黄河曲复流。","隨风依北岸，逐浪向南洲。","波瀾浩淼淼，懷抱直悠悠。","自覺生如寄，方知世若浮。","蓬萊何处在？坐使百年秋。"]', '诗', 'shi', '', NULL, '泛船河上 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc019d6-6b8a-414a-bf23-645e7aa83936', '過程處士飲率爾成詠', '過程处士饮率爾成詠', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["莫道山中泉石好，莫畏人間行路難。","蜀郡鑪家何必鬧，宜城酒店舊來寬。","盃至定知懸怪晚，飲盡祇應速唱看。","但使百年相續醉，何愁萬里客衣單。"]', '["莫道山中泉石好，莫畏人间行路难。","蜀郡鑪家何必鬧，宜城酒店旧来寬。","盃至定知懸怪晚，饮尽祇應速唱看。","但使百年相續醉，何愁万里客衣單。"]', '诗', 'shi', '', NULL, '過程處士飲率爾成詠 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c909f0f0-d8e7-43d3-ba2e-bd3ed274a670', '解六合丞還', '解六合丞還', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["我家滄海白雲邊，還將別業對林泉，不同功名喧一世，直取煙霞送百年。","彭澤有田唯種黍，步兵從宦豈論錢？","但願朝朝長得醉（李抄本此句作「但使百年相續醉」），何辭夜夜甕間眠。"]', '["我家滄海白云邊，還將別業对林泉，不同功名喧一世，直取煙霞送百年。","彭澤有田唯種黍，步兵從宦豈論錢？","但願朝朝长得醉（李抄本此句作「但使百年相續醉」），何辞夜夜甕间眠。"]', '诗', 'shi', '', NULL, '解六合丞還 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb5282f1-54fd-4068-b346-7203357734fb', '山中獨坐', '山中独坐', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["試逐遊山去，聊觀避俗情。","引流還當井，憑樹即爲楹。","酒中添藥氣，琴裏作松聲。","石鑪煎玉髓，土釜出金精。","水碧連年服，雲丹計日成。","還看市朝路，無處不營營。","。"]', '["試逐游山去，聊观避俗情。","引流還當井，憑樹即爲楹。","酒中添藥氣，琴裏作松声。","石鑪煎玉髓，土釜出金精。","水碧連年服，云丹計日成。","還看市朝路，無处不營營。","。"]', '诗', 'shi', '', NULL, '山中獨坐 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa900f60-2950-4fe3-9d69-e4a225948745', '題畫幛背', '題畫幛背', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["雲霞圖幛子，山水畫屏風。","不應須對許，坐慣青溪中。"]', '["云霞圖幛子，山水畫屏风。","不應須对許，坐慣青溪中。"]', '诗', 'shi', '', NULL, '題畫幛背 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('431636a0-a7f5-4331-9ada-f6d573e90b62', '春園興後', '春园兴後', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["比日尋常醉，經年獨未醒。","迴瞻後園柳，忽值數行青。","定是春來意，低頭更好聽。","歌鶯遼亂動，蓮葉繞池生。","散腰追阮籍，招手喚劉伶。","隔架窺前[空，未餘几]（據李抄本補）小瓶。","風光須用卻，留此待誰傾。"]', '["比日尋常醉，經年独未醒。","迴瞻後园柳，忽值數行青。","定是春来意，低头更好听。","歌鶯遼亂动，蓮葉繞池生。","散腰追阮籍，招手喚劉伶。","隔架窺前[空，未餘几]（據李抄本補）小瓶。","风光須用卻，留此待誰傾。"]', '诗', 'shi', '', NULL, '春園興後 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1261cef-d262-42fc-aec5-80bf049172da', '山園', '山园', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["幽人養性靈，長嘯坐山扃。","二月蘭心紫，三春柳色青。","捲簾看水石，開牖望園亭。","琴曲唯留古，書名半是經。","風煙長入詠，几杖悉爲銘。","切直平生盡，何爲勞是形？","（按：《文獻通考·經籍考》引《周氏涉筆》錄「琴曲唯留古，書多半是經」二句，《全唐詩》卷三七收入。","）。"]', '["幽人養性靈，长嘯坐山扃。","二月蘭心紫，三春柳色青。","捲簾看水石，开牖望园亭。","琴曲唯留古，书名半是經。","风煙长入詠，几杖悉爲銘。","切直平生尽，何爲勞是形？","（按：《文獻通考·經籍考》引《周氏涉笔》錄「琴曲唯留古，书多半是經」二句，《全唐诗》卷三七收入。","）。"]', '诗', 'shi', '', NULL, '山園 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2366dde3-9231-4edf-9a62-e5ac1749e720', '春日還莊', '春日還莊', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["居人姓仲長，端坐悅年光。","地形疑谷口，川勢似河陽。","傍山移草石，橫渠種稻粱。","滋蘭依舊畹，接菓著新行。","自持茅作屋，無用杏爲梁。","蓬埋張仲徑，藜破管寧牀。","浴蠶溫織室，分蜂煖蜜房。","竹密連堦暗，花飛滿宅香。","坐棠思邵伯，看柳憶嵇康。","自得終焉趣，無論懷故鄉。"]', '["居人姓仲长，端坐悅年光。","地形疑谷口，川勢似河陽。","傍山移草石，橫渠種稻粱。","滋蘭依旧畹，接菓著新行。","自持茅作屋，無用杏爲梁。","蓬埋張仲徑，藜破管寧牀。","浴蠶溫织室，分蜂煖蜜房。","竹密連堦暗，花飞满宅香。","坐棠思邵伯，看柳憶嵇康。","自得終焉趣，無論懷故乡。"]', '诗', 'shi', '', NULL, '春日還莊 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090cadfc-c071-4d0f-b620-ba2dcc96819e', '尋苗道士山居', '尋苗道士山居', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["抱琴欲隱去，杖策訪幽潛。","青溪無限曲，丹障幾重簾。","水聲全繞砌，樹影半橫檐。","甑塵炊暫拂，鑪香盡更添。","短茅新縛薦，細藋始編簷。","寫咒桃爲板，題經竹作籤。","紫文千歲蝠，丹書五月蟾。","三山今近遠，飛路幸相兼。"]', '["抱琴欲隐去，杖策訪幽潛。","青溪無限曲，丹障幾重簾。","水声全繞砌，樹影半橫檐。","甑塵炊暫拂，鑪香尽更添。","短茅新縛薦，細藋始編簷。","寫咒桃爲板，題經竹作籤。","紫文千歲蝠，丹书五月蟾。","三山今近远，飞路幸相兼。"]', '诗', 'shi', '', NULL, '尋苗道士山居 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86ca6185-0476-4400-8221-876c886a9c39', '端坐詠思', '端坐詠思', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["張衡賦《四愁》，梁鴻歌《五噫》。","慷慨□□□，憔悴將焉如？","紛吾獨無悶，高臥喜閒居。","世途何足數，人事本來虛。","三王無定策，五帝有殘書。","咄嗟建城市，倏忽觀丘墟。","明治若不足，昏暴常有餘。","寄言忘懷者，歸來任卷舒。","（按：《野客叢書》卷二十錄「咄嗟建城市」一句。","）。"]', '["張衡賦《四愁》，梁鴻歌《五噫》。","慷慨□□□，憔悴將焉如？","紛吾独無悶，高臥喜閒居。","世途何足數，人事本来虛。","三王無定策，五帝有殘书。","咄嗟建城市，倏忽观丘墟。","明治若不足，昏暴常有餘。","寄言忘懷者，归来任卷舒。","（按：《野客叢书》卷二十錄「咄嗟建城市」一句。","）。"]', '诗', 'shi', '', NULL, '端坐詠思 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6520119f-f5f5-4bbf-966a-d20dc91e8253', '山中採藥', '山中採藥', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["採藥北巖陰，乘興獨幽尋。","澗尾泉恆細，山腰溪轉深。","石橫疑路斷，雲暗覺峰沉。","薄暮歸來去，松丘橫夜琴。"]', '["採藥北巖陰，乘兴独幽尋。","澗尾泉恆細，山腰溪轉深。","石橫疑路斷，云暗覺峰沉。","薄暮归来去，松丘橫夜琴。"]', '诗', 'shi', '', NULL, '山中採藥 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e07ac4a-911d-4f94-abd0-27c815135e48', '晚秋夜坐', '晚秋夜坐', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["園亭物候奇，舒嘯樂無爲。","芰荷高出岸，楊柳下敧池。","蟬噪黏遠舉，魚驚鉤暫移。"]', '["园亭物候奇，舒嘯乐無爲。","芰荷高出岸，楊柳下敧池。","蟬噪黏远舉，鱼驚鉤暫移。"]', '诗', 'shi', '', NULL, '晚秋夜坐 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c27b8b5b-75a3-4835-81d0-5aa61d22d2ae', '在邊三首 一', '在邊三首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["客行秋未歸，蕭索意多違。","雁門霜雪苦，龍城冠蓋稀。","穹廬還作室，短褐更爲衣。","自憐書信斷，空瞻鴻雁飛。"]', '["客行秋未归，蕭索意多違。","雁门霜雪苦，龙城冠蓋稀。","穹廬還作室，短褐更爲衣。","自怜书信斷，空瞻鴻雁飞。"]', '诗', 'shi', '', NULL, '在邊三首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ceecff2-7122-4344-9ae7-5cd4581c7686', '在邊三首 二', '在邊三首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["羈旅滯胡中，思歸道路窮。","猶擎蘇武節，尚抱李陵弓。","漠北平無樹，關南迥有風。","長安知遠近，徒想灞池東。","。"]', '["羈旅滯胡中，思归道路窮。","猶擎蘇武節，尚抱李陵弓。","漠北平無樹，关南迥有风。","长安知远近，徒想灞池东。","。"]', '诗', 'shi', '', NULL, '在邊三首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bbe6bbd-97f8-4b09-afc6-b9fd872471a4', '在邊三首 三', '在邊三首 三', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["昔歲銜王命，今秋獨未旋。","節毛風落盡，衣袖雪霑鮮。","瀚海平連地，狼山峻入天。","何當携侍子，相逐拜甘泉。"]', '["昔歲銜王命，今秋独未旋。","節毛风落尽，衣袖雪霑鲜。","瀚海平連地，狼山峻入天。","何當携侍子，相逐拜甘泉。"]', '诗', 'shi', '', NULL, '在邊三首 三 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a4369a-0e4b-437a-b22a-94cd5b27e2d9', '冬夜載酒於鄉館尋崔使君善爲', '冬夜載酒於乡館尋崔使君善爲', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["思君夜漸闌，載酒一相看。","野館含煙冷，山衣犯雪寒。","停車聊捧袂，倒屣共臨盤。","今夕山陰賞，誰知逢道安。"]', '["思君夜漸闌，載酒一相看。","野館含煙冷，山衣犯雪寒。","停车聊捧袂，倒屣共臨盤。","今夕山陰賞，誰知逢道安。"]', '诗', 'shi', '', NULL, '冬夜載酒於鄉館尋崔使君善爲 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a988814-d7e0-4d65-b68f-a0e85ce28479', '讀《真隱傳》見披裘公及漢濱老父因題四韻', '读《真隐傳》见披裘公及漢濱老父因題四韻', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["被褐延陵逕，耕田漢水陰。","由來驩擊壤，何處視遺金？","季子停驂謝，張溫下道尋。"]', '["被褐延陵逕，耕田漢水陰。","由来驩擊壤，何处視遺金？","季子停驂謝，張溫下道尋。"]', '诗', 'shi', '', NULL, '讀《真隱傳》見披裘公及漢濱老父因題四韻 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a22ec2e9-4fde-4850-989f-1bfe7be84852', '性不好治產興後言懷', '性不好治產兴後言懷', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["自有人間分，何須郭外田？","和光遊聚落，獨興入山泉。","河曲編蕭坐，靈臺結絮眠。","還應多藏客，辛苦沒殘年。"]', '["自有人间分，何須郭外田？","和光游聚落，独兴入山泉。","河曲編蕭坐，靈台結絮眠。","還應多藏客，辛苦沒殘年。"]', '诗', 'shi', '', NULL, '性不好治產興後言懷 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('217d13dd-a945-45c2-b615-60b04374816b', '山家夏日九首 一', '山家夏日九首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["寂寞坐山家，蕭條翫物華。","樹奇（李抄本作「倚」）全擁石，蒲長半侵砂。","池光連壁動，日影對窗斜。","石榴兼布葉，金䔲唯作花。","落藤斜引蔓，伏筍暗抽芽。","高臥長無客，方知人事賒。"]', '["寂寞坐山家，蕭條翫物华。","樹奇（李抄本作「倚」）全擁石，蒲长半侵砂。","池光連壁动，日影对窗斜。","石榴兼布葉，金䔲唯作花。","落藤斜引蔓，伏筍暗抽芽。","高臥长無客，方知人事賒。"]', '诗', 'shi', '', NULL, '山家夏日九首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb786fc-b917-4f77-b9aa-9355aac26ac5', '山家夏日九首 二', '山家夏日九首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["隱士長松壑，先生孤竹丘。","溪深常抱凍，磵冷鎮含秋。","九春寧解褐，五月自披裘。","誰信湯年旱，山燋金石流？。"]', '["隐士长松壑，先生孤竹丘。","溪深常抱凍，磵冷鎮含秋。","九春寧解褐，五月自披裘。","誰信湯年旱，山燋金石流？。"]', '诗', 'shi', '', NULL, '山家夏日九首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9969dbc8-9495-4ecc-a76f-0cd2f4072f1f', '山家夏日九首 三', '山家夏日九首 三', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["山中舊可安，無處不盤桓。","嶺澁攀藤易，巖崎策杖難。","藥供無限食，石起自然壇。","樹密簷偏冷，泉深階鎮寒。","松根聊入釀，竹實試調丹。","孔淳書數帙，朝朝還自看。"]', '["山中旧可安，無处不盤桓。","嶺澁攀藤易，巖崎策杖难。","藥供無限食，石起自然壇。","樹密簷偏冷，泉深階鎮寒。","松根聊入釀，竹實試調丹。","孔淳书數帙，朝朝還自看。"]', '诗', 'shi', '', NULL, '山家夏日九首 三 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c20b2037-b52d-4c01-b45f-6f9b7092802f', '山家夏日九首 四', '山家夏日九首 四', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["巖居何啻好，野性本規閒。","青松生戶側，奔泉湧砌間。","老父循渾沌，稚子服斒斕。","自得爲巢許，無勞買却山。"]', '["巖居何啻好，野性本規閒。","青松生戶側，奔泉湧砌间。","老父循渾沌，稚子服斒斕。","自得爲巢許，無勞買却山。"]', '诗', 'shi', '', NULL, '山家夏日九首 四 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0656ca-be0a-4a6a-bb84-a0656a2a3f63', '山家夏日九首 五', '山家夏日九首 五', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["追涼剩不歸，高臥隱松闈。","野竹欄堦種，巖花入戶飛。","磵幽人路斷，山曠鳥啼稀。","不特嫌周粟，時時須采薇。"]', '["追涼剩不归，高臥隐松闈。","野竹欄堦種，巖花入戶飞。","磵幽人路斷，山曠鸟啼稀。","不特嫌周粟，时时須采薇。"]', '诗', 'shi', '', NULL, '山家夏日九首 五 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d74ab22-8a87-46f9-bd2c-aca42b9f9337', '山家夏日九首 六', '山家夏日九首 六', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["山人（李抄本作「中」）有敝廬，竹樹近扶疎。","傍巖開竈井，橫磵引庭除。","障子遊仙畫，屏風章草書。","誰言非面俗，更欲賦《閒居》。"]', '["山人（李抄本作「中」）有敝廬，竹樹近扶疎。","傍巖开竈井，橫磵引庭除。","障子游仙畫，屏风章草书。","誰言非面俗，更欲賦《閒居》。"]', '诗', 'shi', '', NULL, '山家夏日九首 六 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff04f7d-d34c-4569-86fa-47bb210a88ea', '山家夏日九首 七', '山家夏日九首 七', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["幽居枕廣川，長望鬱芊芊。","北巖採樵路，東坡種藥田。","磵泉通院井，山氣雜廚煙。","向夕林庭曠，蕭條鳴一弦。"]', '["幽居枕廣川，长望鬱芊芊。","北巖採樵路，东坡種藥田。","磵泉通院井，山氣杂廚煙。","向夕林庭曠，蕭條鳴一弦。"]', '诗', 'shi', '', NULL, '山家夏日九首 七 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('539fe12c-e30b-48db-8062-9ef52076c078', '山家夏日九首 八', '山家夏日九首 八', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["山居自可安，樂道不爲難。","甲乙題書卷，梧桐數藥丸。","樹陰連戶靜，泉影度窗寒。","抱琴聊倚石，高眠風自彈。"]', '["山居自可安，乐道不爲难。","甲乙題书卷，梧桐數藥丸。","樹陰連戶静，泉影度窗寒。","抱琴聊倚石，高眠风自彈。"]', '诗', 'shi', '', NULL, '山家夏日九首 八 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d4516dd-8657-45f2-ba03-9a3419871ed4', '山家夏日九首 九', '山家夏日九首 九', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["避暑長巖東，蕭條趣不窮。","密藤成斗帳，疎樹即簷櫳。","槿花礙前浦，荷香欄上風。","寄言覆苔客，無事菓園中。","。"]', '["避暑长巖东，蕭條趣不窮。","密藤成斗帳，疎樹即簷櫳。","槿花礙前浦，荷香欄上风。","寄言覆苔客，無事菓园中。","。"]', '诗', 'shi', '', NULL, '山家夏日九首 九 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15b88447-1bf8-4c70-a926-dac7f546a1d4', '洛水南看漢王馬射', '洛水南看漢王马射', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["君王馬態驕。","蹀躞過河橋。","雨息銅街靜，塵飛金埒遙。","鐵絲纏箭脚，玉片抱弓腰。","日□矜百中，唯看楊柳條。","（以上三十九首均見北京圖書館藏清陳氏晚晴軒抄本五卷本《王無功文集》卷二。","）。"]', '["君王马態驕。","蹀躞過河橋。","雨息銅街静，塵飞金埒遙。","鐵絲纏箭脚，玉片抱弓腰。","日□矜百中，唯看楊柳條。","（以上三十九首均见北京圖书館藏清陳氏晚晴軒抄本五卷本《王無功文集》卷二。","）。"]', '诗', 'shi', '', NULL, '洛水南看漢王馬射 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e8540e-8939-4b08-ac4e-e625a7aa37c5', '駕過觀獵', '駕過观獵', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["天廵總禁營，詰旦擁戈城。","旗常紛出沒，彀騎鬱縱橫。","圍塵千里暗，獵火四山明。","獸竭郊原迥，禽殫灌莽平。","割鮮同飲至，振旅以休兵。","動作威容備，周旋軍令成。","金鐃清御道，玉鼓節神行。","別有磻溪叟，無日戰逢迎。"]', '["天廵總禁營，詰旦擁戈城。","旗常紛出沒，彀騎鬱縱橫。","圍塵千里暗，獵火四山明。","獸竭郊原迥，禽殫灌莽平。","割鲜同饮至，振旅以休兵。","动作威容備，周旋軍令成。","金鐃清御道，玉鼓節神行。","別有磻溪叟，無日戰逢迎。"]', '诗', 'shi', '', NULL, '駕過觀獵 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b438b7e6-f599-477e-8d36-6bd0c602ace0', '山中獨坐自贈', '山中独坐自贈', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["幽人似不平，獨坐北山楹。","攜妻梁處士，別婦許先生。","擯俗勞長歎，尋山倦遠行。","空山斜照落，古樹寒煙生。","解組陶元亮，辭家向子平。","是非何處在？潭泊苦縱橫。"]', '["幽人似不平，独坐北山楹。","携妻梁处士，別婦許先生。","擯俗勞长歎，尋山倦远行。","空山斜照落，古樹寒煙生。","解組陶元亮，辞家向子平。","是非何处在？潭泊苦縱橫。"]', '诗', 'shi', '', NULL, '山中獨坐自贈 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc3d4669-6f2b-430e-b066-ce84669b111c', '自答', '自答', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["公子澹無爲，非關懷□移。","老萊猶[有]（據李抄本補）婦，王霸豈無兒。","人世何勞隔，生涯故可知。","溪流無限水，樹長自然枝。","竹林橫□□，梧桐倚惠施。","楊朱那早計，煩此泣途歧。"]', '["公子澹無爲，非关懷□移。","老萊猶[有]（據李抄本補）婦，王霸豈無兒。","人世何勞隔，生涯故可知。","溪流無限水，樹长自然枝。","竹林橫□□，梧桐倚惠施。","楊朱那早計，煩此泣途歧。"]', '诗', 'shi', '', NULL, '自答 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b564b04d-9ad5-4758-80a5-2f4eeb66e511', '過鄭處士山莊二首 一', '過鄭处士山莊二首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["鑿溪南浦曲，栽援北巖阿。","野膳調藜荏，山依緝薜蘿。","釣潭因舊迹，樵路起新歌。","欲知幽賞處，青青松桂多。","。"]', '["鑿溪南浦曲，栽援北巖阿。","野膳調藜荏，山依緝薜蘿。","釣潭因旧迹，樵路起新歌。","欲知幽賞处，青青松桂多。","。"]', '诗', 'shi', '', NULL, '過鄭處士山莊二首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bbaa537-9981-4460-ad43-45da7f21b321', '過鄭處士山莊二首 二', '過鄭处士山莊二首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["僻處開三徑，幽居無四隣。","橫文彪子褥，碎點鹿胎巾。","斷籬栖夜雉，荒砌起朝麕。","薄暮東溪上，猶言在渭濱。"]', '["僻处开三徑，幽居無四隣。","橫文彪子褥，碎点鹿胎巾。","斷籬栖夜雉，荒砌起朝麕。","薄暮东溪上，猶言在渭濱。"]', '诗', 'shi', '', NULL, '過鄭處士山莊二首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c221462-d331-4858-a718-072dffdd6694', '病後醮宅', '病後醮宅', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["公幹苦沉綿，居山畏不延。","白驢迎蒯子，青牛下葛仙。","度符南竈曲，寫咒北階前。","龍行初禁火，鳥步即凌煙。","淨席三天坐，香鑪五帝筵。","埋沙禳疫氣，鎮石禦兇年。","鬼用泥爲壁，神將紙作錢。","山精愁鏡厭，野魅怯燈然。","今日揚雄宅，應堪草《太玄》。"]', '["公幹苦沉綿，居山畏不延。","白驢迎蒯子，青牛下葛仙。","度符南竈曲，寫咒北階前。","龙行初禁火，鸟步即凌煙。","淨席三天坐，香鑪五帝筵。","埋沙禳疫氣，鎮石禦兇年。","鬼用泥爲壁，神將紙作錢。","山精愁镜厭，野魅怯灯然。","今日揚雄宅，應堪草《太玄》。"]', '诗', 'shi', '', NULL, '病後醮宅 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6996de02-de51-4677-a0d1-173d009343e0', '過鄉學', '過乡学', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["杖蔾尋學舍，摳衣向講堂。","杏壇花正落，槐市葉新長。","聚徒疑魯國，遊人即鄭鄉。","先生坐不議，弟子入成行。","邴元（韓理洲云應作「邴原」）供灑埽，劉俊脫衣裳。","組帶填中塾，青衿溢下庠。","佩猳情已變，術蟻藝應光。","寄語安眠者，無爲糞二墻。"]', '["杖蔾尋学舍，摳衣向講堂。","杏壇花正落，槐市葉新长。","聚徒疑魯国，游人即鄭乡。","先生坐不議，弟子入成行。","邴元（韓理洲云應作「邴原」）供灑埽，劉俊脫衣裳。","組带填中塾，青衿溢下庠。","佩猳情已变，術蟻藝應光。","寄語安眠者，無爲糞二墻。"]', '诗', 'shi', '', NULL, '過鄉學 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ad5ad7-5d01-43be-a3c1-32029d250779', '春莊酒後', '春莊酒後', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["郊扉乘曉闢，山醖及年開。","柏葉投新釀，松花潑舊醅。","野妻臨甕倚，村竪捧瓶來。","竹瘤還作杓，樹癭即成盃。","北潭因醉往，南畝帶星迴。"]', '["郊扉乘晓闢，山醖及年开。","柏葉投新釀，松花潑旧醅。","野妻臨甕倚，村竪捧瓶来。","竹瘤還作杓，樹癭即成盃。","北潭因醉往，南畝带星迴。"]', '诗', 'shi', '', NULL, '春莊酒後 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b6568f-a792-4362-8ad2-85015eba2a32', '題酒店樓壁絕句八首 一', '題酒店楼壁絕句八首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["欲識幽人伴，非是俗情量。","有業開屠肆，無名坐餅行。","。"]', '["欲識幽人伴，非是俗情量。","有業开屠肆，無名坐餅行。","。"]', '诗', 'shi', '', NULL, '題酒店樓壁絕句八首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6cae40c-68d9-4e9b-93bc-98de8d098615', '題酒店樓壁絕句八首 二', '題酒店楼壁絕句八首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["或問遊人道，那能獨步憂？飲時含救藥，醉罷不能愁。"]', '["或问游人道，那能独步憂？饮时含救藥，醉罷不能愁。"]', '诗', 'shi', '', NULL, '題酒店樓壁絕句八首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bafb49aa-1ab3-4c19-853b-2c50da6b35fb', '題酒店樓壁絕句八首 三', '題酒店楼壁絕句八首 三', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["仲任書卷盡，平君（韓理洲疑爲「君平」之倒文，即嚴君平）不（韓校改爲「卜」）數充。","相逢何以慰？","細酌對春風。","（按：《全唐詩》卷三七收入其一、其二、其三、其六、其七等五首，題作《過酒家五首》。","）。"]', '["仲任书卷尽，平君（韓理洲疑爲「君平」之倒文，即嚴君平）不（韓校改爲「卜」）數充。","相逢何以慰？","細酌对春风。","（按：《全唐诗》卷三七收入其一、其二、其三、其六、其七等五首，題作《過酒家五首》。","）。"]', '诗', 'shi', '', NULL, '題酒店樓壁絕句八首 三 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7547599d-5873-4836-9a2c-02db7e6e1872', '山中避暑', '山中避暑', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["幽人自可憐，避暑更蕭然。","片雲堪度雨，小樹即生煙。","巖雪頻經夏，溪冰定幾年？","橫階看臥石，隔牖聽飛泉。","地使炎涼變，人疑歲序遷。","詎知來遁俗，更似得逃年。"]', '["幽人自可怜，避暑更蕭然。","片云堪度雨，小樹即生煙。","巖雪頻經夏，溪冰定幾年？","橫階看臥石，隔牖听飞泉。","地使炎涼变，人疑歲序遷。","詎知来遁俗，更似得逃年。"]', '诗', 'shi', '', NULL, '山中避暑 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a91d13-5613-47f5-afa4-518cc0a7f9f5', '圍碁', '圍碁', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["飽食端居暇，披襟[弈]（奕）思專。","雕盤蜃脛飾，帖局象牙緣。","裂地四維舉，分麾兩陣前。","攢眉思上策，屈指計中權。","勁卒衡（韓校疑爲「衝」）圍度，奇軍略地旋。","魚鱗張九拒，鶴翅擁三邊。","逐征何待應，爭鋒豈厭先。","雙關防易斷，隻眼畏難全。","將驕多受辱，敵恥屢摧堅。","驟覩成爲敗，頻看絕更連。","許知愁越復，恤弱貴邢遷。","誹俗韋弘嗣，邀名葛稚川。","分陰雖可重，小道詎宜捐？","相公摧屐日，樵客爛柯年。","唐堯猶不棄，孔父尚稱賢。","博術存書錄，壺經著禮篇。","寄言陸士衡，無嗤王仲宣。","（按：《韻語陽秋》卷十七、《全唐詩》卷三七收「全」、「邊」二韻，題作《圍棋長篇》。","）。"]', '["飽食端居暇，披襟[弈]（奕）思專。","雕盤蜃脛飾，帖局象牙緣。","裂地四維舉，分麾兩陣前。","攢眉思上策，屈指計中權。","勁卒衡（韓校疑爲「衝」）圍度，奇軍略地旋。","鱼鱗張九拒，鹤翅擁三邊。","逐征何待應，爭鋒豈厭先。","雙关防易斷，隻眼畏难全。","將驕多受辱，敵恥屢摧堅。","驟覩成爲敗，頻看絕更連。","許知愁越复，恤弱貴邢遷。","誹俗韋弘嗣，邀名葛稚川。","分陰雖可重，小道詎宜捐？","相公摧屐日，樵客爛柯年。","唐堯猶不棄，孔父尚稱賢。","博術存书錄，壺經著禮篇。","寄言陸士衡，無嗤王仲宣。","（按：《韻語陽秋》卷十七、《全唐诗》卷三七收「全」、「邊」二韻，題作《圍棋长篇》。","）。"]', '诗', 'shi', '', NULL, '圍碁 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a78505d-2fe3-4edc-80ed-c90310353d36', '詠隱', '詠隐', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["獨有幽棲趣，能令俗網賒。","耕夫田作業，巢叟樹爲家。","晚令柔殘黍，春園掃落花。","恝然乘興往，何必御雲車？。"]', '["独有幽棲趣，能令俗網賒。","耕夫田作業，巢叟樹爲家。","晚令柔殘黍，春园掃落花。","恝然乘兴往，何必御云车？。"]', '诗', 'shi', '', NULL, '詠隱 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e7c705-ea2d-46aa-ac42-66bdc389362f', '春夜過翟處士正師飲酒醉後自問答二首 一', '春夜過翟处士正師饮酒醉後自问答二首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["樽酒泛流霞，相將臨歲華。","酣歌吹樹葉，醉舞拂燈花。","對飲情何已，思歸月漸斜。"]', '["樽酒泛流霞，相將臨歲华。","酣歌吹樹葉，醉舞拂灯花。","对饮情何已，思归月漸斜。"]', '诗', 'shi', '', NULL, '春夜過翟處士正師飲酒醉後自問答二首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508e9680-5cab-4b69-828d-55a972adf349', '春夜過翟處士正師飲酒醉後自問答二首 二', '春夜過翟处士正師饮酒醉後自问答二首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["春來物候妍，夜飲但留連。","晚鎗交鬢側，殘樽倚膝前。","縱橫抱琴舞，狼籍枕書眠。","解酲須及曙，路遠莫言旋。"]', '["春来物候妍，夜饮但留連。","晚鎗交鬢側，殘樽倚膝前。","縱橫抱琴舞，狼籍枕书眠。","解酲須及曙，路远莫言旋。"]', '诗', 'shi', '', NULL, '春夜過翟處士正師飲酒醉後自問答二首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d9b12c9-b6ba-4dcb-8fba-65f59a9489e8', '被舉應徵別鄉中故人', '被舉應徵別乡中故人', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["皇明照區域，帝思屬風雲。","燒山出隱士，治道送徵君。","自惟[蓬]（逢）艾影，叨名蘭桂芬。","使君留白璧，天子降玄纁。","山鷄終失望，野鹿暫辭羣。","川氣含丹日，鄉煙間白雲。","停驂無以贈，握管遂成文。","（按：祝尚書《〈全唐詩〉小補》云宋潘自牧《記纂淵海》卷六九引「自惟蓬艾影，叨名蘭桂芳」二句。","）。"]', '["皇明照區域，帝思屬风云。","燒山出隐士，治道送徵君。","自惟[蓬]（逢）艾影，叨名蘭桂芬。","使君留白璧，天子降玄纁。","山鷄終失望，野鹿暫辞羣。","川氣含丹日，乡煙间白云。","停驂無以贈，握管遂成文。","（按：祝尚书《〈全唐诗〉小補》云宋潘自牧《記纂淵海》卷六九引「自惟蓬艾影，叨名蘭桂芳」二句。","）。"]', '诗', 'shi', '', NULL, '被舉應徵別鄉中故人 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4420ae9b-b756-4df7-94a4-ce3d4f5af528', '同蔡學士君知詠雲', '同蔡学士君知詠云', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["固陽陰正密，侍族□方和。","巫山臣作賦，汾水帝爲歌。","繪色還成錦，輕飛更作羅。"]', '["固陽陰正密，侍族□方和。","巫山臣作賦，汾水帝爲歌。","繪色還成錦，轻飞更作羅。"]', '诗', 'shi', '', NULL, '同蔡學士君知詠雲 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f37c2cf-8dfc-42c7-972b-27e683dd2533', '贈山居黃道士', '贈山居黄道士', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["潔身何必是，避俗豈能全？","動息都無隔，浮沉最可憐。","嵇山《高士傳》，莊叟《讓王篇》。","逃名遂得志，□□若爲傳？。"]', '["潔身何必是，避俗豈能全？","动息都無隔，浮沉最可怜。","嵇山《高士傳》，莊叟《讓王篇》。","逃名遂得志，□□若爲傳？。"]', '诗', 'shi', '', NULL, '贈山居黃道士 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4db65e79-96f2-4a79-ba27-7347c9ad8843', '新園旦坐', '新园旦坐', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["林宅資餘搆，園亭今創營。","［接梨過半箸］（據李抄本補），從此近全生。","鑿沼三泉漏，爲山九仞成。","草香羅戶穴，茅茹結簷楹。","松栽一當伴，柳種五爲名。","獨對三春酌，無人來共傾。"]', '["林宅資餘搆，园亭今創營。","［接梨過半箸］（據李抄本補），從此近全生。","鑿沼三泉漏，爲山九仞成。","草香羅戶穴，茅茹結簷楹。","松栽一當伴，柳種五爲名。","独对三春酌，無人来共傾。"]', '诗', 'shi', '', NULL, '新園旦坐 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86da740e-6318-4d0a-bae1-b5ec19e00591', '閱家書', '閱家书', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["張氏前鈔本，班家舊賜餘。","尚應千許帙，何啻五盈車。","縫悉龜文印，題皆龍爪書。","牙籤過半在，玉軸已全疎。","蘖繫防黏蠹，芸香辟紙魚。","下帷堪發憤，閉戶足爲儲。","爲向揚雄說，無勞羨石渠。"]', '["張氏前鈔本，班家旧賜餘。","尚應千許帙，何啻五盈车。","縫悉龟文印，題皆龙爪书。","牙籤過半在，玉軸已全疎。","蘖繫防黏蠹，芸香辟紙鱼。","下帷堪發憤，閉戶足爲儲。","爲向揚雄说，無勞羨石渠。"]', '诗', 'shi', '', NULL, '閱家書 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e9acb3-5520-46a4-a57e-ec08866353dc', '九月九日', '九月九日', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["九日重陽節，三秋季月殘。","菊花催晚［氣］（據《古今歲時雜詠》補），萸房避早寒。","霜濃鷹擊遠，霧重雁飛難。","誰憶龍山外，蕭條邊興闌？","（按：《古今歲時雜詠》卷三十三以此詩爲崔善爲作，《全唐詩》卷八八二據以收入。","今移正重收。","）。"]', '["九日重陽節，三秋季月殘。","菊花催晚［氣］（據《古今歲时杂詠》補），萸房避早寒。","霜濃鷹擊远，霧重雁飞难。","誰憶龙山外，蕭條邊兴闌？","（按：《古今歲时杂詠》卷三十三以此诗爲崔善爲作，《全唐诗》卷八八二據以收入。","今移正重收。","）。"]', '诗', 'shi', '', NULL, '九月九日 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('991cb146-04e4-4c33-974c-b778f4e7de40', '登隴坂二首 一', '登隴坂二首 一', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["客行登隴坂，長望一思歸。","地險關山密，天平鴻雁稀。","轉蓬無定去，驚葉但知飛。","目極征途遠，勞情歌《式微》。"]', '["客行登隴坂，长望一思归。","地險关山密，天平鴻雁稀。","轉蓬無定去，驚葉但知飞。","目極征途远，勞情歌《式微》。"]', '诗', 'shi', '', NULL, '登隴坂二首 一 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0237c88-5881-4a3f-ac5e-68e3d3b75e43', '登隴坂二首 二', '登隴坂二首 二', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["隴坂三秦望，遊人萬里悲。","何關嗚咽水，自是斷腸時。","風高黃葉散，日下白雲滋。","悵望東飛翼，憂來不自持。","。"]', '["隴坂三秦望，游人万里悲。","何关嗚咽水，自是斷腸时。","风高黄葉散，日下白云滋。","悵望东飞翼，憂来不自持。","。"]', '诗', 'shi', '', NULL, '登隴坂二首 二 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b76de8a-38f3-40fb-9691-3b5eb95bfaf2', '遊山寺', '游山寺', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["赤城仙觀啓，青山梵宇裁。","中天疏寶座，半景出香臺。","雁翼金橋轉，魚鱗石道迴。","經文連樹刻，仙影對巖開。","別有迷方者，終慙無礙才。","摳衣祇杖錫，斂袂謁浮盃。","暫識𡺸闍嶺，聯詢劫燼灰。","持花龍女至，獻菓象王來。","講坐真乘闡，談筵外法催。","方希除八難，從此滌三災。"]', '["赤城仙观啓，青山梵宇裁。","中天疏寶座，半景出香台。","雁翼金橋轉，鱼鱗石道迴。","經文連樹刻，仙影对巖开。","別有迷方者，終慙無礙才。","摳衣祇杖錫，斂袂謁浮盃。","暫識𡺸闍嶺，聯詢劫燼灰。","持花龙女至，獻菓象王来。","講坐真乘闡，談筵外法催。","方希除八难，從此滌三災。"]', '诗', 'shi', '', NULL, '遊山寺 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('486f471d-fa07-4fa0-9e59-6c0974c37b3b', '觀石壁諸龕禮拜成詠', '观石壁諸龕禮拜成詠', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["萬里疏煙壁，千龕對日宮。","瞻顏猶不暇，合掌更難窮。","嶺路橫攜斷，山心暗鑿通。","真如何處泊？坐費計人功。"]', '["万里疏煙壁，千龕对日宮。","瞻顏猶不暇，合掌更难窮。","嶺路橫携斷，山心暗鑿通。","真如何处泊？坐費計人功。"]', '诗', 'shi', '', NULL, '觀石壁諸龕禮拜成詠 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49049dee-8beb-47d8-847a-f30288a86032', '久客齋府病歸言志', '久客斋府病归言志', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["君王[邸茅]（據李抄本補）寬，[脩]（行）竹正檀欒。","搆山臨下杜，穿渠入上蘭。","天人多晏喜，賓宷盛鵷鸞。","玉舄鎮花簟，金環□果盤。","鬭鷄新市望，走馬章臺看。","別有恩光重，恆嗟報答難。","沉綿赴漳浦，羈旅別長安。","玄渚蘆花白，黃山梨葉丹。","故人儻相念，應知歸路寒。"]', '["君王[邸茅]（據李抄本補）寬，[脩]（行）竹正檀欒。","搆山臨下杜，穿渠入上蘭。","天人多晏喜，賓宷盛鵷鸾。","玉舄鎮花簟，金环□果盤。","鬭鷄新市望，走马章台看。","別有恩光重，恆嗟報答难。","沉綿赴漳浦，羈旅別长安。","玄渚蘆花白，黄山梨葉丹。","故人儻相念，應知归路寒。"]', '诗', 'shi', '', NULL, '久客齋府病歸言志 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016862e4-fe72-406f-9fc2-627836c88a9a', '秋園夜坐', '秋园夜坐', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["秋來木葉黃，半夜坐林塘。","淺溜含新凍，輕雲護早霜。","落螢飛未起，驚鳥亂無行。","寂寞知何事？東籬菊稍芳。","（以上二十八首均見北京圖館藏清陳氏晚晴軒鈔本五卷本《王無功文集》卷三。","此本承鄭永曉同志抄示。","另參校之李抄本，即東武李氏研錄山房鈔本，轉引自韓理洲同志校點本《王無功文集》）（五卷本會校）。","）（按：《王無功文集》五卷本所錄王績詩題，有幾首與《全唐詩》所錄者有較大不同，錄如次：《夜還東溪中口號》，《全唐詩》作《夜還東溪》；《題黃頰山壁》，《全唐詩》作《黃頰山》；《山中別李處士播》，《全唐詩》缺「播」字；《秋夜喜遇姚處士義》，《全唐詩》作《秋夜喜遇王處士》；《過山觀尋蘇道士不見題壁四首》，《全唐詩》作《遊仙四首》；《盧新平宅賦古題得策杖尋隱士》，《全唐詩》僅作《策杖尋隱士》；《裴僕射宅詠妓》，《全唐詩》作《詠妓》。","）。"]', '["秋来木葉黄，半夜坐林塘。","淺溜含新凍，轻云護早霜。","落螢飞未起，驚鸟亂無行。","寂寞知何事？东籬菊稍芳。","（以上二十八首均见北京圖館藏清陳氏晚晴軒鈔本五卷本《王無功文集》卷三。","此本承鄭永晓同志抄示。","另參校之李抄本，即东武李氏研錄山房鈔本，轉引自韓理洲同志校点本《王無功文集》）（五卷本會校）。","）（按：《王無功文集》五卷本所錄王績诗題，有幾首與《全唐诗》所錄者有較大不同，錄如次：《夜還东溪中口號》，《全唐诗》作《夜還东溪》；《題黄頰山壁》，《全唐诗》作《黄頰山》；《山中別李处士播》，《全唐诗》缺「播」字；《秋夜喜遇姚处士義》，《全唐诗》作《秋夜喜遇王处士》；《過山观尋蘇道士不见題壁四首》，《全唐诗》作《游仙四首》；《盧新平宅賦古題得策杖尋隐士》，《全唐诗》僅作《策杖尋隐士》；《裴僕射宅詠妓》，《全唐诗》作《詠妓》。","）。"]', '诗', 'shi', '', NULL, '秋園夜坐 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a1fb15d-9791-49ba-a118-8d5cd9553ede', '句', '句', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["側望卿相門，難入堅如石。","（同前卷七四。","轉錄自祝尚書《〈全唐詩〉小補》。","）。"]', '["側望卿相门，难入堅如石。","（同前卷七四。","轉錄自祝尚书《〈全唐诗〉小補》。","）。"]', '诗', 'shi', '', NULL, '句 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44cbbaf4-1fe9-4c5d-8df2-be3b59e52243', '四言曲池酺飲座銘', '四言曲池酺饮座銘', '31570ba5-84d5-4018-8db2-07de23c9e63c', '唐', '["羣公酺飲，列坐水湄。","花飄翠蓋，葉覆丹帷。","俱傾聖酒，爭摛雅詩。","下國賤隸，含毫無辭。","（《翰林學士集》）（按：此詩署「越王文學陸搢」。","越王即李泰，後徙魏王。","張步雲《唐代逸詩輯存》收入本詩。","）。"]', '["羣公酺饮，列坐水湄。","花飄翠蓋，葉覆丹帷。","俱傾聖酒，爭摛雅诗。","下国賤隸，含毫無辞。","（《翰林学士集》）（按：此诗署「越王文学陸搢」。","越王即李泰，後徙魏王。","張步云《唐代逸诗輯存》收入本诗。","）。"]', '诗', 'shi', '', NULL, '四言曲池酺飲座銘 陸搢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e72104ed-0d69-412d-a105-99687837c752', '五言春日侍宴望海應詔', '五言春日侍宴望海應詔', '674082e0-f20e-4845-a5a2-68e31e646153', '唐', '["巨壑觀無際，靈異藴難詳。","尋真遊漢武，架石駐秦皇。","方丈神仙敻，蓬萊道路長。","俱由肆情慾，非爲恤封壃（同「疆」）。","何如應順動，鳴鑾事省方。","徘徊臨委輸，迢遰極扶桑。","滔滔四瀆府，浩浩百川王。","浮天還納漢，浴日乍翻光。","夷洲曖淑景，有島麗時芳。","幸屬滄波謐，欣逢寶化昌。","（《翰林學士集》）（按：此詩原署「侍中清苑縣開國男臣劉泊上」，「泊」爲「洎」之誤。","張步雲《唐代逸詩輯存》收本詩。","）。"]', '["巨壑观無際，靈異藴难詳。","尋真游漢武，架石駐秦皇。","方丈神仙敻，蓬萊道路长。","俱由肆情慾，非爲恤封壃（同「疆」）。","何如應順动，鳴鑾事省方。","徘徊臨委輸，迢遰極扶桑。","滔滔四瀆府，浩浩百川王。","浮天還納漢，浴日乍翻光。","夷洲曖淑景，有島丽时芳。","幸屬滄波謐，欣逢寶化昌。","（《翰林学士集》）（按：此诗原署「侍中清苑縣开国男臣劉泊上」，「泊」爲「洎」之誤。","張步云《唐代逸诗輯存》收本诗。","）。"]', '诗', 'shi', '', NULL, '五言春日侍宴望海應詔 劉洎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c163a5b-59e4-4eef-bde2-1da535b0b86e', '五言春日侍宴望海應詔', '五言春日侍宴望海應詔', '586bafa4-cbba-45a3-af6a-5dd16b70c7a9', '唐', '["五材□水流，千流會谷王。","委輸綿厚載，朝宗極大荒。","浮天納星漢，浴日吐扶桑。","奔濤疑疊島，驚浪似浮航。","雲撤青丘見，霧卷碧流長。","金臺煥霞景，銀闕藻春光。","九夷驕巨壑，五輅出遼陽。","朝神汎弘舸，鞭石濟飛梁。","曜戈威海□，振楫落星芒。","幸廁[歌]旅□，極望恧成章。","（《翰林學士集》）（按：此詩原署「中書令江陵縣開國子弘文館學士臣岑文本上」。","張步雲《唐代逸詩輯存》收此詩。","）。"]', '["五材□水流，千流會谷王。","委輸綿厚載，朝宗極大荒。","浮天納星漢，浴日吐扶桑。","奔濤疑叠島，驚浪似浮航。","云撤青丘见，霧卷碧流长。","金台煥霞景，銀闕藻春光。","九夷驕巨壑，五輅出遼陽。","朝神汎弘舸，鞭石濟飞梁。","曜戈威海□，振楫落星芒。","幸廁[歌]旅□，極望恧成章。","（《翰林学士集》）（按：此诗原署「中书令江陵縣开国子弘文館学士臣岑文本上」。","張步云《唐代逸诗輯存》收此诗。","）。"]', '诗', 'shi', '', NULL, '五言春日侍宴望海應詔 岑文本 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d94e85ce-4b0d-46ea-888f-77190f02a3ec', '四言曲池酺飲座銘', '四言曲池酺饮座銘', 'fa45b2ba-793f-4419-9e45-a7d1b28d816b', '唐', '["離酺將促，遠就池臺。","酒隨歡至，花逐風來。","鶴歸波動，魚躍萍開。","人生所盛，何過樂哉。","（《翰林學士集》）（按：此詩原署「沛公鄭元璹」。","張步雲《唐代逸詩輯存》收此詩。","）。"]', '["離酺將促，远就池台。","酒隨歡至，花逐风来。","鹤归波动，鱼躍萍开。","人生所盛，何過乐哉。","（《翰林学士集》）（按：此诗原署「沛公鄭元璹」。","張步云《唐代逸诗輯存》收此诗。","）。"]', '诗', 'shi', '', NULL, '四言曲池酺飲座銘 鄭元璹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0a6f67-4930-425d-a1b7-acd7a86301fb', '四言曲池酺飲座銘', '四言曲池酺饮座銘', 'ed391fa3-ea59-4c9c-aa80-ca6417b5f715', '唐', '["天地開泰，日月貞明。","政教弘闡，至治隆平。","三陽應節，百卉舒榮。","憓流方外，酺飲上京。","（《翰林學士集》）（按：此詩原署「武康公沈叔安」。","張步雲《唐代逸詩輯存》收入。","）。"]', '["天地开泰，日月貞明。","政教弘闡，至治隆平。","三陽應節，百卉舒榮。","憓流方外，酺饮上京。","（《翰林学士集》）（按：此诗原署「武康公沈叔安」。","張步云《唐代逸诗輯存》收入。","）。"]', '诗', 'shi', '', NULL, '四言曲池酺飲座銘 沈叔安 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e19d5771-95bf-4807-a56e-b0c706bc7f87', '五言春日侍宴次望海應詔', '五言春日侍宴次望海應詔', '15aa9887-587f-4ef2-a36a-f51fb4e9615b', '唐', '["玉律應青陽，鸞駕幸春方。","篲雲陳罕罼，亘野列旗常。","雕弓連月彩，雄劍聚星光。","觀兵遼碣上，停驂渤澥傍。","浮天既淼淼，浴日復滄滄。","水映紅桃色，風飄丹𪱳（疑爲「桂」字）香。","蜃結疑樓峙，濤驚似蓋張。","三韓沐醇化，四郡竚唯良。","深仁苞動植，神武讋遐荒。","願草登封禮，簪紱奉周行。","（《翰林學士集》）（按：此詩原署「開府儀同三司申國公臣高士廉上」。","張步雲《唐代逸詩輯存》收入。","）。"]', '["玉律應青陽，鸾駕幸春方。","篲云陳罕罼，亘野列旗常。","雕弓連月彩，雄劍聚星光。","观兵遼碣上，停驂渤澥傍。","浮天既淼淼，浴日复滄滄。","水映紅桃色，风飄丹𪱳（疑爲「桂」字）香。","蜃結疑楼峙，濤驚似蓋張。","三韓沐醇化，四郡竚唯良。","深仁苞动植，神武讋遐荒。","願草登封禮，簪紱奉周行。","（《翰林学士集》）（按：此诗原署「开府儀同三司申国公臣高士廉上」。","張步云《唐代逸诗輯存》收入。","）。"]', '诗', 'shi', '', NULL, '五言春日侍宴次望海應詔 高士廉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('effdd9f4-9b70-4762-8c5e-5d28657a570d', '五言奉日侍宴望海應詔', '五言奉日侍宴望海應詔', '78f64428-0e9c-4a35-844a-f3af7222b02b', '唐', '["御龍稱曩載，仙駕紀前皇。","直謂窮遊覽，非爲務省方。","大君弘覆燾，禁暴撫遐荒。","觀兵臨碣石，極目眺扶桑。","周區廓靈府，接漢委歸塘。","淼淼經綸闊，悠悠控注長。","標空□絕島，跨日起飛梁。","銀闕浮朝氣，金臺映晚光。","蕩穢符神略，安流表會昌。","徒欣奉奇觀，傾蠡詎可量？","（《翰林學士集》）（按：此詩原署「左宗衛率府長史弘文館直學士臣鄭仁軌上」。","張步雲《唐代逸詩輯存》收入。","）。"]', '["御龙稱曩載，仙駕紀前皇。","直謂窮游覽，非爲務省方。","大君弘覆燾，禁暴撫遐荒。","观兵臨碣石，極目眺扶桑。","周區廓靈府，接漢委归塘。","淼淼經綸闊，悠悠控注长。","標空□絕島，跨日起飞梁。","銀闕浮朝氣，金台映晚光。","蕩穢符神略，安流表會昌。","徒欣奉奇观，傾蠡詎可量？","（《翰林学士集》）（按：此诗原署「左宗衛率府长史弘文館直学士臣鄭仁軌上」。","張步云《唐代逸诗輯存》收入。","）。"]', '诗', 'shi', '', NULL, '五言奉日侍宴望海應詔 鄭仁軌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f1d2134-4a1d-4c80-8da5-8ff8e669ab99', '雜言詩', '杂言诗', 'faa6b30a-a174-4330-9d64-fae124ad6c88', '唐', '["嘉辰令月歡無極，萬歲千秋樂未央。","（見《日本古典文學大系》七三冊收日人藤原公任一○一八年左右纂《和漢朗詠集》卷下《祝》。","）（按：題據川口久雄校注引架藏私注本。","）。"]', '["嘉辰令月歡無極，万歲千秋乐未央。","（见《日本古典文学大系》七三冊收日人藤原公任一○一八年左右纂《和漢朗詠集》卷下《祝》。","）（按：題據川口久雄校注引架藏私注本。","）。"]', '诗', 'shi', '', NULL, '雜言詩 謝偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65eb875c-d5dc-4b32-bfbf-2a466aab3f1b', '祀五方用舒和歌', '祀五方用舒和歌', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["笙歌籥舞屬年韶，鷺鼓鳧鐘展時豫。","調露初迎綺春節。","承雲遽踐蒼霄馭。","（見《唐詩紀事》卷四）（按：《祀五方上帝五郊樂》，《舊唐書》卷三十《音樂志》三云「貞觀中魏徵等作」。","《全唐詩》卷三一均收魏徵名下，實誤。","《紀事》以此首爲亮作，必有所據，故錄出之。","）。"]', '["笙歌籥舞屬年韶，鷺鼓鳧鐘展时豫。","調露初迎綺春節。","承云遽踐蒼霄馭。","（见《唐诗紀事》卷四）（按：《祀五方上帝五郊乐》，《旧唐书》卷三十《音乐志》三云「貞观中魏徵等作」。","《全唐诗》卷三一均收魏徵名下，實誤。","《紀事》以此首爲亮作，必有所據，故錄出之。","）。"]', '诗', 'shi', '', NULL, '祀五方用舒和歌 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e34e094c-2724-4944-8d6c-05c4acc6bdc9', '宗廟九德之歌辭', '宗廟九德之歌辞', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["皇祖誕慶，於昭於天。","積德斯遠，茂緒攸（一作「攸緒」）先。","繼天應曆（一作「維文應曆」），神武弘宣。","肇跡嬀水，成功版（一作「坂」）泉。","道光覆載，聲穆乾元（一作「吉先」），式備犧象，用潔牲牷。","禮終九獻，樂展四懸。","神貺景福，遐哉永年。","（見中華書局排印本《初學記》卷十三）（按：《全唐詩》卷八八二《補遺》已收此詩，有缺文，故重錄出。","注「一作」者，爲《全唐詩》所收本異文。","）。"]', '["皇祖誕慶，於昭於天。","積德斯远，茂緒攸（一作「攸緒」）先。","繼天應曆（一作「維文應曆」），神武弘宣。","肇跡嬀水，成功版（一作「坂」）泉。","道光覆載，声穆乾元（一作「吉先」），式備犧象，用潔牲牷。","禮終九獻，乐展四懸。","神貺景福，遐哉永年。","（见中华书局排印本《初学記》卷十三）（按：《全唐诗》卷八八二《補遺》已收此诗，有缺文，故重錄出。","注「一作」者，爲《全唐诗》所收本異文。","）。"]', '诗', 'shi', '', NULL, '宗廟九德之歌辭 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('594c3509-8167-46f8-9748-9fb3e8d19322', '祭太社樂章八首（存目○見《舊唐書》卷三十《音樂志》三）（按：《舊唐書》謂此組詩「貞觀中褚亮等作」。然孰爲亮作，則已無從考詳。詩已收《全唐詩》卷十二，不重錄。）', '祭太社乐章八首（存目○见《旧唐书》卷三十《音乐志》三）（按：《旧唐书》謂此組诗「貞观中褚亮等作」。然孰爲亮作，則已無從考詳。诗已收《全唐诗》卷十二，不重錄。）', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '祭太社樂章八首（存目○見《舊唐書》卷三十《音樂志》三）（按：《舊唐書》謂此組詩「貞觀中褚亮等作」。然孰爲亮作，則已無從考詳。詩已收《全唐詩》卷十二，不重錄。） 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7285ae84-824b-4b64-afee-192a543ab38e', '享太廟樂章十三首（存目○見同書卷三十一《音樂志》四）（按：《舊唐書》謂此組詩「貞觀中魏徵、褚亮等作」。《全唐詩》卷三十一均收魏徵名下，未允。然孰爲亮作，亦無從甄別，姑存目以備考。）', '享太廟乐章十三首（存目○见同书卷三十一《音乐志》四）（按：《旧唐书》謂此組诗「貞观中魏徵、褚亮等作」。《全唐诗》卷三十一均收魏徵名下，未允。然孰爲亮作，亦無從甄別，姑存目以備考。）', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '享太廟樂章十三首（存目○見同書卷三十一《音樂志》四）（按：《舊唐書》謂此組詩「貞觀中魏徵、褚亮等作」。《全唐詩》卷三十一均收魏徵名下，未允。然孰爲亮作，亦無從甄別，姑存目以備考。） 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd814f9-0332-442a-af1e-6b19c3047357', '五言早秋[儀鸞殿]侍宴應詔', '五言早秋[儀鸾殿]侍宴應詔', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["秋氣灑雲景，高絃韻早風。","雕梁尚飛鷰，洛浦未驚鴻。","水泛芙蕖影，橋臨芳桂叢。","稱觴奉高興，長願比華嵩。","（見清末貴陽陳田影刊日本尾張國真福寺藏唐卷子本《翰林學士集》）（按：此詩原署：「中書令駙馬都尉安德郡開國公臣楊師道上」。","）。"]', '["秋氣灑云景，高絃韻早风。","雕梁尚飞鷰，洛浦未驚鴻。","水泛芙蕖影，橋臨芳桂叢。","稱觴奉高兴，长願比华嵩。","（见清末貴陽陳田影刊日本尾張国真福寺藏唐卷子本《翰林学士集》）（按：此诗原署：「中书令駙马都尉安德郡开国公臣楊師道上」。","）。"]', '诗', 'shi', '', NULL, '五言早秋[儀鸞殿]侍宴應詔 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc992a1-5c9c-48fa-afaf-1fcae5ae750f', '五言奉和行經破薛舉戰地應詔', '五言奉和行經破薛舉戰地應詔', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["鳳紀初膺籙，龍顏昔在田。","鳴祠憑隴嶂，召雨竊涇川。","受律威丹浦，揚兵震阪泉。","止戈基此地，握契硉斯年。","六轡乘秋景，三驅被廣壥。","凝笳入曉囀，析羽雜風懸。","塞雲銜落日，關城帶斷煙。","回輿登故壘，駐蹕想荒阡。","歲月方悠敻，神功逾赫然。","微臣願奉職，導禮翠華前。","（同前）（按：此詩原署「太常卿駙馬都尉安德郡開國公臣楊師道上」。","張步雲《唐代逸詩輯存》收錄本詩。","）。"]', '["鳳紀初膺籙，龙顏昔在田。","鳴祠憑隴嶂，召雨竊涇川。","受律威丹浦，揚兵震阪泉。","止戈基此地，握契硉斯年。","六轡乘秋景，三驱被廣壥。","凝笳入晓囀，析羽杂风懸。","塞云銜落日，关城带斷煙。","回輿登故壘，駐蹕想荒阡。","歲月方悠敻，神功逾赫然。","微臣願奉職，導禮翠华前。","（同前）（按：此诗原署「太常卿駙马都尉安德郡开国公臣楊師道上」。","張步云《唐代逸诗輯存》收錄本诗。","）。"]', '诗', 'shi', '', NULL, '五言奉和行經破薛舉戰地應詔 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6cb012-d6fc-4ede-a266-450893c058fb', '笙歌（二首） 一', '笙歌（二首） 一', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["新聲雖自知，舊寵會應移。","無令棗下吹，便作一枯枝。"]', '["新声雖自知，旧寵會應移。","無令棗下吹，便作一枯枝。"]', '诗', 'shi', '', NULL, '笙歌（二首） 一 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('540a6b10-9fdd-4ee7-9c53-baee2460ac19', '笙歌（二首） 二', '笙歌（二首） 二', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["爲相雍門歎，當思執燭遊。","不惜妾身難再得，方期君壽度千秋。","（見中華書局影印本《文苑英華》卷七一李百藥《笙賦》）。"]', '["爲相雍门歎，當思執燭游。","不惜妾身难再得，方期君壽度千秋。","（见中华书局影印本《文苑英华》卷七一李百藥《笙賦》）。"]', '诗', 'shi', '', NULL, '笙歌（二首） 二 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd62a889-12b8-407f-a055-6f8b58cf33f6', '賜李百藥', '賜李百藥', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["項棄范增善，紂妬比干才。","嗟此二賢沒，余喜得卿來。","（《冊府元龜》卷九七《帝王部·禮賢》。","此首承陶敏先生錄示。","）。"]', '["項棄范增善，紂妬比干才。","嗟此二賢沒，余喜得卿来。","（《冊府元龟》卷九七《帝王部·禮賢》。","此首承陶敏先生錄示。","）。"]', '诗', 'shi', '', NULL, '賜李百藥 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03212a8-2f39-4f0f-bd06-09fc75436b2c', '五言悼姜確（題擬）', '五言悼姜確（題擬）', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["鑿門初奉衛，伏節始臨戎。","振鱗方躍浪，騁翼正凌風。","未展六騎術，先虧一簣功。","防身不足智，狥命有餘忠。","悲驂嘶向路，哀笳咽遠空。","淒涼大樹下，流悼滿深衷。","（《冊府元龜》卷一四一《帝王部·念良臣》）（按：《全唐詩》卷一錄前八句題作《傷遼東戰亡》。","）。"]', '["鑿门初奉衛，伏節始臨戎。","振鱗方躍浪，騁翼正凌风。","未展六騎術，先虧一簣功。","防身不足智，狥命有餘忠。","悲驂嘶向路，哀笳咽远空。","淒涼大樹下，流悼满深衷。","（《冊府元龟》卷一四一《帝王部·念良臣》）（按：《全唐诗》卷一錄前八句題作《傷遼东戰亡》。","）。"]', '诗', 'shi', '', NULL, '五言悼姜確（題擬） 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f06ac95-bf6b-43bf-9996-fd4cbee075a9', '魏徵葬日登凌煙閣賦七言詩（題擬）', '魏徵葬日登凌煙閣賦七言诗（題擬）', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["勁篠逢霜摧美質，台星失位夭良臣。","唯當掩泣雲臺上，空對餘形無復人。","（唐王方慶纂《魏鄭公諫錄》卷五）（〖1〗《魏鄭公諫錄》云：「公葬日，勑京官文武九品以上及計吏幷送至開遠門外。","太宗幸苑西樓望哭盡哀，令晉王宣勑祭之。","太宗因望遠作詩曰〖詩略〗。","御撰碑文及挽歌詞，仍親爲書。","太宗思之不已，遂登凌煙閣觀其畫，又賦七言詩送靈座焉。","其辭曰〖詩略〗。","」今按：所引二詩，前一首已收《全唐詩》卷一，所據當爲《初學記》卷十四。","後一首失收。","）。"]', '["勁篠逢霜摧美質，台星失位夭良臣。","唯當掩泣云台上，空对餘形無复人。","（唐王方慶纂《魏鄭公諫錄》卷五）（〖1〗《魏鄭公諫錄》云：「公葬日，勑京官文武九品以上及計吏幷送至开远门外。","太宗幸苑西楼望哭尽哀，令晉王宣勑祭之。","太宗因望远作诗曰〖诗略〗。","御撰碑文及挽歌词，仍親爲书。","太宗思之不已，遂登凌煙閣观其畫，又賦七言诗送靈座焉。","其辞曰〖诗略〗。","」今按：所引二诗，前一首已收《全唐诗》卷一，所據當爲《初学記》卷十四。","後一首失收。","）。"]', '诗', 'shi', '', NULL, '魏徵葬日登凌煙閣賦七言詩（題擬） 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6241fc5b-ed19-40eb-85d4-00b0cfb64d7d', '五言塞外同賦山夜臨秋以臨爲韻', '五言塞外同賦山夜臨秋以臨爲韻', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["邊城炎氣沉，塞外涼風侵。","三韓駐旌節，九野蹔登臨。","水淨霞中色，山高{雨/口}（下半字原卷缺。","似爲「雲」字）裏心。","浪帷舒百丈，松蓋偃千尋。","毀橋猶帶石，目闕尚橫金。","煙生遙岸隱，月落半峯陰。","連洲（《初學記》卷三「洲」作「山」）驚鳥亂，隔岫斷猿吟。","早花初密菊，晚葉未疎林。","憑軾望寰宇，流眺極高深。","河山非所恃，於焉鑑古今。","（見貴陽陳田影刊日本尾張國真福寺舊藏唐卷子本《翰林學士集》）（按：《全唐詩》卷一據《初學記》卷三收入本詩，僅存「煙生遙岸隱」以下四句，爲類書刪節之文，今爲補出全詩。","）。"]', '["邊城炎氣沉，塞外涼风侵。","三韓駐旌節，九野蹔登臨。","水淨霞中色，山高{雨/口}（下半字原卷缺。","似爲「云」字）裏心。","浪帷舒百丈，松蓋偃千尋。","毀橋猶带石，目闕尚橫金。","煙生遙岸隐，月落半峯陰。","連洲（《初学記》卷三「洲」作「山」）驚鸟亂，隔岫斷猿吟。","早花初密菊，晚葉未疎林。","憑軾望寰宇，流眺極高深。","河山非所恃，於焉鑑古今。","（见貴陽陳田影刊日本尾張国真福寺旧藏唐卷子本《翰林学士集》）（按：《全唐诗》卷一據《初学記》卷三收入本诗，僅存「煙生遙岸隐」以下四句，爲類书刪節之文，今爲補出全诗。","）。"]', '诗', 'shi', '', NULL, '五言塞外同賦山夜臨秋以臨爲韻 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d29d72b-6138-4626-8c08-ec9612cade00', '五言延慶殿集同賦花間鳥', '五言延慶殿集同賦花间鸟', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["露園芳蘂散，風樹□鸎新。","啼笑非憂樂，嬌莊復對人。","色映枝中錦，歌飛葉裏塵。","所嗟非久質，共視歇餘春。","（同前）。"]', '["露园芳蘂散，风樹□鸎新。","啼笑非憂乐，嬌莊复对人。","色映枝中錦，歌飞葉裏塵。","所嗟非久質，共視歇餘春。","（同前）。"]', '诗', 'shi', '', NULL, '五言延慶殿集同賦花間鳥 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e644576d-f85a-4bbd-bad0-a30d319ad436', '五言咏棋（二首） 一', '五言咏棋（二首） 一', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["手談標昔美，坐隱逸前良。","參差分兩勢，玄素引雙行。","捨生非假命，帶死不關傷。","方知仙嶺側，爛斧幾寒芳。"]', '["手談標昔美，坐隐逸前良。","參差分兩勢，玄素引雙行。","捨生非假命，带死不关傷。","方知仙嶺側，爛斧幾寒芳。"]', '诗', 'shi', '', NULL, '五言咏棋（二首） 一 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('892b78b1-c2ea-4e8f-857f-d4dcbe18baeb', '五言咏棋（二首） 二', '五言咏棋（二首） 二', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["治兵期制勝，裂地不要勳。","半死圍中斷，全生節外分。","鴈行非假翼，陣氣本無雲。","翫此孫吳意，怡神靜俗氛。","（同前）（按：以上三首，張步雲《唐代逸詩輯存》收入。","）。"]', '["治兵期制勝，裂地不要勳。","半死圍中斷，全生節外分。","鴈行非假翼，陣氣本無云。","翫此孫吳意，怡神静俗氛。","（同前）（按：以上三首，張步云《唐代逸诗輯存》收入。","）。"]', '诗', 'shi', '', NULL, '五言咏棋（二首） 二 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e949f377-d46e-4639-9505-3d0866d9d774', '贊姚秦三藏羅什法師詩', '贊姚秦三藏羅什法師诗', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["秦朝朗現聖人星，遠表吾師德至靈。","十萬流沙來振錫，三千弟子共翻經。","文含金玉知無朽，舌似蘭蓀尚有馨。","堪歎逍遙薗裏事，空餘明月草青青。","（清陸耀遹《金石續編》卷二十）（按：《金石續編》謂此詩石刻爲正書，在陝西鄠縣。","詩後有題記云：「維那僧定瑞、副寺僧祖瞻、祖肹、監寺僧祖□、祖）（曦，正大乙酉歲仲冬望日，主持傳法沙門義金重錄立石。","長安樊世亨刊。","」正大爲金哀宗年號。","既云重錄，當有所自，惜未見更早記載。","民國二十二年刊《鄠縣縣志》卷七云：「其石刊舊存草堂寺，今佚。","」）。"]', '["秦朝朗現聖人星，远表吾師德至靈。","十万流沙来振錫，三千弟子共翻經。","文含金玉知無朽，舌似蘭蓀尚有馨。","堪歎逍遙薗裏事，空餘明月草青青。","（清陸耀遹《金石續編》卷二十）（按：《金石續編》謂此诗石刻爲正书，在陝西鄠縣。","诗後有題記云：「維那僧定瑞、副寺僧祖瞻、祖肹、監寺僧祖□、祖）（曦，正大乙酉歲仲冬望日，主持傳法沙门義金重錄立石。","长安樊世亨刊。","」正大爲金哀宗年號。","既云重錄，當有所自，惜未见更早記載。","民国二十二年刊《鄠縣縣志》卷七云：「其石刊旧存草堂寺，今佚。","」）。"]', '诗', 'shi', '', NULL, '贊姚秦三藏羅什法師詩 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2d17730-15a7-43f1-8d38-e33679b65c62', '焚經臺', '焚經台', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["門徑蕭蕭長綠苔，一回登此一徘徊。","青牛謾說函關去，白馬親從印土來。","確實是非憑烈焰，要分真僞築高臺。","春風也解嫌狼籍，吹盡當年道教灰。","（見《四部叢刊初編》影宋本釋法雲《翻譯名義集》卷七「續補譯師」條注。","日本《續藏經》本宋釋子昇、如祐輯《禪門諸祖師偈頌》卷下之下稱此詩爲「唐太宗《題白馬寺》」。","）（按：《全唐詩》卷七八六以此詩歸無名氏，云「其聲調不類，要是後人妄託。","」然此詩徵引甚早。","《翻譯名義集》亦非僞妄之書。","同卷錄義淨三藏詩，亦初唐時人。","恐館臣之意不在聲類，而在此詩有玷太宗之盛德耳。","義淨詩亦誤錄。","岑仲勉先生《讀全唐詩札記》已斥其妄。","初唐七律傳世甚少。","故重錄之。","）。"]', '["门徑蕭蕭长綠苔，一回登此一徘徊。","青牛謾说函关去，白马親從印土来。","確實是非憑烈焰，要分真僞築高台。","春风也解嫌狼籍，吹尽當年道教灰。","（见《四部叢刊初編》影宋本釋法云《翻譯名義集》卷七「續補譯師」條注。","日本《續藏經》本宋釋子昇、如祐輯《禪门諸祖師偈頌》卷下之下稱此诗爲「唐太宗《題白马寺》」。","）（按：《全唐诗》卷七八六以此诗归無名氏，云「其声調不類，要是後人妄託。","」然此诗徵引甚早。","《翻譯名義集》亦非僞妄之书。","同卷錄義淨三藏诗，亦初唐时人。","恐館臣之意不在声類，而在此诗有玷太宗之盛德耳。","義淨诗亦誤錄。","岑仲勉先生《读全唐诗札記》已斥其妄。","初唐七律傳世甚少。","故重錄之。","）。"]', '诗', 'shi', '', NULL, '焚經臺 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e38c770c-d2ad-4bb0-8cbb-75cae155a9da', '缺題讚', '缺題讚', '33e40c7d-52f8-4390-a2bb-1c993f02f308', '唐', '["功成積劫印紋端，不是南山得恐難。","眼覩數重金色潤，手擎一片玉光寒。","煉時百火精神透，藏處千年瑩彩完。","定果薰脩真秘密，信心莫作等閑看。","（見《大正新修大藏經》第五十二冊元釋詳邁撰《辨僞錄》卷五，云出元如意長老《聖旨特建釋迦舍利靈通感通之塔碑文》。","《佛祖統紀》卷四五作宋太宗《佛牙讚》。","）。"]', '["功成積劫印紋端，不是南山得恐难。","眼覩數重金色潤，手擎一片玉光寒。","煉时百火精神透，藏处千年瑩彩完。","定果薰脩真秘密，信心莫作等闲看。","（见《大正新修大藏經》第五十二冊元釋詳邁撰《辨僞錄》卷五，云出元如意长老《聖旨特建釋迦舍利靈通感通之塔碑文》。","《佛祖統紀》卷四五作宋太宗《佛牙讚》。","）。"]', '诗', 'shi', '', NULL, '缺題讚 太宗皇帝李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e81880a-b1df-4b93-b441-e0b2535aa264', '舞劍歌', '舞劍歌', '7f0375a4-46aa-408b-8f60-d5cc62c3cc19', '唐', '["陟崇岡兮望四圍，□□閃□兮斷虹飛，嗟嗟三軍唱凱歸。","（見《欽定盤山志》卷一、《日下舊聞考》卷一一六。","）（按：顧炎武《金石文字記》卷五《盤山題名》云：「薊州西北三十里盤山上有『李靖舞劍臺，李從簡曾遊』十大字，刻於石。","」復引《冊府元龜》謂從簡爲文宗開成初人。","又按：《全芳備祖前集》卷十一收李靖「澤蘭多衆芳，妍姿不相匹」爲李德裕詩，已收入《全唐詩》卷四七五。","此因二人皆封衛國公而致誤。","）。"]', '["陟崇岡兮望四圍，□□閃□兮斷虹飞，嗟嗟三軍唱凱归。","（见《欽定盤山志》卷一、《日下旧闻考》卷一一六。","）（按：顧炎武《金石文字記》卷五《盤山題名》云：「薊州西北三十里盤山上有『李靖舞劍台，李從簡曾游』十大字，刻於石。","」复引《冊府元龟》謂從簡爲文宗开成初人。","又按：《全芳備祖前集》卷十一收李靖「澤蘭多衆芳，妍姿不相匹」爲李德裕诗，已收入《全唐诗》卷四七五。","此因二人皆封衛国公而致誤。","）。"]', '诗', 'shi', '', NULL, '舞劍歌 李靖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f7b0b68-4534-4fa6-b83a-963f027260b2', '宿雲門東客院', '宿云门东客院', '51f3758c-8031-4cec-9eb5-430cc4fb59a6', '唐', '["路入山西又向（《蘭亭考》作「路更」）西，雨和春雪旋成泥。","風吹疊巘雲頭散，月照平湖雁影低。","拄杖負書尋遠寺，倩童牽鹿渡深溪。","今朝獨宿巖東院，唯聽猿吟與鳥啼。","（見《會稽掇英總集》卷六、桑世昌《蘭亭考》卷十。","）（〖1〗《蘭亭考》附高似孫跋云：「右蕭翼詩辭不多見，此二詩在雲門作，所謂『拄杖負書』者，正訪蘭亭時也。","似孫題。","」所云二詩，另一爲《留題雲門》，已收《全唐詩續補遺》卷一。","〖2〗同書桑世昌跋：「世昌近於東墅閱高續古校書法名畫，方見此詩及跋。","使御史不有此行，烏得是清絕語。","故具載之。","」〖3〗《六藝之一錄》卷一六○《褉帖類林目錄》著錄蕭翼《題雲門寺詩二首》。","）。"]', '["路入山西又向（《蘭亭考》作「路更」）西，雨和春雪旋成泥。","风吹叠巘云头散，月照平湖雁影低。","拄杖負书尋远寺，倩童牽鹿渡深溪。","今朝独宿巖东院，唯听猿吟與鸟啼。","（见《會稽掇英總集》卷六、桑世昌《蘭亭考》卷十。","）（〖1〗《蘭亭考》附高似孫跋云：「右蕭翼诗辞不多见，此二诗在云门作，所謂『拄杖負书』者，正訪蘭亭时也。","似孫題。","」所云二诗，另一爲《留題云门》，已收《全唐诗續補遺》卷一。","〖2〗同书桑世昌跋：「世昌近於东墅閱高續古校书法名畫，方见此诗及跋。","使御史不有此行，烏得是清絕語。","故具載之。","」〖3〗《六藝之一錄》卷一六○《褉帖類林目錄》著錄蕭翼《題云门寺诗二首》。","）。"]', '诗', 'shi', '', NULL, '宿雲門東客院 蕭翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('536287cb-8ecd-4c7d-a75b-8b7d9ee656d7', '赴召', '赴召', 'c712938f-f2b8-4907-b041-1f2c85c2f1ac', '唐', '["雲霄只（疑當作「咫」）尺別松關，禪室空留碧嶂間。","縱使朝廷卿相貴，爭如心與白雲閒。","（見《古今禪藻集》卷七）。"]', '["云霄只（疑當作「咫」）尺別松关，禪室空留碧嶂间。","縱使朝廷卿相貴，爭如心與白云閒。","（见《古今禪藻集》卷七）。"]', '诗', 'shi', '', NULL, '赴召 辨才 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b381d5e4-b038-40db-af9b-1a6887bf0cad', '詠泥', '詠泥', '74862f53-0fa2-457d-b0cc-d7c53d305238', '唐', '["椒塗香氣溢，芝封璽文生。","色逐梨陽紫，名隨蜀道清。","一丸封漢塞，數斗濁秦涇。","不分（一作「曉」）高樓妾，特況別離情。","（見《十萬卷樓叢書》本皎然《詩式》卷三。","參《四友齋叢說》卷二十四。","）（按：《詩式》收此詩置隋人間。","今考《新唐書》卷七二《宰相世系表》二趙郡李氏東祖房有「君武，蔚州司馬」。","其從伯孝端，爲隋獲嘉丞。","其子思貞，文明元年自婺州刺史改越州刺史，見《會稽掇英總集》卷十八。","因知君武以作唐初人爲是。","逯欽立編《先秦漢魏晉南北朝詩》未收此詩。","）。"]', '["椒塗香氣溢，芝封璽文生。","色逐梨陽紫，名隨蜀道清。","一丸封漢塞，數斗濁秦涇。","不分（一作「晓」）高楼妾，特況別離情。","（见《十万卷楼叢书》本皎然《诗式》卷三。","參《四友斋叢说》卷二十四。","）（按：《诗式》收此诗置隋人间。","今考《新唐书》卷七二《宰相世系表》二趙郡李氏东祖房有「君武，蔚州司马」。","其從伯孝端，爲隋獲嘉丞。","其子思貞，文明元年自婺州刺史改越州刺史，见《會稽掇英總集》卷十八。","因知君武以作唐初人爲是。","逯欽立編《先秦漢魏晉南北朝诗》未收此诗。","）。"]', '诗', 'shi', '', NULL, '詠泥 李君武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad887360-08eb-4a78-9baf-ec3a0f4fd5fa', '戲賈元遜', '戲賈元遜', '35dab1aa-ee87-469a-9311-32bec6dc83fb', '唐', '["千具羖䍽皮，唯裁一量靺。","（見《歷代笑話集》所收開元十二年敦煌寫本侯白《啓顏錄》）。"]', '["千具羖䍽皮，唯裁一量靺。","（见《歷代笑話集》所收开元十二年敦煌寫本侯白《啓顏錄》）。"]', '诗', 'shi', '', NULL, '戲賈元遜 王威德 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac638f8-30d5-4109-91a8-74a01e3bd02f', '戲王威德', '戲王威德', '7d8c2f9d-48e8-433a-b761-1eed6d993e37', '唐', '["千丈黃楊木，空爲一個梳。","（同前）（〖1〗《啓顏錄》云：「國初，賈元遜、王威德俱有辯捷，舊不相識，先各知名，無因相見。","元遜髭鬚甚多，威德鼻極長大。","嘗有一人置酒喚客，兼喚此二人。","此二人在座，各問知姓名，然始相識。","座上諸客及主人即請此二人言戲。","威德即先云〖略〗。","諸人問云：『餘皮既多，擬作何用？","』威德曰：『擬作元遜頰。","』元遜即應聲云〖略〗。","諸人又問云：『餘木擬作何用？","』元遜答云：『擬作威德枇子。","』四座莫不大笑。","」按：前人多以侯白爲隋人，然王利器先生將六本《啓顏錄》彙爲一帙，其中載白在唐時事甚衆。","此條所云「國初」，當指唐初。","另《新唐書》卷七五《宰相世系表》五有殿中丞賈元遜，爲中唐人，與此處所云者無涉。","）。"]', '["千丈黄楊木，空爲一個梳。","（同前）（〖1〗《啓顏錄》云：「国初，賈元遜、王威德俱有辯捷，旧不相識，先各知名，無因相见。","元遜髭鬚甚多，威德鼻極长大。","嘗有一人置酒喚客，兼喚此二人。","此二人在座，各问知姓名，然始相識。","座上諸客及主人即請此二人言戲。","威德即先云〖略〗。","諸人问云：『餘皮既多，擬作何用？","』威德曰：『擬作元遜頰。","』元遜即應声云〖略〗。","諸人又问云：『餘木擬作何用？","』元遜答云：『擬作威德枇子。","』四座莫不大笑。","」按：前人多以侯白爲隋人，然王利器先生將六本《啓顏錄》彙爲一帙，其中載白在唐时事甚衆。","此條所云「国初」，當指唐初。","另《新唐书》卷七五《宰相世系表》五有殿中丞賈元遜，爲中唐人，與此处所云者無涉。","）。"]', '诗', 'shi', '', NULL, '戲王威德 賈元遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18877209-2ceb-4e2d-8d77-336b33d80e6a', '詩', '诗', '23e547c7-655b-4784-a090-cc53adce28a0', '唐', '["惟憐一派溫泉水，不逐人心冷暖移。","（《記纂淵海》卷一○○）。"]', '["惟怜一派溫泉水，不逐人心冷暖移。","（《記纂淵海》卷一○○）。"]', '诗', 'shi', '', NULL, '詩 杜正倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01c31de-fc72-48df-b245-d63868ee88c7', '詩', '诗', '9279b662-55f1-4073-b80c-5bea08dc5827', '唐', '["昨望巫山峽，流淚滿征衣。","今赴長安道，含笑逐春歸。","（《陝兩金石志》卷六五《唐故魏州昌樂縣令孫君〖義普〗墓誌銘》引）（按：孫義普卒於高宗上元二年，年九十三。","墓誌謂其臨終前恒詠薛開府此詩，知薛應爲高宗前人。","一說即隋道衡。","）。"]', '["昨望巫山峽，流泪满征衣。","今赴长安道，含笑逐春归。","（《陝兩金石志》卷六五《唐故魏州昌乐縣令孫君〖義普〗墓誌銘》引）（按：孫義普卒於高宗上元二年，年九十三。","墓誌謂其臨終前恒詠薛开府此诗，知薛應爲高宗前人。","一说即隋道衡。","）。"]', '诗', 'shi', '', NULL, '詩 薛開府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709b623a-bee9-4222-86a4-f40cfc1ac2c4', '五言奉和咏棋應詔 一', '五言奉和咏棋應詔 一', '6082b8ab-9dea-4cab-aa87-de37b358f671', '唐', '["一枰位纔設，兩敵智俱申。","勢危翻効古，行[險]乍爲新。","稱征非禦寇，言劫詎侵人。","欲知情慮審，鴻雁不留神。"]', '["一枰位纔設，兩敵智俱申。","勢危翻効古，行[險]乍爲新。","稱征非禦寇，言劫詎侵人。","欲知情慮審，鴻雁不留神。"]', '诗', 'shi', '', NULL, '五言奉和咏棋應詔 一 劉子翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c275cff1-5263-44ec-8580-96eaddb99b2c', '五言奉和咏棋應詔 二', '五言奉和咏棋應詔 二', '6082b8ab-9dea-4cab-aa87-de37b358f671', '唐', '["鋭心爭決勝，運功□圖全。","眼均須執後，氣等欲乘先。","引行遙下雁，徇地遠侵邊。","借問逢仙日，[何]如偶聖年？","（《翰林學士集》）（按：此詩原署「承議郎守著作郎弘文館學士劉子翼上」。","張步雲《唐代逸詩輯存》收入。","）。"]', '["鋭心爭決勝，運功□圖全。","眼均須執後，氣等欲乘先。","引行遙下雁，徇地远侵邊。","借问逢仙日，[何]如偶聖年？","（《翰林学士集》）（按：此诗原署「承議郎守著作郎弘文館学士劉子翼上」。","張步云《唐代逸诗輯存》收入。","）。"]', '诗', 'shi', '', NULL, '五言奉和咏棋應詔 二 劉子翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('800875e0-518e-4f4c-bb36-f14b99cdc66f', '四言曲池酺飲座銘', '四言曲池酺饮座銘', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["和風習習，落景沉沉。","俯映綠水，仰睎翠林。","友朋好合，如□瑟琴。","勉矣君子，俱奉堯心。","（《翰林學士集》）（按：此詩原署「酆王友張文琮」。","張步雲《唐代逸詩輯存》收入。","）。"]', '["和风習習，落景沉沉。","俯映綠水，仰睎翠林。","友朋好合，如□瑟琴。","勉矣君子，俱奉堯心。","（《翰林学士集》）（按：此诗原署「酆王友張文琮」。","張步云《唐代逸诗輯存》收入。","）。"]', '诗', 'shi', '', NULL, '四言曲池酺飲座銘 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45983bc1-efb3-4dd1-ac03-33eb1b4cf61e', '四言曲池酺飲座銘', '四言曲池酺饮座銘', 'cc51ec54-349f-4007-8b2b-e8fff7216737', '唐', '["公侯盛集，酺醼梁園。","鸎多谷響，樹密花繁。","波流東逝，落照西奔。","人生行樂，此外何論。","（《翰林學士集》）（按：此詩原署「燕王友張後胤」。","張步雲《唐代逸詩輯存》收入。","）。"]', '["公侯盛集，酺醼梁园。","鸎多谷响，樹密花繁。","波流东逝，落照西奔。","人生行乐，此外何論。","（《翰林学士集》）（按：此诗原署「燕王友張後胤」。","張步云《唐代逸诗輯存》收入。","）。"]', '诗', 'shi', '', NULL, '四言曲池酺飲座銘 張後胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35b8cbee-0331-491d-a342-7ef1f2716473', '五言[儀鸞殿]早秋侍宴應詔', '五言[儀鸾殿]早秋侍宴應詔', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["金飆扇徂暑，玉露下層臺。","接綬芳筵合，臨池紫殿開。","日斜林影去，風度荷香來。","既承百吳味酒，願上萬年杯。","（《翰林學士集》）（按：此詩原署：「司空趙國公臣長孫無忌上。","」）。"]', '["金飆扇徂暑，玉露下層台。","接綬芳筵合，臨池紫殿开。","日斜林影去，风度荷香来。","既承百吳味酒，願上万年杯。","（《翰林学士集》）（按：此诗原署：「司空趙国公臣长孫無忌上。","」）。"]', '诗', 'shi', '', NULL, '五言[儀鸞殿]早秋侍宴應詔 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2cd2eca-b16c-4449-84d6-707dc28355e3', '五言春日侍宴望海應詔', '五言春日侍宴望海應詔', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["靈夔振窮髮，淑景麗青陽。","千乘隱雷轉，萬騎儼騰驤。","目極三山嶮，流睇百川長。","仙湖遙藹藹，蜃氣遠蒼蒼。","下物深逾廣，引濁清詎傷。","帶霧含天碧，浮霞映日光。","樓臺自接影，雲島間相望。","春波飛碣石，曉浪拂扶桑。","喧聲騁遊□，旅浴恣翾翔。","羣鷗心久狎，如何□稻粱？","（同前）。"]', '["靈夔振窮髮，淑景丽青陽。","千乘隐雷轉，万騎儼腾驤。","目極三山嶮，流睇百川长。","仙湖遙藹藹，蜃氣远蒼蒼。","下物深逾廣，引濁清詎傷。","带霧含天碧，浮霞映日光。","楼台自接影，云島间相望。","春波飞碣石，晓浪拂扶桑。","喧声騁游□，旅浴恣翾翔。","羣鷗心久狎，如何□稻粱？","（同前）。"]', '诗', 'shi', '', NULL, '五言春日侍宴望海應詔 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce75491-eb40-40c5-b0f6-35a449fbe438', '五言奉和行經破薛舉戰地應詔', '五言奉和行經破薛舉戰地應詔', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["天步昔未平，隴上駐神兵。","戈迴曦御轉，弓滿桂輪明。","屏塵安地軸，卷霧靜乾扃。","往振雷霆氣，今垂雨露情。","高垣起新邑，長楊布故營。","山川澄素景，林薄動秋聲。","風野征翼駃，霜渚寒流清。","朝煙澹雲䍐，夕吹繞霓旌。","鳴鑾出雁塞，疊鼓入龍城。","方陪東覲禮，奉璧侍雲亭。","（同前）。"]', '["天步昔未平，隴上駐神兵。","戈迴曦御轉，弓满桂輪明。","屏塵安地軸，卷霧静乾扃。","往振雷霆氣，今垂雨露情。","高垣起新邑，长楊布故營。","山川澄素景，林薄动秋声。","风野征翼駃，霜渚寒流清。","朝煙澹云䍐，夕吹繞霓旌。","鳴鑾出雁塞，叠鼓入龙城。","方陪东覲禮，奉璧侍云亭。","（同前）。"]', '诗', 'shi', '', NULL, '五言奉和行經破薛舉戰地應詔 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a557b4-009d-471e-b3ff-f5482830b846', '五言侍宴延慶殿同賦別題得寒桂叢應詔', '五言侍宴延慶殿同賦別題得寒桂叢應詔', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["根連八樹裏，枝拂九華端。","風急小山外，葉下大江干。","霜中花轉馥，露上色逾丹。","自負凌{夊/羊}性，巖幽待歲寒。","（同前）（按：以上三首皆署「司徒趙國公臣長孫無忌上」。","以上四首，張步雲《唐代逸詩輯存》收入。","）。"]', '["根連八樹裏，枝拂九华端。","风急小山外，葉下大江干。","霜中花轉馥，露上色逾丹。","自負凌{夊/羊}性，巖幽待歲寒。","（同前）（按：以上三首皆署「司徒趙国公臣长孫無忌上」。","以上四首，張步云《唐代逸诗輯存》收入。","）。"]', '诗', 'shi', '', NULL, '五言侍宴延慶殿同賦別題得寒桂叢應詔 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0937146f-8fbb-4491-bbf7-0beb4aaee033', '晚景遊泛懷友詩', '晚景游泛懷友诗', '9385c40c-bf3e-4774-bf65-6251f6057d4f', '唐', '["龍門（丁誤作「開」）依御溝，鳳轄轉芳洲。","雲峰初辨（《御覽》作「辯」）夏，麥氣早迎秋。","山翠餘煙積，川平晚照收。","浪隨文鷁轉，渡（《御覽》作「波」）逐彩鴛浮。","風花輕未落（《御覽》作「洛」），巖泉咽不流。","一辭金谷苑，空想（丁注：「一作思」）竹林遊。","（見《初學記》卷十八，以《太平御覽》卷四一○、丁福保輯《全梁詩》卷十參校。","）（按：《初學記》收此詩，題爲「梁蕭鈞」，《御覽》則僅云「蕭鈞」，不注朝代。","丁福保輯入《全梁詩》，然作者小傳則採《南齊書》卷四五齊太祖十一子鈞傳，另注云：「按《唐書》亦有蕭鈞，蕭瑀從子也，仕至太子率更令。","」又於詩題下注：「此詩類唐人作，當爲唐蕭鈞也。","《初學記》作梁。","」其說是。","南齊之蕭鈞，於海陵初立未久即遇害，未入梁，不得稱梁人。","此其一。","齊梁之際，南北分割，南人除了出使或奔降，無緣入洛。","此詩明言龍門御溝，非南朝人所作甚明。","南齊蕭鈞自十餘歲領江州刺史，至二十二歲遇害，皆在江南，仕歷甚明，無入洛事。","此其二。","唐之蕭鈞，其曾祖蕭詧爲後梁宣帝，祖巋爲後梁明帝，父珣入隋復封梁國公，恐徐堅等即因此而誤署其爲梁人。","此其三。","唐史稱鈞「博學有才望」，屢爲舍人、學士，其集三十卷，開元《古今書錄》收入。","其身份、經歷均與詩合，徐堅亦得以採擷。","此其四。","綜以上諸證，故收入。","今人逯欽立編《先秦漢魏晉南北朝詩》不收此篇，甚是。","）。"]', '["龙门（丁誤作「开」）依御溝，鳳轄轉芳洲。","云峰初辨（《御覽》作「辯」）夏，麦氣早迎秋。","山翠餘煙積，川平晚照收。","浪隨文鷁轉，渡（《御覽》作「波」）逐彩鴛浮。","风花轻未落（《御覽》作「洛」），巖泉咽不流。","一辞金谷苑，空想（丁注：「一作思」）竹林游。","（见《初学記》卷十八，以《太平御覽》卷四一○、丁福保輯《全梁诗》卷十參校。","）（按：《初学記》收此诗，題爲「梁蕭鈞」，《御覽》則僅云「蕭鈞」，不注朝代。","丁福保輯入《全梁诗》，然作者小傳則採《南齊书》卷四五齊太祖十一子鈞傳，另注云：「按《唐书》亦有蕭鈞，蕭瑀從子也，仕至太子率更令。","」又於诗題下注：「此诗類唐人作，當爲唐蕭鈞也。","《初学記》作梁。","」其说是。","南齊之蕭鈞，於海陵初立未久即遇害，未入梁，不得稱梁人。","此其一。","齊梁之際，南北分割，南人除了出使或奔降，無緣入洛。","此诗明言龙门御溝，非南朝人所作甚明。","南齊蕭鈞自十餘歲領江州刺史，至二十二歲遇害，皆在江南，仕歷甚明，無入洛事。","此其二。","唐之蕭鈞，其曾祖蕭詧爲後梁宣帝，祖巋爲後梁明帝，父珣入隋复封梁国公，恐徐堅等即因此而誤署其爲梁人。","此其三。","唐史稱鈞「博学有才望」，屢爲舍人、学士，其集三十卷，开元《古今书錄》收入。","其身份、經歷均與诗合，徐堅亦得以採擷。","此其四。","綜以上諸證，故收入。","今人逯欽立編《先秦漢魏晉南北朝诗》不收此篇，甚是。","）。"]', '诗', 'shi', '', NULL, '晚景遊泛懷友詩 蕭鈞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eabcc34-e8a2-42c0-8d62-5ca1aacbd955', '嘲道士李榮（題擬）', '嘲道士李榮（題擬）', 'b0364566-63b0-4ece-98b0-1999316623de', '唐', '["李榮烏黮，何異蛣蜣。","先師米賊，汝亦不良。","（見《大正新修大藏經》第五十二冊釋道宣撰《集古今佛道論衡》卷丁）（按：此詩爲顯慶五年八月二人辯論時作。","文長不錄。","）。"]', '["李榮烏黮，何異蛣蜣。","先師米賊，汝亦不良。","（见《大正新修大藏經》第五十二冊釋道宣撰《集古今佛道論衡》卷丁）（按：此诗爲显慶五年八月二人辯論时作。","文长不錄。","）。"]', '诗', 'shi', '', NULL, '嘲道士李榮（題擬） 靜泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11875d00-759f-4036-bfc8-4c60796bd078', '嘲道士（題擬） 一', '嘲道士（題擬） 一', 'b3e2fe7c-c91f-4788-903f-077aead13172', '唐', '["般若非愚智，破愚歎爲智。","道士若亡愚，我智藥亦遺。"]', '["般若非愚智，破愚歎爲智。","道士若亡愚，我智藥亦遺。"]', '诗', 'shi', '', NULL, '嘲道士（題擬） 一 義褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5739fd9a-2877-4951-9dbb-39f7f9338934', '嘲道士（題擬） 二', '嘲道士（題擬） 二', 'b3e2fe7c-c91f-4788-903f-077aead13172', '唐', '["一彈彈黃雀，已射兩鵄鶚。","彈彈黃雀足，射射鵄鶚腰。"]', '["一彈彈黄雀，已射兩鵄鶚。","彈彈黄雀足，射射鵄鶚腰。"]', '诗', 'shi', '', NULL, '嘲道士（題擬） 二 義褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d78cd917-37b7-48eb-a81a-3a8f683e9509', '嘲道士（題擬） 三', '嘲道士（題擬） 三', 'b3e2fe7c-c91f-4788-903f-077aead13172', '唐', '["兩人助一人，三愚成一智。","昔聞今始見，斯言無有從（一作「有從記」）于時。","（同前）。"]', '["兩人助一人，三愚成一智。","昔闻今始见，斯言無有從（一作「有從記」）于时。","（同前）。"]', '诗', 'shi', '', NULL, '嘲道士（題擬） 三 義褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cdf94d3-f8ff-4f83-a330-c482d5a6c6d4', '嘲義褒（題擬）', '嘲義褒（題擬）', 'b0af6032-eace-4680-aa38-7df769572965', '唐', '["僧頭似彈丸，解義亦團欒。","（同前）。"]', '["僧头似彈丸，解義亦團欒。","（同前）。"]', '诗', 'shi', '', NULL, '嘲義褒（題擬） 李榮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a4d14dc-3f93-4288-b1c7-569609792149', '嘲洛邑僧靜泰（題擬）', '嘲洛邑僧静泰（題擬）', 'b0af6032-eace-4680-aa38-7df769572965', '唐', '["靜泰語，莫慞惶。","我未發，汝剩揚。","（同前）。"]', '["静泰語，莫慞惶。","我未發，汝剩揚。","（同前）。"]', '诗', 'shi', '', NULL, '嘲洛邑僧靜泰（題擬） 李榮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c1165fb-3aea-4b7d-98b4-59ab903fee19', '嘲道士李榮（題擬）', '嘲道士李榮（題擬）', '19f5dda1-81a0-4b75-95b9-0b5be74ab9ea', '唐', '["老子兩卷本未研尋，莊生七篇何曾披讀？頭戴死穀皮，欲似鈍啄木。"]', '["老子兩卷本未研尋，莊生七篇何曾披读？头戴死穀皮，欲似鈍啄木。"]', '诗', 'shi', '', NULL, '嘲道士李榮（題擬） 靈辯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65244d12-7e3f-4abd-835a-8308e9bdd43b', '榮未及對又嘲', '榮未及对又嘲', '19f5dda1-81a0-4b75-95b9-0b5be74ab9ea', '唐', '["聞君來蜀道，蜀道信爲難。","何不乘鳧遊帝里，翻被枷項入長安。","（勑追榮入京日著枷）。"]', '["闻君来蜀道，蜀道信爲难。","何不乘鳧游帝里，翻被枷項入长安。","（勑追榮入京日著枷）。"]', '诗', 'shi', '', NULL, '榮未及對又嘲 靈辯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c105bf20-25da-497a-ae9e-7ab38d850d75', '又嘲', '又嘲', '19f5dda1-81a0-4b75-95b9-0b5be74ab9ea', '唐', '["槁木猶應重，死灰方未然。","既逢田甲尿，仍遭酷吏懸。"]', '["槁木猶應重，死灰方未然。","既逢田甲尿，仍遭酷吏懸。"]', '诗', 'shi', '', NULL, '又嘲 靈辯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f010e610-2b98-43fc-abde-ce7dd5718bba', '又嘲', '又嘲', '19f5dda1-81a0-4b75-95b9-0b5be74ab9ea', '唐', '["柱枷異支策（一作「榮」），擎枷非椐（一作「据」）梧。","閉口臨枷柄，真似濫吹竽。"]', '["柱枷異支策（一作「榮」），擎枷非椐（一作「据」）梧。","閉口臨枷柄，真似濫吹竽。"]', '诗', 'shi', '', NULL, '又嘲 靈辯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c63993f-d103-4863-bd70-6cb228754c22', '又嘲', '又嘲', '19f5dda1-81a0-4b75-95b9-0b5be74ab9ea', '唐', '["區區蜀地老，竊號道門英。"]', '["區區蜀地老，竊號道门英。"]', '诗', 'shi', '', NULL, '又嘲 靈辯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8fd37c1-3bd6-4c03-b54b-73ef38447560', '又嘲', '又嘲', '19f5dda1-81a0-4b75-95b9-0b5be74ab9ea', '唐', '["衆僧本來齋潔，故當飡飯進蔬。","道士唯當醮祭，應須酌醴焚魚。","。"]', '["衆僧本来斋潔，故當飡飯進蔬。","道士唯當醮祭，應須酌醴焚鱼。","。"]', '诗', 'shi', '', NULL, '又嘲 靈辯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39cb8328-b5c6-49fe-8d88-950e3e711308', '又嘲', '又嘲', '19f5dda1-81a0-4b75-95b9-0b5be74ab9ea', '唐', '["道士當諦聽，沙門贈子言：鴻鶴（疑應作鵠）已高逝，燕雀徒自喧。","（均見《集古今佛道論衡》卷丁）（按：以上七首均龍朔三年與李榮辯論時作。","）。"]', '["道士當諦听，沙门贈子言：鴻鹤（疑應作鵠）已高逝，燕雀徒自喧。","（均见《集古今佛道論衡》卷丁）（按：以上七首均龙朔三年與李榮辯論时作。","）。"]', '诗', 'shi', '', NULL, '又嘲 靈辯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7f4249e-353c-4ea0-9e4c-f268e1fb1aa7', '五言遼東侍宴山夜臨秋同賦臨韻應詔', '五言遼东侍宴山夜臨秋同賦臨韻應詔', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["奉駕凌稽阜，同御掩□岑。","肆賞乖濡足，窮覽{忄口}（疑爲「惕」字）乾心。","一德光神武，萬象鏡冲襟。","御□遼山夕，凝麾溟海潯。","帷殿（《初》作「殿帳」）清炎氣，輦道含秋陰。","凄風移漢筑，流水入虞琴。","雲飛送斷鴈，月上淨疎林。","滴瀝露枝響，空濛煙壑深。","撫躬謝仁智，泉石忝登臨。","信美陪仙蹕，長歌[慰]（尉）陸沉。","（見影日本藏唐卷子本《翰林學士集》，以《初學記》卷三引詩參校。","）（按：《全唐詩》卷四十據《初學記》、《唐詩紀事》收入本詩，僅存「殿帳清炎氣」以下八句。","卷子本詩題下署：「秘書郎弘文館直學士臣上官儀上。","」）。"]', '["奉駕凌稽阜，同御掩□岑。","肆賞乖濡足，窮覽{忄口}（疑爲「惕」字）乾心。","一德光神武，万象镜冲襟。","御□遼山夕，凝麾溟海潯。","帷殿（《初》作「殿帳」）清炎氣，輦道含秋陰。","凄风移漢筑，流水入虞琴。","云飞送斷鴈，月上淨疎林。","滴瀝露枝响，空濛煙壑深。","撫躬謝仁智，泉石忝登臨。","信美陪仙蹕，长歌[慰]（尉）陸沉。","（见影日本藏唐卷子本《翰林学士集》，以《初学記》卷三引诗參校。","）（按：《全唐诗》卷四十據《初学記》、《唐诗紀事》收入本诗，僅存「殿帳清炎氣」以下八句。","卷子本诗題下署：「秘书郎弘文館直学士臣上官儀上。","」）。"]', '诗', 'shi', '', NULL, '五言遼東侍宴山夜臨秋同賦臨韻應詔 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22bddfd9-33b7-486d-b4a2-f854c44a4e3a', '五言奉和咏棋應詔 一', '五言奉和咏棋應詔 一', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["寶局光仙岫，瑤棋掩帝臺。","圖雲雙陣起，鴈寫兩行開。","固節修常道，侵邊慎禍胎。","□□□儲妙，空挹季長才。"]', '["寶局光仙岫，瑤棋掩帝台。","圖云雙陣起，鴈寫兩行开。","固節修常道，侵邊慎禍胎。","□□□儲妙，空挹季长才。"]', '诗', 'shi', '', NULL, '五言奉和咏棋應詔 一 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae00a7d2-92a3-491e-9f6d-6be2f38fe9ae', '五言奉和咏棋應詔 二', '五言奉和咏棋應詔 二', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["定位資裨將，制變佇中權。","重關□宿竝，六出帶花圓。","引寇疎疑絕，窺彊怯未前。","金枰自韞粹，玉帳豈能傳。","（同前）（按：此二詩題下署：「起居郎弘文館直學士臣□□□上。","」姓名處適殘缺。","《文學遺產》一九八三年第二期刊張步雲同志《唐代逸詩輯存》收作缺名詩。","今考定應爲上官儀作。","《舊唐書》卷八十《上官儀傳》云：「舉進士。","太宗聞其名，召授弘文館直學士，累遷秘書郎。","時太宗雅好屬文，每遣儀視草，又多令繼和，凡有宴集，儀嘗預焉。","俄又預撰《晉書》成，轉起居郎，加級賜帛。","」前詩署儀官爲「秘書郎弘文館直學士」，此作「起居郎弘文館直學士」，正與本傳相合。","《晉書》撰成於貞觀二十年，太宗幸遼東則爲前一年事，時序亦合。","二詩可確定爲儀作。","）。"]', '["定位資裨將，制变佇中權。","重关□宿竝，六出带花圓。","引寇疎疑絕，窺彊怯未前。","金枰自韞粹，玉帳豈能傳。","（同前）（按：此二诗題下署：「起居郎弘文館直学士臣□□□上。","」姓名处適殘缺。","《文学遺產》一九八三年第二期刊張步云同志《唐代逸诗輯存》收作缺名诗。","今考定應爲上官儀作。","《旧唐书》卷八十《上官儀傳》云：「舉進士。","太宗闻其名，召授弘文館直学士，累遷秘书郎。","时太宗雅好屬文，每遣儀視草，又多令繼和，凡有宴集，儀嘗預焉。","俄又預撰《晉书》成，轉起居郎，加級賜帛。","」前诗署儀官爲「秘书郎弘文館直学士」，此作「起居郎弘文館直学士」，正與本傳相合。","《晉书》撰成於貞观二十年，太宗幸遼东則爲前一年事，时序亦合。","二诗可確定爲儀作。","）。"]', '诗', 'shi', '', NULL, '五言奉和咏棋應詔 二 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8d0864-44e4-4dc0-a724-c7427fe29972', '五言春日侍宴望海應詔', '五言春日侍宴望海應詔', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["青丘橫日域，碧海貫乾綱。","奇怪儲神府，朝宗擅穀王。","靈官耀三嶽，仙槎泛□□。","蜃樓朝氣上，鷄樹早花芳。","別島春潮駃，連汀宿霧長。","驚湍蕩雲色，沓浪倒霞光。","宸行肅遼隧，降望臨歸塘。","夾林朱鷺澈，分空翠鳳翔。","憑深體嬀后，徒御叶周王。","游聖霑玄澤，詎假濯滄浪。","（同前）。"]', '["青丘橫日域，碧海貫乾綱。","奇怪儲神府，朝宗擅穀王。","靈官耀三嶽，仙槎泛□□。","蜃楼朝氣上，鷄樹早花芳。","別島春潮駃，連汀宿霧长。","驚湍蕩云色，沓浪倒霞光。","宸行肅遼隧，降望臨归塘。","夾林朱鷺澈，分空翠鳳翔。","憑深體嬀后，徒御叶周王。","游聖霑玄澤，詎假濯滄浪。","（同前）。"]', '诗', 'shi', '', NULL, '五言春日侍宴望海應詔 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b01e242-825e-45b3-96ea-22ca97fd02ae', '五言奉和行經破薛舉戰地應詔', '五言奉和行經破薛舉戰地應詔', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["策星暎霄極，飛鴻浹地區。","鮪水騰周駕，涿鹿驚軒弧。","榮河開秘篆，柳谷薦靈符。","天遊御長策，侮食被來蘇。","秋原懷八陣，武校燭三駈。","投石堙舊壘，削樹委荒途。","□野驚[宵]（霄）燐，頹墉噪晚烏。","毒涇晦凉雨，塞井蔽荒蕪。","冲情朗金鏡，睿藻邃玄珠。","□恩奉御什，撫己濫齊竽。","（同前）。"]', '["策星暎霄極，飞鴻浹地區。","鮪水腾周駕，涿鹿驚軒弧。","榮河开秘篆，柳谷薦靈符。","天游御长策，侮食被来蘇。","秋原懷八陣，武校燭三駈。","投石堙旧壘，削樹委荒途。","□野驚[宵]（霄）燐，頹墉噪晚烏。","毒涇晦凉雨，塞井蔽荒蕪。","冲情朗金镜，睿藻邃玄珠。","□恩奉御什，撫己濫齊竽。","（同前）。"]', '诗', 'shi', '', NULL, '五言奉和行經破薛舉戰地應詔 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd495820-7f0c-4e84-afce-97b3c80fa325', '五言侍宴延慶殿同賦別離得凌霜雁應詔', '五言侍宴延慶殿同賦別離得凌霜雁應詔', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["涼沙起關塞，候雁下江干。","流聲度迥月，浮影入長瀾。","繫書天路遠，避繳曉風寒。","□□□□曲，先驚霜翮殘。","（同前）（按：以上三詩皆署「秘書郎弘文館直學士臣上官儀上」。","張步雲《唐代逸詩輯存》收以上三詩。","）。"]', '["涼沙起关塞，候雁下江干。","流声度迥月，浮影入长瀾。","繫书天路远，避繳晓风寒。","□□□□曲，先驚霜翮殘。","（同前）（按：以上三诗皆署「秘书郎弘文館直学士臣上官儀上」。","張步云《唐代逸诗輯存》收以上三诗。","）。"]', '诗', 'shi', '', NULL, '五言侍宴延慶殿同賦別離得凌霜雁應詔 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8257482d-574f-49dc-9990-caf62d50dad1', '假作屏風詩', '假作屏风诗', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["綠葉霜中夏，紅花雪裏春。","去馬不移迹（《詩格》作「足」），來車豈動輪（《詩格》作「塵」）。","（此首爲直言志）。"]', '["綠葉霜中夏，紅花雪裏春。","去马不移迹（《诗格》作「足」），来车豈动輪（《诗格》作「塵」）。","（此首爲直言志）。"]', '诗', 'shi', '', NULL, '假作屏風詩 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d7f0f9c-2356-40f9-91d2-88bf92786772', '假作贈別詩', '假作贈別诗', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["離情絃上急（《詩格》作「怨」），別曲雁邊嘶。","低雲百種（一作「千過」）鬱，垂露幾（一作「千」）行啼。","（此詩爲比附志）。"]', '["離情絃上急（《诗格》作「怨」），別曲雁邊嘶。","低云百種（一作「千過」）鬱，垂露幾（一作「千」）行啼。","（此诗爲比附志）。"]', '诗', 'shi', '', NULL, '假作贈別詩 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b989ab2-7d1f-4c4f-969d-36de17b50b19', '假作幽蘭詩', '假作幽蘭诗', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["日月雖不照，馨香（一作「多」）要自豐。","有怨生幽地，無由（《詩格》作「情」）逐遠風。","（此首爲寄懷志）。"]', '["日月雖不照，馨香（一作「多」）要自豐。","有怨生幽地，無由（《诗格》作「情」）逐远风。","（此首爲寄懷志）。"]', '诗', 'shi', '', NULL, '假作幽蘭詩 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1c8e96-4a0c-4977-aa3c-c6214a02f708', '假作賦得魯司寇詩', '假作賦得魯司寇诗', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["隱見通榮辱，行藏備卷舒。","避席談曾子，趨庭誨伯魚。","（此首爲起賦志）。"]', '["隐见通榮辱，行藏備卷舒。","避席談曾子，趨庭誨伯鱼。","（此首爲起賦志）。"]', '诗', 'shi', '', NULL, '假作賦得魯司寇詩 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f1b3ccc-6c6d-4d9d-a1cf-96c0f3d9671b', '假作田家詩', '假作田家诗', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["有意嫌千石，無心羨九卿。","且悅丘園好（《詩格》作「死」），何論冠蓋生（《詩格》作「未甘冠蓋榮」）。","（此首爲貶毀志）。"]', '["有意嫌千石，無心羨九卿。","且悅丘园好（《诗格》作「死」），何論冠蓋生（《诗格》作「未甘冠蓋榮」）。","（此首爲貶毀志）。"]', '诗', 'shi', '', NULL, '假作田家詩 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e036ae86-9ecb-4c00-a830-edb887e53673', '假作美人詩', '假作美人诗', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["宋臘何須說，虞姬未足談。","頰態花翻愧，眉成月倒懸（《詩格》作「妝罷花更醜，眉成月對愁」。","此首爲讚譽志。","以上六首皆見《文鏡秘府論》地卷《六志》引上官儀《筆札華梁》。","《吟窗雜錄》卷一引託名魏文帝《詩格》每首各引二句。","）（按：《文鏡秘府論》原注「《筆札》略同」，《筆札》即指《筆札華梁》。","王夢鷗《唐初詩學著述考》考證僞題魏文帝《詩格》，實即《筆札華梁》之刪節本，又謂「其『假作某詩』云云，其詩疑即上官儀詩」。","王利器《文鏡秘府論校注》云：「蓋無適例，故爾假作也。","」今據以收歸上官儀名下。","）。"]', '["宋臘何須说，虞姬未足談。","頰態花翻愧，眉成月倒懸（《诗格》作「妝罷花更醜，眉成月对愁」。","此首爲讚譽志。","以上六首皆见《文镜秘府論》地卷《六志》引上官儀《笔札华梁》。","《吟窗杂錄》卷一引託名魏文帝《诗格》每首各引二句。","）（按：《文镜秘府論》原注「《笔札》略同」，《笔札》即指《笔札华梁》。","王梦鷗《唐初诗学著述考》考證僞題魏文帝《诗格》，實即《笔札华梁》之刪節本，又謂「其『假作某诗』云云，其诗疑即上官儀诗」。","王利器《文镜秘府論校注》云：「蓋無適例，故爾假作也。","」今據以收归上官儀名下。","）。"]', '诗', 'shi', '', NULL, '假作美人詩 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc3be617-0ade-408a-bb87-087020701e42', '四言曲池酺飲座銘', '四言曲池酺饮座銘', 'ff0f5f00-c510-47f7-b483-b689de401fa9', '唐', '["涇抽冠箏，源開綬花。","水隨灣曲，樹逐風斜。","始攀幽桂，更折疎麻。","再歡難遇，聊賞山家。","（《翰林學士集》）（按：此詩原署「兵部侍郎于志寧」。","張步雲《唐代逸詩輯存》收錄本詩。","）。"]', '["涇抽冠箏，源开綬花。","水隨灣曲，樹逐风斜。","始攀幽桂，更折疎麻。","再歡难遇，聊賞山家。","（《翰林学士集》）（按：此诗原署「兵部侍郎于志寧」。","張步云《唐代逸诗輯存》收錄本诗。","）。"]', '诗', 'shi', '', NULL, '四言曲池酺飲座銘 于志寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d81bb1e8-b727-458f-900f-002bb3cc586c', '題西天捨眼塔（在西天）', '題西天捨眼塔（在西天）', '9d131733-93ab-4a39-8bed-ee20848793a0', '唐', '["帝釋傾心崇二塔，爲憐捨眼滿千生。","不因行苦過人表，豈得光流法界明。"]', '["帝釋傾心崇二塔，爲怜捨眼满千生。","不因行苦過人表，豈得光流法界明。"]', '诗', 'shi', '', NULL, '題西天捨眼塔（在西天） 玄奘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca5e023-59ef-41e4-95ca-a7e81ad63912', '題尼蓮河七言', '題尼蓮河七言', '9d131733-93ab-4a39-8bed-ee20848793a0', '唐', '["尼蓮河水正東流，曾浴金人體得柔。","自此更誰登彼岸，西看佛樹幾千秋。","（按：《大唐西域記》卷八《伽耶城與伽耶山》云：「戒賢伽藍西南行四五十里，渡尼連禪河。","」）。"]', '["尼蓮河水正东流，曾浴金人體得柔。","自此更誰登彼岸，西看佛樹幾千秋。","（按：《大唐西域記》卷八《伽耶城與伽耶山》云：「戒賢伽藍西南行四五十里，渡尼連禪河。","」）。"]', '诗', 'shi', '', NULL, '題尼蓮河七言 玄奘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a875877a-233e-446c-bac5-4ab4a643fa59', '題半偈捨身山（在西天）', '題半偈捨身山（在西天）', '9d131733-93ab-4a39-8bed-ee20848793a0', '唐', '["忽聞八字超詩境，不借丹軀捨此山。","偈句篇留方石上，樂音時奏半空間。","（按：《大唐西域記》卷三有《大石門及王子捨身飼虎處》條。","）。"]', '["忽闻八字超诗境，不借丹軀捨此山。","偈句篇留方石上，乐音时奏半空间。","（按：《大唐西域記》卷三有《大石门及王子捨身飼虎处》條。","）。"]', '诗', 'shi', '', NULL, '題半偈捨身山（在西天） 玄奘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8412db1d-9c4f-4533-8c35-287696be0e5f', '題童子寺五言（在太原□□北京）', '題童子寺五言（在太原□□北京）', '9d131733-93ab-4a39-8bed-ee20848793a0', '唐', '["西登童子寺，東望晉陽城。","金川千點淥，汾水一條清。"]', '["西登童子寺，东望晉陽城。","金川千点淥，汾水一條清。"]', '诗', 'shi', '', NULL, '題童子寺五言（在太原□□北京） 玄奘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('134d1d76-9427-477a-9fb0-7ffcdf98dfa0', '題中嶽山七言（在京南）', '題中嶽山七言（在京南）', '9d131733-93ab-4a39-8bed-ee20848793a0', '唐', '["孤峰絕頂萬餘嶒，策杖攀蘿漸漸登。","行到目邊天上寺，白雲相伴兩三僧。","（以上五首均見斯三七三卷）（按：《題西天捨眼塔》前署「大唐三藏」，應即指玄奘。","其前抄李存勗詩五首。","）。"]', '["孤峰絕頂万餘嶒，策杖攀蘿漸漸登。","行到目邊天上寺，白云相伴兩三僧。","（以上五首均见斯三七三卷）（按：《題西天捨眼塔》前署「大唐三藏」，應即指玄奘。","其前抄李存勗诗五首。","）。"]', '诗', 'shi', '', NULL, '題中嶽山七言（在京南） 玄奘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47c4d1bc-9daa-44cd-9d50-a426626b7375', '言離廣府還望桂林去留愴然自述贈懷云爾', '言離廣府還望桂林去留愴然自述贈懷云爾', '8c2adca1-9043-4a64-9516-b2829c582338', '唐', '["標心之梵宇，運想入仙洲。","嬰痼乖同好，沉情阻若抽。","葉落乍難聚，情離不可收。","何日乘杯至，詳觀演法流。","（錄自《大正新修大藏經》第五十一冊唐釋義淨撰《大唐西域求法高僧傳》卷下）（按：《全唐詩》卷八○八收此詩於義淨名下，實誤。","詳詩意及義淨所敍前後文意，此詩應爲玄逵作，義淨不過鈔錄入）（傳而已。","義淨另有傷玄逵二詩，亦見同書，《全唐詩》已收入。","《古今禪藻集》卷一收三詩皆歸玄逵，亦誤。","又日本《天理圖書館善本叢書》影印古寫本《大唐西域求法高僧傳》，「玄逵」皆寫作「玄達」。","未詳孰是，謹錄出備考。","）。"]', '["標心之梵宇，運想入仙洲。","嬰痼乖同好，沉情阻若抽。","葉落乍难聚，情離不可收。","何日乘杯至，詳观演法流。","（錄自《大正新修大藏經》第五十一冊唐釋義淨撰《大唐西域求法高僧傳》卷下）（按：《全唐诗》卷八○八收此诗於義淨名下，實誤。","詳诗意及義淨所敍前後文意，此诗應爲玄逵作，義淨不過鈔錄入）（傳而已。","義淨另有傷玄逵二诗，亦见同书，《全唐诗》已收入。","《古今禪藻集》卷一收三诗皆归玄逵，亦誤。","又日本《天理圖书館善本叢书》影印古寫本《大唐西域求法高僧傳》，「玄逵」皆寫作「玄達」。","未詳孰是，謹錄出備考。","）。"]', '诗', 'shi', '', NULL, '言離廣府還望桂林去留愴然自述贈懷云爾 玄逵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab7394e-7858-4d02-820d-1584977d6c0e', '因致酒歡會述志爲詩', '因致酒歡會述志爲诗', '5e63beb2-f939-4db7-8d94-36a6d86aa9c8', '唐', '["一乘本非有，三空何所歸？","幸得金門詔，行背玉毫暉。","未能齊物我，猶懷識是非。","賴爾同心契，知余志不違。","幕齊雲葉捲，酒度榴花飛。","寄語繩牀執，辭君匡坐威。","（見《卍續藏經》本唐釋懷信撰《釋門自鏡錄》卷中。","《續高僧傳》卷三五錄首二句）。"]', '["一乘本非有，三空何所归？","幸得金门詔，行背玉毫暉。","未能齊物我，猶懷識是非。","賴爾同心契，知余志不違。","幕齊云葉捲，酒度榴花飞。","寄語繩牀執，辞君匡坐威。","（见《卍續藏經》本唐釋懷信撰《釋门自镜錄》卷中。","《續高僧傳》卷三五錄首二句）。"]', '诗', 'shi', '', NULL, '因致酒歡會述志爲詩 明解 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c840f153-c23b-4636-bfe8-823bf59483e1', '賦城上烏勒歸飛二字（題擬）', '賦城上烏勒归飞二字（題擬）', '53be91b6-cf8d-4f58-96eb-936a00040d23', '唐', '["靈臺自可依，爰止竟何歸？祇由城上冷，故向日輪飛。","（見《襄陽冢墓遺文》收《唐將仕郎張君墓誌銘》引）。"]', '["靈台自可依，爰止竟何归？祇由城上冷，故向日輪飞。","（见《襄陽冢墓遺文》收《唐將仕郎張君墓誌銘》引）。"]', '诗', 'shi', '', NULL, '賦城上烏勒歸飛二字（題擬） 張敬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5bbdc66-74f7-4be4-a9cb-308d57e5e782', '四言奉陪皇太子釋奠詩一首應令 一', '四言奉陪皇太子釋奠诗一首應令 一', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["天鈞初播，流形硉分。","應圖作極，執契爲君。","經邦測景，命秩頒雲。","功弘海謐，□洽風薰。","（其一）。"]', '["天鈞初播，流形硉分。","應圖作極，執契爲君。","經邦測景，命秩頒云。","功弘海謐，□洽风薰。","（其一）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 一 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d9eced5-83c7-4991-b50a-d64a3d9c7524', '四言奉陪皇太子釋奠詩一首應令 二', '四言奉陪皇太子釋奠诗一首應令 二', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["彝典潛敷，至淳冥{郵阝=欠}。","六位斯辨，九疇爰設。","叔世時訛，滔天作孽。","雅誥咸蕩，微言殆絕。","（其二）。"]', '["彝典潛敷，至淳冥{郵阝=欠}。","六位斯辨，九疇爰設。","叔世时訛，滔天作孽。","雅誥咸蕩，微言殆絕。","（其二）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 二 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2437298a-106c-4191-98e5-480f9cd08dcd', '四言奉陪皇太子釋奠詩一首應令 三', '四言奉陪皇太子釋奠诗一首應令 三', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["皇靈拓統，帝宅遐光。","馳威日域，浹化乾綱。","網羅千代，並吞百王。","禎凝國太（疑應作「泰」），慶襲元良。","（其三）。"]', '["皇靈拓統，帝宅遐光。","驰威日域，浹化乾綱。","網羅千代，並吞百王。","禎凝国太（疑應作「泰」），慶襲元良。","（其三）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 三 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4d1c9a-6d07-4f18-9c2e-5f4adfc1b516', '四言奉陪皇太子釋奠詩一首應令 四', '四言奉陪皇太子釋奠诗一首應令 四', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["前星降彩，猗蘭挺秀。","少海揚清，若華騰茂。","仙簧妙響，長琴雅奏。","具體生知，尅昌宸[構]。","（其四）。"]', '["前星降彩，猗蘭挺秀。","少海揚清，若华腾茂。","仙簧妙响，长琴雅奏。","具體生知，尅昌宸[構]。","（其四）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 四 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e2673a9-a5a9-400e-8f8e-6207211ab423', '四言奉陪皇太子釋奠詩一首應令 五', '四言奉陪皇太子釋奠诗一首應令 五', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["天庭朗玉，睿掌暉珠。","問安昏定，奉禮晨趨。","照宣離景，幾亞神摳。","承綸太極，肄業鴻都。","（其五）。"]', '["天庭朗玉，睿掌暉珠。","问安昏定，奉禮晨趨。","照宣離景，幾亞神摳。","承綸太極，肄業鴻都。","（其五）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 五 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7856ad3e-7b20-4647-8d7a-4bb01aa77c08', '四言奉陪皇太子釋奠詩一首應令 六', '四言奉陪皇太子釋奠诗一首應令 六', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["望苑方春，震宮將旦。","吟笳順動，連旗遠煥。","冊府開扃，儒庠引泮。","迴輪馳道，增華甲觀。","（其六）。"]', '["望苑方春，震宮將旦。","吟笳順动，連旗远煥。","冊府开扃，儒庠引泮。","迴輪驰道，增华甲观。","（其六）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 六 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b008a0-4069-4d92-bae2-1850e48848c8', '四言奉陪皇太子釋奠詩一首應令 七', '四言奉陪皇太子釋奠诗一首應令 七', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["尊師上德，齒學崇年。","登歌暢美，啐爵思虔。","雩童鼓篋，碩老重筵。","辭雕辯囿，矢激言泉。","（其七）。"]', '["尊師上德，齒学崇年。","登歌暢美，啐爵思虔。","雩童鼓篋，碩老重筵。","辞雕辯囿，矢激言泉。","（其七）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 七 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d24c35d8-a288-4640-99d1-13d200f37fbf', '四言奉陪皇太子釋奠詩一首應令 八', '四言奉陪皇太子釋奠诗一首應令 八', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["九宮率職，六{聫大=心}（張步雲疑爲「聰」）咸事。","濟濟飛纓，昂昂踐位。","栝箭成德，瑑瑜爲器。","仰仞齊高，陞堂寫秘。","（其八）。"]', '["九宮率職，六{聫大=心}（張步云疑爲「聰」）咸事。","濟濟飞纓，昂昂踐位。","栝箭成德，瑑瑜爲器。","仰仞齊高，陞堂寫秘。","（其八）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 八 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d636df-6506-4fc0-b0bb-9cffe37ff2eb', '四言奉陪皇太子釋奠詩一首應令 九', '四言奉陪皇太子釋奠诗一首應令 九', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["初芳候律，新𠯴諧音。","罄喧浮泗，絃靜淄林。","珪{石|彐/止}炫目，璧水澄心。","蘂飄蹊靄，葉滿帷深。","（其九）。"]', '["初芳候律，新𠯴諧音。","罄喧浮泗，絃静淄林。","珪{石|彐/止}炫目，璧水澄心。","蘂飄蹊靄，葉满帷深。","（其九）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 九 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91050e53-f81b-4335-90f6-e94a22f0d2e3', '四言奉陪皇太子釋奠詩一首應令 十', '四言奉陪皇太子釋奠诗一首應令 十', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["縟禮光備，文思可紀。","日駟輪斜，雲門祝止。","景福垂裕，受釐延祉。","嚴訓一尊，澄湮萬汜。","（其十。","《翰林學士集》）（按：本詩原署：「銀青光祿大夫中書侍郎行太子右庶子弘文館學士高陽縣開國男臣許敬宗上。","」）。"]', '["縟禮光備，文思可紀。","日駟輪斜，云门祝止。","景福垂裕，受釐延祉。","嚴訓一尊，澄湮万汜。","（其十。","《翰林学士集》）（按：本诗原署：「銀青光祿大夫中书侍郎行太子右庶子弘文館学士高陽縣开国男臣許敬宗上。","」）。"]', '诗', 'shi', '', NULL, '四言奉陪皇太子釋奠詩一首應令 十 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62579a47-5d3a-45cb-a437-c90f4cb5be04', '四言曲池酺飲座銘', '四言曲池酺饮座銘', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["日月揚彩，爟烽撤候。","賜飲平郊，列筵春岫。","露鮮芳薄，影華清溜。","倒載言旋，驪歌貮奏。","（同前）（按：本詩原署：「給事中高陽縣開國男臣許敬宗上。","」）。"]', '["日月揚彩，爟烽撤候。","賜饮平郊，列筵春岫。","露鲜芳薄，影华清溜。","倒載言旋，驪歌貮奏。","（同前）（按：本诗原署：「給事中高陽縣开国男臣許敬宗上。","」）。"]', '诗', 'shi', '', NULL, '四言曲池酺飲座銘 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e53c214-4c96-4e32-949e-1ba931c77eb1', '五言遼東侍宴山夜臨秋同賦[臨]韻應詔', '五言遼东侍宴山夜臨秋同賦[臨]韻應詔', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["稽山騰禹計，姑射蕩堯心。","豈如臨碣石，軒衛警摐金。","轅門縈□水，大斾掩長岑。","復屬高秋夜，澄空素景臨。","層巖多麗色，幽澗有清音。","含星光淺瀨，褰霧靜疎林。","高明興睿賞，仁知輔冲襟。","湛露浮仙爵，凄風韻雅琴。","秋令生威遠，寒光被物深。","方懷草封禪，陪禮泰山陰。","（同前）（按：本詩原署：「太子右庶子高陽縣開國男弘文館學士臣許敬宗上。","」）。"]', '["稽山腾禹計，姑射蕩堯心。","豈如臨碣石，軒衛警摐金。","轅门縈□水，大斾掩长岑。","复屬高秋夜，澄空素景臨。","層巖多丽色，幽澗有清音。","含星光淺瀨，褰霧静疎林。","高明兴睿賞，仁知輔冲襟。","湛露浮仙爵，凄风韻雅琴。","秋令生威远，寒光被物深。","方懷草封禪，陪禮泰山陰。","（同前）（按：本诗原署：「太子右庶子高陽縣开国男弘文館学士臣許敬宗上。","」）。"]', '诗', 'shi', '', NULL, '五言遼東侍宴山夜臨秋同賦[臨]韻應詔 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b24361-86eb-47cd-85c5-8b27845c1081', '五言侍宴延慶殿同賦別題得阿閣鳳應詔', '五言侍宴延慶殿同賦別題得阿閣鳳應詔', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["帝臺凌紫霧，仙鳳下丹霄。","層巢依綺閣，清歌入洞簫。","逸彩桐[間]艷，浮聲竹外嬌。","自欣棲大廈，率儛爲聞韶。","（同前）（按：本詩原署：「銀青光祿大夫行右庶子高陽縣開國男弘文館學士臣許敬宗上。","」）。"]', '["帝台凌紫霧，仙鳳下丹霄。","層巢依綺閣，清歌入洞簫。","逸彩桐[间]艷，浮声竹外嬌。","自欣棲大廈，率儛爲闻韶。","（同前）（按：本诗原署：「銀青光祿大夫行右庶子高陽縣开国男弘文館学士臣許敬宗上。","」）。"]', '诗', 'shi', '', NULL, '五言侍宴延慶殿同賦別題得阿閣鳳應詔 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f9e9506-844b-4cd6-8f54-a4e4347155b0', '五言侍宴延慶殿集同賦得花間鳥一首應詔', '五言侍宴延慶殿集同賦得花间鸟一首應詔', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["落花飛禁蓹，時鳥咔芳晨。","飄香入綺殿，流響度天津。","千笑千嬌切，一囀一驚新。","方知物華處，偏在上林春。","（同前）（按：本詩原署：「中書侍郎臣許敬宗上。","」）。"]', '["落花飞禁蓹，时鸟咔芳晨。","飄香入綺殿，流响度天津。","千笑千嬌切，一囀一驚新。","方知物华处，偏在上林春。","（同前）（按：本诗原署：「中书侍郎臣許敬宗上。","」）。"]', '诗', 'shi', '', NULL, '五言侍宴延慶殿集同賦得花間鳥一首應詔 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7105a974-7b62-4688-8e75-9eb1725ad58d', '五言後池侍宴迴文詩一首應詔', '五言後池侍宴迴文诗一首應詔', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["凉氣澄佳序，碧沚澹遙空。","篁林下儀鳳，彩鷁間賓鴻。","蒼山帶落日，麗苑扇薰風。","長筵列廣醼，慶洽載恩隆。","（同前）（按：本詩原署與前詩同。","）。"]', '["凉氣澄佳序，碧沚澹遙空。","篁林下儀鳳，彩鷁间賓鴻。","蒼山带落日，丽苑扇薰风。","长筵列廣醼，慶洽載恩隆。","（同前）（按：本诗原署與前诗同。","）。"]', '诗', 'shi', '', NULL, '五言後池侍宴迴文詩一首應詔 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51cecf76-cad9-406c-9427-1030ce5249e6', '五言奉和詠棋應詔 一', '五言奉和詠棋應詔 一', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["魚麗新整陣，鸐□忽爭先。","八圍規破眼，略野務開邊。","分行漸雲布，亂點逐星連。","勝是精神得，非關品格懸。"]', '["鱼丽新整陣，鸐□忽爭先。","八圍規破眼，略野務开邊。","分行漸云布，亂点逐星連。","勝是精神得，非关品格懸。"]', '诗', 'shi', '', NULL, '五言奉和詠棋應詔 一 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715032a7-51ef-44a9-b895-b761c87174eb', '五言奉和詠棋應詔 二', '五言奉和詠棋應詔 二', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["拂局初料敵，陰謀比用師。","觀形已決勝，怯下復徐思。","摶戰類相劫，圖全且自持。","宸襟協堯智，遊藝發初絲。","（同前）（按：本詩原署：「銀青光祿大夫行太子右庶子高陽縣開國男弘文館學士臣許敬宗上。","」以上許敬宗詩十七首，張步雲《唐代逸詩輯存》已收入。","）。"]', '["拂局初料敵，陰謀比用師。","观形已決勝，怯下复徐思。","摶戰類相劫，圖全且自持。","宸襟協堯智，游藝發初絲。","（同前）（按：本诗原署：「銀青光祿大夫行太子右庶子高陽縣开国男弘文館学士臣許敬宗上。","」以上許敬宗诗十七首，張步云《唐代逸诗輯存》已收入。","）。"]', '诗', 'shi', '', NULL, '五言奉和詠棋應詔 二 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a15bc1-cee5-4f76-b1dc-979ad41709f0', '五言七夕侍宴賦得歸衣飛機一首應詔', '五言七夕侍宴賦得归衣飞機一首應詔', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["一年銜別怨，七夕始言歸。","破涕開新靨，微步登雲梯。","天迴兔漸沒，河曠鵲停飛。","那堪盡今夜，復往弄殘機。","（同前）（按：《全唐詩》卷三五據《唐詩紀事》錄《七夕賦詠成篇》，爲七律，中有四句與本詩相近，今人或疑七律爲後人僞作，實無的據。","七律見收於宋綬《歲時雜詠》〖見《古今歲時雜詠》卷二五〗。","詩句重用，古人多有。","今另作一首收入。","）。"]', '["一年銜別怨，七夕始言归。","破涕开新靨，微步登云梯。","天迴兔漸沒，河曠鵲停飞。","那堪尽今夜，复往弄殘機。","（同前）（按：《全唐诗》卷三五據《唐诗紀事》錄《七夕賦詠成篇》，爲七律，中有四句與本诗相近，今人或疑七律爲後人僞作，實無的據。","七律见收於宋綬《歲时杂詠》〖见《古今歲时杂詠》卷二五〗。","诗句重用，古人多有。","今另作一首收入。","）。"]', '诗', 'shi', '', NULL, '五言七夕侍宴賦得歸衣飛機一首應詔 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f503398e-b82f-401c-b689-e12746030d00', '句', '句', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["白雪裝梅樹。","（見李壁《王荆文公詩箋注》卷二九《次韻王勝之詠雪》）。"]', '["白雪裝梅樹。","（见李壁《王荆文公诗箋注》卷二九《次韻王勝之詠雪》）。"]', '诗', 'shi', '', NULL, '句 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1edc2ba4-c86d-48c1-aa87-10be78b698b6', '誡殺生文', '誡殺生文', '38299282-e4e8-4e7f-8701-abafa07b9ca7', '唐', '["麟甲羽毛諸□類，秉性與我元無二。","只爲前生作用愚，致使今生頭角異。","或水中游，或林裏戲，爭忍傷殘供品味。","磨刀着火欲烹時，口不能言眼還視。","我聞天地之大德曰生，莫把羣生當容易。","殘雙賊命傷太和，□子勸妻誇便利。","只知合眼恣無明，不悟幽冥毫髮記。","命將終，冤對至，面覩陰官爭許諱。","人□爲獸獸爲人，物裏輪迴深可畏。","不殺名爲大放生，免落阿毗無間地。","（《八瓊室金石補正》卷一一一。","爲北宋政間和登封石刻。","）。"]', '["麟甲羽毛諸□類，秉性與我元無二。","只爲前生作用愚，致使今生头角異。","或水中游，或林裏戲，爭忍傷殘供品味。","磨刀着火欲烹时，口不能言眼還視。","我闻天地之大德曰生，莫把羣生當容易。","殘雙賊命傷太和，□子勸妻誇便利。","只知合眼恣無明，不悟幽冥毫髮記。","命將終，冤对至，面覩陰官爭許諱。","人□爲獸獸爲人，物裏輪迴深可畏。","不殺名爲大放生，免落阿毗無间地。","（《八瓊室金石補正》卷一一一。","爲北宋政间和登封石刻。","）。"]', '诗', 'shi', '', NULL, '誡殺生文 李元禮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3856595b-774f-4722-b82c-3b40a90caad7', '採蓮賦附歌', '採蓮賦附歌', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["榮華息，功名惻（以上二句，《英華》作「芳草懼脩名」，周必大等校《英華》引集本作「芳華懼功名」），奇秀兮異植，紅光兮碧色。","稟天地之淑麗，承雨露之霑飾（周引集本作「華飾」），蓮有藕兮藕有枝，才有用兮用有時，何當婀娜花（《英華》作「華」）實移，爲君含香藻鳳池。","（見《四部叢刊》本《王子安集》卷二，校以《文苑英華》卷一四八）。"]', '["榮华息，功名惻（以上二句，《英华》作「芳草懼脩名」，周必大等校《英华》引集本作「芳华懼功名」），奇秀兮異植，紅光兮碧色。","稟天地之淑丽，承雨露之霑飾（周引集本作「华飾」），蓮有藕兮藕有枝，才有用兮用有时，何當婀娜花（《英华》作「华」）實移，爲君含香藻鳳池。","（见《四部叢刊》本《王子安集》卷二，校以《文苑英华》卷一四八）。"]', '诗', 'shi', '', NULL, '採蓮賦附歌 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00526fe6-60a5-43ea-a7d6-a6ddf2d77289', '觀音大士神歌讚', '观音大士神歌讚', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["南海海深幽絕處，碧紺嵯峨連水府，號名七寶恪迦山，自在觀音於彼住。","寶陁隨意金鰲藏，雲現兜羅銀世界。","衆玉裝成七寶臺，真珠砌就千花蓋。","足下祥雲五色捧，頂上飛仚歌萬種。","頻伽孔雀盡來朝，諸海龍王齊獻供。","寶冠晃耀圓光列，纓絡遍身明皈潔。","臉如水面瑞蓮芳，眉似天邊秋夜月。","繡衣金縷披霞袂，縹緲素服褊袒臂。","𤤒珈珂珮響珊珊，雲羅綬帶真珠綴。","紅纖十指疑酥膩，青蓮兩目秋波細，咽頸如同玉碾[成]（咸），羅紋黛染青山翠。","朱唇豔瑩齒排河，端坐昂昂劫幾何。","化身百億度衆生，發願河沙救鼻阿。","我慚我愧無由到，遙望觀音拜讚歌。","大聖大慈垂愍念，願舒金手頂中摩。","（見《選印宛委別藏》本《古清涼傳》附大元丘茲盛熙明述《補陁駞洛迦山傳》引王勃《觀音大士讚》附）（按：此篇疑爲後人託名之作。","）。"]', '["南海海深幽絕处，碧紺嵯峨連水府，號名七寶恪迦山，自在观音於彼住。","寶陁隨意金鰲藏，云現兜羅銀世界。","衆玉裝成七寶台，真珠砌就千花蓋。","足下祥云五色捧，頂上飞仚歌万種。","頻伽孔雀尽来朝，諸海龙王齊獻供。","寶冠晃耀圓光列，纓絡遍身明皈潔。","臉如水面瑞蓮芳，眉似天邊秋夜月。","繡衣金縷披霞袂，縹緲素服褊袒臂。","𤤒珈珂珮响珊珊，云羅綬带真珠綴。","紅纖十指疑酥膩，青蓮兩目秋波細，咽頸如同玉碾[成]（咸），羅紋黛染青山翠。","朱唇豔瑩齒排河，端坐昂昂劫幾何。","化身百億度衆生，發願河沙救鼻阿。","我慚我愧無由到，遙望观音拜讚歌。","大聖大慈垂愍念，願舒金手頂中摩。","（见《選印宛委別藏》本《古清涼傳》附大元丘茲盛熙明述《補陁駞洛迦山傳》引王勃《观音大士讚》附）（按：此篇疑爲後人託名之作。","）。"]', '诗', 'shi', '', NULL, '觀音大士神歌讚 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f3622f-6162-4808-927f-30a3ee453693', '道林養性歌二首（題擬） 一', '道林養性歌二首（題擬） 一', '1680b0e9-4afe-4090-a5a9-33fdcdd7106f', '唐', '["美食須熟嚼，生食不麤吞。","問我居止處，大宅揔林村。","胎息守五藏，氣至骨成仙。"]', '["美食須熟嚼，生食不麤吞。","问我居止处，大宅揔林村。","胎息守五藏，氣至骨成仙。"]', '诗', 'shi', '', NULL, '道林養性歌二首（題擬） 一 孫思邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('231ae6ad-0643-414e-a4cb-e4ff7a4d0b0d', '道林養性歌二首（題擬） 二', '道林養性歌二首（題擬） 二', '1680b0e9-4afe-4090-a5a9-33fdcdd7106f', '唐', '["日公三箇毒，不嚼而自消。","錦繡爲五藏，身著糞掃袍。","（見《備急千金要方》卷二七《養性·道林養性》）。"]', '["日公三箇毒，不嚼而自消。","錦繡爲五藏，身著糞掃袍。","（见《備急千金要方》卷二七《養性·道林養性》）。"]', '诗', 'shi', '', NULL, '道林養性歌二首（題擬） 二 孫思邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e13beb28-161d-41be-a5bf-b569a3f131e0', '養生銘（《悅心集》題作《攝生詠》）', '養生銘（《悅心集》題作《攝生詠》）', '1680b0e9-4afe-4090-a5a9-33fdcdd7106f', '唐', '["怒甚偏傷氣，思多太損神。","神疲（《悅心集》作「虛」）心易役，氣弱病相侵。","勿被（《悅心集》作「使」）悲懽（《悅心集》作「觀」）極，當令飯（《悅心集》作「飲」）食均。","再三防夜醉，第一戒晨嗔。","亥（《悅心集》作「夜」）寢鳴雲（《悅心集》作「雷」）鼓，（《悅心集》注：「謂叩齒。","」）寅（《悅心集》作「晨」）興潄玉津。","（《悅心集》注：「謂燕唾。","」）妖邪（《悅心集》作「神」）難犯己，精氣自全身。","若要無諸（《悅心集》作「百」）病，常當節五辛。","安神直悅樂，惜氣保和純。","壽夭休論（《悅心集》作「言」）命，修行本在人。","若能（《悅心集》作「時時」）遵此理，平地可朝真。","（舊題孫思邈撰《孫真人海上方》、清世宗編《悅心集》卷一。","）。"]', '["怒甚偏傷氣，思多太損神。","神疲（《悅心集》作「虛」）心易役，氣弱病相侵。","勿被（《悅心集》作「使」）悲懽（《悅心集》作「观」）極，當令飯（《悅心集》作「饮」）食均。","再三防夜醉，第一戒晨嗔。","亥（《悅心集》作「夜」）寢鳴云（《悅心集》作「雷」）鼓，（《悅心集》注：「謂叩齒。","」）寅（《悅心集》作「晨」）兴潄玉津。","（《悅心集》注：「謂燕唾。","」）妖邪（《悅心集》作「神」）难犯己，精氣自全身。","若要無諸（《悅心集》作「百」）病，常當節五辛。","安神直悅乐，惜氣保和純。","壽夭休論（《悅心集》作「言」）命，修行本在人。","若能（《悅心集》作「时时」）遵此理，平地可朝真。","（旧題孫思邈撰《孫真人海上方》、清世宗編《悅心集》卷一。","）。"]', '诗', 'shi', '', NULL, '養生銘（《悅心集》題作《攝生詠》） 孫思邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c13511fa-e773-4568-8cd4-334118e257c2', '枕上記', '枕上記', '1680b0e9-4afe-4090-a5a9-33fdcdd7106f', '唐', '["侵晨一碗粥，夜食（《海上方》作「飯」）莫教足。","撞動景陽鐘，扣齒三十六。","大寒與大熱，且莫貪色慾。","醉飽莫行房，五臟皆翻覆。","火艾（《海上方》作「艾火」）漫燒身，爭如獨自宿。","坐臥莫當風，頻於暖處浴。","食飽行百步，常以手摩腹。","莫食無鱗魚，諸般禽獸肉。","自死禽與獸（《海上方》作「獸與禽」），食之多命促。","土木爲形象，求之有恩福。","父精母生肉（《海上方》作「母血生」），那忍分南北。","惜命惜身人，六白光如玉。","（日本汲古書院出版《和刻本類書集成》本南宋陳元靚《新編群書類要事林廣記己集》卷二、原題唐孫思邈撰《孫真人海上方》末附）（按：此詩原題《孫真人枕上記》。","以上二首皆附見於《孫真人海上方》，疑爲僞託。","因《枕上記》南宋時已被引錄，故仍錄存。","另《孫真人海上方》收七言絕句一百二十一首，爲託名孫思邈作，僞託時代僅知在明中葉以前。","以下錄附首二首，以見一斑。","）。"]', '["侵晨一碗粥，夜食（《海上方》作「飯」）莫教足。","撞动景陽鐘，扣齒三十六。","大寒與大熱，且莫貪色慾。","醉飽莫行房，五臟皆翻覆。","火艾（《海上方》作「艾火」）漫燒身，爭如独自宿。","坐臥莫當风，頻於暖处浴。","食飽行百步，常以手摩腹。","莫食無鱗鱼，諸般禽獸肉。","自死禽與獸（《海上方》作「獸與禽」），食之多命促。","土木爲形象，求之有恩福。","父精母生肉（《海上方》作「母血生」），那忍分南北。","惜命惜身人，六白光如玉。","（日本汲古书院出版《和刻本類书集成》本南宋陳元靚《新編群书類要事林廣記己集》卷二、原題唐孫思邈撰《孫真人海上方》末附）（按：此诗原題《孫真人枕上記》。","以上二首皆附见於《孫真人海上方》，疑爲僞託。","因《枕上記》南宋时已被引錄，故仍錄存。","另《孫真人海上方》收七言絕句一百二十一首，爲託名孫思邈作，僞託时代僅知在明中葉以前。","以下錄附首二首，以见一斑。","）。"]', '诗', 'shi', '', NULL, '枕上記 孫思邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6ac5c1a-6c30-4d31-bfd5-4368ffb3654f', '枕上記 暑月傷熱', '枕上記 暑月傷熱', '1680b0e9-4afe-4090-a5a9-33fdcdd7106f', '唐', '["途中大暑最堪憐，急取車輪土五錢。","盞內澄清湯服盡，身輕體健即安然。"]', '["途中大暑最堪怜，急取车輪土五錢。","盞內澄清湯服尽，身轻體健即安然。"]', '诗', 'shi', '', NULL, '枕上記 暑月傷熱 孫思邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c2def49-6b4c-4a8a-909e-5b5909cabeeb', '枕上記 傷寒咳𠻳', '枕上記 傷寒咳𠻳', '1680b0e9-4afe-4090-a5a9-33fdcdd7106f', '唐', '["傷寒咳嗽夜無眠，細碾明礬末一錢。","半夏橘皮薑共煮，煎湯調下化粘涎。"]', '["傷寒咳嗽夜無眠，細碾明礬末一錢。","半夏橘皮薑共煮，煎湯調下化粘涎。"]', '诗', 'shi', '', NULL, '枕上記 傷寒咳𠻳 孫思邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('754ec24e-d759-40d0-a722-e155430a9083', '保生銘', '保生銘', '1680b0e9-4afe-4090-a5a9-33fdcdd7106f', '唐', '["人若勞於形，百病不能成。","飲酒忌大醉，諸疾自不生。","食了行百步，數將手摩肚。","睡不苦高枕，唾涕不遠顧。","寅丑日剪甲，理髮須百度。","飽則立小便，饑乃坐漩溺。","行坐莫當風，居處無小隙。","向北大小便，一生昏羃羃。","日月固然忌，水火仍畏避。","每夜洗脚臥，飽食終無益。","忍辱爲上乘，讒言斷親戚。","思慮最傷神，喜怒傷和息。","每去鼻中毛，常習不唾地。","平明欲起時，不床先左脚。","一日免灾咎，去邪兼辟惡。","但能七星步，令人長壽樂。","酸味傷於筋，辛味損正氣。","苦則損於心，甘則傷其志。","鹹多促人壽，不得偏耽嗜。","春夏任宣通，秋冬固陽事。","獨臥是守真，慎靜最爲貴。","財帛生有分，知是將爲利。","強知是大患，少欲終無累。","神氣自然存，學道須終始。","書於壁戶間，將用傳君子。","（《正統道藏·洞神部·方法類》。","此首亦疑爲僞託之作。","）。"]', '["人若勞於形，百病不能成。","饮酒忌大醉，諸疾自不生。","食了行百步，數將手摩肚。","睡不苦高枕，唾涕不远顧。","寅丑日剪甲，理髮須百度。","飽則立小便，饑乃坐漩溺。","行坐莫當风，居处無小隙。","向北大小便，一生昏羃羃。","日月固然忌，水火仍畏避。","每夜洗脚臥，飽食終無益。","忍辱爲上乘，讒言斷親戚。","思慮最傷神，喜怒傷和息。","每去鼻中毛，常習不唾地。","平明欲起时，不床先左脚。","一日免灾咎，去邪兼辟惡。","但能七星步，令人长壽乐。","酸味傷於筋，辛味損正氣。","苦則損於心，甘則傷其志。","鹹多促人壽，不得偏耽嗜。","春夏任宣通，秋冬固陽事。","独臥是守真，慎静最爲貴。","財帛生有分，知是將爲利。","強知是大患，少欲終無累。","神氣自然存，学道須終始。","书於壁戶间，將用傳君子。","（《正統道藏·洞神部·方法類》。","此首亦疑爲僞託之作。","）。"]', '诗', 'shi', '', NULL, '保生銘 孫思邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae00779d-75d4-4ab8-a56e-3caf7a5c31bc', '出家箴', '出家箴', '696cf4cb-79c6-49be-989f-099cff32394a', '唐', '["捨家出家何所以，稽首空王求出離。","三師七證定初機，剃髮染衣發弘誓。","去貪嗔，除鄙悋，十二時中須（一作「常」）謹慎。","鍊磨真性若虛空，自然戰退魔軍陣。","勤學業（一作「習」）尋師匠，說與行（一作「同」）人堪倚仗。","莫教心地亂如麻，百歲光陰等閑喪。","踵前賢，效先聖，盡假聞思修所（一作「得」）證。","行住坐臥要真（一作「精」）專，念念無差始相應。","佛真經，十二部，縱橫指示菩提路。","不習不學（一作「聽」）不依行，問君何日心開悟。","速須救（一作「究」），似頭燃，莫待明年與後年。","一息不來即後世，誰能保得此身堅。","不蠶衣，不田食，織婦（一作「女」）耕夫汗血力。","爲成道果（一作「業」）施將來，道果（一作「業」）未成爭消得。","哀哀父，哀哀母，嚥苦吐甘大辛苦。","就濕回乾養育成，要襲門風繼先祖。","一旦中（一作「一旦辭親」），求剃落，八十九十無倚（一作「依」）託。","若不超凡越聖流，向此因循全大錯。","福田衣，降龍鉢，受用一身求解脫。","若將（一作「因」）小利繫心懷，彼岸湼槃爭得達（一作「達得」）。","善男子，汝須知，修行（一作「遭逢」）難得似今時。","若得（一作「既遇」）出家披縷褐，猶如浮木值盲龜。","大丈夫，須猛利，緊束身心莫容易。","倘能行願力相扶，決定龍華親授記。","（日本《續藏經》宋釋子昇、如祐編《禪門諸祖師偈頌》卷下之下。","校以《大正藏》本明袾宏《緇門警訓》卷二。","二書皆稱作者爲「慈恩大師」。","）。"]', '["捨家出家何所以，稽首空王求出離。","三師七證定初機，剃髮染衣發弘誓。","去貪嗔，除鄙悋，十二时中須（一作「常」）謹慎。","鍊磨真性若虛空，自然戰退魔軍陣。","勤学業（一作「習」）尋師匠，说與行（一作「同」）人堪倚仗。","莫教心地亂如麻，百歲光陰等闲喪。","踵前賢，效先聖，尽假闻思修所（一作「得」）證。","行住坐臥要真（一作「精」）專，念念無差始相應。","佛真經，十二部，縱橫指示菩提路。","不習不学（一作「听」）不依行，问君何日心开悟。","速須救（一作「究」），似头燃，莫待明年與後年。","一息不来即後世，誰能保得此身堅。","不蠶衣，不田食，织婦（一作「女」）耕夫汗血力。","爲成道果（一作「業」）施將来，道果（一作「業」）未成爭消得。","哀哀父，哀哀母，嚥苦吐甘大辛苦。","就濕回乾養育成，要襲门风繼先祖。","一旦中（一作「一旦辞親」），求剃落，八十九十無倚（一作「依」）託。","若不超凡越聖流，向此因循全大錯。","福田衣，降龙鉢，受用一身求解脫。","若將（一作「因」）小利繫心懷，彼岸湼槃爭得達（一作「達得」）。","善男子，汝須知，修行（一作「遭逢」）难得似今时。","若得（一作「既遇」）出家披縷褐，猶如浮木值盲龟。","大丈夫，須猛利，緊束身心莫容易。","倘能行願力相扶，決定龙华親授記。","（日本《續藏經》宋釋子昇、如祐編《禪门諸祖師偈頌》卷下之下。","校以《大正藏》本明袾宏《緇门警訓》卷二。","二书皆稱作者爲「慈恩大師」。","）。"]', '诗', 'shi', '', NULL, '出家箴 窺基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f16da2fe-e6cc-4192-a158-4b3976b73b34', '大唐大慈恩寺大師畫贊', '大唐大慈恩寺大師畫贊', 'beda9249-7e81-417e-949f-9168f42bf729', '唐', '["慈恩大師尉遲氏，諱大乘基長安人。","族貴五陵光三輔，鄂公敬德是其親。","智勇冠世超衛霍，李唐之初大功臣。","文皇崇師稱大聖，生立碑文垂絲綸。","羯羅藍位多正夢，[漢]（漠）月入口母方娠。","金人持神珠寶杵，託干胎中吉兆頻。","身相圓滿載誕肓，[彤]（肜）雲成蓋覆菓脣。","眼浮紫電夏天影，面駐素娥秋夜輪。","少少之時早拔萃，齠齔之間含慈惇。","依止三藏學性相，三千徒裏絕等倫。","七十達者四賢聖，就中大師深入神。","亞聖具體比顏子，窮源盡性同大[鈞]（鉤）。","三性五重唯識義，博涉學海到要津。","百部疏主五明祖，著述以來誰得均？","字字句句不空置，皆有證據永因循。","伯牙響琴徒秘典，卞和泣玉獨霑巾。","論鼓一振疑關破，他宗望風自委塵。","對龍象衆能降伏，昇師子座檀嚬伸。","每月必造慈氏像，一生偏慕兜率身。","每日必誦菩薩戒，唯杖木叉制波旬。","一時高樓秋燈下，有人窺見偷逡巡。","大光普照觀自在，金手染翰顯其真。","不圖漢土化等覺，開甘露門利兆民。","自書般若何所至，清凉山曉五臺春。","瑞光赫赫慶雲起，文殊正現示宿因。","遊博陵原製玄贊，法華賾旨傳遠賓。","當寶塔品人有夢，諸佛證明遍照鄰。","二十八字一挑句，文章微婉柢獲麟。","傳導大師以此偈，千佛滅度讚大仁。","不嫌暗漏作章疏，齒牙煥炳光曜新。","咫尺龍顏奉鳳詔，出入金殿陪紫[宸]（震）。","天不與善化緣盡，歲五十三俄已泯。","永淳二年十一月，仲旬三日爲忌辰。","先師慕（疑應作「墓」）側行袝禮，風悲雲愁慘松筠。","本願不回奉彌勒，生第四天奉華茵。","名垂萬古涉五竺，玄蹤雖多難盡陳。","（見《卍續藏經》本《玄奘三藏師資叢書》卷下，原署「特進行門下侍郎兼鎮西員外都督江滿昌文」。","卷首目錄署「唐江滿昌文撰」。","）（按：唐代史乘未見江滿昌事迹，頗可疑。","而按之詩意，則顯然爲窺基卒後不久作。","疑其人應爲日本或新羅人而入唐者。","）。"]', '["慈恩大師尉遲氏，諱大乘基长安人。","族貴五陵光三輔，鄂公敬德是其親。","智勇冠世超衛霍，李唐之初大功臣。","文皇崇師稱大聖，生立碑文垂絲綸。","羯羅藍位多正梦，[漢]（漠）月入口母方娠。","金人持神珠寶杵，託干胎中吉兆頻。","身相圓满載誕肓，[彤]（肜）云成蓋覆菓脣。","眼浮紫電夏天影，面駐素娥秋夜輪。","少少之时早拔萃，齠齔之间含慈惇。","依止三藏学性相，三千徒裏絕等倫。","七十達者四賢聖，就中大師深入神。","亞聖具體比顏子，窮源尽性同大[鈞]（鉤）。","三性五重唯識義，博涉学海到要津。","百部疏主五明祖，著述以来誰得均？","字字句句不空置，皆有證據永因循。","伯牙响琴徒秘典，卞和泣玉独霑巾。","論鼓一振疑关破，他宗望风自委塵。","对龙象衆能降伏，昇師子座檀嚬伸。","每月必造慈氏像，一生偏慕兜率身。","每日必誦菩薩戒，唯杖木叉制波旬。","一时高楼秋灯下，有人窺见偷逡巡。","大光普照观自在，金手染翰显其真。","不圖漢土化等覺，开甘露门利兆民。","自书般若何所至，清凉山晓五台春。","瑞光赫赫慶云起，文殊正現示宿因。","游博陵原製玄贊，法华賾旨傳远賓。","當寶塔品人有梦，諸佛證明遍照鄰。","二十八字一挑句，文章微婉柢獲麟。","傳導大師以此偈，千佛滅度讚大仁。","不嫌暗漏作章疏，齒牙煥炳光曜新。","咫尺龙顏奉鳳詔，出入金殿陪紫[宸]（震）。","天不與善化緣尽，歲五十三俄已泯。","永淳二年十一月，仲旬三日爲忌辰。","先師慕（疑應作「墓」）側行袝禮，风悲云愁慘松筠。","本願不回奉彌勒，生第四天奉华茵。","名垂万古涉五竺，玄蹤雖多难尽陳。","（见《卍續藏經》本《玄奘三藏師資叢书》卷下，原署「特進行门下侍郎兼鎮西員外都督江满昌文」。","卷首目錄署「唐江满昌文撰」。","）（按：唐代史乘未见江满昌事迹，頗可疑。","而按之诗意，則显然爲窺基卒後不久作。","疑其人應爲日本或新羅人而入唐者。","）。"]', '诗', 'shi', '', NULL, '大唐大慈恩寺大師畫贊 江滿昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad9cc744-b481-4cea-8efe-5c173b14795e', '頌六十二首 一', '頌六十二首 一', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["騄驥資鞭策，蘭蕙佇薰風。","至理信難見，非人孰可通。","輸心仰圓寂，瑩曬入玄中。","總轡超三有，摶飛上四空。","簪纓猶忽夢，財利若塵蒙。","高揖謝時俗，蕭灑出煩籠。","（見《大正新修大藏經》第五四冊道世《諸經要集》卷二《三寶部》）（按：《古今禪藻集》卷一收此首爲隋無名釋作，題作《順益頌》，實誤。","）。"]', '["騄驥資鞭策，蘭蕙佇薰风。","至理信难见，非人孰可通。","輸心仰圓寂，瑩曬入玄中。","總轡超三有，摶飞上四空。","簪纓猶忽梦，財利若塵蒙。","高揖謝时俗，蕭灑出煩籠。","（见《大正新修大藏經》第五四冊道世《諸經要集》卷二《三寶部》）（按：《古今禪藻集》卷一收此首爲隋無名釋作，題作《順益頌》，實誤。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 一 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cc4f067-c765-4f7f-bf3b-f078c1906474', '頌六十二首 二', '頌六十二首 二', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["遺身八萬塔，寶飾高百丈。","儀鳳異靈鳥，金槃代佛（一作「盤代仙」）掌。","積拱承彫月（一作「角」），高簷掛樹網。","寶地若池沙，風鈴如積響。","刻削生千變，丹青圖萬像。","煙霞時出沒，神仙乍來往。","晨霧半層生，飛幡接雲上。","遊蜺不敢息，翔鵾詎能仰。","福地下金繩，天報豈虛枉（一作「聖變無窮端，感福豈三兩」）。","願假舟航末（一作「木」），彼岸誰云廣？","（見同書卷三《敬塔部》。","注一作者，爲《法苑珠林》卷五一《敬塔篇》之異文。","）。"]', '["遺身八万塔，寶飾高百丈。","儀鳳異靈鸟，金槃代佛（一作「盤代仙」）掌。","積拱承彫月（一作「角」），高簷掛樹網。","寶地若池沙，风鈴如積响。","刻削生千变，丹青圖万像。","煙霞时出沒，神仙乍来往。","晨霧半層生，飞幡接云上。","游蜺不敢息，翔鵾詎能仰。","福地下金繩，天報豈虛枉（一作「聖变無窮端，感福豈三兩」）。","願假舟航末（一作「木」），彼岸誰云廣？","（见同书卷三《敬塔部》。","注一作者，爲《法苑珠林》卷五一《敬塔篇》之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 二 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7fe8273-47e1-47ad-a72e-9ff8ef460d2d', '頌六十二首 三', '頌六十二首 三', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["牧（一作「沒」）杖信爲急，調絃貴不奢。","騰猨安可制，逸馬本難罝。","驅馳習聲色，冠蓋競豪華。","既入王孫第，還向季倫家。","靜心澄業累，省念勗身瑕。","庶茲憑七覺（一作「寶」），時用免三邪。","（見同書同卷《攝念部》）。"]', '["牧（一作「沒」）杖信爲急，調絃貴不奢。","腾猨安可制，逸马本难罝。","驱驰習声色，冠蓋競豪华。","既入王孫第，還向季倫家。","静心澄業累，省念勗身瑕。","庶茲憑七覺（一作「寶」），时用免三邪。","（见同书同卷《攝念部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e728db3-81af-44de-8f90-24b82b63ba92', '頌六十二首 四', '頌六十二首 四', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["三山羽化竟無成，五熱殷憂徒自縈。","並入繁（一作「樊」）籠處塵館，何如寂慮出危城。","鏡智圓規光且淨，月行馳輪皎復晴。","側徑崎嶇爾迴轍，通莊達老豈同征。","（見同書同卷《入道部》）。"]', '["三山羽化竟無成，五熱殷憂徒自縈。","並入繁（一作「樊」）籠处塵館，何如寂慮出危城。","镜智圓規光且淨，月行驰輪皎复晴。","側徑崎嶇爾迴轍，通莊達老豈同征。","（见同书同卷《入道部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83412116-c49e-4dfe-9f9a-6d941d323df9', '頌六十二首 五', '頌六十二首 五', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["玄亮吐清氣，神響徹幽籠（一作「聾」）。","登臺發春詠，高興避希（一作「希避」）蹤。","乘虛感靈覺，魚（一作「漁」）山振思童。","摹寫天歌梵，冀布法音同。","哀婉（一作「忘高」）故不下，飄（一作「颻」）颺數仞中。","比丘歌聲唄，人畜振心鐘。","斯由暢玄句，即感鴈遊空。","神朝（一作「期」）發筌悟，豁爾自靈通。","（見同書同卷《唄贊部》。","注一作者，爲《法苑珠林》卷五十《唄讚篇·音樂部》之異文。","）。"]', '["玄亮吐清氣，神响徹幽籠（一作「聾」）。","登台發春詠，高兴避希（一作「希避」）蹤。","乘虛感靈覺，鱼（一作「漁」）山振思童。","摹寫天歌梵，冀布法音同。","哀婉（一作「忘高」）故不下，飄（一作「颻」）颺數仞中。","比丘歌声唄，人畜振心鐘。","斯由暢玄句，即感鴈游空。","神朝（一作「期」）發筌悟，豁爾自靈通。","（见同书同卷《唄贊部》。","注一作者，爲《法苑珠林》卷五十《唄讚篇·音乐部》之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 五 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec3641be-732e-461a-a469-093457a66cfe', '頌六十二首 六', '頌六十二首 六', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["久厭無明樹，方欣奈苑鮮。","始入香山路，終逢不壞身。","定花發智果，神燈照梵天。","霞幡同錦色，芬馥合鑪煙。","宛轉騰空颺，倒下似紅蓮。","夙夜風吹轉，香疊輪王因。","攀仰無厭足，結侶感留瞻。","何知色中綵（一作「來彩」），招福壽延年。","（見同書同卷《香燈部》）。"]', '["久厭無明樹，方欣奈苑鲜。","始入香山路，終逢不壞身。","定花發智果，神灯照梵天。","霞幡同錦色，芬馥合鑪煙。","宛轉腾空颺，倒下似紅蓮。","夙夜风吹轉，香叠輪王因。","攀仰無厭足，結侶感留瞻。","何知色中綵（一作「来彩」），招福壽延年。","（见同书同卷《香灯部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 六 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958c2b2d-3bbe-4c2e-86a3-21c74f94c1a3', '頌六十二首 七', '頌六十二首 七', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["令月建清齋，佳辰召無強（一作「疆」）。","四部依時集，七衆會陞堂。","蕭條清梵舉，哀宛（一作「怨」）動宮商。","香氣騰空上，乘風散遐方。","歎德研沖邃，詞辯暢玄芳。","折煩呈妙句，臨時拆婉章。","緇素相依託，財法發神光。","神田今夕滿，恩慧（一作「惠」）導存亡。","（見同書卷五《受請部》。","注一作者爲《法苑珠林》卷一百九之異文。","）。"]', '["令月建清斋，佳辰召無強（一作「疆」）。","四部依时集，七衆會陞堂。","蕭條清梵舉，哀宛（一作「怨」）动宮商。","香氣腾空上，乘风散遐方。","歎德研沖邃，词辯暢玄芳。","折煩呈妙句，臨时拆婉章。","緇素相依託，財法發神光。","神田今夕满，恩慧（一作「惠」）導存亡。","（见同书卷五《受請部》。","注一作者爲《法苑珠林》卷一百九之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 七 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5082212-5ea6-4a0d-9b88-ebf46c1529f7', '頌六十二首 八', '頌六十二首 八', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["禁饕緣芳味，持聲唯節儉。","一坐肅容儀，五萬豐餘歛。","戒香飛且馥，情關閉愈（一作「逾」）掩。","勿言徒辛苦，終然越危嶮。","（見同書卷六《受齋部》）。"]', '["禁饕緣芳味，持声唯節儉。","一坐肅容儀，五万豐餘歛。","戒香飞且馥，情关閉愈（一作「逾」）掩。","勿言徒辛苦，終然越危嶮。","（见同书卷六《受斋部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 八 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd409b87-f6df-4688-89a4-0ff96234c5d3', '頌六十二首 九', '頌六十二首 九', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["虧功九仞罷崇山，頓駕千里倦長路。","改塗悔善因芳音，易情梁惡良妖嫗。","五福精修既不成，八關守戒誰能護。","攸攸極夜爾何期，森森愛流安可度。","（見同書同卷《破齋部》）。"]', '["虧功九仞罷崇山，頓駕千里倦长路。","改塗悔善因芳音，易情梁惡良妖嫗。","五福精修既不成，八关守戒誰能護。","攸攸極夜爾何期，森森愛流安可度。","（见同书同卷《破斋部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 九 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba41f144-dce3-4cc9-a1de-b52107c83ebc', '頌六十二首 十', '頌六十二首 十', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["韞石諒非真，飾瓶信爲假。","寵（一作「竊」）服高（一作「臯」）門上，濫吹緇軒下。","風（一作「鳳」）祀結驚心，騶文終好野。","真相豈或（一作「式」）昭，浮榮未能捨。","跡殊冠冕客，事襲驅馳者。","已矣歇鄭聲，天然亂周雅。","富貴空爭名，寵辱虛相駡。","須臾風火燭，幻泡何足把。","（見同書同卷《富貴部》。","注一作者，爲《法苑珠林》卷七十之異文。","）。"]', '["韞石諒非真，飾瓶信爲假。","寵（一作「竊」）服高（一作「臯」）门上，濫吹緇軒下。","风（一作「鳳」）祀結驚心，騶文終好野。","真相豈或（一作「式」）昭，浮榮未能捨。","跡殊冠冕客，事襲驱驰者。","已矣歇鄭声，天然亂周雅。","富貴空爭名，寵辱虛相駡。","須臾风火燭，幻泡何足把。","（见同书同卷《富貴部》。","注一作者，爲《法苑珠林》卷七十之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 十 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ce6de7-e359-4dfa-929e-80989e4322a5', '頌六十二首 十一', '頌六十二首 十一', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["浮雲南北竟無歸，子客東西何可依。","原憲糟糖竊有望，田氏膏腴詎敢希。","藹藹廡庭絕車馬，寂寂蓬門掩席扉。","宿昔偷光恡餘照，今日窮途空自欺。","（同書同卷《貧賤部》）。"]', '["浮云南北竟無归，子客东西何可依。","原憲糟糖竊有望，田氏膏腴詎敢希。","藹藹廡庭絕车马，寂寂蓬门掩席扉。","宿昔偷光恡餘照，今日窮途空自欺。","（同书同卷《貧賤部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 十一 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4aa3781-d28e-4c8a-a0b0-61ec6e9023f3', '頌六十二首 十二', '頌六十二首 十二', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["建志誠心愚，高慕欣朋儔。","相與立弘誓，捨俗慕閑丘。","蕭散人物外，晃朗免綢繆。","寂寂求戒（一作「誠」）真，亹亹勵心柔。","警策修三業，激切澄四流。","興心願弘誓，救溺運慈舟。","嘉期歸妙覺，善會湼槃修。","存心八正道，立志三祇休。","（見同書卷七《獎導部》。","注一作者，爲《法苑珠林》卷六一之異文。","）。"]', '["建志誠心愚，高慕欣朋儔。","相與立弘誓，捨俗慕闲丘。","蕭散人物外，晃朗免綢繆。","寂寂求戒（一作「誠」）真，亹亹勵心柔。","警策修三業，激切澄四流。","兴心願弘誓，救溺運慈舟。","嘉期归妙覺，善會湼槃修。","存心八正道，立志三祇休。","（见同书卷七《獎導部》。","注一作者，爲《法苑珠林》卷六一之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 十二 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f025d7-fe26-40a3-af9b-595a66b674d3', '頌六十二首 十三', '頌六十二首 十三', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["含識皆畏死，有命懼嶮危。","如魚困池涸，難逢流水希。","親疎皆父母，何得不悲時（一作「輒相欺」）。","何慈救厄苦（一作「慈悲救危苦」）。","福報自然隨。","（見同書卷八《放生部》。","注一作者，爲《法苑珠林》卷八二之異文。","）。"]', '["含識皆畏死，有命懼嶮危。","如鱼困池涸，难逢流水希。","親疎皆父母，何得不悲时（一作「輒相欺」）。","何慈救厄苦（一作「慈悲救危苦」）。","福報自然隨。","（见同书卷八《放生部》。","注一作者，爲《法苑珠林》卷八二之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 十三 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a2336c-3e4a-4e61-94ee-d4f0bd5ca751', '頌六十二首 十四', '頌六十二首 十四', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["瞻蔔改蓬心，伊蘭變芳樹。","規輪時有缺，皓絲不常素。","三益竊所忻，四隙行當護。","勗哉深自勉，誡之誠可慕。","（見同書卷九《擇交部》）。"]', '["瞻蔔改蓬心，伊蘭变芳樹。","規輪时有缺，皓絲不常素。","三益竊所忻，四隙行當護。","勗哉深自勉，誡之誠可慕。","（见同书卷九《擇交部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 十四 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac3cf42-8ae0-4ee7-b88d-a30bfed194a8', '頌六十二首 十五', '頌六十二首 十五', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["尋因途乃異，及捨趣猶並。","苦極思歸樂，樂極苦還生。","豈非罪福別，皆由封著情。","若斷有漏業，常見法身寧。","（見同書卷十一《業因部》）。"]', '["尋因途乃異，及捨趣猶並。","苦極思归乐，乐極苦還生。","豈非罪福別，皆由封著情。","若斷有漏業，常见法身寧。","（见同书卷十一《業因部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 十五 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8542b02f-f109-4018-936b-21265bc9eca0', '頌六十二首 十六', '頌六十二首 十六', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["五慾昏神識，五蓋蔽福力。","六根成苦集，六賊亂心色。","慾泿逐情飄，愛網隨心織。","三毒障人空，四流漂不息。","至金雖改秋，斬籌方未極。","觀鴿既無窮，猿攀此焉（一作「烏」）伏。","自非絕慾蓋，何能遠昇陟。","齊獁（一作「⿰車犬」）屆寶城，共覩能仁德。","（見同書卷十二《慾蓋部》。","注一作者，爲《法苑珠林》卷八九之異文。","）。"]', '["五慾昏神識，五蓋蔽福力。","六根成苦集，六賊亂心色。","慾泿逐情飄，愛網隨心织。","三毒障人空，四流漂不息。","至金雖改秋，斬籌方未極。","观鴿既無窮，猿攀此焉（一作「烏」）伏。","自非絕慾蓋，何能远昇陟。","齊獁（一作「⿰车犬」）屆寶城，共覩能仁德。","（见同书卷十二《慾蓋部》。","注一作者，爲《法苑珠林》卷八九之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 十六 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b4f95b-71f9-412c-9bf6-22f05edcebdb', '頌六十二首 十七', '頌六十二首 十七', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["業理信多緒，生途非一門。","安危誠易轍，清濁豈同源。","墜質空遺貌，尋香有去魂。","幽衢下寮落，暠路上飛翻。","凝陰淒復緊，聲威聒已喧。","投身庇茅屋，懌慮入花園。","伉儷情多亂，貪嗔坐自昏。","遍知稱自覺，挑手獨爲尊。","（見同書同卷《四生部》）。"]', '["業理信多緒，生途非一门。","安危誠易轍，清濁豈同源。","墜質空遺貌，尋香有去魂。","幽衢下寮落，暠路上飞翻。","凝陰淒复緊，声威聒已喧。","投身庇茅屋，懌慮入花园。","伉儷情多亂，貪嗔坐自昏。","遍知稱自覺，挑手独爲尊。","（见同书同卷《四生部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 十七 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff38a9c7-8dc8-4c51-b171-9db1e0443552', '頌六十二首 十八', '頌六十二首 十八', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["惰學迷三教，問者不知一。","合萼不結核，敷華何得實。","徒生高慢心，凌他非好畢。","墜落幽闇道，開閉牢深密。","一入百千年，萬億苦逼切。","對苦悔無知，方由墮慢媟。","至人善取譬，立志須明律。","英雄慢法時，焉知悔今日。","（見同書卷十六《墮慢部》。","又見百卷本《法苑珠林》卷五四。","）。"]', '["惰学迷三教，问者不知一。","合萼不結核，敷华何得實。","徒生高慢心，凌他非好畢。","墜落幽闇道，开閉牢深密。","一入百千年，万億苦逼切。","对苦悔無知，方由墮慢媟。","至人善取譬，立志須明律。","英雄慢法时，焉知悔今日。","（见同书卷十六《墮慢部》。","又见百卷本《法苑珠林》卷五四。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 十八 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('721b739c-cf6d-4cd2-bb8e-a95fe49a78b6', '頌六十二首 十九', '頌六十二首 十九', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["生來死還送，日往月復旋。","弱喪昏風動，流浪逐物遷。","愚戇失正路，漂沒入重淵。","一墜幽闇處，萬劫履鋒辛（一作「鋋」）。","六道旋寰（一作「環」）苦，三業未曾全。","墜（一作「隨」）流無人救，悽傷還自憐。","歸誠觀像物，方知虛妄筌。","苦海深河趣，思登般若船。","（見同書卷十八《地獄部》。","注一作者，爲《法苑珠林》卷十二《地獄部之餘》之異文。","）。"]', '["生来死還送，日往月复旋。","弱喪昏风动，流浪逐物遷。","愚戇失正路，漂沒入重淵。","一墜幽闇处，万劫履鋒辛（一作「鋋」）。","六道旋寰（一作「环」）苦，三業未曾全。","墜（一作「隨」）流無人救，悽傷還自怜。","归誠观像物，方知虛妄筌。","苦海深河趣，思登般若船。","（见同书卷十八《地獄部》。","注一作者，爲《法苑珠林》卷十二《地獄部之餘》之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 十九 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ece225-86a3-4924-bf7d-88844da72e74', '頌六十二首 二十', '頌六十二首 二十', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["高堂信逆旅，懷（一作「壞」）業理常牽。","玉匣方委觀，金臺不復延。","挽聲隨徑遠，蘿影帶松懸。","詎能留十念，唯應逐四緣。","幻工作同異，變弄巧（一作「作」）多聲（一作「身」）。","愚俗諍人我，誰復非謂真。","謬者疑久固，達者知幻賓。","陞沉苦樂異，徒祭哭蒼天（一作「親疎既無定，何勞非蒼旻」。","）（見同書卷十九《送終部》。","注一作者，爲《法苑珠林》卷一百十六之異文。","）。"]', '["高堂信逆旅，懷（一作「壞」）業理常牽。","玉匣方委观，金台不复延。","挽声隨徑远，蘿影带松懸。","詎能留十念，唯應逐四緣。","幻工作同異，变弄巧（一作「作」）多声（一作「身」）。","愚俗諍人我，誰复非謂真。","謬者疑久固，達者知幻賓。","陞沉苦乐異，徒祭哭蒼天（一作「親疎既無定，何勞非蒼旻」。","）（见同书卷十九《送終部》。","注一作者，爲《法苑珠林》卷一百十六之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('973ede19-c44d-46c7-8351-82b2a0c9915c', '頌六十二首 二十一', '頌六十二首 二十一', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["百旬芥易盡，三災理自傾。","石火無恒焰，電光非久停。","饑窘自相噉，刀兵競相征。","疫病無醫効，空勞怨苦聲。","親戚無相救，殘害有餘情。","遺文虛滿笥，徒欣富貴盈。","太息波川迅，悲斯苦業縈。","生滅恒敦逼，煎迫未安寧。","（見《法苑珠林》卷四《大三災部之餘》）。"]', '["百旬芥易尽，三災理自傾。","石火無恒焰，電光非久停。","饑窘自相噉，刀兵競相征。","疫病無醫効，空勞怨苦声。","親戚無相救，殘害有餘情。","遺文虛满笥，徒欣富貴盈。","太息波川迅，悲斯苦業縈。","生滅恒敦逼，煎迫未安寧。","（见《法苑珠林》卷四《大三災部之餘》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十一 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4f3c03-e653-4b99-b5e7-e328e309ae3b', '頌六十二首 二十二', '頌六十二首 二十二', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["火氣上昇煙，雲氣靉靆雲。","神龍吐津霧，颺埃坋人塵。","酒爲放逸門，婬爲生死源。","金銀生患重，邪命壞戒根。","（見同書卷七《失候部》）。"]', '["火氣上昇煙，云氣靉靆云。","神龙吐津霧，颺埃坋人塵。","酒爲放逸门，婬爲生死源。","金銀生患重，邪命壞戒根。","（见同书卷七《失候部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十二 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3607aa34-1474-4079-b46e-ec5db39e6c85', '頌六十二首 二十三', '頌六十二首 二十三', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["經行林樹下，求道志能堅。","既有神通力，振錫遠乘煙。","一登四弘誓，至道莫能先。","不貪曠劫壽，何論延促年。","（見同書卷二七《違損部》）。"]', '["經行林樹下，求道志能堅。","既有神通力，振錫远乘煙。","一登四弘誓，至道莫能先。","不貪曠劫壽，何論延促年。","（见同书卷二七《違損部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十三 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd3cce64-b69a-425f-8c48-56d382f35ab6', '頌六十二首 二十四', '頌六十二首 二十四', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["封迷昏闇久，徘徊夢裏藏。","心塵既未洗，怖霑甘露漿。","慈顏發暉曜，燭我見朝陽。","忽逢善知友，開導益神光。","稍悟心澄靜，方猒俗蒼茫。","緇徒既肅肅，法侶亦鏘鏘。","見者心歡喜，歸誠向道場。","若存信邪倒，來苦未何殃。","（見同書卷二九《大乘部》）。"]', '["封迷昏闇久，徘徊梦裏藏。","心塵既未洗，怖霑甘露漿。","慈顏發暉曜，燭我见朝陽。","忽逢善知友，开導益神光。","稍悟心澄静，方猒俗蒼茫。","緇徒既肅肅，法侶亦鏘鏘。","见者心歡喜，归誠向道場。","若存信邪倒，来苦未何殃。","（见同书卷二九《大乘部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十四 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30db71ef-a7f8-4828-bbe4-b22c5e29b9e6', '頌六十二首 二十五', '頌六十二首 二十五', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["五欲混神因，六賊亂心色。","幻焰逐情飄，愛網隨心織。","鑄金雖改秋，斬籌方未極。","觀鴿既無辯，攀猿此焉息。","（見同書卷三十《姦僞部》）。"]', '["五欲混神因，六賊亂心色。","幻焰逐情飄，愛網隨心织。","鑄金雖改秋，斬籌方未極。","观鴿既無辯，攀猿此焉息。","（见同书卷三十《姦僞部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十五 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba15492-22ed-4628-a5b1-a5dab3c6dc93', '頌六十二首 二十六', '頌六十二首 二十六', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["冬狐理豐毳，春蠶緒輕絲。","形骸翻爲阻，心識還自欺。","齠齓歌鼓腹，平生少年時。","驅車追俠客，酌酒弄妖姬。","但念目前好，安知後世悲。","惕然一以愧，永與情愛辭。","願識真妄本，染淨自分離。","羞慚滯五蓋，焉知同四依。","（見同書卷三一《引證部》）。"]', '["冬狐理豐毳，春蠶緒轻絲。","形骸翻爲阻，心識還自欺。","齠齓歌鼓腹，平生少年时。","驱车追俠客，酌酒弄妖姬。","但念目前好，安知後世悲。","惕然一以愧，永與情愛辞。","願識真妄本，染淨自分離。","羞慚滯五蓋，焉知同四依。","（见同书卷三一《引證部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十六 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3b03d5-9a4a-4ee3-8bfc-039fee9e5be8', '頌六十二首 二十七', '頌六十二首 二十七', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["賢人軌玄度，弱喪升虛遷。","師通資自發，神光照有緣。","應變各殊別，聖錄同靈篇。","乘乾因九五，逸響亮三千。","法鼓振玄教，龍飛應人天。","恬智冥微妙，縹𦕈詠重玄。","磐紆七七紀，嘉運莅中旛。","挺此四八姿，映蔚華林園。","（見同書卷三四《見解篇》）。"]', '["賢人軌玄度，弱喪升虛遷。","師通資自發，神光照有緣。","應变各殊別，聖錄同靈篇。","乘乾因九五，逸响亮三千。","法鼓振玄教，龙飞應人天。","恬智冥微妙，縹𦕈詠重玄。","磐紆七七紀，嘉運莅中旛。","挺此四八姿，映蔚华林园。","（见同书卷三四《见解篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十七 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23e94e9-27a3-4858-8254-e7499b4fbd86', '頌六十二首 二十八', '頌六十二首 二十八', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["善惡宿薰習，感報各殊方。","曾爲鬼害怨，或作狼讐殃。","屠兒憶殺業，須蜜戲獼鄉。","宿祐除患者，在處遊天堂。","觸類興清遘，目擊洞兼忘。","凡聖欽嘉會，賢愚慶流芳。","四生行善業，六趣感神光。","苦樂雖殊別，同知命短長。","（見同書卷三五《五通部》）。"]', '["善惡宿薰習，感報各殊方。","曾爲鬼害怨，或作狼讐殃。","屠兒憶殺業，須蜜戲獼乡。","宿祐除患者，在处游天堂。","觸類兴清遘，目擊洞兼忘。","凡聖欽嘉會，賢愚慶流芳。","四生行善業，六趣感神光。","苦乐雖殊別，同知命短长。","（见同书卷三五《五通部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十八 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1098ac3-515b-4a12-97b8-982a36c7e30d', '頌六十二首 二十九', '頌六十二首 二十九', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["志誠抱冰雪，暮齒迫桑榆。","太息波川迅，悲哉人代拘。","歲聿皆採穫，冬晚懼嚴枯。","精誠求施戒，忍精定慧眸。","結侶同共遠，勝地心相符。","商人不顧死，羅剎未能逾。","求寶竭大海，神怖捧明珠。","寄言求道者，立志菩提株。","（見同書卷三六《濟難部》）。"]', '["志誠抱冰雪，暮齒迫桑榆。","太息波川迅，悲哉人代拘。","歲聿皆採穫，冬晚懼嚴枯。","精誠求施戒，忍精定慧眸。","結侶同共远，勝地心相符。","商人不顧死，羅剎未能逾。","求寶竭大海，神怖捧明珠。","寄言求道者，立志菩提株。","（见同书卷三六《濟难部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 二十九 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ca24741-2c99-4b53-b3bc-c8ca2e6e5982', '頌六十二首 三十', '頌六十二首 三十', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["求寶失舟濟，飄浮思救形。","幻媚多方趣，妖魅誑人情。","假接度海難，虛發親愛聲。","自非馬王負，危苦詎安寧。","（見同書卷四二《妖怪篇》）。"]', '["求寶失舟濟，飄浮思救形。","幻媚多方趣，妖魅誑人情。","假接度海难，虛發親愛声。","自非马王負，危苦詎安寧。","（见同书卷四二《妖怪篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3819b114-2546-4682-9054-74139e852257', '頌六十二首 三十一', '頌六十二首 三十一', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["靜念遺志慮，有慮非理盡。","境來投虛空，虛空何所軫。","託陰遊重冥，冥亡影迹隕。","四果皆欣求，一乘獨玄泯。","（見同書卷四六《攝念部》）。"]', '["静念遺志慮，有慮非理尽。","境来投虛空，虛空何所軫。","託陰游重冥，冥亡影迹隕。","四果皆欣求，一乘独玄泯。","（见同书卷四六《攝念部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十一 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('392376e9-b440-4799-a49f-964b9b27cec0', '頌六十二首 三十二', '頌六十二首 三十二', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["賢人慕高節，志願菩提因。","御鶴翔伊水，策馬出王田。","本祈立弘誓，感報彌陁身。","能仁修八正，超逾九劫前。","聲流徧三界，慈化通大千。","掩塵息妄想，凡聖幷欣然。","含生同志趣，保益啓心神。","生死必永盡，豈同莊老仙。","（見同書同卷《發願篇》）。"]', '["賢人慕高節，志願菩提因。","御鹤翔伊水，策马出王田。","本祈立弘誓，感報彌陁身。","能仁修八正，超逾九劫前。","声流徧三界，慈化通大千。","掩塵息妄想，凡聖幷欣然。","含生同志趣，保益啓心神。","生死必永尽，豈同莊老仙。","（见同书同卷《發願篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十二 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d05349c0-c993-4eb4-8e9f-4b3d1c351fe2', '頌六十二首 三十三', '頌六十二首 三十三', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["藕樹交無極，華雲衣數重。","織竹能爲象，縛荻巧成龍。","落灰然蘂盛，垂油濕晝峰。","天宮儻若照，燈王復可逢。","（見同書卷四八《然燈部》）。"]', '["藕樹交無極，华云衣數重。","织竹能爲象，縛荻巧成龙。","落灰然蘂盛，垂油濕晝峰。","天宮儻若照，灯王复可逢。","（见同书卷四八《然灯部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十三 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7239d32f-e1f4-4a2d-acb6-f073d2cf4136', '頌六十二首 三十四', '頌六十二首 三十四', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["寶剎承高露，綺綵映空天。","宛轉雲間颺，倒下似紅蓮。","霞旛開錦色，香氣合爐煙。","飄颻無定所。","祇爲本輕旋。","池沼萬影現，泉弄百華鮮。","夙夜風吹動，重疊輪王因。","攀仰無猒足，結侶感流瞻。","何知色中綵，招福壽長年。","（見同書同卷《懸旛篇》）。"]', '["寶剎承高露，綺綵映空天。","宛轉云间颺，倒下似紅蓮。","霞旛开錦色，香氣合爐煙。","飄颻無定所。","祇爲本轻旋。","池沼万影現，泉弄百华鲜。","夙夜风吹动，重叠輪王因。","攀仰無猒足，結侶感流瞻。","何知色中綵，招福壽长年。","（见同书同卷《懸旛篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十四 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e400b7c-77b8-4abd-8b41-98123cc7d92d', '頌六十二首 三十五', '頌六十二首 三十五', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["久猒無明樹，方欣柰苑華。","始入香山路，仍逢火宅車。","慈父屢引接，幼子背恩賒。","雖悟危藤鼠，終悲在篋虵。","鹿苑禪林茂，鷲嶺動枝柯。","定華發智果，乘空具度河。","法雨時時落，香雲片片多。","若爲將羽化，來濟在塵羅。","（見同書卷四九《華香篇》）。"]', '["久猒無明樹，方欣柰苑华。","始入香山路，仍逢火宅车。","慈父屢引接，幼子背恩賒。","雖悟危藤鼠，終悲在篋虵。","鹿苑禪林茂，鷲嶺动枝柯。","定华發智果，乘空具度河。","法雨时时落，香云片片多。","若爲將羽化，来濟在塵羅。","（见同书卷四九《华香篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十五 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1089496f-f6cc-4a47-b8ed-c9cd6b8eb521', '頌六十二首 三十六', '頌六十二首 三十六', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["玄風冠西土，內範軼東矜。","大川開寶匣，福地下金繩。","繡松高可暎，畫栱氎相承。","日馭非難假，雲師本易憑。","陽樓疑難燧，陰軒類鑿冰。","迥題飛星沒，長楣宿露凝。","旌門曙光轉，輦道夕雲蒸。","祇桓多靈物，竹園滿休徵。","虛薄筆難紀，微驅竊自凌。","優遊從可恃，恩蔭永難勝。","（見同書卷五二《致敬部》）。"]', '["玄风冠西土，內範軼东矜。","大川开寶匣，福地下金繩。","繡松高可暎，畫栱氎相承。","日馭非难假，云師本易憑。","陽楼疑难燧，陰軒類鑿冰。","迥題飞星沒，长楣宿露凝。","旌门曙光轉，輦道夕云蒸。","祇桓多靈物，竹园满休徵。","虛薄笔难紀，微驱竊自凌。","優游從可恃，恩蔭永难勝。","（见同书卷五二《致敬部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十六 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727abbfd-ed5a-4982-9783-c65702d852e4', '頌六十二首 三十七', '頌六十二首 三十七', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["金軀遺散骨，寶塔徧天龍。","創開於十塔，終成八萬興。","珠蓋靈光變，剎柱吐芙蓉。","屢開朝霧露，數示曉靈徵。","紅霓相映發，風搖響和鐘。","仙鸞往往見，神僧數數從。","獨超群聖上，合識普生恭。","砧碓擊不碎，方知聖叵窮。","（見同書卷五三《感福部》）（按：《明州阿育王山志》卷十錄此首，題作《頌佛舍利》。","）。"]', '["金軀遺散骨，寶塔徧天龙。","創开於十塔，終成八万兴。","珠蓋靈光变，剎柱吐芙蓉。","屢开朝霧露，數示晓靈徵。","紅霓相映發，风搖响和鐘。","仙鸾往往见，神僧數數從。","独超群聖上，合識普生恭。","砧碓擊不碎，方知聖叵窮。","（见同书卷五三《感福部》）（按：《明州阿育王山志》卷十錄此首，題作《頌佛舍利》。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十七 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc1f56b-6316-4077-bcfd-c3906e2590ee', '頌六十二首 三十八', '頌六十二首 三十八', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["法會設佳供，齋日感神靈。","普召無別請，客主發休禎。","凡聖俱晨往，災難普安寧。","良由慈善力，翻惡就福城。","（見同書卷五五《施福部》）。"]', '["法會設佳供，斋日感神靈。","普召無別請，客主發休禎。","凡聖俱晨往，災难普安寧。","良由慈善力，翻惡就福城。","（见同书卷五五《施福部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十八 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf325b42-3b05-4c56-af61-866142de6437', '頌六十二首 三十九', '頌六十二首 三十九', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["六情無福志，四攝啓幽心。","儉約避人物，偃息慕山林。","曲𡼏停騶響，交枝落慢陰。","池臺聚凍雪，簷牖參歸禽。","石來無新故，峯形詎古今。","大車何杳杳，奔馬送駸駸。","何以修六念，虔誠枉一音。","未泛慈舟寶，徒勞抒海深。","（見同書卷五九《儉約篇》）。"]', '["六情無福志，四攝啓幽心。","儉約避人物，偃息慕山林。","曲𡼏停騶响，交枝落慢陰。","池台聚凍雪，簷牖參归禽。","石来無新故，峯形詎古今。","大车何杳杳，奔马送駸駸。","何以修六念，虔誠枉一音。","未泛慈舟寶，徒勞抒海深。","（见同书卷五九《儉約篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 三十九 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57221fff-3e0f-4dcb-9603-186637a5f7fe', '頌六十二首 四十', '頌六十二首 四十', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["業風恒泛濫，苦海濤波聲。","漂我常游浪，遠離湼槃城。","忽遇（一作「何時」）慈舟至，運我出愛瀛。","是（一作「寔」）知高慕友（一作「施」），懲過改凡（一作「頓捨貧窮」）情。","罪垢蒙除結，神珠啓闇冥。","釋（一作「貴」）門光麗景（一作「景麗」），俗務苦重縈（一作「賤業永休寧」）。","冀除五昏蓋，方悟六塵輕。","自非乘寶輅，何以息燄寧（一作「志求八解脫，誓捨六塵縈。","儻遇慈父誨，開我心中經。","」）（見同書卷六十《懲過篇》。","注一作者，爲同書卷七一《貧女部》之異文。","）。"]', '["業风恒泛濫，苦海濤波声。","漂我常游浪，远離湼槃城。","忽遇（一作「何时」）慈舟至，運我出愛瀛。","是（一作「寔」）知高慕友（一作「施」），懲過改凡（一作「頓捨貧窮」）情。","罪垢蒙除結，神珠啓闇冥。","釋（一作「貴」）门光丽景（一作「景丽」），俗務苦重縈（一作「賤業永休寧」）。","冀除五昏蓋，方悟六塵轻。","自非乘寶輅，何以息燄寧（一作「志求八解脫，誓捨六塵縈。","儻遇慈父誨，开我心中經。","」）（见同书卷六十《懲過篇》。","注一作者，爲同书卷七一《貧女部》之異文。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('562be31a-04f1-422e-a849-3c20e8ac2381', '頌六十二首 四十一', '頌六十二首 四十一', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["善惡自相違，明闇不同上。","聖人愍迷徒，乘機入生死。","慕德祛囂塵，徵心見真理。","擇交惡自終，出苦方有死。","（見同書卷六四《擇交篇》）。"]', '["善惡自相違，明闇不同上。","聖人愍迷徒，乘機入生死。","慕德祛囂塵，徵心见真理。","擇交惡自終，出苦方有死。","（见同书卷六四《擇交篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十一 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f9037de-0ea4-4344-97bf-7c0b3f970294', '頌六十二首 四十二', '頌六十二首 四十二', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["峨峨王舍城，鬱鬱靈竹園。","中有神化長，巧誘入幽玄。","善人募授福，惡友樂讎怨。","善惡昇沉異，薰蕕別路門。","（見同書同卷《惡交篇》）（按：《古今禪藻集》卷一、《古詩紀》卷一二八收此首爲隋無名釋典詩，丁福保、逯欽立皆從之，實誤。","）。"]', '["峨峨王舍城，鬱鬱靈竹园。","中有神化长，巧誘入幽玄。","善人募授福，惡友乐讎怨。","善惡昇沉異，薰蕕別路门。","（见同书同卷《惡交篇》）（按：《古今禪藻集》卷一、《古诗紀》卷一二八收此首爲隋無名釋典诗，丁福保、逯欽立皆從之，實誤。","）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十二 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd125645-8b91-4862-9da6-a3ffb0f1eef1', '頌六十二首 四十三', '頌六十二首 四十三', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["眷屬多孜擾，染著亂心神。","親疎未可定，何得偏憎憐。","乾城無片實，渴鹿諍燄塵。","息心上空響，廢念心真源。","（見同書卷六五《離著部》）。"]', '["眷屬多孜擾，染著亂心神。","親疎未可定，何得偏憎怜。","乾城無片實，渴鹿諍燄塵。","息心上空响，廢念心真源。","（见同书卷六五《離著部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十三 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ce8731-b63b-475f-bc04-0aa1617ba392', '頌六十二首 四十四', '頌六十二首 四十四', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["樞機巧對辯，善誘令心伏。","八水潤焦芽，三明啓瞽目。","來問各不同，詶答皆芬郁。","冀捨四龍驚，亦除二鼠逼。","意樹發空華，心蓮吐輕馥。","喻此滄海變，譬彼庵羅熟。","妙智方縟錦，詞深同霧縠。","善學乖梵爪，真言異鍱腹。","（見同書卷六六《羅漢部》）。"]', '["樞機巧对辯，善誘令心伏。","八水潤焦芽，三明啓瞽目。","来问各不同，詶答皆芬郁。","冀捨四龙驚，亦除二鼠逼。","意樹發空华，心蓮吐轻馥。","喻此滄海变，譬彼庵羅熟。","妙智方縟錦，词深同霧縠。","善学乖梵爪，真言異鍱腹。","（见同书卷六六《羅漢部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十四 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8e5f794-33b0-4b64-b080-8e0a49d44908', '頌六十二首 四十五', '頌六十二首 四十五', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["愛網結心闇，貪癡背智明。","雖蒙慧炬照，愚昧猶自盲。","頑戇恒不覺，慧種未開萌。","自非慕高友，何得悟神英。","（見同書同卷《雜癡部》）。"]', '["愛網結心闇，貪癡背智明。","雖蒙慧炬照，愚昧猶自盲。","頑戇恒不覺，慧種未开萌。","自非慕高友，何得悟神英。","（见同书同卷《杂癡部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十五 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a08f98f9-f31c-4d7a-b5a1-a2762d837eb3', '頌六十二首 四十六', '頌六十二首 四十六', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["正邪乖明昧，善惡異相征。","大慈降梵志，乘空各變形。","六千俱捨執，七衆各休禎。","邪徒虛抗志，鍱腹浪求名。","身子多才智，陵化照機庭。","四辯無不可，六通奮英情。","乘權摧異見，伏邪同幽冥。","自知螢光劣，徒諍太陽精。","（見同書卷六八《破邪篇》）。"]', '["正邪乖明昧，善惡異相征。","大慈降梵志，乘空各变形。","六千俱捨執，七衆各休禎。","邪徒虛抗志，鍱腹浪求名。","身子多才智，陵化照機庭。","四辯無不可，六通奮英情。","乘權摧異见，伏邪同幽冥。","自知螢光劣，徒諍太陽精。","（见同书卷六八《破邪篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十六 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54e75b8c-a11b-4701-99e0-19e69f2e40b8', '頌六十二首 四十七', '頌六十二首 四十七', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["貴富諍人我，貪賤自然羞。","强弱相辜負，鬬訟未曾休。","恥恨相侵奪，覓便報其讐。","怨結恒對值，累劫常苦愁。","（見同書卷七二《諍訟篇》）。"]', '["貴富諍人我，貪賤自然羞。","强弱相辜負，鬬訟未曾休。","恥恨相侵奪，覓便報其讐。","怨結恒对值，累劫常苦愁。","（见同书卷七二《諍訟篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十七 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20758a0e-2afb-4185-bdb7-32348b63f6f1', '頌六十二首 四十八', '頌六十二首 四十八', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["沉痾誠已久，痼疾實難痊。","四魔恒相嬈，六賊競來牽。","困厄無人救，惟忻大慈憐。","遙愍愚心網，振錫遠乘煙。","授茲甘露藥，邪見莫能先。","消災除業累，拔濟苦相煎。","恩流振玄教，普利該大千。","自非神咒力，何能益延年。","（見同書卷七五《雜咒部》）。"]', '["沉痾誠已久，痼疾實难痊。","四魔恒相嬈，六賊競来牽。","困厄無人救，惟忻大慈怜。","遙愍愚心網，振錫远乘煙。","授茲甘露藥，邪见莫能先。","消災除業累，拔濟苦相煎。","恩流振玄教，普利該大千。","自非神咒力，何能益延年。","（见同书卷七五《杂咒部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十八 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44176d6-fbd3-4d36-b484-94cfc028c2d1', '頌六十二首 四十九', '頌六十二首 四十九', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["玄言始開闡，雲霧上昇天。","靉靆垂下布，駛雨徧山園。","百草俱滋茂，五穀皆熟田。","自非慈福力，豈感樂豐年。","（見同書卷七九《河海部》）。"]', '["玄言始开闡，云霧上昇天。","靉靆垂下布，駛雨徧山园。","百草俱滋茂，五穀皆熟田。","自非慈福力，豈感乐豐年。","（见同书卷七九《河海部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 四十九 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc02f16-d398-417a-9065-44e7059d528e', '頌六十二首 五十', '頌六十二首 五十', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["祇園感神夾，鹿苑化拘隣。","聖人居福地，賢士樂山園。","乍聞千葉現，時動百華鮮。","香草皆滿地，靈芝徧房前。","甘池流八水，神井涌九泉。","華旛高颻颺，應感下飛仙。","鳥弄千聲囀，人歌百福田。","盛哉茲勝處，誰見不留連。","（見同書卷八十《種子部》）。"]', '["祇园感神夾，鹿苑化拘隣。","聖人居福地，賢士乐山园。","乍闻千葉現，时动百华鲜。","香草皆满地，靈芝徧房前。","甘池流八水，神井涌九泉。","华旛高颻颺，應感下飞仙。","鸟弄千声囀，人歌百福田。","盛哉茲勝处，誰见不留連。","（见同书卷八十《種子部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('526cfc19-1709-4460-94bd-82b8c480efe0', '頌六十二首 五十一', '頌六十二首 五十一', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["能仁矜幻苦，聖意愍重昏。","哀愚開攝受，訓誘方便門。","法身徧法界，攝化指祇園。","俱銷五道縛，共解四魔怨。","三修祛愛馬，六念靜心猿。","禪池澄定水，覺意動聲喧。","慧風吹法鼓，振我無明塵。","常須近善友，開我未曾聞。","（見同書卷八一《觀苦部》）。"]', '["能仁矜幻苦，聖意愍重昏。","哀愚开攝受，訓誘方便门。","法身徧法界，攝化指祇园。","俱銷五道縛，共解四魔怨。","三修祛愛马，六念静心猿。","禪池澄定水，覺意动声喧。","慧风吹法鼓，振我無明塵。","常須近善友，开我未曾闻。","（见同书卷八一《观苦部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十一 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5820bbf-3abe-404c-97b1-47281d99702f', '頌六十二首 五十二', '頌六十二首 五十二', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["普親皆眷屬，隔世即相欺。","但求現在樂，不知來苦資。","牽我入三塗，楚痛受萬危。","自非慈放捨，何得命延時。","（見同書卷八二《放生篇》）。"]', '["普親皆眷屬，隔世即相欺。","但求現在乐，不知来苦資。","牽我入三塗，楚痛受万危。","自非慈放捨，何得命延时。","（见同书卷八二《放生篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十二 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e2c15c-cb12-4fd3-8900-130a78c772a4', '頌六十二首 五十三', '頌六十二首 五十三', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["盛年好放逸，凶猛勸不移。","天長曉露促，生老病來資。","百節俱酸痛，千痾幷著時。","華堂相一捨，幽塗萬苦㧗。","（見同書卷八四《地獄部》）。"]', '["盛年好放逸，凶猛勸不移。","天长晓露促，生老病来資。","百節俱酸痛，千痾幷著时。","华堂相一捨，幽塗万苦㧗。","（见同书卷八四《地獄部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十三 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c52af08a-9b4c-45d9-8e25-725ae4bd34f6', '頌六十二首 五十四', '頌六十二首 五十四', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["尋因途乃異，及捨趣猶幷。","苦極思歸樂，樂極苦還生。","豈非罪福別，皆由對著情。","若斷有漏業，常見法身寧。","（見同書卷八八《福行部》）。"]', '["尋因途乃異，及捨趣猶幷。","苦極思归乐，乐極苦還生。","豈非罪福別，皆由对著情。","若斷有漏業，常见法身寧。","（见同书卷八八《福行部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十四 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea3b358-2e8c-47d8-aa14-0d4a0c7a0c33', '頌六十二首 五十五', '頌六十二首 五十五', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["四生誠易轉，五陰病難痊。","壽報雖延促，終成丘墓塵。","徒知餌六色，會當悲九泉。","復愍輪迴趣，難成不壞身。","（見同書卷八九《五生部》）。"]', '["四生誠易轉，五陰病难痊。","壽報雖延促，終成丘墓塵。","徒知餌六色，會當悲九泉。","复愍輪迴趣，难成不壞身。","（见同书卷八九《五生部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十五 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c79985-29a5-4e51-a1db-8c913e9db290', '頌六十二首 五十六', '頌六十二首 五十六', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["邈邈愛王城，峨峨欣鷲嶺。","業結三界獄，利鈍十使頸。","濁惡順下趣，斷漏升上頂。","著我甘苦報，怖象投丘井。","翹翹羨化倫，念念除心癭。","宿祐遇釋尊，高慕大仙穎。","既破無明結，還同欣鷲嶺。","荷戢怡沖心，隨憇靡不靜。","（見同書卷九十《斷障部》）。"]', '["邈邈愛王城，峨峨欣鷲嶺。","業結三界獄，利鈍十使頸。","濁惡順下趣，斷漏升上頂。","著我甘苦報，怖象投丘井。","翹翹羨化倫，念念除心癭。","宿祐遇釋尊，高慕大仙穎。","既破無明結，還同欣鷲嶺。","荷戢怡沖心，隨憇靡不静。","（见同书卷九十《斷障部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十六 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47e8cc7-6ad6-480e-a07f-9758e8c3a13f', '頌六十二首 五十七', '頌六十二首 五十七', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["五體悔前朝，三屈懺中夕。","鳴椎誡旭旦，哀我苦勞役。","引目寓金言，悲傷塵垢積。","咄哉形非我，嗟往恒沉溺。","踟躕歧路嵎，揮手謝中折。","洗滌歸誠懺，皎潔凌雲釋。","蕭索業苦離，升陟隨緣益。","雖未齊高蹤，且免幽途歷。","（見同書卷一百三《洗懺部》）。"]', '["五體悔前朝，三屈懺中夕。","鳴椎誡旭旦，哀我苦勞役。","引目寓金言，悲傷塵垢積。","咄哉形非我，嗟往恒沉溺。","踟躕歧路嵎，揮手謝中折。","洗滌归誠懺，皎潔凌云釋。","蕭索業苦離，升陟隨緣益。","雖未齊高蹤，且免幽途歷。","（见同书卷一百三《洗懺部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十七 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('279a95c3-9219-4492-ba33-4a36f8deeb46', '頌六十二首 五十八', '頌六十二首 五十八', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["大慈振法鼓，開悟無明聾。","鑪冶心穢垢，防非如利鋒。","護鵝不惜命，守草養生同。","五篇遮輕重，七聚蕩心胸。","晨朝宣寶偈，夕夜虔誠恭。","近求出苦海，遠念法身蹤。","七支淨三業，五分滿金容。","各願堅固戒，淨土得相逢。","（見同書卷一百七《三聚部》）。"]', '["大慈振法鼓，开悟無明聾。","鑪冶心穢垢，防非如利鋒。","護鵝不惜命，守草養生同。","五篇遮轻重，七聚蕩心胸。","晨朝宣寶偈，夕夜虔誠恭。","近求出苦海，远念法身蹤。","七支淨三業，五分满金容。","各願堅固戒，淨土得相逢。","（见同书卷一百七《三聚部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十八 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9de538-0b54-4ab3-a58b-97e62e800936', '頌六十二首 五十九', '頌六十二首 五十九', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["愚夫貪世利，俗士重虛名。","三空既難辯，八風恒易傾。","物我久空性，色心仍自縈。","盛年愛華好，老死丘墓成。","居高非慮禍，持滿不憂盈。","名利甘刀害，將非安久禎。","凡愚苟求利，譬犬見穢精。","不知禍來至，焉知怨苦聲。","（見同書卷一百十一《利害篇》）。"]', '["愚夫貪世利，俗士重虛名。","三空既难辯，八风恒易傾。","物我久空性，色心仍自縈。","盛年愛华好，老死丘墓成。","居高非慮禍，持满不憂盈。","名利甘刀害，將非安久禎。","凡愚苟求利，譬犬见穢精。","不知禍来至，焉知怨苦声。","（见同书卷一百十一《利害篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 五十九 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf5fe07-d5d5-4eda-9ee2-1df0af303bd6', '頌六十二首 六十', '頌六十二首 六十', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["噉他身血肉，貪毒無慈矜。","養茲身穢質，蟲㝢內消融。","不護僧淨器，受此厠中蟲。","後報入地獄，苦痛未知窮。","（見同書卷一百十三《便利部》）。"]', '["噉他身血肉，貪毒無慈矜。","養茲身穢質，蟲㝢內消融。","不護僧淨器，受此厠中蟲。","後報入地獄，苦痛未知窮。","（见同书卷一百十三《便利部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 六十 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7302cb31-458f-4694-97e8-72fe0c811a48', '頌六十二首 六十一', '頌六十二首 六十一', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["紫紈未可得，漳濱徒再離。","一逢犬馬病，賁育罷驅馳。","既無九轉術，復闕萬金奇。","不看授鹽掌，唯夢蓮華池。","（見同書卷一百十四《安置部》）。"]', '["紫紈未可得，漳濱徒再離。","一逢犬马病，賁育罷驱驰。","既無九轉術，复闕万金奇。","不看授鹽掌，唯梦蓮华池。","（见同书卷一百十四《安置部》）。"]', '诗', 'shi', '', NULL, '頌六十二首 六十一 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7563aa8e-3e7f-4fa0-ac22-bb2bca62a020', '頌六十二首 六十二', '頌六十二首 六十二', '45ec1e8a-5035-44ae-820a-37d7ef0f4d0c', '唐', '["龔勝無遺生，季業有窮盡。","嵇叟理既迫，霍子命亦殞。","屢屢厚霜指，納納衝風菌。","邂逅竟既時，脩短非所慜。","恨我君子志，不得嚴上泯。","送心正覺前，斯痛久已忍。","既知人我空，何愁心不謹。","唯願乘來生，怨親同誠朕。","（見同書卷一百十五《捨身篇》）。"]', '["龔勝無遺生，季業有窮尽。","嵇叟理既迫，霍子命亦殞。","屢屢厚霜指，納納衝风菌。","邂逅竟既时，脩短非所慜。","恨我君子志，不得嚴上泯。","送心正覺前，斯痛久已忍。","既知人我空，何愁心不謹。","唯願乘来生，怨親同誠朕。","（见同书卷一百十五《捨身篇》）。"]', '诗', 'shi', '', NULL, '頌六十二首 六十二 道世 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c86bec-ba25-4d81-a6f2-7753ac618047', '澄州無虞縣清泰鄉都萬里六合堅固大宅詩（五言）', '澄州無虞縣清泰乡都万里六合堅固大宅诗（五言）', '0b525329-b398-47d4-80b5-5999869f88cf', '唐', '["近濆縱橫越，募岱去來闌。","千岑爲□絕，三峽以衢難。","庶捷猶求跨，郡攘□能觀。","苦固於茲第，永世保無殘。","（見廣西上林縣麒麟山唐永淳元年立《六合堅固大宅頌》碑附。","轉錄自《廣西少數民族地區石刻碑文集》。","）。"]', '["近濆縱橫越，募岱去来闌。","千岑爲□絕，三峽以衢难。","庶捷猶求跨，郡攘□能观。","苦固於茲第，永世保無殘。","（见廣西上林縣麒麟山唐永淳元年立《六合堅固大宅頌》碑附。","轉錄自《廣西少數民族地區石刻碑文集》。","）。"]', '诗', 'shi', '', NULL, '澄州無虞縣清泰鄉都萬里六合堅固大宅詩（五言） 韋敬辨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49543d46-144f-4f04-9c42-4012f60937ee', '詠竹（卒章）', '詠竹（卒章）', 'efbf18f9-0e1e-4ef1-86d8-c947ae853919', '唐', '["別有鄰人笛，偏傷懷舊情。","（廖彩樑《乾陵稽古》收崔融撰《大唐故中書令贈光祿大夫秦州都督薛公墓誌銘》引。","墓誌爲近年於乾陵陪葬墓出土。","）（〖1〗《薛公墓誌銘》：「八歲，善屬文。","時房玄齡、虞世南試公詠竹，援毫立就，卒章云〖詩略〗。","玄齡等即公之父黨，深所感歎。","」）。"]', '["別有鄰人笛，偏傷懷旧情。","（廖彩樑《乾陵稽古》收崔融撰《大唐故中书令贈光祿大夫秦州都督薛公墓誌銘》引。","墓誌爲近年於乾陵陪葬墓出土。","）（〖1〗《薛公墓誌銘》：「八歲，善屬文。","时房玄齡、虞世南試公詠竹，援毫立就，卒章云〖诗略〗。","玄齡等即公之父黨，深所感歎。","」）。"]', '诗', 'shi', '', NULL, '詠竹（卒章） 薛元超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('180c1a2f-6df5-4a76-a40c-74f66c8f5edf', '詩（幷序） 一', '诗（幷序） 一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["遙看世間人，村坊安社邑。","一家有死生，合村相就泣。","張口哭他屍，不知身去急。","本是長眠鬼，蹔來地上立。","欲似養兒氈，迴乾且就濕。","前死深埋却，後死續即人。"]', '["遙看世间人，村坊安社邑。","一家有死生，合村相就泣。","張口哭他屍，不知身去急。","本是长眠鬼，蹔来地上立。","欲似養兒氈，迴乾且就濕。","前死深埋却，後死續即人。"]', '诗', 'shi', '', NULL, '詩（幷序） 一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5437dfee-9c37-4397-866f-44551f17cfb6', '詩（幷序） 二', '诗（幷序） 二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["吾富有錢時，婦兒看我好。","吾若脫衣裳，與吾疊袍襖。","吾出經（一作「絰」）求去，送吾即上道。","將錢入舍來，見吾滿面笑。","遶吾白鴿旋，恰似鸚鵡鳥。","邂逅暫時貧，看吾即貌哨（戴密微校作「藐峭」）。","人有七貧時，七富還相報。","徒（《大正藏》作「從」，項、袁謂通「圖」，不誤。","）財不顧人，且看來時道。"]', '["吾富有錢时，婦兒看我好。","吾若脫衣裳，與吾叠袍襖。","吾出經（一作「絰」）求去，送吾即上道。","將錢入舍来，见吾满面笑。","遶吾白鴿旋，恰似鸚鵡鸟。","邂逅暫时貧，看吾即貌哨（戴密微校作「藐峭」）。","人有七貧时，七富還相報。","徒（《大正藏》作「從」，項、袁謂通「圖」，不誤。","）財不顧人，且看来时道。"]', '诗', 'shi', '', NULL, '詩（幷序） 二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dcfdef5-298d-4ebf-97fb-e2a65e45d917', '詩（幷序） 三', '诗（幷序） 三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["家口總死盡，吾死無親表（張改作「衰」，郭校作「哀」）。","急首賣（一作「買」）資產，與設逆修齋。","託生得好處，身死雇人埋。","錢財隣保出，任你自相差。"]', '["家口總死尽，吾死無親表（張改作「衰」，郭校作「哀」）。","急首賣（一作「買」）資產，與設逆修斋。","託生得好处，身死雇人埋。","錢財隣保出，任你自相差。"]', '诗', 'shi', '', NULL, '詩（幷序） 三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54799a77-2bd2-4d69-8c4d-7b5cf5f3a25e', '詩（幷序） 四', '诗（幷序） 四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["身如圈裏羊，命報恰（一作「怜「）相當。","羊即披毛走，人著好衣裳。","脫衣（一作「却」）赤體立，刑（一作「則」）役不如羊。","羊即日日死，人還日日亡。","從頭捉將去，還同肥好羊。","羊（一作「人」）即辛苦死，人去無破傷。","命絕逐他走，魂魄歷他鄉。","有錢多造福，喫著好衣裳。","愚人廣造罪，志（張改作「智」）者好思量。"]', '["身如圈裏羊，命報恰（一作「怜「）相當。","羊即披毛走，人著好衣裳。","脫衣（一作「却」）赤體立，刑（一作「則」）役不如羊。","羊即日日死，人還日日亡。","從头捉將去，還同肥好羊。","羊（一作「人」）即辛苦死，人去無破傷。","命絕逐他走，魂魄歷他乡。","有錢多造福，喫著好衣裳。","愚人廣造罪，志（張改作「智」）者好思量。"]', '诗', 'shi', '', NULL, '詩（幷序） 四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a9c6ac1-6c15-4bb5-8d0c-2c6b038e71c1', '詩（幷序） 五', '诗（幷序） 五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["可笑世間人，癡多黠者少。","不愁死路長，貪著苦煩惱。","夜眠遊鬼界，天曉歸人道。","忽起相羅拽，啾唧索租調。","貧苦無處得，相接被鞭拷（一作「𢭦」）。","生時有苦痛，不如早死好。"]', '["可笑世间人，癡多黠者少。","不愁死路长，貪著苦煩惱。","夜眠游鬼界，天晓归人道。","忽起相羅拽，啾唧索租調。","貧苦無处得，相接被鞭拷（一作「𢭦」）。","生时有苦痛，不如早死好。"]', '诗', 'shi', '', NULL, '詩（幷序） 五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88cf75e5-95c4-45cb-a34d-6112bf5dbd5d', '詩（幷序） 六', '诗（幷序） 六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["他家笑吾貧，吾貧（五貧）極快樂。","無牛亦無馬，不愁賊（一作「賤」）抄掠。","你富戶役高，差（一作「羞」）科並用却。","吾無呼喚處，飽喫長展脚。","你富披錦袍，尋常被纒縛。","窮苦無煩惱，草衣隨體著。"]', '["他家笑吾貧，吾貧（五貧）極快乐。","無牛亦無马，不愁賊（一作「賤」）抄掠。","你富戶役高，差（一作「羞」）科並用却。","吾無呼喚处，飽喫长展脚。","你富披錦袍，尋常被纒縛。","窮苦無煩惱，草衣隨體著。"]', '诗', 'shi', '', NULL, '詩（幷序） 六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa6643e-e24a-4566-95f7-1c267efdc519', '詩（幷序） 七', '诗（幷序） 七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["大有愚（一作「禺」）癡君，獨身無兒子。","廣貪多覓財，養奴多養婢。","伺（張改作「司」，項以爲不誤。","）命門前喚，不容（一作「客」）別隣里。","死得四片板，一條黃衾被。","錢財奴婢用，任將別經（一作「絰」）紀。","有錢不解用，空手入都市（一作「示」）。"]', '["大有愚（一作「禺」）癡君，独身無兒子。","廣貪多覓財，養奴多養婢。","伺（張改作「司」，項以爲不誤。","）命门前喚，不容（一作「客」）別隣里。","死得四片板，一條黄衾被。","錢財奴婢用，任將別經（一作「絰」）紀。","有錢不解用，空手入都市（一作「示」）。"]', '诗', 'shi', '', NULL, '詩（幷序） 七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d5505e-7916-4f07-a110-254910975f37', '詩（幷序） 八', '诗（幷序） 八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["沉淪三惡道，家內無人知。","有衣不能著，有馬不能騎。","有奴不能使，有婢不相隨。","有食不能喫，向前恒受饑。","冥冥地獄苦，難見出頭時。","依巡（一作「相逐」）次第去，却活知有誰。"]', '["沉淪三惡道，家內無人知。","有衣不能著，有马不能騎。","有奴不能使，有婢不相隨。","有食不能喫，向前恒受饑。","冥冥地獄苦，难见出头时。","依巡（一作「相逐」）次第去，却活知有誰。"]', '诗', 'shi', '', NULL, '詩（幷序） 八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ba2766-a815-4cde-be94-394f60871e21', '詩（幷序） 九', '诗（幷序） 九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["沉淪三惡道，負持（一作「時」，松尾良樹謂應作「特」）愚癡鬼。","荒忙身卒死，即遍（張改「追」，項校作「屬」）伺（張改作「司」）命使。","反縛棒打走，先渡奈何水。","倒拽至廳前，枷棒這（張改「遍」，郭云不誤。","）身起。","死經一七日，刑名受罪鬼。","牛頭鐵叉杈，獄（從項說補）卒（此字據《大正藏》補）把刀搨。","碓[擣]（檮）磑磨身，覆生還覆（項校作「復」）死。"]', '["沉淪三惡道，負持（一作「时」，松尾良樹謂應作「特」）愚癡鬼。","荒忙身卒死，即遍（張改「追」，項校作「屬」）伺（張改作「司」）命使。","反縛棒打走，先渡奈何水。","倒拽至廳前，枷棒這（張改「遍」，郭云不誤。","）身起。","死經一七日，刑名受罪鬼。","牛头鐵叉杈，獄（從項说補）卒（此字據《大正藏》補）把刀搨。","碓[擣]（檮）磑磨身，覆生還覆（項校作「复」）死。"]', '诗', 'shi', '', NULL, '詩（幷序） 九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2912f38-7cc5-41cb-bbd3-2a02096dbbfc', '詩（幷序） 十', '诗（幷序） 十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["撩亂失精神，無由見家裏。","妻是他人妻（一作「事」），兒被後翁使。","駟馬被金鞍，鏤鐙銀鞦轡。","角弓無主張，寶劍拋著地。","設却百日齋，渾家忘却你。","錢財他人用，古來尋常事。","前人多貯積，後人無慚愧。","此是守財奴，不兌（張改作「免」）貧窮事。"]', '["撩亂失精神，無由见家裏。","妻是他人妻（一作「事」），兒被後翁使。","駟马被金鞍，鏤鐙銀鞦轡。","角弓無主張，寶劍拋著地。","設却百日斋，渾家忘却你。","錢財他人用，古来尋常事。","前人多貯積，後人無慚愧。","此是守財奴，不兌（張改作「免」）貧窮事。"]', '诗', 'shi', '', NULL, '詩（幷序） 十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c37fc873-d348-4597-98ba-7b54763fcdb6', '詩（幷序） 十一', '诗（幷序） 十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["夫婦相對坐，千年亦不足。","一箇病着床，遙看手不[觸]（𧢻）。","正報到頭來，徒費將錢卜。","寶物積如山，死得一棺木。","空手把兩拳，口裏徒含玉。","永離臺上鏡，無心開（一作「關」）衣眠（戴、松尾校作「服」）。","鏡裏（戴、項校作「匣」）塵滿中，剪刀生衣醭。"]', '["夫婦相对坐，千年亦不足。","一箇病着床，遙看手不[觸]（𧢻）。","正報到头来，徒費將錢卜。","寶物積如山，死得一棺木。","空手把兩拳，口裏徒含玉。","永離台上镜，無心开（一作「关」）衣眠（戴、松尾校作「服」）。","镜裏（戴、項校作「匣」）塵满中，剪刀生衣醭。"]', '诗', 'shi', '', NULL, '詩（幷序） 十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2ee1ed4-a31f-4a54-b10c-8e13863086a5', '詩（幷序） 十二', '诗（幷序） 十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["平坐歌舞處，無由更習曲。","琵琶絕巧（一作「咲」）聲，琴絃斷不續。","花帳（一作「悵」）後人眠，前人自薄福。","生坐七寶堂，死入土角觸（郭校作「䚥」）。","喪車相勾牽，鬼朴還相哭。","日理（項、松尾校作「埋」）幾千般，光影急迅速。"]', '["平坐歌舞处，無由更習曲。","琵琶絕巧（一作「咲」）声，琴絃斷不續。","花帳（一作「悵」）後人眠，前人自薄福。","生坐七寶堂，死入土角觸（郭校作「䚥」）。","喪车相勾牽，鬼朴還相哭。","日理（項、松尾校作「埋」）幾千般，光影急迅速。"]', '诗', 'shi', '', NULL, '詩（幷序） 十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131c2c06-11bf-4046-b182-3df46901864f', '詩（幷序） 十三', '诗（幷序） 十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["富者辦棺木，貧窮席裹（一作「裏」）角。","相共唱奈河（周校作「何」），送着空塚各（項校作「閣」）。","千休即萬休，永別生平樂。","志（張改作「智」）者入西方，愚人墮地獄。","掇（一作「{扌鵽}」，黃、項校作「綴」）頭入苦海，冥冥不省覺。","擎頭鄉里行，事當逞靴襖。","有錢但著用，莫作千年調。"]', '["富者辦棺木，貧窮席裹（一作「裏」）角。","相共唱奈河（周校作「何」），送着空塚各（項校作「閣」）。","千休即万休，永別生平乐。","志（張改作「智」）者入西方，愚人墮地獄。","掇（一作「{扌鵽}」，黄、項校作「綴」）头入苦海，冥冥不省覺。","擎头乡里行，事當逞靴襖。","有錢但著用，莫作千年調。"]', '诗', 'shi', '', NULL, '詩（幷序） 十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c0a00d0-e8e5-42b8-8fee-89fdf2ba09d6', '詩（幷序） 十四', '诗（幷序） 十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["百歲乃有一人，得七十者稀。","張眼看他死，不能自覺知。","癡皮裹膿血，頑骨強相隨。","兩步行衣架，步步入阿鼻。","雙盲不識鬼，伺命急來追。","赤繩串著項，反縛棒脊（一作「背」）皮。","露頭赤脚走，身上無衣被。","。"]', '["百歲乃有一人，得七十者稀。","張眼看他死，不能自覺知。","癡皮裹膿血，頑骨強相隨。","兩步行衣架，步步入阿鼻。","雙盲不識鬼，伺命急来追。","赤繩串著項，反縛棒脊（一作「背」）皮。","露头赤脚走，身上無衣被。","。"]', '诗', 'shi', '', NULL, '詩（幷序） 十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a6872a0-f923-493f-b9f9-e3e756806ae6', '詩（幷序） 十五', '诗（幷序） 十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["獨自心中驟，四面被兵圍。","向前十道捝（張改「稅」，戴、蔣校「挽」，黃校「棁」），背後鐵鎚鎚。","伺命張弓射，苦痛劇刀錐。","使者門前喚，忙怕不容（一作「客」）遲。","倮（張校作「裸」）體逐他走，渾舍共號悲。","宅舍無人護，妻子被人欺。","錢財不關己，莊（郭校「藏」）收永長離。","三魂無倚住，七魄散頭飛。"]', '["独自心中驟，四面被兵圍。","向前十道捝（張改「稅」，戴、蔣校「挽」，黄校「棁」），背後鐵鎚鎚。","伺命張弓射，苦痛劇刀錐。","使者门前喚，忙怕不容（一作「客」）遲。","倮（張校作「裸」）體逐他走，渾舍共號悲。","宅舍無人護，妻子被人欺。","錢財不关己，莊（郭校「藏」）收永长離。","三魂無倚住，七魄散头飞。"]', '诗', 'shi', '', NULL, '詩（幷序） 十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d578cb-f38a-4c8f-beed-5ef79eb22787', '詩（幷序） 十六', '诗（幷序） 十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["善勸諸貴等，□□□□□。","火急造橋樑，運度身得過。","福至生西方，各難知厭足。","身是有限身，程期太劇促。","縱有百年活，徘徊如轉燭。","憨人連腦癡，買錦妻裝束。","無心造福田，有意事奴僕。","只得蹔時勞（項校「牢」），曠身入苦毒。"]', '["善勸諸貴等，□□□□□。","火急造橋樑，運度身得過。","福至生西方，各难知厭足。","身是有限身，程期太劇促。","縱有百年活，徘徊如轉燭。","憨人連腦癡，買錦妻裝束。","無心造福田，有意事奴僕。","只得蹔时勞（項校「牢」），曠身入苦毒。"]', '诗', 'shi', '', NULL, '詩（幷序） 十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ffee7c6-c152-43a6-88af-976c174f2ab9', '詩（幷序） 十七', '诗（幷序） 十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["傍看數箇大憨癡，造宅舍擬作萬年期。","人人百歲乃有一，縱令長命七十稀。","少少撩亂死。","□□□□期却半，欲似流星光暫時。","中途少少遼亂死，亦有初生嬰孩兒。","無問男夫及女婦，不得驚忙審三思。","年年相續罪根重，月月增長肉身肥。","日日造罪不知足，恰似獨養神猪兒。","不能透圈四方走，還須圈裏待死時。","自造惡業還自受，如今痛苦還自知。","（以上十八首均錄自張錫厚《王梵志詩校輯》卷一。","張氏所據本爲斯七七八、斯五七九六、斯五四七四、斯一三九九卷，幷以《大正藏》第八十五冊《王梵志詩集》參校。","）（按：本卷所錄王梵志詩，皆據張錫厚《王梵志詩校輯》，另曾參校《大正藏》本及《敦煌掇瑣》。","錄詩的原則是，儘可能地保持王詩的原貌。","凡原文可通者，儘可能保持原文。","原文顯誤，張氏所改爲無可移易者，即予改正。","原文雖誤，張氏所作改動尚難成定論者，則仍保留原文，而以張說附收其下。","各本有異文者，擇其善者爲正文，異文注出「一作某」。","張錫厚爲王梵志詩的校錄、寫定作了十分可貴的努力，本卷充分利用了他的成果，筆者只在少數詩章的分篇及文字的定奪上提出了自己的看法，這是應該在這裏說明的。","）。"]', '["傍看數箇大憨癡，造宅舍擬作万年期。","人人百歲乃有一，縱令长命七十稀。","少少撩亂死。","□□□□期却半，欲似流星光暫时。","中途少少遼亂死，亦有初生嬰孩兒。","無问男夫及女婦，不得驚忙審三思。","年年相續罪根重，月月增长肉身肥。","日日造罪不知足，恰似独養神猪兒。","不能透圈四方走，還須圈裏待死时。","自造惡業還自受，如今痛苦還自知。","（以上十八首均錄自張錫厚《王梵志诗校輯》卷一。","張氏所據本爲斯七七八、斯五七九六、斯五四七四、斯一三九九卷，幷以《大正藏》第八十五冊《王梵志诗集》參校。","）（按：本卷所錄王梵志诗，皆據張錫厚《王梵志诗校輯》，另曾參校《大正藏》本及《敦煌掇瑣》。","錄诗的原則是，儘可能地保持王诗的原貌。","凡原文可通者，儘可能保持原文。","原文显誤，張氏所改爲無可移易者，即予改正。","原文雖誤，張氏所作改动尚难成定論者，則仍保留原文，而以張说附收其下。","各本有異文者，擇其善者爲正文，異文注出「一作某」。","張錫厚爲王梵志诗的校錄、寫定作了十分可貴的努力，本卷充分利用了他的成果，笔者只在少數诗章的分篇及文字的定奪上提出了自己的看法，這是應該在這裏说明的。","）。"]', '诗', 'shi', '', NULL, '詩（幷序） 十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9bf58f7-1413-4f48-8ebd-9ff51037ae75', '詩（幷序） 十八', '诗（幷序） 十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["吾家多有田，不善（戴校「若」）廣平王（戴校「玉」）。","有錢怕（項校「惜」）不用，身死留何益？","承聞七七齋，蹔施鬼來喫。","永別生時盤，酒食無蹤跡。","配罪剔（張改「別」，袁謂不誤）受苦，隔命絕相覓。","。"]', '["吾家多有田，不善（戴校「若」）廣平王（戴校「玉」）。","有錢怕（項校「惜」）不用，身死留何益？","承闻七七斋，蹔施鬼来喫。","永別生时盤，酒食無蹤跡。","配罪剔（張改「別」，袁謂不誤）受苦，隔命絕相覓。","。"]', '诗', 'shi', '', NULL, '詩（幷序） 十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1da99391-10c1-4f78-8df9-e6579d6a9c54', '詩（幷序） 十九', '诗（幷序） 十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["借貸不交通，有酒深藏善（張改作「窖」、項校「着」）。","有錢怕人知，眷屬相輕薄。","身入黃泉下，他喫他人着。","破除不由你，用盡遮他莫。"]', '["借貸不交通，有酒深藏善（張改作「窖」、項校「着」）。","有錢怕人知，眷屬相轻薄。","身入黄泉下，他喫他人着。","破除不由你，用尽遮他莫。"]', '诗', 'shi', '', NULL, '詩（幷序） 十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e42fc77e-76e8-4873-8d26-cca8745af5ca', '詩（幷序） 二十', '诗（幷序） 二十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["道士頭側方，渾甚（張改作「身」）總着黃。","無心禮拜佛，恆貴天尊堂。","三教同一體，徒自[浪]（朗）褒揚。","一被（項校「種」）霑賢聖，無弱[亦]（赤）無強。","莫爲分別相，師僧自設長。","同尊佛道教，凡恪（項、戴校「俗」）送衣裳。","糧食逢醫藥，垂死續命湯。","敕取一生活，應報上天堂。"]', '["道士头側方，渾甚（張改作「身」）總着黄。","無心禮拜佛，恆貴天尊堂。","三教同一體，徒自[浪]（朗）褒揚。","一被（項校「種」）霑賢聖，無弱[亦]（赤）無強。","莫爲分別相，師僧自設长。","同尊佛道教，凡恪（項、戴校「俗」）送衣裳。","糧食逢醫藥，垂死續命湯。","敕取一生活，應報上天堂。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('872910fe-f2e1-491e-9b70-631a7f36c5df', '詩（幷序） 二十一', '诗（幷序） 二十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["觀內有婦人（一作「女」），號名是女官。","各各服梳畋（項謂通「略」），悉帶芙蓉冠。","長裙並金色，橫披（一作「被」，張改作「帔」）黃儭單。","朝朝步虛讚，道聲數千般。","貧無巡門乞，得穀相共飡。","常住無貯積，鐺釜當房安。","眷屬王侵（張改作「役」）苦，衣食遠求難。","出無夫婿見，病困絕人看。","乞就（一作「與活」）生緣活，交即免飢寒。"]', '["观內有婦人（一作「女」），號名是女官。","各各服梳畋（項謂通「略」），悉带芙蓉冠。","长裙並金色，橫披（一作「被」，張改作「帔」）黄儭單。","朝朝步虛讚，道声數千般。","貧無巡门乞，得穀相共飡。","常住無貯積，鐺釜當房安。","眷屬王侵（張改作「役」）苦，衣食远求难。","出無夫婿见，病困絕人看。","乞就（一作「與活」）生緣活，交即免飢寒。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d68ed4f-cd9d-461e-b028-1c74275477be', '詩（幷序） 二十二', '诗（幷序） 二十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["道人頭兀雷（郭謂即「兀硉」），例頭肥特肚。","本是俗家人，出身勝地立。","飲食哺盂中，衣裳架上出。","每日趁齋家（一本「家」前有「時」字），即禮七拜佛。","飽喫更索錢，低頭着門出。","手把數珠行，開肚元無物。","生平未必識，獨養肥沒忽。","蟲蛇能報恩，人子何處出。"]', '["道人头兀雷（郭謂即「兀硉」），例头肥特肚。","本是俗家人，出身勝地立。","饮食哺盂中，衣裳架上出。","每日趁斋家（一本「家」前有「时」字），即禮七拜佛。","飽喫更索錢，低头着门出。","手把數珠行，开肚元無物。","生平未必識，独養肥沒忽。","蟲蛇能報恩，人子何处出。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a73e04b1-f0b4-4fe7-9d9a-4c61bf60e4a3', '詩（幷序） 二十三', '诗（幷序） 二十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["寺內數箇尼，各各事威儀。","本是俗人女，出家挂佛衣。","徒衆數十箇，詮擇補[綱]（剛）維。","一一依佛教，五事總合知。","莫看他破戒，身自牢住持。","佛殿元不識，損（一作「捐」）壞法與衣。","常住無貯積，家人受寒飢。","衆廚空安竈，粗飯當房𠯈（項校作「吹」，爲「炊」音訛）。","只求多財富（一作「寶」），餘事且隨宜。","富者相過重，貧者往還稀。","但知一日樂，忘却百年飢。","不採生緣瘦，唯願當身肥。","今多損却寶，來年更若爲？","。"]', '["寺內數箇尼，各各事威儀。","本是俗人女，出家挂佛衣。","徒衆數十箇，詮擇補[綱]（剛）維。","一一依佛教，五事總合知。","莫看他破戒，身自牢住持。","佛殿元不識，損（一作「捐」）壞法與衣。","常住無貯積，家人受寒飢。","衆廚空安竈，粗飯當房𠯈（項校作「吹」，爲「炊」音訛）。","只求多財富（一作「寶」），餘事且隨宜。","富者相過重，貧者往還稀。","但知一日乐，忘却百年飢。","不採生緣瘦，唯願當身肥。","今多損却寶，来年更若爲？","。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29f800d-e1f1-4dd8-9f32-f57e9d3e8b64', '詩（幷序） 二十四', '诗（幷序） 二十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["生即巧風吹，死須業道過。","來去不相知，展脚陽坡臥。","只見生（一作「主」）人悲，不聞鬼唱禍。","子細審三思，慈母莫生我。"]', '["生即巧风吹，死須業道過。","来去不相知，展脚陽坡臥。","只见生（一作「主」）人悲，不闻鬼唱禍。","子細審三思，慈母莫生我。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97f6e4f6-eed1-478a-92d6-45519ebb1a0d', '詩（幷序） 二十五', '诗（幷序） 二十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["佐史非（一作「作」）臺補，任官州縣上。","未是好出身，丁兒避征防。","不慮棄家門，狗偷且求養。","每日求行案，尋常恐迸仗。","食即衆廚飡，童兒更護當。","有事檢（一作「機」）案追，出帖付里正。","火急捉將來，險語唯須胱（一作「就」）。"]', '["佐史非（一作「作」）台補，任官州縣上。","未是好出身，丁兒避征防。","不慮棄家门，狗偷且求養。","每日求行案，尋常恐迸仗。","食即衆廚飡，童兒更護當。","有事檢（一作「機」）案追，出帖付里正。","火急捉將来，險語唯須胱（一作「就」）。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa9417f-e4bc-4e92-ab2d-cc86ea24f56c', '詩（幷序） 二十六', '诗（幷序） 二十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["前人心裏怯，乾喚愧曹長。","紙筆見續到，仍送一縑箱（一作「想」）。","錢多早發遣，物少被頡頏。","解寫除却名，楷（項校「揩」）赤將頭放。"]', '["前人心裏怯，乾喚愧曹长。","紙笔见續到，仍送一縑箱（一作「想」）。","錢多早發遣，物少被頡頏。","解寫除却名，楷（項校「揩」）赤將头放。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6d28a4-c377-4174-986c-33da04c5a9cb', '詩（幷序） 二十七', '诗（幷序） 二十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["得錢自喫用，留着櫃裏重。","一日厥摩師，空得紙錢送。","死入惡道中，量（張改作「良」）由罪根重。","埋向黃泉下，妻嫁別人用。","智者好思量，爲（一作「乃」）他受枷棒。"]', '["得錢自喫用，留着櫃裏重。","一日厥摩師，空得紙錢送。","死入惡道中，量（張改作「良」）由罪根重。","埋向黄泉下，妻嫁別人用。","智者好思量，爲（一作「乃」）他受枷棒。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('187d9a00-43b9-4179-aea7-33705c1b949b', '詩（幷序） 二十八', '诗（幷序） 二十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["當鄉何物貴，不過五里官。","縣局南衙點，食並衆廚飡。","文簿鄉頭執，餘者配雜看。","差科取高戶，賦役數千般。","處分須平等，併檑出時難。","職任（張改作「事」）無祿料，專仰筆頭鑽。","管戶無五百，雷同一概看。","愚者守直（一作「{穴/日}」，蔣謂即「冥冥」）坐，黠者馺馺看。"]', '["當乡何物貴，不過五里官。","縣局南衙点，食並衆廚飡。","文簿乡头執，餘者配杂看。","差科取高戶，賦役數千般。","处分須平等，併檑出时难。","職任（張改作「事」）無祿料，專仰笔头鑽。","管戶無五百，雷同一概看。","愚者守直（一作「{穴/日}」，蔣謂即「冥冥」）坐，黠者馺馺看。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f172fe81-8dfb-4ac9-996f-bd3fb4621134', '詩（幷序） 二十九', '诗（幷序） 二十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["愚人癡涳涳，錐刺不轉動。","身着好衣裳，有錢不解用。","貯積留妻兒，死得紙錢送。","好去更莫來，門前有桃棒。"]', '["愚人癡涳涳，錐刺不轉动。","身着好衣裳，有錢不解用。","貯積留妻兒，死得紙錢送。","好去更莫来，门前有桃棒。"]', '诗', 'shi', '', NULL, '詩（幷序） 二十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('045ed9fd-97fd-4202-a70a-e4f715598100', '詩（幷序） 三十', '诗（幷序） 三十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["愚人癡涳涳，常守無明塚。","飄入闊海中，出頭兼沒頂。","手擎金玉行，不解隨身用。","昏昏消好日，頑皮不轉動。","廣貪世間樂，故故招枷棒。","罪根漸漸深，命絕何人送。","積金作寶山，氣絕誰將用。"]', '["愚人癡涳涳，常守無明塚。","飄入闊海中，出头兼沒頂。","手擎金玉行，不解隨身用。","昏昏消好日，頑皮不轉动。","廣貪世间乐，故故招枷棒。","罪根漸漸深，命絕何人送。","積金作寶山，氣絕誰將用。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d65762ee-dc08-42d2-bfc3-bf3a32f711a9', '詩（幷序） 三十一', '诗（幷序） 三十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兀兀（一作「杌杌」）貪生業，憨人合腦癡。","漫作千年調，活得沒多時。","急手求三寶，願入湼槃期。","杓柄依僧次，巡到厥摩師。"]', '["兀兀（一作「杌杌」）貪生業，憨人合腦癡。","漫作千年調，活得沒多时。","急手求三寶，願入湼槃期。","杓柄依僧次，巡到厥摩師。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc0b5ef-208e-4647-9aaf-dae77611e4bf', '詩（幷序） 三十二', '诗（幷序） 三十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["一種同翁兒，一種同母女。","無愛亦無[憎]（增），非關後父母。","若箇與好言，若箇與惡語。","耶孃無偏頗，何須怨父母。","男女孝心我，我亦無別肚。"]', '["一種同翁兒，一種同母女。","無愛亦無[憎]（增），非关後父母。","若箇與好言，若箇與惡語。","耶孃無偏頗，何須怨父母。","男女孝心我，我亦無別肚。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1179a4f3-8b0f-4add-b5ff-3b064994f89b', '詩（幷序） 三十三', '诗（幷序） 三十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["你若是好兒，孝心看父母。","五更牀前立，即問安穩不。","天明汝好心，錢財橫入戶。","玉祥敬母恩，冬竹抽笋與。","孝是韓伯[俞]（倫），董永孤養母。"]', '["你若是好兒，孝心看父母。","五更牀前立，即问安穩不。","天明汝好心，錢財橫入戶。","玉祥敬母恩，冬竹抽笋與。","孝是韓伯[俞]（倫），董永孤養母。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb44d9af-6d6d-474e-b831-57b861020d76', '詩（幷序） 三十四', '诗（幷序） 三十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["你孝我亦孝，不絕孝門戶。","只見母憐兒，不見兒憐母。","長大取得妻，却嫌父母醜。","耶娘不採括（張改作「睬聒」），專心聽婦語。","生時不恭（一作「供」）養，死後祭泥土。","如此倒見賊，打煞無人護。"]', '["你孝我亦孝，不絕孝门戶。","只见母怜兒，不见兒怜母。","长大取得妻，却嫌父母醜。","耶娘不採括（張改作「睬聒」），專心听婦語。","生时不恭（一作「供」）養，死後祭泥土。","如此倒见賊，打煞無人護。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('238a1788-720d-42e5-80b2-7c953f19ec9d', '詩（幷序） 三十五', '诗（幷序） 三十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["父母生男女，沒娑可憐許。","逢着好飲食，紙裏將（一作「相」）來與。","心恆意（一作「憶」）不忘，入家覓男女。","養大長（一作「將」）成人，角睛（項校「眼」）難共語。","五逆前後事，我死即到汝。"]', '["父母生男女，沒娑可怜許。","逢着好饮食，紙裏將（一作「相」）来與。","心恆意（一作「憶」）不忘，入家覓男女。","養大长（一作「將」）成人，角睛（項校「眼」）难共語。","五逆前後事，我死即到汝。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('072590e1-f79f-4aff-9b76-693b204fd942', '詩（幷序） 三十六', '诗（幷序） 三十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["興生市郭兒，從頭市內坐。","例有百餘千，火下三五箇。","行行皆有鋪，鋪裏有雜（一作「新」）貨。","山鄣買物來，巧語能相和。","眼勾穩物著，不肯遣放過。","意盡端坐取，得利過一倍（此字失韻）。"]', '["兴生市郭兒，從头市內坐。","例有百餘千，火下三五箇。","行行皆有鋪，鋪裏有杂（一作「新」）貨。","山鄣買物来，巧語能相和。","眼勾穩物著，不肯遣放過。","意尽端坐取，得利過一倍（此字失韻）。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2420b427-a490-4e53-a363-2754786521cc', '詩（幷序） 三十七', '诗（幷序） 三十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["□□□□□，分毫擘眼諍。","他買（項、蔣校「賣」）抑遣賤，自買即高擎。","心裏無平等，尺寸不分明。","名霑（項校「帖」）是百姓，不肯遠征行。","不是人強了，良由方孔兄。"]', '["□□□□□，分毫擘眼諍。","他買（項、蔣校「賣」）抑遣賤，自買即高擎。","心裏無平等，尺寸不分明。","名霑（項校「帖」）是百姓，不肯远征行。","不是人強了，良由方孔兄。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d616e4a1-6fa3-4faf-93a9-7e6e443abc01', '詩（幷序） 三十八', '诗（幷序） 三十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有錢惜不喫，身死留（一作「由」）妻兒。","只得紙錢送，欠少元不知。","門前空言語，還將紙作衣。","除非夢裏見，觸體更何時。","獨守深泉下，冥冥長夜飢。","憶想（一作「相」）平生日，悔不著羅衣。"]', '["有錢惜不喫，身死留（一作「由」）妻兒。","只得紙錢送，欠少元不知。","门前空言語，還將紙作衣。","除非梦裏见，觸體更何时。","独守深泉下，冥冥长夜飢。","憶想（一作「相」）平生日，悔不著羅衣。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81344702-5965-4f65-9b7c-a289a8b18aa1', '詩（幷序） 三十九', '诗（幷序） 三十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["生（一作「坐」）時同飯瓮（一作「翁」），死則同食瓶。","火急早掘塚，不遣暫時停。","永別世間樂，唯聞哭我聲。","四海交遊絕，籍帳便除名。"]', '["生（一作「坐」）时同飯瓮（一作「翁」），死則同食瓶。","火急早掘塚，不遣暫时停。","永別世间乐，唯闻哭我声。","四海交游絕，籍帳便除名。"]', '诗', 'shi', '', NULL, '詩（幷序） 三十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad6ea94-0e28-4755-b460-aebfe4bd3a0e', '詩（幷序） 四十', '诗（幷序） 四十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["見有愚癡君，甚富無男女。","不知死急促，百方更造屋。","死得一棺木，一條衾被覆。","妻嫁他人家，你身不能護。","有時急造福，實莫相疑悮。"]', '["见有愚癡君，甚富無男女。","不知死急促，百方更造屋。","死得一棺木，一條衾被覆。","妻嫁他人家，你身不能護。","有时急造福，實莫相疑悮。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51189967-6a08-4b25-a4ef-12d09f4141a9', '詩（幷序） 四十一', '诗（幷序） 四十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["虛霑一百年，八十最是老。","長命得八十，不解學修道。","悠悠度好日，無心念三寶。","根（一作「報」，張改作「抱」，項校作「把」）拳入地獄，天堂無人到。","圻（項校作「坼」）破五戒身，却入三惡道。","一入恆沙劫，不須自懊惱。"]', '["虛霑一百年，八十最是老。","长命得八十，不解学修道。","悠悠度好日，無心念三寶。","根（一作「報」，張改作「抱」，項校作「把」）拳入地獄，天堂無人到。","圻（項校作「坼」）破五戒身，却入三惡道。","一入恆沙劫，不須自懊惱。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdd508cc-3757-4d56-b37d-791dcebc1d45', '詩（幷序） 四十二', '诗（幷序） 四十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["說錢心即喜，見死元不愁。","廣貪財色樂，時時度日休。","平生不造福，死被業道收。","但看三惡處，大有我般流。"]', '["说錢心即喜，见死元不愁。","廣貪財色乐，时时度日休。","平生不造福，死被業道收。","但看三惡处，大有我般流。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38ec43b-fedb-4063-93e8-f5ff1d935551', '詩（幷序） 四十三', '诗（幷序） 四十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["好住四合舍，殷勤堂上妻。","無常煞鬼至，火急被追[催]（摧）。","露頭赤脚走，不容得着鞋。","向前任料理，難見却回來。","有意造一佛，爲設百人齋。","無情任改嫁，資產聽將陪。","吾在惜不用，死後他人財。","憶[想]（相）生平日，悔不唱《三臺》。"]', '["好住四合舍，殷勤堂上妻。","無常煞鬼至，火急被追[催]（摧）。","露头赤脚走，不容得着鞋。","向前任料理，难见却回来。","有意造一佛，爲設百人斋。","無情任改嫁，資產听將陪。","吾在惜不用，死後他人財。","憶[想]（相）生平日，悔不唱《三台》。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545b2f16-0865-4963-897e-206cc94922be', '詩（幷序） 四十四', '诗（幷序） 四十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["地下須夫急，逢頭取次捉。","一家抽一箇，勘數申（項校作「由」，通「猶」）未足。","科出排門夫，不許私遮却（戴謂此字衍）曲。","合去取正身，名字付司錄。","棒驅火急走，向前任縛束。"]', '["地下須夫急，逢头取次捉。","一家抽一箇，勘數申（項校作「由」，通「猶」）未足。","科出排门夫，不許私遮却（戴謂此字衍）曲。","合去取正身，名字付司錄。","棒驱火急走，向前任縛束。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61631435-7587-4289-9d08-ea16d074104f', '詩（幷序） 四十五', '诗（幷序） 四十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["奉使親監鑄，改故造新光。","開通萬里達，元寶出青黃。","本姓使流傳，涓涓億兆陽（張改作「揚」）。","無心念貧事，□□□□□。","有時見即喜，貴重劇耶孃。","唯須家中足，時時對孟常（張改「嘗」，項校「光」）。","。"]', '["奉使親監鑄，改故造新光。","开通万里達，元寶出青黄。","本姓使流傳，涓涓億兆陽（張改作「揚」）。","無心念貧事，□□□□□。","有时见即喜，貴重劇耶孃。","唯須家中足，时时对孟常（張改「嘗」，項校「光」）。","。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f4b234d-8d08-4d0f-8646-5ef3f3db8248', '詩（幷序） 四十六', '诗（幷序） 四十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["怨家煞人賊，即是短命子。","生兒擬替翁，長大拋我死。","債主蹔過來，徵我夫妻淚。","父母眼乾枯，良由我憶你。","好去更莫來，門前有煞鬼。"]', '["怨家煞人賊，即是短命子。","生兒擬替翁，长大拋我死。","債主蹔過来，徵我夫妻泪。","父母眼乾枯，良由我憶你。","好去更莫来，门前有煞鬼。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4bdff0-da54-4da2-ba10-4a6fc24c413a', '詩（幷序） 四十七', '诗（幷序） 四十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["來如塵蹔[起]（去），[去]（起）如一墜（項校「隊」）風。","來去無形影，變見極忩忩。","不見無常急，業道自迎君。","何此事有真實，還凑入冥空。"]', '["来如塵蹔[起]（去），[去]（起）如一墜（項校「隊」）风。","来去無形影，变见極忩忩。","不见無常急，業道自迎君。","何此事有真實，還凑入冥空。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9767faa2-650e-49dd-aea0-6b9c9b0213c3', '詩（幷序） 四十八', '诗（幷序） 四十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兄弟義[居]（君）活，一種有男女。","兒小教讀書，女小教針補。","兒大與（郭校「須」）娶妻，女大須嫁去。","當房作私產，共語覓嗔處。","好貪競盛喫，無心奉父母。","外姓能蛆姡，啾唧由女婦。","一日三場鬬，自分不由父。","近逢窮業至，緣身一物無。","披繩兼帶索，行時須杖扶。","四海交遊絕，眷屬永還（張改作「遠」）疏。","東西無濟着，到處即女君（張改「安居」，項、戴校作「汝居」）。","（以上錄自張錫厚《王梵志詩校輯》卷二，原卷爲伯三二一一、斯五四四一、斯五六四一。","以《敦煌掇瑣》三一參校。","）（按：《全唐詩續補遺》卷二據《敦煌掇瑣》錄伯三二一一卷收其中二十六首爲缺名《五言白話詩》。","張錫厚考證此卷爲王梵志作，可以定論。","今將童氏未收之作皆錄出。","）。"]', '["兄弟義[居]（君）活，一種有男女。","兒小教读书，女小教針補。","兒大與（郭校「須」）娶妻，女大須嫁去。","當房作私產，共語覓嗔处。","好貪競盛喫，無心奉父母。","外姓能蛆姡，啾唧由女婦。","一日三場鬬，自分不由父。","近逢窮業至，緣身一物無。","披繩兼带索，行时須杖扶。","四海交游絕，眷屬永還（張改作「远」）疏。","东西無濟着，到处即女君（張改「安居」，項、戴校作「汝居」）。","（以上錄自張錫厚《王梵志诗校輯》卷二，原卷爲伯三二一一、斯五四四一、斯五六四一。","以《敦煌掇瑣》三一參校。","）（按：《全唐诗續補遺》卷二據《敦煌掇瑣》錄伯三二一一卷收其中二十六首爲缺名《五言白話诗》。","張錫厚考證此卷爲王梵志作，可以定論。","今將童氏未收之作皆錄出。","）。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('356a6e33-ef5c-47d7-a632-cddbd5e4bfc1', '詩（幷序） 四十九', '诗（幷序） 四十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["（前缺）人去像還去，人來像以明。","像有投鏡意，人無合像情。","鏡像俱磨滅，何處有衆生。"]', '["（前缺）人去像還去，人来像以明。","像有投镜意，人無合像情。","镜像俱磨滅，何处有衆生。"]', '诗', 'shi', '', NULL, '詩（幷序） 四十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6cc0fa9-b2ac-4fd5-b057-17a9a5dbb3d7', '詩（幷序） 五十', '诗（幷序） 五十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["一身元本別（張、項校作「利」），四大聚會同。","直似風吹火，還如火逐風。","火強火（項校「風」）熾疾，風[疾]（即）火[愈]（逾）烘。","火風俱氣盡，星散總成空。"]', '["一身元本別（張、項校作「利」），四大聚會同。","直似风吹火，還如火逐风。","火強火（項校「风」）熾疾，风[疾]（即）火[愈]（逾）烘。","火风俱氣尽，星散總成空。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a8377a6-679e-4818-8676-e2ae313687d8', '詩（幷序） 五十一', '诗（幷序） 五十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["以影觀他影，以身觀我身。","身影何處昵？身共影何親？","身行影你（張改作「作」）伴，身住影爲鄰。","身影百年外，相看一聚塵。"]', '["以影观他影，以身观我身。","身影何处昵？身共影何親？","身行影你（張改作「作」）伴，身住影爲鄰。","身影百年外，相看一聚塵。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c4c3f4-f65b-4760-8856-b70e18669a0f', '詩（幷序） 五十二', '诗（幷序） 五十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["觀影元非有，觀身亦是空。","如採水底月，似捉樹吹（張改作「頭」）風。","攬之不可見，尋之不可窮。","衆生隨[業]（葉）轉，恰似寐夢中。"]', '["观影元非有，观身亦是空。","如採水底月，似捉樹吹（張改作「头」）风。","攬之不可见，尋之不可窮。","衆生隨[業]（葉）轉，恰似寐梦中。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25c1a97c-1f75-49ea-8123-cfd79dcd3f67', '詩（幷序） 五十三', '诗（幷序） 五十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["雷發南山上，雨落北浮（張改作「澤」，戴校「海」，項校「溪」）中。","雷驚{石擘}礰（張改作「霹靂」）火，雨激咆哮風。","倏忽威靈歇，須臾勢乃窮。","天地不能以，如女爲身空。"]', '["雷發南山上，雨落北浮（張改作「澤」，戴校「海」，項校「溪」）中。","雷驚{石擘}礰（張改作「霹靂」）火，雨激咆哮风。","倏忽威靈歇，須臾勢乃窮。","天地不能以，如女爲身空。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8119b3eb-d7cc-430d-84c3-764b352aa561', '詩（幷序） 五十四', '诗（幷序） 五十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["非相非非相，無明[無無]（元元）明。","[相]（傷）逐妄中出，明從暗裏生。","明通暗即盡，妄絕[相]（明）還清。","能知寂滅樂，自然無色聲。"]', '["非相非非相，無明[無無]（元元）明。","[相]（傷）逐妄中出，明從暗裏生。","明通暗即尽，妄絕[相]（明）還清。","能知寂滅乐，自然無色声。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f257a8b-05e9-4009-9c5c-c2b6cbe663b6', '詩（幷序） 五十五', '诗（幷序） 五十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["但看蛾（項改「繭」）作蛾（張改作「卵」），不憶蠶生箔。","但看睡寐時，還將夢爲樂。","蛾既不羨蠶，夢亦不爲樂。","當作如是觀，死生無好惡。"]', '["但看蛾（項改「繭」）作蛾（張改作「卵」），不憶蠶生箔。","但看睡寐时，還將梦爲乐。","蛾既不羨蠶，梦亦不爲乐。","當作如是观，死生無好惡。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1a40b5-8772-4504-a10b-c98799c146bb', '詩（幷序） 五十六', '诗（幷序） 五十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["黃母化爲鼈，祇爲鼈爲身。","牛裏（項校「哀」）化爲虎，亦是虎爲人。","不憶當時[業]（葉），寧知過去因。","死生一變化，若箇是師親。"]', '["黄母化爲鼈，祇爲鼈爲身。","牛裏（項校「哀」）化爲虎，亦是虎爲人。","不憶當时[業]（葉），寧知過去因。","死生一变化，若箇是師親。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ec6646-c76d-4ce2-86a0-072e780d6263', '詩（幷序） 五十七', '诗（幷序） 五十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["古來服丹石，相次入黃泉。","萬寶不贖命，千金不買年。","有生即有死，何後復何先。","人人總色活，注（項改「拄」）著上頭天。"]', '["古来服丹石，相次入黄泉。","万寶不贖命，千金不買年。","有生即有死，何後复何先。","人人總色活，注（項改「拄」）著上头天。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b670f6d7-1dd5-44d0-987a-07c639a2a658', '詩（幷序） 五十八', '诗（幷序） 五十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["死竟土底眠，生時土上走。","死竟不出氣，生時不住口。","早死一生{曰/丰}（張改作「畢」），誰論百年後。","召我還天公，不須盡出手。"]', '["死竟土底眠，生时土上走。","死竟不出氣，生时不住口。","早死一生{曰/丰}（張改作「畢」），誰論百年後。","召我還天公，不須尽出手。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ba3def-65a8-4afe-8c39-5069dda21a06', '詩（幷序） 五十九', '诗（幷序） 五十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["行善爲基路，偷盜五不作，耶●（張謂以上三字爲衍文）五不當（戴校二句作「偷盜吾不作，邪淫吾不當。","」）。","不解讒朝廷，不解佞君王。","不能行左道，於中說一傷（張改作「場」）。","一直逢閻夫，盡地取天堂。","。"]', '["行善爲基路，偷盜五不作，耶●（張謂以上三字爲衍文）五不當（戴校二句作「偷盜吾不作，邪淫吾不當。","」）。","不解讒朝廷，不解佞君王。","不能行左道，於中说一傷（張改作「場」）。","一直逢閻夫，尽地取天堂。","。"]', '诗', 'shi', '', NULL, '詩（幷序） 五十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('454077f6-0b17-4bb3-90ad-0c4615e134c1', '詩（幷序） 六十', '诗（幷序） 六十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["前業作因緣，[今]（金）身都不記。","今也（項、郭校「世」）受苦拙（張改作「惱」），[未]（末）來當富貴。","不是後身奴，來生作事地。","不如多溫酒，相逢一時醉。"]', '["前業作因緣，[今]（金）身都不記。","今也（項、郭校「世」）受苦拙（張改作「惱」），[未]（末）来當富貴。","不是後身奴，来生作事地。","不如多溫酒，相逢一时醉。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7b3605c-e2d1-4ec6-974c-32d0ee45b690', '詩（幷序） 六十一', '诗（幷序） 六十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["少年何必好，老去何須嗔。","祖公日日故，孫子朝朝新。","祇道人祭鬼，何曾鬼祭人。","蹔來何（項疑「還」）須去，知我是誰親？","（張錫厚錄作二首）。"]', '["少年何必好，老去何須嗔。","祖公日日故，孫子朝朝新。","祇道人祭鬼，何曾鬼祭人。","蹔来何（項疑「還」）須去，知我是誰親？","（張錫厚錄作二首）。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43c5fd80-466d-4a5e-bc14-af5cad96214b', '詩（幷序） 六十二', '诗（幷序） 六十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["悲喜相纏繞，不許暫踟躕。","東家比葬地，西家看產圖。","生者歌滿路，死者哭盈衢。","循環何太急，槌鑿（二字從戴校補）相[催]（崔）驅。"]', '["悲喜相纏繞，不許暫踟躕。","东家比葬地，西家看產圖。","生者歌满路，死者哭盈衢。","循环何太急，槌鑿（二字從戴校補）相[催]（崔）驱。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59c7aab-5d8b-4076-8693-9c61067d3340', '詩（幷序） 六十三', '诗（幷序） 六十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["無常元不避，[業]（葉）（項謂通「業」）到即須行。","從（項校「徒」）作七尺影，俱墳一丈坑。","妻兒啼哭送，鬼子唱歌迎。","故來皆有死，何必得如（郭疑「長」）生。"]', '["無常元不避，[業]（葉）（項謂通「業」）到即須行。","從（項校「徒」）作七尺影，俱墳一丈坑。","妻兒啼哭送，鬼子唱歌迎。","故来皆有死，何必得如（郭疑「长」）生。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b270ab-10b4-4f07-a9c4-a62b87b064d0', '詩（幷序） 六十四', '诗（幷序） 六十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["造化成爲我，如人弄郭郎（「郎」字出韻，似當從《顏氏家訓》作「郭禿」爲是）。","魂魄似繩子，形骸若柳木。","掣取細腰肢，抽牽動眉目。","繩子作（張改作「乍」）斷去，即是乾柳模。"]', '["造化成爲我，如人弄郭郎（「郎」字出韻，似當從《顏氏家訓》作「郭禿」爲是）。","魂魄似繩子，形骸若柳木。","掣取細腰肢，抽牽动眉目。","繩子作（張改作「乍」）斷去，即是乾柳模。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28425b8-0d99-4d60-ab50-840ab1c76a4c', '詩（幷序） 六十五', '诗（幷序） 六十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["觀此身意相，都由水火風。","有生皆有滅，有始皆有終。","氣聚即爲我，氣散即成空。","一羣泊（項校「怕」）死漢，何以（張改「似」，項校「異」）叫（項校「叩」）頭蟲。","（以上三首，張錫厚分爲五首，似未允。","）。"]', '["观此身意相，都由水火风。","有生皆有滅，有始皆有終。","氣聚即爲我，氣散即成空。","一羣泊（項校「怕」）死漢，何以（張改「似」，項校「異」）叫（項校「叩」）头蟲。","（以上三首，張錫厚分爲五首，似未允。","）。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('975a52a7-15bf-43a6-8be0-baae8c3735cf', '詩（幷序） 六十六', '诗（幷序） 六十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["貪暴無用漢，資財爲他守。","惜衣不蓋形，[惜]（借）食不供口。","積聚萬金花，望得千年有。","不知名（張改作「冥」）道[中]（忠），車子來相受。"]', '["貪暴無用漢，資財爲他守。","惜衣不蓋形，[惜]（借）食不供口。","積聚万金花，望得千年有。","不知名（張改作「冥」）道[中]（忠），车子来相受。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab6efbf1-8115-4fe0-a7ac-0c61ce45da11', '詩（幷序） 六十七', '诗（幷序） 六十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["亡（張改作「妄」）隨（項校「玉髓」）長年術，金剛不壞身。","俱傷生死苦，誰兌（項校「免」）湼槃因。","精魂歸寂滅，骨肉化灰塵。","釋老由自氣（戴校「猶自去」，項校「猶自棄」），何況迷遇（項校「愚」）人。","。"]', '["亡（張改作「妄」）隨（項校「玉髓」）长年術，金剛不壞身。","俱傷生死苦，誰兌（項校「免」）湼槃因。","精魂归寂滅，骨肉化灰塵。","釋老由自氣（戴校「猶自去」，項校「猶自棄」），何況迷遇（項校「愚」）人。","。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f750aaf-a765-463d-a64e-e50a5f2e5f37', '詩（幷序） 六十八', '诗（幷序） 六十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["差着即須行，遣去莫求住。","名字石函裏，官職天曹注。","錢財鬼料量，衣食明分付。","進退不由我，何須滿優衢（張改作「憂懼」）。"]', '["差着即須行，遣去莫求住。","名字石函裏，官職天曹注。","錢財鬼料量，衣食明分付。","進退不由我，何須满優衢（張改作「憂懼」）。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a573ca80-2910-4601-8776-74c25905004d', '詩（幷序） 六十九', '诗（幷序） 六十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["向（郭、項校「伺」）命取人鬼，[屠]（暑）兒殺羊客。","鬼識人興料，客辨羊肉厄。","人自不覺死，羊亦不覺搦。","恰似園中瓜，合熟即須擿。"]', '["向（郭、項校「伺」）命取人鬼，[屠]（暑）兒殺羊客。","鬼識人兴料，客辨羊肉厄。","人自不覺死，羊亦不覺搦。","恰似园中瓜，合熟即須擿。"]', '诗', 'shi', '', NULL, '詩（幷序） 六十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5699c8a-937d-42f8-a7b3-70c41257d607', '詩（幷序） 七十', '诗（幷序） 七十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["運命滿悠悠，人生浪聒聒。","死時天遣死，活時天遣活。","一旦罷因緣，千金須判割。","饒君鐵甕子，走藏不得脫。"]', '["運命满悠悠，人生浪聒聒。","死时天遣死，活时天遣活。","一旦罷因緣，千金須判割。","饒君鐵甕子，走藏不得脫。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bd03e6e-d338-4fcc-89f9-c2cc6f88987f', '詩（幷序） 七十一', '诗（幷序） 七十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["官職亦須求，錢財亦須覓。","天雨麻點孔，三年著一滴。","王相（張改作「妄想」）逢便宜，參差著局席。","[兀兀]（瓦瓦）舍底坐，餓你眠（張改作「眼」）赫赤（戴校「饒你眼赫赫」）。"]', '["官職亦須求，錢財亦須覓。","天雨麻点孔，三年著一滴。","王相（張改作「妄想」）逢便宜，參差著局席。","[兀兀]（瓦瓦）舍底坐，餓你眠（張改作「眼」）赫赤（戴校「饒你眼赫赫」）。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc34a9b0-1267-4c2e-a170-a6284f866c8d', '詩（幷序） 七十二', '诗（幷序） 七十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["生時不須歌，死時不須哭。","天地捉秤量，鬼神用斗斛。","體上須得衣，口裏須得祿。","人人覓長命，沒地可種穀。"]', '["生时不須歌，死时不須哭。","天地捉秤量，鬼神用斗斛。","體上須得衣，口裏須得祿。","人人覓长命，沒地可種穀。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c883e918-d189-4311-8c8c-44cad73a1d0a', '詩（幷序） 七十三', '诗（幷序） 七十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["運命隨身搏（張改作「縛」，袁謂不錯，戴校「轉」），人生不自覺。","業厚即福來，業強（項疑「薄」之訛）福不著。","淳善皆安穩，蠱害總煞却。","身作身自當，將頭來自斫。"]', '["運命隨身搏（張改作「縛」，袁謂不錯，戴校「轉」），人生不自覺。","業厚即福来，業強（項疑「薄」之訛）福不著。","淳善皆安穩，蠱害總煞却。","身作身自當，將头来自斫。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe143964-03f4-4ddd-bcf2-1988aff60de5', '詩（幷序） 七十四', '诗（幷序） 七十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["先因崇福德，今日受肥胎。","果報迎先種，橋梁預早開。","奪我先時樂，將充死後媒。"]', '["先因崇福德，今日受肥胎。","果報迎先種，橋梁預早开。","奪我先时乐，將充死後媒。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eccda27-76dc-4666-86d1-3608099e5a7c', '詩（幷序） 七十五', '诗（幷序） 七十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兀兀身死後，冥冥不自知。","爲人[何]（可）必樂，爲鬼何[必]悲。","[競]（竟）地徒張眼，諍官慢豎眉。","窟[裏]（裹捋）長[展]（鹿）脚，[將]知我是誰（友）？","（均從項校）。"]', '["兀兀身死後，冥冥不自知。","爲人[何]（可）必乐，爲鬼何[必]悲。","[競]（竟）地徒張眼，諍官慢豎眉。","窟[裏]（裹捋）长[展]（鹿）脚，[將]知我是誰（友）？","（均從項校）。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('675ec93c-229e-46c0-bc23-ecc3d59661be', '詩（幷序） 七十六', '诗（幷序） 七十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["請看漢武帝，請看秦始皇。","年年合[仙]（山）藥，處處求[醫]（鑿）方。","結構千秋殿，經營萬壽堂。","百年有一倒，自去遣誰當。"]', '["請看漢武帝，請看秦始皇。","年年合[仙]（山）藥，处处求[醫]（鑿）方。","結構千秋殿，經營万壽堂。","百年有一倒，自去遣誰當。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f834af2d-ca99-4f8f-b2da-455cdd6dd04f', '詩（幷序） 七十七', '诗（幷序） 七十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["饒你王侯[職]（識），饒君將相官。","蛾眉珠玉珮，寶馬金銀鞍。","錦綺嫌不着，猪羊死不飡。","口中乞朴（項改「新」、張改作「扑」）斷，眷屬不相看。"]', '["饒你王侯[職]（識），饒君將相官。","蛾眉珠玉珮，寶马金銀鞍。","錦綺嫌不着，猪羊死不飡。","口中乞朴（項改「新」、張改作「扑」）斷，眷屬不相看。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b173dbfe-acb3-4586-b32e-7cc14c7248d0', '詩（幷序） 七十八', '诗（幷序） 七十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["自死與鳥殘，如來相體[恕]（怒）。","莫養圖口腸，莫煞共盤筯。","鋪頭錢買取，飽噉何須慮。","儻見閻羅王，亦有分疏取。"]', '["自死與鸟殘，如来相體[恕]（怒）。","莫養圖口腸，莫煞共盤筯。","鋪头錢買取，飽噉何須慮。","儻见閻羅王，亦有分疏取。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1252278f-5463-45bd-be06-fb82606e4d6e', '詩（幷序） 七十九', '诗（幷序） 七十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["衆生眼盼盼，心路甚堂堂。","三（袁、項校「一」）種逐耶孃，一種惜身命，一種憂死亡。","側長恭勉（張改作「拋」）面，長生跪拜羊。","口中不解語，情下極荒忙。","何忍刺他煞，曾無阡許惶。","牛頭捉得你，鑊裏熟煎湯。"]', '["衆生眼盼盼，心路甚堂堂。","三（袁、項校「一」）種逐耶孃，一種惜身命，一種憂死亡。","側长恭勉（張改作「拋」）面，长生跪拜羊。","口中不解語，情下極荒忙。","何忍刺他煞，曾無阡許惶。","牛头捉得你，鑊裏熟煎湯。"]', '诗', 'shi', '', NULL, '詩（幷序） 七十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c83503b-2a30-4308-899a-9dcf51a4f9b7', '詩（幷序） 八十', '诗（幷序） 八十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["男婚藉嘉偶，女娉希好仇。","但令捉如息，何尤無公侯。","菩薩常梳髮，如來不剃頭。","何須禿兀硉，怨（項校「然」）始學薰脩。","榮官赤赫赫，滅族黃髮人（郭謂「人」爲疊字符號）。"]', '["男婚藉嘉偶，女娉希好仇。","但令捉如息，何尤無公侯。","菩薩常梳髮，如来不剃头。","何須禿兀硉，怨（項校「然」）始学薰脩。","榮官赤赫赫，滅族黄髮人（郭謂「人」爲叠字符號）。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa96a66-1e20-44f5-9e6d-91999f0c090e', '詩（幷序） 八十一', '诗（幷序） 八十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["死王羨活鼠，寧及尋常人。","得官何須喜，失職何須憂。","不可將財覓，不可智力求。","儻來可柜突（張改作「櫃藏」），□（張補「任」，項疑「運」）去不可留。","（二句戴校「儻來不可拒，俄去不可留。","」）任來還任去，智（戴、項校「知」）命何須愁。"]', '["死王羨活鼠，寧及尋常人。","得官何須喜，失職何須憂。","不可將財覓，不可智力求。","儻来可柜突（張改作「櫃藏」），□（張補「任」，項疑「運」）去不可留。","（二句戴校「儻来不可拒，俄去不可留。","」）任来還任去，智（戴、項校「知」）命何須愁。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5926ac23-e9f5-4872-adaf-ec01e5f096f2', '詩（幷序） 八十二', '诗（幷序） 八十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["索須得好婦，自到更須求。","面似三拳作，心知一代休。","遮莫你崔盧，遮（鄭）莫你[鄭]（彭城）劉。","若無主物子（項校「主子物」），誰家死骨頭。","。"]', '["索須得好婦，自到更須求。","面似三拳作，心知一代休。","遮莫你崔盧，遮（鄭）莫你[鄭]（彭城）劉。","若無主物子（項校「主子物」），誰家死骨头。","。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ed6f1a-9beb-4aa4-a592-0b3aef9deefa', '詩（幷序） 八十三', '诗（幷序） 八十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["思量小家婦，貧奇惡行迹。","酒肉獨自抽（項疑「袖」），糟糠遣他喫。","生活九牛挽，[唱]（嗢）叫（蘇一四八七卷作「說唱」）百夫敵。","自著紫臭翁，餘人赤羖䍽。","索得屈烏爵，家風不禁益。"]', '["思量小家婦，貧奇惡行迹。","酒肉独自抽（項疑「袖」），糟糠遣他喫。","生活九牛挽，[唱]（嗢）叫（蘇一四八七卷作「说唱」）百夫敵。","自著紫臭翁，餘人赤羖䍽。","索得屈烏爵，家风不禁益。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f82505b3-35b0-4d39-ab89-db9f8be27f8e', '詩（幷序） 八十四', '诗（幷序） 八十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["讒臣亂人國，姡婦破人家。","客到雙[眉]（媚）腫，夫來兩手㧝（項、戴校「拏」）。","醜皮不憂敵，面面却憎花。","親姻共歡樂，夫婦作榮花。"]', '["讒臣亂人国，姡婦破人家。","客到雙[眉]（媚）腫，夫来兩手㧝（項、戴校「拏」）。","醜皮不憂敵，面面却憎花。","親姻共歡乐，夫婦作榮花。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b6fcad7-37ec-4076-b1c8-ed925bd8eb94', '詩（幷序） 八十五', '诗（幷序） 八十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["前身有何罪，色（項、戴謂通「索」）得湼（項校「鳩」）槃荼。","天下惡風俗，臨喪命獨（項校「犢」）車。","男婚不（項校「傅」）香粉，女嫁著釵花。","屍櫪（項疑「厝」）陰地臥，知堵（項校「者」）是誰家。"]', '["前身有何罪，色（項、戴謂通「索」）得湼（項校「鳩」）槃荼。","天下惡风俗，臨喪命独（項校「犢」）车。","男婚不（項校「傅」）香粉，女嫁著釵花。","屍櫪（項疑「厝」）陰地臥，知堵（項校「者」）是誰家。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2068af0a-4749-4c25-a785-68295bb2ec98', '詩（幷序） 八十六', '诗（幷序） 八十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["古人數下畢，今我（項校「代」）少高門。","錢少婢不嫁，財多奴共婚。","各各服（項校「販」）父祖，家家賣子孫。","自言望性（項校「姓」）望，聲盡不可論。"]', '["古人數下畢，今我（項校「代」）少高门。","錢少婢不嫁，財多奴共婚。","各各服（項校「販」）父祖，家家賣子孫。","自言望性（項校「姓」）望，声尽不可論。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f4c83c-0acd-4588-962a-02b5d0e9a2bb', '詩（幷序） 八十七', '诗（幷序） 八十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["敬他還自敬，輕他還自輕。","駡他一兩口，他駡幾千聲。","觸他父母（諍）諱，他觸祖公名。","欲覓無嗔根（項校「報」），少語最爲精。"]', '["敬他還自敬，轻他還自轻。","駡他一兩口，他駡幾千声。","觸他父母（諍）諱，他觸祖公名。","欲覓無嗔根（項校「報」），少語最爲精。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0c23129-4b46-48ee-95c5-1063df8f6d56', '詩（幷序） 八十八', '诗（幷序） 八十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["難[忍]儻能忍，能忍最爲難。","伏肉虎不食，病鳥人不彈。","當時雖{各寺}（張改作「碕」）堵，過後必身安。","唾面不須拭，從風自蔭乾。"]', '["难[忍]儻能忍，能忍最爲难。","伏肉虎不食，病鸟人不彈。","當时雖{各寺}（張改作「碕」）堵，過後必身安。","唾面不須拭，從风自蔭乾。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c70df690-2047-43a5-9797-1c8bac70058c', '詩（幷序） 八十九', '诗（幷序） 八十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["負恩必須酬，施恩慎勿（色）索。","得他一石麪，還他十斗麥。","得他半疋練，還他二丈帛。","瓠蘆作朾車，棒莫作出客。"]', '["負恩必須酬，施恩慎勿（色）索。","得他一石麪，還他十斗麦。","得他半疋練，還他二丈帛。","瓠蘆作朾车，棒莫作出客。"]', '诗', 'shi', '', NULL, '詩（幷序） 八十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdd8ff0e-98b2-4b02-89b3-e29236279781', '詩（幷序） 九十', '诗（幷序） 九十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["敬他保自貴，辱他□□□（戴補「招自耻」，呂朋林補「實辱己」。","張補「還自受」三字，不韻，恐非是。","）。","你若敬（項校「計」，下同）算他，他還敬算你。","勾他一盞酒，他勾十巡至。","子細審思量，此言有道理。","。"]', '["敬他保自貴，辱他□□□（戴補「招自耻」，呂朋林補「實辱己」。","張補「還自受」三字，不韻，恐非是。","）。","你若敬（項校「計」，下同）算他，他還敬算你。","勾他一盞酒，他勾十巡至。","子細審思量，此言有道理。","。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8517d65d-7599-484d-b7fc-7262c2065075', '詩（幷序） 九十一', '诗（幷序） 九十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["不知愁大小，不知愁好醜。","爲當面似雞，爲當面似狗。","道愁不愛食，聞愁偏怕酒。","剩打三五盞，愁應來（張改作「如」）屍走。"]', '["不知愁大小，不知愁好醜。","爲當面似雞，爲當面似狗。","道愁不愛食，闻愁偏怕酒。","剩打三五盞，愁應来（張改作「如」）屍走。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319900be-250b-4354-998a-89171d32ca80', '詩（幷序） 九十二', '诗（幷序） 九十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["本巡連索索，樽主告平平。","當不怪來晚，覆盞可憐精。","門前夜狐哭，屋上鵄梟鳴。","一種聲響音，何如刮鉢聲。"]', '["本巡連索索，樽主告平平。","當不怪来晚，覆盞可怜精。","门前夜狐哭，屋上鵄梟鳴。","一種声响音，何如刮鉢声。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e6f5a7-ad15-4a6f-a125-b02fbc4ce59c', '詩（幷序） 九十三', '诗（幷序） 九十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我家在何處，結對（張改作「隊」）守先阿（戴校「結草守山阿」、項校「結宇對山阿」）。","[院]（𨺋）側狐狸窟，門前烏鵲窠。","聞[鶯]（應）便下種，聽雁即收禾。","悶遣奴吹笛，閑令如其唱歌。","如（鄭振鐸改「男」，項云通「兒」）即教誦賦，女即學調梭。","寄語天公道，寧能那我何。"]', '["我家在何处，結对（張改作「隊」）守先阿（戴校「結草守山阿」、項校「結宇对山阿」）。","[院]（𨺋）側狐狸窟，门前烏鵲窠。","闻[鶯]（應）便下種，听雁即收禾。","悶遣奴吹笛，闲令如其唱歌。","如（鄭振鐸改「男」，項云通「兒」）即教誦賦，女即学調梭。","寄語天公道，寧能那我何。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eedf942-558c-438b-9a8f-c04face0a179', '詩（幷序） 九十四', '诗（幷序） 九十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["第一須景行，第二須強明。","律令波濤[涌]（誦），文詞花草生，心神潡（張改作「激」）前（項校「箭」）直，懷抱徹沙清。","觀察總如此，何愁不太平。"]', '["第一須景行，第二須強明。","律令波濤[涌]（誦），文词花草生，心神潡（張改作「激」）前（項校「箭」）直，懷抱徹沙清。","观察總如此，何愁不太平。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ab0fe42-dfe8-49c5-87bb-e65aa6fb7385', '詩（幷序） 九十五', '诗（幷序） 九十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["天子與你官，俸祿生（項校「坐」）地（張改作「由他」）授。","飲響（戴、項校「飨」）不知足，貪婪得動手。","每懷劫賊心，恆張餓狼口。","[枷]（加）鎖忽然至，飯蓋遭毒手。"]', '["天子與你官，俸祿生（項校「坐」）地（張改作「由他」）授。","饮响（戴、項校「飨」）不知足，貪婪得动手。","每懷劫賊心，恆張餓狼口。","[枷]（加）鎖忽然至，飯蓋遭毒手。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('571d9224-4ba5-410a-b59c-1641c326ae5e', '詩（幷序） 九十六', '诗（幷序） 九十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["百姓被欺屈，三官須爲申。","朝朝團坐入，漸漸曲精（戴、項校「情」）新。","斷榆翻作柳，判鬼却爲人。","天子抱冤屈，他於（張改作「揚」）陌上塵。"]', '["百姓被欺屈，三官須爲申。","朝朝團坐入，漸漸曲精（戴、項校「情」）新。","斷榆翻作柳，判鬼却爲人。","天子抱冤屈，他於（張改作「揚」）陌上塵。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189ab079-f233-472e-8b4e-d6d9d445623d', '詩（幷序） 九十七', '诗（幷序） 九十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["[代]（伐）天理百[姓]（性），格戒（項校「式」）亦須遵。","官喜律即喜，官嗔律即嗔。","總由官斷法，何須法斷人。","一時截却項，有理若爲申。"]', '["[代]（伐）天理百[姓]（性），格戒（項校「式」）亦須遵。","官喜律即喜，官嗔律即嗔。","總由官斷法，何須法斷人。","一时截却項，有理若爲申。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66992b08-4950-47d7-ba4f-986157f4d114', '詩（幷序） 九十八', '诗（幷序） 九十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["天下惡官職，未過御史臺（戴校「寺」）。","好眉福張眼（戴、項、袁校「努眉復張眼」），何須弄師子。","傍看甚可畏，自家困求死。","脫却面頭皮，還共人相似。"]', '["天下惡官職，未過御史台（戴校「寺」）。","好眉福張眼（戴、項、袁校「努眉复張眼」），何須弄師子。","傍看甚可畏，自家困求死。","脫却面头皮，還共人相似。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34b3afd8-b677-4ec8-a563-30f02ef119a5', '詩（幷序） 九十九', '诗（幷序） 九十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["家同（張改作「僮」）須飽暖，裝束唯粗疏。","俗人作憐愛，處置失形模。","衣袴白如鶴（一作「衣苦自如鸖」），頭巾黑如烏。","裌袍實誇（戴校「姱」）錦，衫改（項校「段」）高機蘆（張改作「纑」）。","未羨霍去病，誰論馮子都。","此是丈夫妾，何關曹主奴。","他道恆（項校「肥」）飽食，我瘦我（項校「餓」）欲死。","唯須學一種，勿復青當（張改作「當青」）史。","行年五十餘，始學無（張改作「悟」）道理。","回頭義（戴校「議」，張改作「憶」）經營，窮因只由你。"]', '["家同（張改作「僮」）須飽暖，裝束唯粗疏。","俗人作怜愛，处置失形模。","衣袴白如鹤（一作「衣苦自如鸖」），头巾黑如烏。","裌袍實誇（戴校「姱」）錦，衫改（項校「段」）高機蘆（張改作「纑」）。","未羨霍去病，誰論馮子都。","此是丈夫妾，何关曹主奴。","他道恆（項校「肥」）飽食，我瘦我（項校「餓」）欲死。","唯須学一種，勿复青當（張改作「當青」）史。","行年五十餘，始学無（張改作「悟」）道理。","回头義（戴校「議」，張改作「憶」）經營，窮因只由你。"]', '诗', 'shi', '', NULL, '詩（幷序） 九十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7dbe44a-3c4a-40d6-b2ae-c5739c94c2cb', '詩（幷序） 一○○', '诗（幷序） 一○○', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["鴻鵠盡（項校「晝」）飛颺，蝙蝠夜陵（項校「紛」）泊。","幽顯雖不同，志性不相博（張改作「搏」，袁謂不誤）。","他家求官官（張改作「宦」），我專慕客作。","齋得貳斗米，鐺前交摎脚。","脫帽安懷中，坐兒膝頭著。","不羨榮華好，不羞貧賤惡。","隨緣適世間，自得恣情樂。","無事強人選，散官先即著。","年年愁上番，獼猴帶[斧]（父）鑿。"]', '["鴻鵠尽（項校「晝」）飞颺，蝙蝠夜陵（項校「紛」）泊。","幽显雖不同，志性不相博（張改作「搏」，袁謂不誤）。","他家求官官（張改作「宦」），我專慕客作。","斋得貳斗米，鐺前交摎脚。","脫帽安懷中，坐兒膝头著。","不羨榮华好，不羞貧賤惡。","隨緣適世间，自得恣情乐。","無事強人選，散官先即著。","年年愁上番，獼猴带[斧]（父）鑿。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○○ 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1df9ce3-a25f-4bbf-9be6-14af42435a4b', '詩（幷序） 一○一', '诗（幷序） 一○一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["父子相憐愛，千金不肯博。","忽死賤如泥，遙看畏近着。","東家朾（項疑「釘」）桃符，西家縣赤索。","藂（張改作「聚」）頭唱奈何，相催早埋却。"]', '["父子相怜愛，千金不肯博。","忽死賤如泥，遙看畏近着。","东家朾（項疑「釘」）桃符，西家縣赤索。","藂（張改作「聚」）头唱奈何，相催早埋却。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0361f2-bb7f-4045-8c70-0bacbaba79b5', '詩（幷序） 一○二', '诗（幷序） 一○二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["平生不喫著，於身一世錯。","一日命終時，拔釜交樛杓。","若有大官職，身苦妻兒樂。","叉手立公庭，終朝併[兩]（雨）脚。","得祿奴婢飡，請賜妻兒著。","一日事參差，獨自煞你却。"]', '["平生不喫著，於身一世錯。","一日命終时，拔釜交樛杓。","若有大官職，身苦妻兒乐。","叉手立公庭，終朝併[兩]（雨）脚。","得祿奴婢飡，請賜妻兒著。","一日事參差，独自煞你却。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8ffa94b-d179-4bb9-96c1-1b8335109740', '詩（幷序） 一○三', '诗（幷序） 一○三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["人生能幾時，朝夕不可保。","死亡今古傳，何須愁此道。","有酒但當飲，立即相看老。","兀兀信因緣，終歸有一到。"]', '["人生能幾时，朝夕不可保。","死亡今古傳，何須愁此道。","有酒但當饮，立即相看老。","兀兀信因緣，終归有一到。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b63918d4-f0b4-49a9-b0d3-bf8ca8dfc29f', '詩（幷序） 一○四', '诗（幷序） 一○四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["王二羊（項、蔣校「美」）年少，梵志亦不惡。","借問[今]（金）時人，阿誰肯伏弱？。"]', '["王二羊（項、蔣校「美」）年少，梵志亦不惡。","借问[今]（金）时人，阿誰肯伏弱？。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a1acb0-b7c7-497d-ae09-8327fe2363b9', '詩（幷序） 一○五', '诗（幷序） 一○五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["忍辱收珍寶，嗔●捐福田。","高心難見佛，下意得生天。"]', '["忍辱收珍寶，嗔●捐福田。","高心难见佛，下意得生天。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a87546-a841-4964-b69c-b2690e950d41', '詩（幷序） 一○六', '诗（幷序） 一○六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["嗔恚滅功德，如火燎豪毛。","百年修善業，一念惡能燒。"]', '["嗔恚滅功德，如火燎豪毛。","百年修善業，一念惡能燒。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a8cdfc-3794-4b44-a44d-8146020260a6', '詩（幷序） 一○七', '诗（幷序） 一○七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["三年作官二年半，修理廳館老癡漢。","但知多□（張補「少」字）與梵志，頭□（張補「戴」字）笠子雨裏判。"]', '["三年作官二年半，修理廳館老癡漢。","但知多□（張補「少」字）與梵志，头□（張補「戴」字）笠子雨裏判。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('274b2662-b9ae-4be1-977c-ddcd42c59606', '詩（幷序） 一○八', '诗（幷序） 一○八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["六賊俱爲患，心賊最爲災。","東西好遊浪，南北事同（張改作「周」）迴。","疾姡終難却，慳貪去即來。","自非通達者，迷性若爲開。"]', '["六賊俱爲患，心賊最爲災。","东西好游浪，南北事同（張改作「周」）迴。","疾姡終难却，慳貪去即来。","自非通達者，迷性若爲开。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2336522f-ed43-411f-8990-53b2f792c590', '詩（幷序） 一○九', '诗（幷序） 一○九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["官職莫貪財，貪財向死親。","有即渾家用，曹（張改作「遭」）羅唯一身。","法律[刑]（形）名重，不許浪推人。","一朝囹圄裏，方始憶清貧。"]', '["官職莫貪財，貪財向死親。","有即渾家用，曹（張改作「遭」）羅唯一身。","法律[刑]（形）名重，不許浪推人。","一朝囹圄裏，方始憶清貧。"]', '诗', 'shi', '', NULL, '詩（幷序） 一○九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80bac59a-e5b4-4301-851a-c7d823338f37', '詩（幷序） 一一○', '诗（幷序） 一一○', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["人受（張改「壽」）百歲不長命，中道仍有死傷人。","唯能縱情造罪過，未能修善自[防]（坊）身。"]', '["人受（張改「壽」）百歲不长命，中道仍有死傷人。","唯能縱情造罪過，未能修善自[防]（坊）身。"]', '诗', 'shi', '', NULL, '詩（幷序） 一一○ 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1fcd392-d896-4707-9bb9-2d2dcc091bde', '詩（幷序） 一一一', '诗（幷序） 一一一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["積善必餘慶，積惡必餘殃。","錢財不能入，三寶先你□（張補「亡」字）。","五色衣裳□，□□□□□。"]', '["積善必餘慶，積惡必餘殃。","錢財不能入，三寶先你□（張補「亡」字）。","五色衣裳□，□□□□□。"]', '诗', 'shi', '', NULL, '詩（幷序） 一一一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('943d1af2-e767-4840-b6c6-576fc21b08d1', '詩（幷序） 一一二', '诗（幷序） 一一二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["出門拗頭戾跨，自道行步趨鏘。","伺命把棒忽至，遍體白汗如漿。","撮你不得辭別，俄爾眷屬分張。","合村送就曠野，回來只見空牀。"]', '["出门拗头戾跨，自道行步趨鏘。","伺命把棒忽至，遍體白汗如漿。","撮你不得辞別，俄爾眷屬分張。","合村送就曠野，回来只见空牀。"]', '诗', 'shi', '', NULL, '詩（幷序） 一一二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5479f91-525b-4ab6-b7fa-1c3563c9b0cc', '詩（幷序） 一一三', '诗（幷序） 一一三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["若言余浪語，請君看即知。","回頭面北臥，寸步更不移。","終身不念食，永世不須衣。","此名無常住，垂（張改作「無」、項改「誰」）人輒得知。"]', '["若言余浪語，請君看即知。","回头面北臥，寸步更不移。","終身不念食，永世不須衣。","此名無常住，垂（張改作「無」、項改「誰」）人輒得知。"]', '诗', 'shi', '', NULL, '詩（幷序） 一一三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d99551c9-6628-4e17-a03a-c6927f6c5456', '詩（幷序） 一一四', '诗（幷序） 一一四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["愚夫癡杌杌，常守無明窟。","沉淪苦海中，出頭還復沒。","頂戴神靈珠，隨身無價物。","二鼠數相侵，四蛇推（項校「摧」）命疾。","似露草頭霜，見日一代畢。","更愚丸（項校「遇刀」，張改「遇炎」）風吹，彼此俱無匹。","貯得滿堂金，知是誰家物。","（以上皆錄自張錫厚《王梵志詩校輯》卷三，原卷爲伯三八三三、伯二九一四、蘇一四八七、二八七一。","該卷有五首已收入《全唐詩補逸》卷二。","）。"]', '["愚夫癡杌杌，常守無明窟。","沉淪苦海中，出头還复沒。","頂戴神靈珠，隨身無價物。","二鼠數相侵，四蛇推（項校「摧」）命疾。","似露草头霜，见日一代畢。","更愚丸（項校「遇刀」，張改「遇炎」）风吹，彼此俱無匹。","貯得满堂金，知是誰家物。","（以上皆錄自張錫厚《王梵志诗校輯》卷三，原卷爲伯三八三三、伯二九一四、蘇一四八七、二八七一。","該卷有五首已收入《全唐诗補逸》卷二。","）。"]', '诗', 'shi', '', NULL, '詩（幷序） 一一四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87ce5bdf-0d5e-45b1-a3f0-6a219c37d110', '詩（幷序） 一一五', '诗（幷序） 一一五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["慧心（一作「眼」）近空心，非關（一作「開」）髑髏孔。","對面說不識，饒你母姓董。","（見張錫厚《王梵志詩校輯》卷六，出敦煌本《歷代法寶記》）（按：《歷代法寶記》謂無住禪師引王梵志此詩，《全唐詩續補遺》誤收入無住名下，今移正。","）。"]', '["慧心（一作「眼」）近空心，非关（一作「开」）髑髏孔。","对面说不識，饒你母姓董。","（见張錫厚《王梵志诗校輯》卷六，出敦煌本《歷代法寶記》）（按：《歷代法寶記》謂無住禪師引王梵志此诗，《全唐诗續補遺》誤收入無住名下，今移正。","）。"]', '诗', 'shi', '', NULL, '詩（幷序） 一一五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95f2a833-ebe0-4e6b-bd7b-2450081c993f', '詩（幷序） 一一六', '诗（幷序） 一一六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["此身如館舍，命似家宿客。","客去館舍空，知是誰家宅。","（見張錫厚《王梵志詩校輯》卷六，出伯三○二一卷佛書引。","）。"]', '["此身如館舍，命似家宿客。","客去館舍空，知是誰家宅。","（见張錫厚《王梵志诗校輯》卷六，出伯三○二一卷佛书引。","）。"]', '诗', 'shi', '', NULL, '詩（幷序） 一一六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0b01a0-d290-485a-8d84-513c30dedf7f', '詩（幷序） 一一七', '诗（幷序） 一一七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["人是無常身。","（同前）（按：本卷及下卷所錄今人校訂意見，皆錄自郭在貽《王梵志記彙校》〖中國訓詁學會第四屆年會論文〗，引錄諸家有項楚〖簡稱項〗、袁賓〖簡稱袁〗、蔣紹愚〖簡稱蔣〗、周一良〖簡稱周〗、黃征〖簡稱黃〗、松尾良樹〖簡稱松尾〗、戴密微〖簡稱戴〗及郭在貽〖簡稱戴〗等。","承袁賓同志提供資料。","）。"]', '["人是無常身。","（同前）（按：本卷及下卷所錄今人校訂意见，皆錄自郭在貽《王梵志記彙校》〖中国訓詁学會第四屆年會論文〗，引錄諸家有項楚〖簡稱項〗、袁賓〖簡稱袁〗、蔣紹愚〖簡稱蔣〗、周一良〖簡稱周〗、黄征〖簡稱黄〗、松尾良樹〖簡稱松尾〗、戴密微〖簡稱戴〗及郭在貽〖簡稱戴〗等。","承袁賓同志提供資料。","）。"]', '诗', 'shi', '', NULL, '詩（幷序） 一一七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76cd0c01-cfe0-4a1d-86e3-11801a181473', '詩 一', '诗 一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我今一身（任錄作「生」）內，修營等一國。","管□□□尸（項楚校作「管屬八萬戶」），隨我債衣食。","外相（項校「想」）去三尸，□（陳補「內」字）思除六賊。","貪望出累身，□□入淨域。"]', '["我今一身（任錄作「生」）內，修營等一国。","管□□□尸（項楚校作「管屬八万戶」），隨我債衣食。","外相（項校「想」）去三尸，□（陳補「內」字）思除六賊。","貪望出累身，□□入淨域。"]', '诗', 'shi', '', NULL, '詩 一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eedbf61-873a-4957-a4b5-eb091f26e5ba', '詩 二', '诗 二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["生亦只物生，死亦只物□（任、陳皆補「死」字）。","□□□（項補「來去不」）相知，苦樂何處是？","唯見生人悲，未聞啼哭鬼。","以此好□（任、陳皆補「思」字）量，未必生勝死。"]', '["生亦只物生，死亦只物□（任、陳皆補「死」字）。","□□□（項補「来去不」）相知，苦乐何处是？","唯见生人悲，未闻啼哭鬼。","以此好□（任、陳皆補「思」字）量，未必生勝死。"]', '诗', 'shi', '', NULL, '詩 二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19ec252c-02da-4b43-a3be-1a0eed558da4', '詩 三', '诗 三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世間不信我，言我□造惡。","不能爲俗情，和光心自各。","財色終不染，妻子不戀者。","共□（任、陳皆補「你」字）□□（陳補「同」字）塵，至理求不錯。","智惠（陳校作「慧」）渾一愚，我心常離縛。","君自未識真，余身桓（任錄、項校均作「恒」）□（陳補「坦」字、項補「快」字）樂。"]', '["世间不信我，言我□造惡。","不能爲俗情，和光心自各。","財色終不染，妻子不戀者。","共□（任、陳皆補「你」字）□□（陳補「同」字）塵，至理求不錯。","智惠（陳校作「慧」）渾一愚，我心常離縛。","君自未識真，余身桓（任錄、項校均作「恒」）□（陳補「坦」字、項補「快」字）乐。"]', '诗', 'shi', '', NULL, '詩 三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6aac2c5-4ecc-4f48-98d7-59544d7b9784', '詩 四', '诗 四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["王二語梵志：俗間無我師。","心中不了義，聞者盡不知。","我今得開悟，先身已受持。","尋經醒無我，披《老》悟無爲。","君身（項校「神」）自寂滅，君身若死屍。","神身一分（任錄作「六」）解，六識自開披。","萬事都無著，憐（項校作「泠」）然無所之。","漏盡無煩惱，神澄自靡斯。","心高鵠共駕，一舉出天池。"]', '["王二語梵志：俗间無我師。","心中不了義，闻者尽不知。","我今得开悟，先身已受持。","尋經醒無我，披《老》悟無爲。","君身（項校「神」）自寂滅，君身若死屍。","神身一分（任錄作「六」）解，六識自开披。","万事都無著，怜（項校作「泠」）然無所之。","漏尽無煩惱，神澄自靡斯。","心高鵠共駕，一舉出天池。"]', '诗', 'shi', '', NULL, '詩 四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c78b0c9-f697-4ddd-b1ad-9ab5dc9ad7ff', '詩 五', '诗 五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["梵志與王生，密敦膠[漆]（柒）友。","共喜[歌一]樂，同欣詠五柳。","適意叙詩書，清淡盃（一作「盂」）淥[酒]。","莫怪頻追逐，只爲相[知]久。","（按：此詩原卷中兩見，茲據另一重抄處校補。","）。"]', '["梵志與王生，密敦膠[漆]（柒）友。","共喜[歌一]乐，同欣詠五柳。","適意叙诗书，清淡盃（一作「盂」）淥[酒]。","莫怪頻追逐，只爲相[知]久。","（按：此诗原卷中兩见，茲據另一重抄处校補。","）。"]', '诗', 'shi', '', NULL, '詩 五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3022cc38-ea30-49f6-9b03-c2434e672efe', '詩 六', '诗 六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["俗人道我癡，我道俗人[騃]。","兩兩相排撥，嘍囉不可解。","世人重榮華，我心今已罷。","惟有如意珠，撩渠不肯買。","耽浮[五]欲樂，幾許難開解。","（任錄此下別作一首）。"]', '["俗人道我癡，我道俗人[騃]。","兩兩相排撥，嘍囉不可解。","世人重榮华，我心今已罷。","惟有如意珠，撩渠不肯買。","耽浮[五]欲乐，幾許难开解。","（任錄此下別作一首）。"]', '诗', 'shi', '', NULL, '詩 六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e9c721-0e8a-46e3-aed9-67d7971127ac', '詩 七', '诗 七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["嗟世俗難有，爲住煩惱處。","塵危三業障，心造恒游生死因。","不覺四蛇六賊藏身內，貪癡五欲競相催。"]', '["嗟世俗难有，爲住煩惱处。","塵危三業障，心造恒游生死因。","不覺四蛇六賊藏身內，貪癡五欲競相催。"]', '诗', 'shi', '', NULL, '詩 七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee6fa301-f4bb-415a-a444-ad3245c0406e', '迴波樂', '迴波乐', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["回波[爾]（來）時[六]（大）（均從任校）賊，不如持心斷惑。","縱使誦經千卷，眼裏見經不識。","不解佛法大意，徒勞排文數黑。","頭陀蘭若精進，希望後世功德。","持心即是大患，聖道何由可剋。","若悟生死之（任校作「如」）夢，一切求心皆息。","（按：原卷此首前題「王梵志迴波樂」六字，以下連抄。","任謂此首及以下六皆屬《迴波樂》之作。","）。"]', '["回波[爾]（来）时[六]（大）（均從任校）賊，不如持心斷惑。","縱使誦經千卷，眼裏见經不識。","不解佛法大意，徒勞排文數黑。","头陀蘭若精進，希望後世功德。","持心即是大患，聖道何由可剋。","若悟生死之（任校作「如」）梦，一切求心皆息。","（按：原卷此首前題「王梵志迴波乐」六字，以下連抄。","任謂此首及以下六皆屬《迴波乐》之作。","）。"]', '诗', 'shi', '', NULL, '迴波樂 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc29e71-eddb-4397-8171-4243b744fb2e', '迴波樂 八', '迴波乐 八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["法性大海如如，風吹波浪溝渠。","我今不生不滅，於中不覺愚夫。","[憎]（增）（從任、陳校）惡若爲是惡，無始流浪三塗。","迷人失路但坐，不見六道清虛。"]', '["法性大海如如，风吹波浪溝渠。","我今不生不滅，於中不覺愚夫。","[憎]（增）（從任、陳校）惡若爲是惡，無始流浪三塗。","迷人失路但坐，不见六道清虛。"]', '诗', 'shi', '', NULL, '迴波樂 八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d39aad3-5acb-4765-82d7-0e0503d6334f', '迴波樂 九', '迴波乐 九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["心本無雙無隻（陳校作「佞」），深難到底淵洪。","無來無去不住，㺃（陳校作「猶」、任校作「獨」）如法性虛空。","復能出生諸法，不遲不疾容（任改作「從」）容。","幸願諸人思忖（原作「恃」，從項校改），自然法性通同。"]', '["心本無雙無隻（陳校作「佞」），深难到底淵洪。","無来無去不住，㺃（陳校作「猶」、任校作「独」）如法性虛空。","复能出生諸法，不遲不疾容（任改作「從」）容。","幸願諸人思忖（原作「恃」，從項校改），自然法性通同。"]', '诗', 'shi', '', NULL, '迴波樂 九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbd6df47-9ec1-4207-9a70-a85882fea43c', '迴波樂 十', '迴波乐 十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["但令但貪但呼，波（陳校作「般」）若法水不枯。","醉時安眠大道，誰能向我停居。","八苦變成甘露，解脫更欲何須。","萬法歸依一相，安然獨坐四衢。","。"]', '["但令但貪但呼，波（陳校作「般」）若法水不枯。","醉时安眠大道，誰能向我停居。","八苦变成甘露，解脫更欲何須。","万法归依一相，安然独坐四衢。","。"]', '诗', 'shi', '', NULL, '迴波樂 十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a820f563-ddda-4d44-8db4-6f0ff217396f', '迴波樂 十一', '迴波乐 十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["凡夫有喜有慮，少樂終日懷愁。","一朝不報明冥，常作千歲遮頭。","財色□（陳補「只」字）緣不足，盡夜拪㨝規求。"]', '["凡夫有喜有慮，少乐終日懷愁。","一朝不報明冥，常作千歲遮头。","財色□（陳補「只」字）緣不足，尽夜拪㨝規求。"]', '诗', 'shi', '', NULL, '迴波樂 十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7106a825-0908-49eb-b5d0-b9050afbf06e', '迴波樂 十二', '迴波乐 十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["不語諦觀如來，逍遙獨脫塵埃。","合眼任心樹下，跏趺端坐花臺。","不懼前後二際，豈著水火三災。","只勸（陳謂「只」字衍，任謂「勸」字衍）遣榮樂[靜]（靖）坐，莫戀妻子錢財。","稱體寶衣三事，等（任錄作「葬」）身錫杖一枚。","常持智[慧]（惠）刀劍，逢者眼目即開。"]', '["不語諦观如来，逍遙独脫塵埃。","合眼任心樹下，跏趺端坐花台。","不懼前後二際，豈著水火三災。","只勸（陳謂「只」字衍，任謂「勸」字衍）遣榮乐[静]（靖）坐，莫戀妻子錢財。","稱體寶衣三事，等（任錄作「葬」）身錫杖一枚。","常持智[慧]（惠）刀劍，逢者眼目即开。"]', '诗', 'shi', '', NULL, '迴波樂 十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('714b4140-d3f5-4b0c-811e-6aa222aa0a81', '迴波樂 十三', '迴波乐 十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["法性本來常存，茫茫無有邊畔。","安身取捨之中，被他二境迴換。","歛念定（任錄作「之」）想坐禪，攝意安心覺觀。","木人機關（任錄作「挾開」）修道，何時可到彼岸？","忽悟諸法體空，欲似熱病得汗。","無智人前莫說，打破君頭萬段。","（按：項楚謂本首及前「回波爾時六賊」一首均系據寶誌《大乘讚》改寫而成。","寶誌之作見本書卷五十九。","）。"]', '["法性本来常存，茫茫無有邊畔。","安身取捨之中，被他二境迴換。","歛念定（任錄作「之」）想坐禪，攝意安心覺观。","木人機关（任錄作「挾开」）修道，何时可到彼岸？","忽悟諸法體空，欲似熱病得汗。","無智人前莫说，打破君头万段。","（按：項楚謂本首及前「回波爾时六賊」一首均系據寶誌《大乘讚》改寫而成。","寶誌之作见本书卷五十九。","）。"]', '诗', 'shi', '', NULL, '迴波樂 十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49cd4ceb-e2a9-413e-8bca-095813c4b5cb', '迴波樂 十四', '迴波乐 十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["隱去來，尋空有，空有[畢]（必）竟兩無名，二境安心欲何守？","不長不短鑒空心，若（任錄作「君」）見空心還是有。","空有俱遣法無依，智者融心自安偶。","隱去來，勿浪波波走。"]', '["隐去来，尋空有，空有[畢]（必）竟兩無名，二境安心欲何守？","不长不短鑒空心，若（任錄作「君」）见空心還是有。","空有俱遣法無依，智者融心自安偶。","隐去来，勿浪波波走。"]', '诗', 'shi', '', NULL, '迴波樂 十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24e3465d-0f6b-4951-9c1f-fe1fc9833a41', '迴波樂 十五', '迴波乐 十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["隱去法，隱去游朝市。","不離煩惱原，無希真妙理。","對境息貪癡，何假求高士？","是非不二見，法界同昆季。","隱去來，大樂無基（項疑「機」）止。"]', '["隐去法，隐去游朝市。","不離煩惱原，無希真妙理。","对境息貪癡，何假求高士？","是非不二见，法界同昆季。","隐去来，大乐無基（項疑「機」）止。"]', '诗', 'shi', '', NULL, '迴波樂 十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fbc1797-fa4d-4f13-bc15-8a6aecd8b9da', '迴波樂 十六', '迴波乐 十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["教君有男女，但令遣出家。","如山覆一壝（項校「㙺」，通「簣」），似草始生牙。","剃頭並去髮，脫俗服袈裟。","聞鐘即禮拜，見佛獻香花。","不思五等貴，寧貪駟馬車。"]', '["教君有男女，但令遣出家。","如山覆一壝（項校「㙺」，通「簣」），似草始生牙。","剃头並去髮，脫俗服袈裟。","闻鐘即禮拜，见佛獻香花。","不思五等貴，寧貪駟马车。"]', '诗', 'shi', '', NULL, '迴波樂 十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b07007d5-63f5-44ee-97a8-8e5ede66e1a9', '迴波樂 十七', '迴波乐 十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["危身不自在，猶如脆風壞。","命盡骸歸士，形移更受胎。","猶如空盡月，凡數幾千迴。"]', '["危身不自在，猶如脆风壞。","命尽骸归士，形移更受胎。","猶如空尽月，凡數幾千迴。"]', '诗', 'shi', '', NULL, '迴波樂 十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9fdc91-3dc3-421a-bad3-5d0db7d13be7', '迴波樂 十八', '迴波乐 十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["若個達苦空？世間無有一。","不見己身非，唯都（項校「覩」）他家失。","貪兒覓長命，論時熟癡漢。","終歸不免死，受苦無崖畔。","非但少衣食，王役偏差喚。","不如早殯地，愁苦一時散。"]', '["若個達苦空？世间無有一。","不见己身非，唯都（項校「覩」）他家失。","貪兒覓长命，論时熟癡漢。","終归不免死，受苦無崖畔。","非但少衣食，王役偏差喚。","不如早殯地，愁苦一时散。"]', '诗', 'shi', '', NULL, '迴波樂 十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dae84efa-716b-41ba-bb0d-ad0ae505799c', '迴波樂 十九', '迴波乐 十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世間何物親？妻子貴於珍。","一朝身命謝，萬事不由人。","財錢任他用，眷屬不隨身。","何須人哭我，終是一聚塵。"]', '["世间何物親？妻子貴於珍。","一朝身命謝，万事不由人。","財錢任他用，眷屬不隨身。","何須人哭我，終是一聚塵。"]', '诗', 'shi', '', NULL, '迴波樂 十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da5cd426-fa8f-4e5c-9470-2d1785ca9439', '迴波樂 二十', '迴波乐 二十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["可惜千金身，從來不懼罪。","見善不肯爲，值惡便當憙。","煞猪請恩福，寧知自損己？","所以有貧富，良田（陳校作「由」）先業起。"]', '["可惜千金身，從来不懼罪。","见善不肯爲，值惡便當憙。","煞猪請恩福，寧知自損己？","所以有貧富，良田（陳校作「由」）先業起。"]', '诗', 'shi', '', NULL, '迴波樂 二十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b23281-9a3c-4acf-9f7c-0f78b587b52f', '迴波樂 二十一', '迴波乐 二十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["夢游萬里自然，覺罷百事憂煎。","欲見神身分別，思此即在眼前。","聖人無夢無想，達士無我無緣。","且寄身爲庵屋，就裏養出神仙。"]', '["梦游万里自然，覺罷百事憂煎。","欲见神身分別，思此即在眼前。","聖人無梦無想，達士無我無緣。","且寄身爲庵屋，就裏養出神仙。"]', '诗', 'shi', '', NULL, '迴波樂 二十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('176c5c44-1f1a-4f93-8690-5658159c99f2', '迴波樂 二十二', '迴波乐 二十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["多緣饒煩惱，省事得心安（項疑作「安心」）。","若能絕妄想，果成堅固林。","捨[邪]（耶）歸六趣，畢竟去貪嗔。","無塵復無垢，何慮不成真。"]', '["多緣饒煩惱，省事得心安（項疑作「安心」）。","若能絕妄想，果成堅固林。","捨[邪]（耶）归六趣，畢竟去貪嗔。","無塵复無垢，何慮不成真。"]', '诗', 'shi', '', NULL, '迴波樂 二十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf6a49b-de64-4f17-b1dc-67a0dbf85207', '迴波樂 二十三', '迴波乐 二十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["不慮天堂遠，非愁地獄虛。","心中一種懼，唯怕土菴廬。","迥靜丘荒外，寂寂遠村墟。","泉門一閉後，開日定知無。"]', '["不慮天堂远，非愁地獄虛。","心中一種懼，唯怕土菴廬。","迥静丘荒外，寂寂远村墟。","泉门一閉後，开日定知無。"]', '诗', 'shi', '', NULL, '迴波樂 二十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ff7cff8-c958-4fea-8b3c-826d37e3e166', '迴波樂 二十四', '迴波乐 二十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["自有無用身，觀他有用體。","子（細）細好推尋，論時幾許騃。","佛性五蔭中，眼看心不解。","終日求有爲，屈屈向他禮。"]', '["自有無用身，观他有用體。","子（細）細好推尋，論时幾許騃。","佛性五蔭中，眼看心不解。","終日求有爲，屈屈向他禮。"]', '诗', 'shi', '', NULL, '迴波樂 二十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18affae4-b0cb-4ef7-ba79-a1790d700641', '迴波樂 二十五', '迴波乐 二十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["壯年凡幾日？死去入士菴。","論情即今漢，各各悉癡㤌（項校作「憨」）。","唯緣二升米，是處即生食。","禮佛遙言之，彼角仍圖攤。","貪錢險不避，逐法易成難。","即今不如此，寧隨體上寒。","乍可無餘仗（項謂應作「伏」，爲「服」之音誤），願得一身安。","無爲日日悟，解脫朝朝喰（陳校作「餐」）。","死去天堂（堂）上，遣你斫額看。"]', '["壯年凡幾日？死去入士菴。","論情即今漢，各各悉癡㤌（項校作「憨」）。","唯緣二升米，是处即生食。","禮佛遙言之，彼角仍圖攤。","貪錢險不避，逐法易成难。","即今不如此，寧隨體上寒。","乍可無餘仗（項謂應作「伏」，爲「服」之音誤），願得一身安。","無爲日日悟，解脫朝朝喰（陳校作「餐」）。","死去天堂（堂）上，遣你斫額看。"]', '诗', 'shi', '', NULL, '迴波樂 二十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53620358-8a34-4f59-81f2-8e92eaa2c110', '迴波樂 二十六', '迴波乐 二十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["若能無著即如來，身中寶藏自然開。","一切生死皆消滅，判不更畏受胞胎。","悮（陳校作「悟」）時剎那不移慮，父子相見付珍財。","衆魔外道皆賓仗（項校「伏」），諸天空中唱善哉。"]', '["若能無著即如来，身中寶藏自然开。","一切生死皆消滅，判不更畏受胞胎。","悮（陳校作「悟」）时剎那不移慮，父子相见付珍財。","衆魔外道皆賓仗（項校「伏」），諸天空中唱善哉。"]', '诗', 'shi', '', NULL, '迴波樂 二十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d5e8ef-2c78-423f-9d52-8bde68790221', '迴波樂 二十七', '迴波乐 二十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世人重金玉，余希衣內珍。","細細辭名利，潮（項校「漸」）漸遠囂塵。","貪癡日日滅，智境朝朝新。","語你世上漢，阿都（項校「堵」）是良田。"]', '["世人重金玉，余希衣內珍。","細細辞名利，潮（項校「漸」）漸远囂塵。","貪癡日日滅，智境朝朝新。","語你世上漢，阿都（項校「堵」）是良田。"]', '诗', 'shi', '', NULL, '迴波樂 二十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('678f4017-0f3a-4176-abea-a3332f862939', '迴波樂 二十八', '迴波乐 二十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["王二與世人，俱來就梵志。","非爲貪與賞，與你論愚智。","凡夫累劫中，不解思量事。","見善不肯爲，見惡喜無睡。","昏昏似夢人，未飲恒如醉。"]', '["王二與世人，俱来就梵志。","非爲貪與賞，與你論愚智。","凡夫累劫中，不解思量事。","见善不肯爲，见惡喜無睡。","昏昏似梦人，未饮恒如醉。"]', '诗', 'shi', '', NULL, '迴波樂 二十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5278e670-7c5d-44b9-87a5-c320ebd3bd99', '迴波樂 二十九', '迴波乐 二十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["榮利皆悉爭，畏死復貪生。","心神爲俗網，蠢蠢暗中行。"]', '["榮利皆悉爭，畏死复貪生。","心神爲俗網，蠢蠢暗中行。"]', '诗', 'shi', '', NULL, '迴波樂 二十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98febcdd-9f70-4f6f-9b9d-a5d4f68b8cca', '迴波樂 三十', '迴波乐 三十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["他見見我見，我見見他見。","二見亦自見，不見喜中面。","手把車釧鏡，終日向外看。","唯見他長短，不肯自洮練（項校「揀」）。","竟竟口合合，猶如冶排扇。","逢人即作動，心舌常交戰。","不肯自看身，看身善不善。","如此癡冥人，只是可惡賤。","勸君學修道，含食但自㖶。","且拔己飢渴，五邪邪毒箭。","獲得身中病，應時乃一現。","安住解脫中，無礙未別見。","住是分別有，任用法界遍。","縱起六十二，非由無罪（項校「最」）殿。","所以得如斯，有大善方便。"]', '["他见见我见，我见见他见。","二见亦自见，不见喜中面。","手把车釧镜，終日向外看。","唯见他长短，不肯自洮練（項校「揀」）。","竟竟口合合，猶如冶排扇。","逢人即作动，心舌常交戰。","不肯自看身，看身善不善。","如此癡冥人，只是可惡賤。","勸君学修道，含食但自㖶。","且拔己飢渴，五邪邪毒箭。","獲得身中病，應时乃一現。","安住解脫中，無礙未別见。","住是分別有，任用法界遍。","縱起六十二，非由無罪（項校「最」）殿。","所以得如斯，有大善方便。"]', '诗', 'shi', '', NULL, '迴波樂 三十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e6062c2-9955-442e-bcb8-76dbd670134a', '迴波樂 三十一', '迴波乐 三十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["人生一世裏，能得幾時活？","迴己審思量，何忍相劫奪。","自命惜求死，煞他不記活。","布施覓聲名，不肯救飢渴。","口道願生天，不免地獄撮。","禮佛至頂盡，終歸被愴割。","一往陷三塗，窮劫不得脫。","寄語世間人，可（項校「不」）可浪夸闊。","各願尋其本，努力棄劫末。","迴心一念頃，萬事即解脫。"]', '["人生一世裏，能得幾时活？","迴己審思量，何忍相劫奪。","自命惜求死，煞他不記活。","布施覓声名，不肯救飢渴。","口道願生天，不免地獄撮。","禮佛至頂尽，終归被愴割。","一往陷三塗，窮劫不得脫。","寄語世间人，可（項校「不」）可浪夸闊。","各願尋其本，努力棄劫末。","迴心一念頃，万事即解脫。"]', '诗', 'shi', '', NULL, '迴波樂 三十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0369829-875c-498a-87f2-5ba81b2632ce', '迴波樂 三十二', '迴波乐 三十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我不畏惡名，惡名不須畏。","四大亦無生，信你痛謗誹。","你自之於我，於我何所費？","不辭應對你，至到（項校「對」）無氣味。"]', '["我不畏惡名，惡名不須畏。","四大亦無生，信你痛謗誹。","你自之於我，於我何所費？","不辞應对你，至到（項校「对」）無氣味。"]', '诗', 'shi', '', NULL, '迴波樂 三十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9b1862-971d-4b2b-9e7c-b0c434c9ac7c', '迴波樂 三十三', '迴波乐 三十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["可笑世間人，爲言恒不死。","貪□（原作「懦」，抹去，旁改字漫漶，陳補「恡」字）不知休，相憎不解止。","背地道他非，對面伊不是。","埋著黃蒿中，猶成薄媚鬼。"]', '["可笑世间人，爲言恒不死。","貪□（原作「懦」，抹去，旁改字漫漶，陳補「恡」字）不知休，相憎不解止。","背地道他非，对面伊不是。","埋著黄蒿中，猶成薄媚鬼。"]', '诗', 'shi', '', NULL, '迴波樂 三十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69c5db9d-69f1-4c43-9739-7172ade9f330', '迴波樂 三十四', '迴波乐 三十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["一旦遊塵境，念俗愛榮華。","不覺三塗苦，八難更來遮。","飄流生死海，託受在毛家。","食蒭無厭足，頭上著繩麻。"]', '["一旦游塵境，念俗愛榮华。","不覺三塗苦，八难更来遮。","飄流生死海，託受在毛家。","食蒭無厭足，头上著繩麻。"]', '诗', 'shi', '', NULL, '迴波樂 三十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd650a6a-b27a-4964-bbae-d10d86e853bd', '迴波樂 三十五', '迴波乐 三十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["縱使千乘君，終齊一箇死。","縱令萬品食，終同一種屎。","釋迦窮八字，老君守一理。","若欲離死生，當須急思此。","夜夢與晝遊，本不相知爾。","夢惡便生懊，夢好覺便喜。","你信齋戒身，本自不識你。","欲驗死更生，方斯以類比。"]', '["縱使千乘君，終齊一箇死。","縱令万品食，終同一種屎。","釋迦窮八字，老君守一理。","若欲離死生，當須急思此。","夜梦與晝游，本不相知爾。","梦惡便生懊，梦好覺便喜。","你信斋戒身，本自不識你。","欲驗死更生，方斯以類比。"]', '诗', 'shi', '', NULL, '迴波樂 三十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e55133bb-5d0d-43ca-903a-91db2055d667', '迴波樂 三十六', '迴波乐 三十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["你今意況大聰，不語修道有功。","亦無二邊不著，亦復不住太空。","衆生不解執有，只爲心裏不通。","迷人已南作北，又亦不[辨]（辯）西東。","念箇癡人學道，終日竟夜忩忩。","只都（項校「覩」）小兒無智，何異世諦盲聾。"]', '["你今意況大聰，不語修道有功。","亦無二邊不著，亦复不住太空。","衆生不解執有，只爲心裏不通。","迷人已南作北，又亦不[辨]（辯）西东。","念箇癡人学道，終日竟夜忩忩。","只都（項校「覩」）小兒無智，何異世諦盲聾。"]', '诗', 'shi', '', NULL, '迴波樂 三十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6fbb9b7-0a98-4579-8e33-71b3c4fabdb4', '迴波樂 三十七', '迴波乐 三十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["大丈夫，遊蕩出三途。","榮名何足捨，妻子士（陳校作「有」，項謂「視」之訛）如無。","法忍先將三毒共，佛性（一）常與六情俱。","但信研心性妙寶，何煩衣外覓明珠。"]', '["大丈夫，游蕩出三途。","榮名何足捨，妻子士（陳校作「有」，項謂「視」之訛）如無。","法忍先將三毒共，佛性（一）常與六情俱。","但信研心性妙寶，何煩衣外覓明珠。"]', '诗', 'shi', '', NULL, '迴波樂 三十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('072d7c62-2bae-47b1-8eb9-450cede557e1', '迴波樂 三十八', '迴波乐 三十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["大丈夫，性識本清虛。","無心妨世事，觸物任情居。"]', '["大丈夫，性識本清虛。","無心妨世事，觸物任情居。"]', '诗', 'shi', '', NULL, '迴波樂 三十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3499716-1b61-4098-8eb4-1d9ed6c319b0', '迴波樂 三十九', '迴波乐 三十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["學問莫倚聰明，打卻我慢貢高。","出家解脫無年（項校「事」），永離三界逍遙。","坐禪解空無相，皆皆實覓□□。","□□□□□□，□□□□□□。","法界以爲家舍，任從自在條條（項校「翛翛」）。","形（下缺）。","。"]', '["学问莫倚聰明，打卻我慢貢高。","出家解脫無年（項校「事」），永離三界逍遙。","坐禪解空無相，皆皆實覓□□。","□□□□□□，□□□□□□。","法界以爲家舍，任從自在條條（項校「翛翛」）。","形（下缺）。","。"]', '诗', 'shi', '', NULL, '迴波樂 三十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b4cbea-fcb5-4d4b-8485-c42ee5526a18', '迴波樂 四十', '迴波乐 四十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["慎事罪不生，忍嗔必有□。","□□□□□，□□□□□。","□□□部宰。","捉此用爲心。","高（下缺）。"]', '["慎事罪不生，忍嗔必有□。","□□□□□，□□□□□。","□□□部宰。","捉此用爲心。","高（下缺）。"]', '诗', 'shi', '', NULL, '迴波樂 四十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc3068c5-1a4b-4789-872b-0f775dfb06c4', '迴波樂 四十一', '迴波乐 四十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["衆生發大願，□□□□□。","□□在前亡，論時依大道。","病得子孫扶，□□□□□。","□□□□□，□須更懊惱。"]', '["衆生發大願，□□□□□。","□□在前亡，論时依大道。","病得子孫扶，□□□□□。","□□□□□，□須更懊惱。"]', '诗', 'shi', '', NULL, '迴波樂 四十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d24adbd3-a97b-436b-a367-6e6c991f352c', '迴波樂 四十二', '迴波乐 四十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["□□□□□，□□□□錯。","終歸一聚塵，何用深棺槨。","土下螻蟻飡，但□□□□（張錄作「衆生發大願」）。","□□□□□，平章自埋卻。"]', '["□□□□□，□□□□錯。","終归一聚塵，何用深棺槨。","土下螻蟻飡，但□□□□（張錄作「衆生發大願」）。","□□□□□，平章自埋卻。"]', '诗', 'shi', '', NULL, '迴波樂 四十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a2b724-6368-421d-80f9-b7138fa62b60', '迴波樂 四十三', '迴波乐 四十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["□□□□□，兒大君須死。","天使遣如然，兩俱不得止。","愚夫無所知，欲得見□□。","□□□□□，□□□欲死。"]', '["□□□□□，兒大君須死。","天使遣如然，兩俱不得止。","愚夫無所知，欲得见□□。","□□□□□，□□□欲死。"]', '诗', 'shi', '', NULL, '迴波樂 四十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d191e2d5-4526-4e02-ad28-bec56ea7e800', '迴波樂 四十四', '迴波乐 四十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兒子有亦好，無亦甚其精。","有時愁□□，□□□□□。","不愁你亦是，一種大星星。"]', '["兒子有亦好，無亦甚其精。","有时愁□□，□□□□□。","不愁你亦是，一種大星星。"]', '诗', 'shi', '', NULL, '迴波樂 四十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b554af12-447a-4f75-ad2c-9b98df8e4d68', '迴波樂 四十五', '迴波乐 四十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["□□□□料，並是天斟酌。","貯積擬孫兒，論時幾許錯。","死活並由天，貧富□□□，□（陳補「己」字）餓畏兒飢，從頭少一杓。","（以上皆見蘇聯科學院東方學研究後列寧格勒分所藏敦煌寫卷，卷末題：「大曆六年五月□日抄王梵志詩一百一十首，沙門弘忍寫之記。","」寫卷前半不存。","轉錄自《敦煌學》第十二輯〖一九八七年出版〗刊陳慶浩《法忍抄本殘卷王梵志詩初校》。","所據爲蘇聯藏列一四五六卷。","另參項楚《列一四五六號王梵志詩殘卷補校》。","又張錫厚《王梵志詩校輯補遺》收七首殘詩，任半塘先生《敦煌歌辭總編》卷三錄《迴波樂》七首、《隱去來》二首，附收詩七首，今均取以參校。","）。"]', '["□□□□料，並是天斟酌。","貯積擬孫兒，論时幾許錯。","死活並由天，貧富□□□，□（陳補「己」字）餓畏兒飢，從头少一杓。","（以上皆见蘇聯科学院东方学研究後列寧格勒分所藏敦煌寫卷，卷末題：「大曆六年五月□日抄王梵志诗一百一十首，沙门弘忍寫之記。","」寫卷前半不存。","轉錄自《敦煌学》第十二輯〖一九八七年出版〗刊陳慶浩《法忍抄本殘卷王梵志诗初校》。","所據爲蘇聯藏列一四五六卷。","另參項楚《列一四五六號王梵志诗殘卷補校》。","又張錫厚《王梵志诗校輯補遺》收七首殘诗，任半塘先生《敦煌歌辞總編》卷三錄《迴波乐》七首、《隐去来》二首，附收诗七首，今均取以參校。","）。"]', '诗', 'shi', '', NULL, '迴波樂 四十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('543ae211-1713-472e-959d-9ef9375f7d6e', '迴波樂 四十六', '迴波乐 四十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世有一種人，可笑窮奇物。","閑則著五欲，急時便□□（項補「依佛」）。","□□□□□，□□持戒律。","好結無情伴，招喚共放逸。","心淨不[禮]□，□□□□□。"]', '["世有一種人，可笑窮奇物。","闲則著五欲，急时便□□（項補「依佛」）。","□□□□□，□□持戒律。","好結無情伴，招喚共放逸。","心淨不[禮]□，□□□□□。"]', '诗', 'shi', '', NULL, '迴波樂 四十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8b4f7eb-9024-4563-a10d-a1bc3af1eeb5', '迴波樂 四十七', '迴波乐 四十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["天下大癡人，皆悉爭名利。","聞好耳卓豎，道□□□□。","□□□□□，各自稱賢智。","一朝糞袋冷，合本總失智。"]', '["天下大癡人，皆悉爭名利。","闻好耳卓豎，道□□□□。","□□□□□，各自稱賢智。","一朝糞袋冷，合本總失智。"]', '诗', 'shi', '', NULL, '迴波樂 四十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('645d277b-0263-4581-a8b3-5abce7b0c021', '迴波樂 四十八', '迴波乐 四十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["教你修道時，使你得長年。","他物實莫取，自物亦□□。","□□□□□，□□□□緣。","若無自他見，何處有心偏。","如斯不得道，從君更問天。"]', '["教你修道时，使你得长年。","他物實莫取，自物亦□□。","□□□□□，□□□□緣。","若無自他见，何处有心偏。","如斯不得道，從君更问天。"]', '诗', 'shi', '', NULL, '迴波樂 四十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5474e028-6d94-4ac6-af7b-65cfa67f1101', '迴波樂 四十九', '迴波乐 四十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["知足即是富，不假多錢財。","谷深塞易滿，心淺最難填。","盛衰皆是一，生死亦同然。","無常意可見，何勞求百年。"]', '["知足即是富，不假多錢財。","谷深塞易满，心淺最难填。","盛衰皆是一，生死亦同然。","無常意可见，何勞求百年。"]', '诗', 'shi', '', NULL, '迴波樂 四十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af464403-8b58-4d98-83c9-4f95f101e294', '迴波樂 五十', '迴波乐 五十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["千年與一年，終同一日活。","昨宵即是空，今朝焉得脫。","無事損心神，內外相宗撮。","驅驅勞你形，耳中常聒聒。"]', '["千年與一年，終同一日活。","昨宵即是空，今朝焉得脫。","無事損心神，內外相宗撮。","驱驱勞你形，耳中常聒聒。"]', '诗', 'shi', '', NULL, '迴波樂 五十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('053fa442-0fb2-4756-ab47-62a497552e80', '迴波樂 五十一', '迴波乐 五十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["凡夫真可念，未達宿因緣。","漫將愁自縛，浪捉寸心懸。","任生不得生，求眠不得眠。","情中常切切，燋燋度百年。"]', '["凡夫真可念，未達宿因緣。","漫將愁自縛，浪捉寸心懸。","任生不得生，求眠不得眠。","情中常切切，燋燋度百年。"]', '诗', 'shi', '', NULL, '迴波樂 五十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdc45399-a118-4e14-b3fc-fb818396c7fa', '迴波樂 五十二', '迴波乐 五十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我身若是我，死活應自由。","死既不由我，自外更何求。","死生人本分，古來有去留。","如能曉此者，知復更何憂。"]', '["我身若是我，死活應自由。","死既不由我，自外更何求。","死生人本分，古来有去留。","如能晓此者，知复更何憂。"]', '诗', 'shi', '', NULL, '迴波樂 五十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56fe4d96-82f7-470b-a18a-2f58f8fdd682', '迴波樂 五十三', '迴波乐 五十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["悟道雖一餉，曠大劫來因。","釋迦登正覺，却禮發心人。","身本不離佛，佛本不離身。","迷心去處暗，明神即辨真。"]', '["悟道雖一餉，曠大劫来因。","釋迦登正覺，却禮發心人。","身本不離佛，佛本不離身。","迷心去处暗，明神即辨真。"]', '诗', 'shi', '', NULL, '迴波樂 五十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f862800-d33c-46aa-8070-cf36fc7be88e', '迴波樂 五十四', '迴波乐 五十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["由心生妄相，無形本會真。","但看氣新斷，妻子即他人。","魂魄歸五道，屍骸謝六塵。","驗斯柏（項校「怕」）散壞，何處有君身。"]', '["由心生妄相，無形本會真。","但看氣新斷，妻子即他人。","魂魄归五道，屍骸謝六塵。","驗斯柏（項校「怕」）散壞，何处有君身。"]', '诗', 'shi', '', NULL, '迴波樂 五十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95511075-9353-4293-88fc-e6e95b0b9bbe', '迴波樂 五十五', '迴波乐 五十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["福門不肯修，福失競奔馳。","熟見苦樂別，偷生佯不知。","安身染著慾，貪世竟無疲。","故知地獄罪，怨佛無慈悲。"]', '["福门不肯修，福失競奔驰。","熟见苦乐別，偷生佯不知。","安身染著慾，貪世竟無疲。","故知地獄罪，怨佛無慈悲。"]', '诗', 'shi', '', NULL, '迴波樂 五十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a403f47-61fd-4a47-83f6-030b241e1225', '迴波樂 五十六', '迴波乐 五十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["莫言己之是，勿說他人非。","道是失其是，道非得其非，白珪之玷尚可磨，斯言之[玷]（理）不可爲。"]', '["莫言己之是，勿说他人非。","道是失其是，道非得其非，白珪之玷尚可磨，斯言之[玷]（理）不可爲。"]', '诗', 'shi', '', NULL, '迴波樂 五十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef2fd41-90e5-456a-a5a1-184a2f81cbf2', '迴波樂 五十七', '迴波乐 五十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我有你不喜，你有我不嗔。","你貧憎我富，我富憐你貧。","行好得天報，爲惡罪你身。","你若不信我，你且勘經文。"]', '["我有你不喜，你有我不嗔。","你貧憎我富，我富怜你貧。","行好得天報，爲惡罪你身。","你若不信我，你且勘經文。"]', '诗', 'shi', '', NULL, '迴波樂 五十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('956d9a15-ca97-4061-a9f8-6c7a800347de', '迴波樂 五十八', '迴波乐 五十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["任意隨流俗，凡夫信是非。","日常三頓飯，年恒兩覆衣。","不問單將複，誰論稠與稀。","但令無外事，祇爾自然肥。"]', '["任意隨流俗，凡夫信是非。","日常三頓飯，年恒兩覆衣。","不问單將複，誰論稠與稀。","但令無外事，祇爾自然肥。"]', '诗', 'shi', '', NULL, '迴波樂 五十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491e0ceb-b340-41c3-80a0-bfcb5e75bf87', '迴波樂 五十九', '迴波乐 五十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["學行百千般，澄心遍照看。","泥犁映兜率，因生有湼槃。","世間諸法相，浩浩亦其寬。","欲說深心義，無求最大安。"]', '["学行百千般，澄心遍照看。","泥犁映兜率，因生有湼槃。","世间諸法相，浩浩亦其寬。","欲说深心義，無求最大安。"]', '诗', 'shi', '', NULL, '迴波樂 五十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('927e3c8e-6c7b-4c71-a898-64f0a880df16', '迴波樂 六十', '迴波乐 六十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["吾有方丈室，裏有一雜物。","萬像俱悉包，參羅亦不出。","日月亮其中，衆生無得失。","三界湛然安，中有無數佛。"]', '["吾有方丈室，裏有一杂物。","万像俱悉包，參羅亦不出。","日月亮其中，衆生無得失。","三界湛然安，中有無數佛。"]', '诗', 'shi', '', NULL, '迴波樂 六十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf5a3154-d66e-41b2-8dec-533112a11014', '迴波樂 六十一', '迴波乐 六十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有此幻身來，尋思不自識。","言從四大生，別有一種賊。","能悉佛性眼，還如暗裏墨。","計此似神通，輸迴有智力。","若欲具真如，勤苦修功德。","佛在五蔭中，努力向心剋。"]', '["有此幻身来，尋思不自識。","言從四大生，別有一種賊。","能悉佛性眼，還如暗裏墨。","計此似神通，輸迴有智力。","若欲具真如，勤苦修功德。","佛在五蔭中，努力向心剋。"]', '诗', 'shi', '', NULL, '迴波樂 六十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93435715-2c41-4bfe-ab6a-ca295025da73', '迴波樂 六十二', '迴波乐 六十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["若欲覓佛道，先觀五蔭好。","妙寶非外求，黑暗由心造。","善惡既不二，元來無大小。","設教顯三乘，法門奇浩浩。","觸目即安心，若箇非珍寶。","明識生死因，努力自研考。"]', '["若欲覓佛道，先观五蔭好。","妙寶非外求，黑暗由心造。","善惡既不二，元来無大小。","設教显三乘，法门奇浩浩。","觸目即安心，若箇非珍寶。","明識生死因，努力自研考。"]', '诗', 'shi', '', NULL, '迴波樂 六十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('484a1c2f-f944-4f05-a2d2-e509d0e65b5e', '迴波樂 六十三', '迴波乐 六十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["人心不可識，善惡實難知。","看面真如相，腹中懷蒺藜。","口共經文語，借猫搦鼠兒。","雖然斷夜食，小家行大慈。","。"]', '["人心不可識，善惡實难知。","看面真如相，腹中懷蒺藜。","口共經文語，借猫搦鼠兒。","雖然斷夜食，小家行大慈。","。"]', '诗', 'shi', '', NULL, '迴波樂 六十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a4ac7d-6085-469f-91bb-1cd680830ff5', '迴波樂 六十四', '迴波乐 六十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["貪癡不肯捨，徒勞斷酒肉。","終日說他過，持齋空餓腹。","三毒日日增，四蛇不可觸。","天堂未有因，箭射入地獄。"]', '["貪癡不肯捨，徒勞斷酒肉。","終日说他過，持斋空餓腹。","三毒日日增，四蛇不可觸。","天堂未有因，箭射入地獄。"]', '诗', 'shi', '', NULL, '迴波樂 六十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a2df13-a281-4453-a8d9-adb45ce983b6', '迴波樂 六十五', '迴波乐 六十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["道從歡喜生，還從瞋恚滅。","佛性[盈兩]（兩盈）間，由人作巧拙。","天堂在目前，地獄非虛說。","努力善思量，終身須急結。","斬斷三毒箭，恩愛亦難絕。","明識大乘因，鑊湯亦不熱。"]', '["道從歡喜生，還從瞋恚滅。","佛性[盈兩]（兩盈）间，由人作巧拙。","天堂在目前，地獄非虛说。","努力善思量，終身須急結。","斬斷三毒箭，恩愛亦难絕。","明識大乘因，鑊湯亦不熱。"]', '诗', 'shi', '', NULL, '迴波樂 六十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50069b2-ff83-492a-867f-58d970be8d15', '迴波樂 六十六', '迴波乐 六十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["斷諸惡，細細詃（項校「去」）貪嗔。","若使如羅漢，即自絕囂塵。","將刀且割無明暗，復用利劍斷親姻。","究竟湼槃非是遠，尋思寂滅即爲鄰。","只是衆生不牽致，所以沉淪罪業深。","努力努力遵三寶，[何]愁何慮不全身。"]', '["斷諸惡，細細詃（項校「去」）貪嗔。","若使如羅漢，即自絕囂塵。","將刀且割無明暗，复用利劍斷親姻。","究竟湼槃非是远，尋思寂滅即爲鄰。","只是衆生不牽致，所以沉淪罪業深。","努力努力遵三寶，[何]愁何慮不全身。"]', '诗', 'shi', '', NULL, '迴波樂 六十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a67bb73c-fb80-4e69-94d5-4e582d5a1350', '迴波樂 六十七', '迴波乐 六十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["一生不作罪，又復非修福。","騰騰處俗間，遊遊覓衣食。","衣食纔以足，不事凡榮飾。","此則是如來，何勞住西域。"]', '["一生不作罪，又复非修福。","腾腾处俗间，游游覓衣食。","衣食纔以足，不事凡榮飾。","此則是如来，何勞住西域。"]', '诗', 'shi', '', NULL, '迴波樂 六十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad8f074-6aac-4368-9d5a-9632255cb33b', '迴波樂 六十八', '迴波乐 六十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我本野外夫，不能恒禮則。","爲性重任真，喫著隨所得。","既與萬物齊，方（項校「於」）□（張錫厚撥補「中」字）守靜默。","一身逢太平，五內無六賊。","（見斯四二七七卷，轉錄自《中華文史論叢》一九八四年第二輯刊張錫厚《斯四二七七殘卷考釋》。","）（按：斯四二七七卷，原無作者名。","張錫厚初擬題爲梵志體詩。","後經與蘇藏列一四五六卷重新綴合，確定此卷亦應爲王梵志詩，今從其說收入。","）。"]', '["我本野外夫，不能恒禮則。","爲性重任真，喫著隨所得。","既與万物齊，方（項校「於」）□（張錫厚撥補「中」字）守静默。","一身逢太平，五內無六賊。","（见斯四二七七卷，轉錄自《中华文史論叢》一九八四年第二輯刊張錫厚《斯四二七七殘卷考釋》。","）（按：斯四二七七卷，原無作者名。","張錫厚初擬題爲梵志體诗。","後經與蘇藏列一四五六卷重新綴合，確定此卷亦應爲王梵志诗，今從其说收入。","）。"]', '诗', 'shi', '', NULL, '迴波樂 六十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd980318-f50d-4abe-a0ab-8b248df53e39', '迴波樂 六十九', '迴波乐 六十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["（上缺）剝削。","貯積千年調，擬覓□□□。","□□□□□，□□[□□]惡。","方便還他債，駈遣耕田□。","□鼻斷領牛，杖打過腿膊。","自造還自受，努力祇當却。"]', '["（上缺）剝削。","貯積千年調，擬覓□□□。","□□□□□，□□[□□]惡。","方便還他債，駈遣耕田□。","□鼻斷領牛，杖打過腿膊。","自造還自受，努力祇當却。"]', '诗', 'shi', '', NULL, '迴波樂 六十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb615933-2f45-48de-865f-049ef2882205', '迴波樂 七十', '迴波乐 七十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["人間養男女，直（項校「真」）成鳥養兒。","長大毛衣好，各自覓高飛。","女嫁他將去，兒心（戴校「征」）死不歸。","夫妻一箇死，喻如黃擘皮。","重重被剝削，獨苦自身知。","生在常煩惱，死後無人悲。","寄語冥路道，還我未生時。","。"]', '["人间養男女，直（項校「真」）成鸟養兒。","长大毛衣好，各自覓高飞。","女嫁他將去，兒心（戴校「征」）死不归。","夫妻一箇死，喻如黄擘皮。","重重被剝削，独苦自身知。","生在常煩惱，死後無人悲。","寄語冥路道，還我未生时。","。"]', '诗', 'shi', '', NULL, '迴波樂 七十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0532facd-d967-48a1-b49f-216b467046ff', '迴波樂 七十一', '迴波乐 七十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["[□□□]有死，來去不相離。","常居五濁地，更亦取頭皮。","縱百年活（此句缺一字），須臾一向子。","彭祖七百歲，終成老爛鬼。","託身得他鄉，隨生作名字。","輪廻[□]動急，生死不[□]你。","身帶無常苦，長命何須喜。"]', '["[□□□]有死，来去不相離。","常居五濁地，更亦取头皮。","縱百年活（此句缺一字），須臾一向子。","彭祖七百歲，終成老爛鬼。","託身得他乡，隨生作名字。","輪廻[□]动急，生死不[□]你。","身带無常苦，长命何須喜。"]', '诗', 'shi', '', NULL, '迴波樂 七十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7210931-cf56-4bfe-af94-0c2662aa2dda', '迴波樂 七十二', '迴波乐 七十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["不見念佛聲，滿街聞哭[響]（嚮）。","生時同氈被，死則嫌屍妨。","臭穢不中停，火急須埋葬。","早死無差科，不愁怕里長。","行人展脚臥，永絕呼征防。","生促死路長，久住何益當。"]', '["不见念佛声，满街闻哭[响]（嚮）。","生时同氈被，死則嫌屍妨。","臭穢不中停，火急須埋葬。","早死無差科，不愁怕里长。","行人展脚臥，永絕呼征防。","生促死路长，久住何益當。"]', '诗', 'shi', '', NULL, '迴波樂 七十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e235d2-ce0a-48f2-8ea0-08a583eb3bbf', '迴波樂 七十三', '迴波乐 七十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["父母生兒身，衣食養兒德。","蹔託寄出來，欲似相便貸。","兒大作兵夫，西征吐蕃賊。","行後渾家死，廻來覓不得。","兒身面向南，死者頭向北。","父子相分擘，不及元不識。"]', '["父母生兒身，衣食養兒德。","蹔託寄出来，欲似相便貸。","兒大作兵夫，西征吐蕃賊。","行後渾家死，廻来覓不得。","兒身面向南，死者头向北。","父子相分擘，不及元不識。"]', '诗', 'shi', '', NULL, '迴波樂 七十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efe8da14-2418-4c75-94b0-22c58f9fe40e', '迴波樂 七十四', '迴波乐 七十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["身是五陰（一作「蔭」）城，周廻無里數。","上下九穴門，膿流皆臭瘀。","湛然膿血間，安置八萬戶。","餘有九（一作「四」）千家，出沒同居住。","攘攘相食噉，貼貼無言語。","總在糞尿中，不解相蛆姡。","身行城即移，身臥城穩具（一作「住」）。","身死城破壞，百姓無安處。"]', '["身是五陰（一作「蔭」）城，周廻無里數。","上下九穴门，膿流皆臭瘀。","湛然膿血间，安置八万戶。","餘有九（一作「四」）千家，出沒同居住。","攘攘相食噉，貼貼無言語。","總在糞尿中，不解相蛆姡。","身行城即移，身臥城穩具（一作「住」）。","身死城破壞，百姓無安处。"]', '诗', 'shi', '', NULL, '迴波樂 七十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c86d996-bace-4772-9141-3ea88d27e038', '迴波樂 七十五', '迴波乐 七十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["生死如流星，涓涓向前去。","前死萬年餘，尋入微塵數。","中死千年外，骨石化爲土。","後死百年強，形骸在墳墓。","續續死將埋，地窄無安處。","已後燒作灰，颺却隨風去。"]', '["生死如流星，涓涓向前去。","前死万年餘，尋入微塵數。","中死千年外，骨石化爲土。","後死百年強，形骸在墳墓。","續續死將埋，地窄無安处。","已後燒作灰，颺却隨风去。"]', '诗', 'shi', '', NULL, '迴波樂 七十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7308d486-8da7-4a81-a380-1d92bc1f57bc', '迴波樂 七十六', '迴波乐 七十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["前死未長別，後來亦非久（項校「非久親」）。","新墳影舊塚，相續似魚鱗。","義陵秋節遠，曾逢幾箇春。","萬刼同今日，一種化微塵。","定知見土裏，還待（一作「得」）昔時人。","頻聞積代骨，爲坑埋我身。","（〖1〗項謂此首爲北周釋亡名《五盛陰詩》之改作。","）。"]', '["前死未长別，後来亦非久（項校「非久親」）。","新墳影旧塚，相續似鱼鱗。","義陵秋節远，曾逢幾箇春。","万刼同今日，一種化微塵。","定知见土裏，還待（一作「得」）昔时人。","頻闻積代骨，爲坑埋我身。","（〖1〗項謂此首爲北周釋亡名《五盛陰诗》之改作。","）。"]', '诗', 'shi', '', NULL, '迴波樂 七十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe5c003-d0a6-4555-94ba-fec05b774c6d', '迴波樂 七十七', '迴波乐 七十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["不淨膿血（一作「流」）袋，四大共爲因（戴校「身」）。","六賊都成體，敗壞一時分。","風者吹將散，火者焰來親。","水者常流急，土者合成人。","體骨變爲土，還歸足下塵。"]', '["不淨膿血（一作「流」）袋，四大共爲因（戴校「身」）。","六賊都成體，敗壞一时分。","风者吹將散，火者焰来親。","水者常流急，土者合成人。","體骨变爲土，還归足下塵。"]', '诗', 'shi', '', NULL, '迴波樂 七十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475780f6-8ec5-457f-8de1-04f01bfbd1f9', '迴波樂 七十八', '迴波乐 七十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["前人敬吾重，吾敬前人深。","恩來即義往，未許却相尋。","有（一作「前」）能賜白玉，吾亦奉黃金。","君看我莫落，還同陌路人。"]', '["前人敬吾重，吾敬前人深。","恩来即義往，未許却相尋。","有（一作「前」）能賜白玉，吾亦奉黄金。","君看我莫落，還同陌路人。"]', '诗', 'shi', '', NULL, '迴波樂 七十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95ac305c-461b-4ee3-bef5-9e44baa10b73', '迴波樂 七十九', '迴波乐 七十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["不思身去促，能貪無限財。","生平惜（一作「借」）不用，命盡如糞堆。","蟲蛆內攘攘，食脉爛穴開。","羅錦纏屍送，枉屈寶將埋。","寧知入土後，二節變爲灰。"]', '["不思身去促，能貪無限財。","生平惜（一作「借」）不用，命尽如糞堆。","蟲蛆內攘攘，食脉爛穴开。","羅錦纏屍送，枉屈寶將埋。","寧知入土後，二節变爲灰。"]', '诗', 'shi', '', NULL, '迴波樂 七十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bac35f8d-dae2-4d37-9d32-a0374580b067', '迴波樂 八十', '迴波乐 八十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["一聯無舍坐，須行去處寬（一作「魂」）。","少食巡門乞，文破忍饑寒。","迥獨一身活，病困遣誰看。","命絕拋坑裡，狼狐（一作「狐狼」）恣意飡。"]', '["一聯無舍坐，須行去处寬（一作「魂」）。","少食巡门乞，文破忍饑寒。","迥独一身活，病困遣誰看。","命絕拋坑裡，狼狐（一作「狐狼」）恣意飡。"]', '诗', 'shi', '', NULL, '迴波樂 八十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d38af41-5f6a-44f9-932f-daa935b7b358', '迴波樂 八十一', '迴波乐 八十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["祭四時八節日（此句衍一字），家家總哭聲。","侍養不孝子，酒食祭先靈。","將（一作「總」）被外鬼哭，家親本無名。","一郡巡門鬼，噇盡捖鳴（一作「椀名」）聲。"]', '["祭四时八節日（此句衍一字），家家總哭声。","侍養不孝子，酒食祭先靈。","將（一作「總」）被外鬼哭，家親本無名。","一郡巡门鬼，噇尽捖鳴（一作「椀名」）声。"]', '诗', 'shi', '', NULL, '迴波樂 八十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125f666a-303b-49b2-b21f-42fd73c61cc4', '迴波樂 八十二', '迴波乐 八十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["身（項校「聞」）強被（一作「避」）却罪，修福只心懃。","專意涓涓念，時時報佛恩。","得病不須卜，實莫浪求神。","專心念三報（一作「寶」），莫亂自家身。","十念得成就，化佛自迎君。","若能自安置，拋（一作「塊」）却帶囚（一作「田」）身。"]', '["身（項校「闻」）強被（一作「避」）却罪，修福只心懃。","專意涓涓念，时时報佛恩。","得病不須卜，實莫浪求神。","專心念三報（一作「寶」），莫亂自家身。","十念得成就，化佛自迎君。","若能自安置，拋（一作「塊」）却带囚（一作「田」）身。"]', '诗', 'shi', '', NULL, '迴波樂 八十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('069ca9bb-7d93-4085-8094-813cc4bc1ef1', '迴波樂 八十三', '迴波乐 八十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["年（一作「牛」）老造新舍，鬼來拍手哭。","身（一作「舍」）得蹔時坐，死後他人（一作「將」）賣。","千年換百主，各自想還（一作「將迴」）改。","前死後人坐，本主何須（項校「相」，即「廂」）在。"]', '["年（一作「牛」）老造新舍，鬼来拍手哭。","身（一作「舍」）得蹔时坐，死後他人（一作「將」）賣。","千年換百主，各自想還（一作「將迴」）改。","前死後人坐，本主何須（項校「相」，即「廂」）在。"]', '诗', 'shi', '', NULL, '迴波樂 八十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3046591-cd7f-4d08-9f9e-75682c8601e8', '迴波樂 八十四', '迴波乐 八十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["身體骨崖崖，面皮千道皺。","行時頭即低，策杖與人語。","眼中雙淚流，鼻涕（一作「滿」）垂入口。","腰似斷（一作「就」）弦弓，引氣{口廋}喘急（一作「𪢐」）。","口裏無牙齒，強嫌寡婦醜。","聞好不惜錢，急送一榼酒。","前人許賜（一作「賜許」）婚，判命（一作「死」）向前走。","迎得少年妻，褒揚殊面首。","傍邊乾咽唾，恰（一作「憐」）似守碓狗。","舂人收糠將，舐略（項校「掠」）空唇口。","忽逢三煞頭，一棒即了手。"]', '["身體骨崖崖，面皮千道皺。","行时头即低，策杖與人語。","眼中雙泪流，鼻涕（一作「满」）垂入口。","腰似斷（一作「就」）弦弓，引氣{口廋}喘急（一作「𪢐」）。","口裏無牙齒，強嫌寡婦醜。","闻好不惜錢，急送一榼酒。","前人許賜（一作「賜許」）婚，判命（一作「死」）向前走。","迎得少年妻，褒揚殊面首。","傍邊乾咽唾，恰（一作「怜」）似守碓狗。","舂人收糠將，舐略（項校「掠」）空唇口。","忽逢三煞头，一棒即了手。"]', '诗', 'shi', '', NULL, '迴波樂 八十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c0d7ee-da3a-4fac-a23b-585212ab5573', '迴波樂 八十五', '迴波乐 八十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["父母憐（一作「烚」）男女，保愛（一作「受」）掌中珠。","亦（張改作「一」）死手遮面，將衣即覆頭。","死朴哭真鬼，連夜不知休。","天明奈何（張改作「河」）送，埋着棘嵩丘（一作「高坵」）。","耶孃腸（一作「腹」）寸斷，曾祖共悲愁。","獨守丘荒界（一作「野」），不知春夏秋（冬）。","但知墳下睡，萬事不能憂。","寒食[墓]（慕）邊哭，却被鬼耶（一作「邪」）由。"]', '["父母怜（一作「烚」）男女，保愛（一作「受」）掌中珠。","亦（張改作「一」）死手遮面，將衣即覆头。","死朴哭真鬼，連夜不知休。","天明奈何（張改作「河」）送，埋着棘嵩丘（一作「高坵」）。","耶孃腸（一作「腹」）寸斷，曾祖共悲愁。","独守丘荒界（一作「野」），不知春夏秋（冬）。","但知墳下睡，万事不能憂。","寒食[墓]（慕）邊哭，却被鬼耶（一作「邪」）由。"]', '诗', 'shi', '', NULL, '迴波樂 八十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d61ce42-cea3-462b-a042-bbd9dd644c76', '迴波樂 八十六', '迴波乐 八十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["富兒少男女，窮漢生一羣。","身上無衣着（一作「挂」），長頭草裏存（一作「蹲」）。","到大（一作「例頭」）肥沒忽，直似飽糠{牛丨=乚}（一作「{月牛}」，項校「{月牛}」）。","長大充兵朴（一作「兵夫來」），未解起（項校「棄」）家門。","積代不得富，號曰（一作「名」）窮漢村。"]', '["富兒少男女，窮漢生一羣。","身上無衣着（一作「挂」），长头草裏存（一作「蹲」）。","到大（一作「例头」）肥沒忽，直似飽糠{牛丨=乚}（一作「{月牛}」，項校「{月牛}」）。","长大充兵朴（一作「兵夫来」），未解起（項校「棄」）家门。","積代不得富，號曰（一作「名」）窮漢村。"]', '诗', 'shi', '', NULL, '迴波樂 八十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f27a41f2-535b-4d68-912f-953c39091835', '迴波樂 八十七', '迴波乐 八十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["仕人作官職，人中第一好。","行即食天廚，坐時（一作「即」）請月（一作「日」）料。","得祿四季（一作「貴」）領，家口尋常飽。","軄田佃人送，牛馬足䜺草。","每日勤判案，曹司無闠鬧。","差科能均平，欲似車上道。","依（一作「衣」）數向前行，運轉處處到。","既能強（一作「經」）了官，百姓省煩惱。","一得清（一作「青」）白狀，二得三上考。","選日通好名，得官入京兆。"]', '["仕人作官職，人中第一好。","行即食天廚，坐时（一作「即」）請月（一作「日」）料。","得祿四季（一作「貴」）領，家口尋常飽。","軄田佃人送，牛马足䜺草。","每日勤判案，曹司無闠鬧。","差科能均平，欲似车上道。","依（一作「衣」）數向前行，運轉处处到。","既能強（一作「經」）了官，百姓省煩惱。","一得清（一作「青」）白狀，二得三上考。","選日通好名，得官入京兆。"]', '诗', 'shi', '', NULL, '迴波樂 八十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f02127c-ebb8-455b-9881-2022ee4ee7ca', '迴波樂 八十八', '迴波乐 八十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["童子得出家，一生受快樂。","飲（一作「欲」）食滿盂中，架上選衣着。","平明欲（一作「飲」）稀粥，食手調羹臛。","飽（一作「飲」）喫取他錢，此是口客作。","天（一作「大」）王元不朝，父母反拜却。","黠兒苦讀經，發願離濁惡。","身心並出家，色慾無染着。","同時小去（一作「少出」）家，有悟亦有錯。","憨癡求身肥，每日服石（一作「食」）藥。","生（戴校「聖」）佛不拜禮（一作「供養」），財色偏染着。","白日趁身名，兼能依逐樂。","不肯逍遙行，故故相纏縛。","滿街肥統統，恰似鱉無脚。","。"]', '["童子得出家，一生受快乐。","饮（一作「欲」）食满盂中，架上選衣着。","平明欲（一作「饮」）稀粥，食手調羹臛。","飽（一作「饮」）喫取他錢，此是口客作。","天（一作「大」）王元不朝，父母反拜却。","黠兒苦读經，發願離濁惡。","身心並出家，色慾無染着。","同时小去（一作「少出」）家，有悟亦有錯。","憨癡求身肥，每日服石（一作「食」）藥。","生（戴校「聖」）佛不拜禮（一作「供養」），財色偏染着。","白日趁身名，兼能依逐乐。","不肯逍遙行，故故相纏縛。","满街肥統統，恰似鱉無脚。","。"]', '诗', 'shi', '', NULL, '迴波樂 八十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec8c213-1077-42d9-8a3a-06131b3f13b1', '迴波樂 八十九', '迴波乐 八十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["出家多種菓，花蘂競來新。","菴羅能逸熟，獲得未來因。","後園多桃李，花盛亂迎春。","花繁條（一作「枝」）結實，何愁子不真。","努力勤心種，多留與後人。","新人食甘菓，慚（一作「愧」）賀（項校「荷」）種花人。","悉達追遠福，學道莫辭貧。","但能求生路，同證（一作「登」）四果身。"]', '["出家多種菓，花蘂競来新。","菴羅能逸熟，獲得未来因。","後园多桃李，花盛亂迎春。","花繁條（一作「枝」）結實，何愁子不真。","努力勤心種，多留與後人。","新人食甘菓，慚（一作「愧」）賀（項校「荷」）種花人。","悉達追远福，学道莫辞貧。","但能求生路，同證（一作「登」）四果身。"]', '诗', 'shi', '', NULL, '迴波樂 八十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8529917-d418-4d57-a3ae-8d4d049809d0', '迴波樂 九十', '迴波乐 九十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["今得入新年，合家蒙喜慶。","人人皆發願，遠離時氣病。","歲日食他肉，肉是他家命。","今朝入新年，昨暮煞他命（一作「煞他競」）。","論時大罪過，食肉身招病。","一則自短命（一作「壽」），二則（一作「即」）還他命。","負債早還却，門前無諠競。","怨怨來相讎，何時解適（項校「釋」）竟。"]', '["今得入新年，合家蒙喜慶。","人人皆發願，远離时氣病。","歲日食他肉，肉是他家命。","今朝入新年，昨暮煞他命（一作「煞他競」）。","論时大罪過，食肉身招病。","一則自短命（一作「壽」），二則（一作「即」）還他命。","負債早還却，门前無諠競。","怨怨来相讎，何时解適（項校「釋」）竟。"]', '诗', 'shi', '', NULL, '迴波樂 九十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3775d629-520b-48a7-b2fc-62146752a4ce', '迴波樂 九十一', '迴波乐 九十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["父母時怨家，生一五逆子。","養大長成人，元來不得使。","身役不肯料，逃走皆（張改作「離」，項、蔣校「背」）家裏。","阿耶替役身，阿孃氣病死。","腹中懷惡來，自生煞人子。","此是前生惡，故故來相值。","蟲蛇來報恩，人子合如此。","前怨續後怨，何時逍祖唯。"]', '["父母时怨家，生一五逆子。","養大长成人，元来不得使。","身役不肯料，逃走皆（張改作「離」，項、蔣校「背」）家裏。","阿耶替役身，阿孃氣病死。","腹中懷惡来，自生煞人子。","此是前生惡，故故来相值。","蟲蛇来報恩，人子合如此。","前怨續後怨，何时逍祖唯。"]', '诗', 'shi', '', NULL, '迴波樂 九十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d3440b0-4662-4711-8989-90bb8fab9157', '迴波樂 九十二', '迴波乐 九十二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["有錢不造福，甚是老愚癡。","自身不喫着，保（張改作「報」）投受（戴校「持授」）妻兒。","打脊眼不痛，十指不同皮。","飽喫身自（一作「自身」）穩，餓肚身自饑。","積十年調寧（項改「貯積千年調」），知身得幾時（張改二句作「莫積千年調，寧知得幾時。","」）。","一朝身磨滅，萬事不能{宀/兌}（項校「窺」，張改作「究」）。","妻嫁後人婦，子變他家兒。","奴婢換曹主，馬即別人騎。","聞強急修福，莫於（項校「逾」）百年期。"]', '["有錢不造福，甚是老愚癡。","自身不喫着，保（張改作「報」）投受（戴校「持授」）妻兒。","打脊眼不痛，十指不同皮。","飽喫身自（一作「自身」）穩，餓肚身自饑。","積十年調寧（項改「貯積千年調」），知身得幾时（張改二句作「莫積千年調，寧知得幾时。","」）。","一朝身磨滅，万事不能{宀/兌}（項校「窺」，張改作「究」）。","妻嫁後人婦，子变他家兒。","奴婢換曹主，马即別人騎。","闻強急修福，莫於（項校「逾」）百年期。"]', '诗', 'shi', '', NULL, '迴波樂 九十二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3fd1d36-0801-4000-afed-c2bb7f54dce7', '迴波樂 九十三', '迴波乐 九十三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["暫時自來生，暫時還即死。","[死]後却還家，生時寄住鬼。","不愁麥不熟，不怕少穀米。","佯（張改作「陽」）坡展脚臥，不來（項校「采」）世間事。","死去長（一作「常」）眠樂，常恐五濁地。"]', '["暫时自来生，暫时還即死。","[死]後却還家，生时寄住鬼。","不愁麦不熟，不怕少穀米。","佯（張改作「陽」）坡展脚臥，不来（項校「采」）世间事。","死去长（一作「常」）眠乐，常恐五濁地。"]', '诗', 'shi', '', NULL, '迴波樂 九十三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c5f85e-388f-456f-9009-672ef1e39b87', '迴波樂 九十四', '迴波乐 九十四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["身是上陣兵，把刀被煞死。","你若不煞我，我還煞却你。","兩既忽相逢，終須一箇死。","死亦不須憂，生亦不須喜。","（原本二句互乙）須入湼槃城，速離五濁地。","天心（張改作「公」）遣我生，地母收我子。","生死不由我，我是長流水。"]', '["身是上陣兵，把刀被煞死。","你若不煞我，我還煞却你。","兩既忽相逢，終須一箇死。","死亦不須憂，生亦不須喜。","（原本二句互乙）須入湼槃城，速離五濁地。","天心（張改作「公」）遣我生，地母收我子。","生死不由我，我是长流水。"]', '诗', 'shi', '', NULL, '迴波樂 九十四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e399b0-4c58-4974-90f0-8d64b01396fc', '迴波樂 九十五', '迴波乐 九十五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世間亂浩浩，賊多好人少。","逢着光火賊，大堡（戴校「太保」）打少保（項校「小堡」）。","賤價得他物，錢亦不還耀（張改作「糶」、項校「還錢亦不糶」）。","自買（張改作「賣」）索錢多，他買還錢少。","不得萬萬年，營作千年調。"]', '["世间亂浩浩，賊多好人少。","逢着光火賊，大堡（戴校「太保」）打少保（項校「小堡」）。","賤價得他物，錢亦不還耀（張改作「糶」、項校「還錢亦不糶」）。","自買（張改作「賣」）索錢多，他買還錢少。","不得万万年，營作千年調。"]', '诗', 'shi', '', NULL, '迴波樂 九十五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37dcc78c-75f9-4459-b66f-316f4b363b8e', '迴波樂 九十六', '迴波乐 九十六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兀兀（張改作「營營」）自免身，擬覓妻兒好。","切迎（張改「巧遇」）打脊使，窮漢每斈{冫号}（項校「年枵」）。","枉法剝衆生，財是人髓腦。","報絕還他債，家家惣須到。","智者星星（項校「惺惺」）行，愚人自纏遶。"]', '["兀兀（張改作「營營」）自免身，擬覓妻兒好。","切迎（張改「巧遇」）打脊使，窮漢每斈{冫号}（項校「年枵」）。","枉法剝衆生，財是人髓腦。","報絕還他債，家家惣須到。","智者星星（項校「惺惺」）行，愚人自纏遶。"]', '诗', 'shi', '', NULL, '迴波樂 九十六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a3c0878-dc47-4016-bcaf-7de4910e0b7b', '迴波樂 九十七', '迴波乐 九十七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世間何物重？","夫妻取（項、蔣校「最」）是好。","一箇厥磨（張改作「摩」）師，眼看絕行道。","𢣤𢣤（張改作「熏熏」）莫恨天，業是前身報。","妻兒嫁與鬼，你向誰邊告。","教你別取妻，不須苦煩惱。"]', '["世间何物重？","夫妻取（項、蔣校「最」）是好。","一箇厥磨（張改作「摩」）師，眼看絕行道。","𢣤𢣤（張改作「熏熏」）莫恨天，業是前身報。","妻兒嫁與鬼，你向誰邊告。","教你別取妻，不須苦煩惱。"]', '诗', 'shi', '', NULL, '迴波樂 九十七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd653af1-d8fc-4ce9-afa2-52dbff3a0197', '迴波樂 九十八', '迴波乐 九十八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["吾頭何謂自（張改作「爲白」），子孫滿堂宅。","吾今與紀年，盡被時催迫。","要須在前去，前客避後客。","于（項校「逾」）時未與死，眼看天地[窄]（官）。"]', '["吾头何謂自（張改作「爲白」），子孫满堂宅。","吾今與紀年，尽被时催迫。","要須在前去，前客避後客。","于（項校「逾」）时未與死，眼看天地[窄]（官）。"]', '诗', 'shi', '', NULL, '迴波樂 九十八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffc69ebf-a000-48c8-98bc-4ebcc6bb9728', '迴波樂 九十九', '迴波乐 九十九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["朝庭來相過，設食因盃酌。","四海同追由（項校「遊」），五郡爲勸樂。","義故及三代，死活相憑託。","合去正身行，不容君（戴校「名」）字錯。","雇人即棒脊，急手攝你脚。"]', '["朝庭来相過，設食因盃酌。","四海同追由（項校「游」），五郡爲勸乐。","義故及三代，死活相憑託。","合去正身行，不容君（戴校「名」）字錯。","雇人即棒脊，急手攝你脚。"]', '诗', 'shi', '', NULL, '迴波樂 九十九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b7cbe0-4a25-4634-9429-89d056769ae8', '迴波樂 一○○', '迴波乐 一○○', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["知識相伴侶，蹔時不覺老。","面皺黑髮白，把杖入長道。","眼中冷淚下，病多好時少。","怨家烏枯眼，無睡（張錄作「眠」字）天難曉。","朝夕乞蹔時，百長（張改作「年」）誰肯保。","使者門前喚，手脚婆羅草。"]', '["知識相伴侶，蹔时不覺老。","面皺黑髮白，把杖入长道。","眼中冷泪下，病多好时少。","怨家烏枯眼，無睡（張錄作「眠」字）天难晓。","朝夕乞蹔时，百长（張改作「年」）誰肯保。","使者门前喚，手脚婆羅草。"]', '诗', 'shi', '', NULL, '迴波樂 一○○ 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83b03363-3c0e-4aa1-ac27-619862c20a21', '迴波樂 一○一', '迴波乐 一○一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["五體一身內，蛆蟲塞破袋。","中間八萬戶，常無啾唧聲。","膿流遍身遶，六賊腹中停。","兩兩相啖食，強弱自相征（張改作「爭」）。","平生事人我，何處有公名（張改作「平」）。","。"]', '["五體一身內，蛆蟲塞破袋。","中间八万戶，常無啾唧声。","膿流遍身遶，六賊腹中停。","兩兩相啖食，強弱自相征（張改作「爭」）。","平生事人我，何处有公名（張改作「平」）。","。"]', '诗', 'shi', '', NULL, '迴波樂 一○一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9ab0f28-5bc2-4c9c-bbb5-e015c357e22b', '迴波樂 一○二', '迴波乐 一○二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["吾家昔富有，你身窮欲死。","你今初有錢，與吾昔相何（張改作「似」）。","吾人乍無初，還同[昔]（借）日你。","可[惜]（借）好靴牙，翻作破皮底。"]', '["吾家昔富有，你身窮欲死。","你今初有錢，與吾昔相何（張改作「似」）。","吾人乍無初，還同[昔]（借）日你。","可[惜]（借）好靴牙，翻作破皮底。"]', '诗', 'shi', '', NULL, '迴波樂 一○二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d50bc5-8b93-4b29-b58e-f196e71d269e', '迴波樂 一○三', '迴波乐 一○三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["夫妻擬百年，妻即在前死。","男女五六箇，小弱未中使。","衣破無人縫，小者肚露（一作「路」）地。","更娶阿娘來，不肯縫補你。","入戶徒衣食，不肯知家事。","合鬪遺啾唧，阿娘嗔兒子。","家內既不和，靈神（張將二字互乙）不歡喜。","後母即後翁，故故來相值。","[□□□□□]，故來尋常事。","欲得家裏知，孤養小兒子。","（以上三十六首皆錄自前國立中央研究院歷史語言研究所專刊之二劉復輯《敦煌掇瑣》三○，原件編號爲伯三四一八。","據張錫厚《王梵志詩校輯》卷五參校。","張氏另參用了伯三七二四、斯六○三二及蘇二八五二卷點校。","）（按：劉復《敦煌掇瑣》目錄謂此卷卷殘，抄出者共五十二首。","童養年輯《全唐詩續補遺》卷二據以選錄十首。","今將童氏未錄者全部錄出，合計共得詩四十二首，不及劉氏所言之數，因篇章分合不同之故耳。","又劉氏於末首眉批：「原本似未寫完。","」然細審詩意及押韻，似第十七句脫去，全詩已抄完。","原卷首殘尾不殘。","按：上錄伯三四一八、伯三七二四、伯六○三二等三卷所錄五言詩，原皆不題作者。","張錫厚考爲王梵志作。","然此組詩內容與王梵志詩有較大不同，是否即王梵志作，尚可討論。","今姑從張說，錄存於王詩之末，以俟考詳。","）。"]', '["夫妻擬百年，妻即在前死。","男女五六箇，小弱未中使。","衣破無人縫，小者肚露（一作「路」）地。","更娶阿娘来，不肯縫補你。","入戶徒衣食，不肯知家事。","合鬪遺啾唧，阿娘嗔兒子。","家內既不和，靈神（張將二字互乙）不歡喜。","後母即後翁，故故来相值。","[□□□□□]，故来尋常事。","欲得家裏知，孤養小兒子。","（以上三十六首皆錄自前国立中央研究院歷史語言研究所專刊之二劉复輯《敦煌掇瑣》三○，原件編號爲伯三四一八。","據張錫厚《王梵志诗校輯》卷五參校。","張氏另參用了伯三七二四、斯六○三二及蘇二八五二卷点校。","）（按：劉复《敦煌掇瑣》目錄謂此卷卷殘，抄出者共五十二首。","童養年輯《全唐诗續補遺》卷二據以選錄十首。","今將童氏未錄者全部錄出，合計共得诗四十二首，不及劉氏所言之數，因篇章分合不同之故耳。","又劉氏於末首眉批：「原本似未寫完。","」然細審诗意及押韻，似第十七句脫去，全诗已抄完。","原卷首殘尾不殘。","按：上錄伯三四一八、伯三七二四、伯六○三二等三卷所錄五言诗，原皆不題作者。","張錫厚考爲王梵志作。","然此組诗內容與王梵志诗有較大不同，是否即王梵志作，尚可討論。","今姑從張说，錄存於王诗之末，以俟考詳。","）。"]', '诗', 'shi', '', NULL, '迴波樂 一○三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28542e1f-803a-40df-b3ef-dc581817101d', '咸亨殿宴近臣諸親柏梁體（題從《全唐詩》）', '咸亨殿宴近臣諸親柏梁體（題從《全唐诗》）', '3bd6f3a7-b9cf-41af-9aad-b1529855bea8', '唐', '["（帝即高宗皇帝李治皇太子即章懷太子李賢霍王元軌高祖第十四子，封霍王，垂拱四年卒相王輪即睿宗皇帝李旦戴至德相州安陽人，歷官西臺侍郎、同東西臺三品，轉戶部尚書，遷尚書右僕射。","儀鳳四年卒來恒揚州江都人，上元中官至黃門侍郎、同中書門下三品薛元超）屏欲除奢政返淳。","（帝）叨恩監守戀晨昏。","（皇太子）聖德無爲同混元。","（霍王元軌）長歡膝下鎮承恩。","（相王輪）天皇萬福振長源。","（右僕射戴至德）策蹇叨榮青瑣門。","（黃門侍郎來[恒]〖嘗〗）鵷池濫職奉王言。","（中書侍郎薛元超）（《冊府元龜》卷一一○《帝王部·宴享二》）（按：《冊府元龜》又云：「自餘羣臣，以次繼作。","」知所錄尚未完。","《全唐詩》卷二據《玉海》僅錄存高宗一句，餘皆失收。","）。"]', '["（帝即高宗皇帝李治皇太子即章懷太子李賢霍王元軌高祖第十四子，封霍王，垂拱四年卒相王輪即睿宗皇帝李旦戴至德相州安陽人，歷官西台侍郎、同东西台三品，轉戶部尚书，遷尚书右僕射。","儀鳳四年卒来恒揚州江都人，上元中官至黄门侍郎、同中书门下三品薛元超）屏欲除奢政返淳。","（帝）叨恩監守戀晨昏。","（皇太子）聖德無爲同混元。","（霍王元軌）长歡膝下鎮承恩。","（相王輪）天皇万福振长源。","（右僕射戴至德）策蹇叨榮青瑣门。","（黄门侍郎来[恒]〖嘗〗）鵷池濫職奉王言。","（中书侍郎薛元超）（《冊府元龟》卷一一○《帝王部·宴享二》）（按：《冊府元龟》又云：「自餘羣臣，以次繼作。","」知所錄尚未完。","《全唐诗》卷二據《玉海》僅錄存高宗一句，餘皆失收。","）。"]', '诗', 'shi', '', NULL, '咸亨殿宴近臣諸親柏梁體（題從《全唐詩》） 高宗皇帝李治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('915760b6-8ff1-43bc-a844-24e330e2164e', '五言過樓巖寺', '五言過楼巖寺', '3bd6f3a7-b9cf-41af-9aad-b1529855bea8', '唐', '["旋騼登雪嶺，飛斾駐香城。","路盤高下騎，峰廻出沒旌。","雲衣縫澗戶，霞綺織山楹。","颺剎移虹影，攜風引梵聲。","岫馥鑪煙合，巖懸疊溜縈。","空結籠檐網，虛谷響臺鈴。","簇野千叢暗，長河一帶明。","散望禪林外，方弘拯溺情。","（見清胡聘之纂《山右石刻叢編》卷五。","參北京圖書館藏石刻拓本。","）（按：詩末原署「咸亨三年十一月八日」。","爲武后時所刻。","胡聘之謂刻石在蒲州府東南十五里，「河東縣文林郎韓懷信書」。","）。"]', '["旋騼登雪嶺，飞斾駐香城。","路盤高下騎，峰廻出沒旌。","云衣縫澗戶，霞綺织山楹。","颺剎移虹影，携风引梵声。","岫馥鑪煙合，巖懸叠溜縈。","空結籠檐網，虛谷响台鈴。","簇野千叢暗，长河一带明。","散望禪林外，方弘拯溺情。","（见清胡聘之纂《山右石刻叢編》卷五。","參北京圖书館藏石刻拓本。","）（按：诗末原署「咸亨三年十一月八日」。","爲武后时所刻。","胡聘之謂刻石在蒲州府东南十五里，「河东縣文林郎韓懷信书」。","）。"]', '诗', 'shi', '', NULL, '五言過樓巖寺 高宗皇帝李治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1318a805-3101-433c-bd2b-22665c73be4d', '守歲', '守歲', '3bd6f3a7-b9cf-41af-9aad-b1529855bea8', '唐', '["今宵冬律盡，來朝麗景新。","花餘凝地雪，條含煖吹分。","綬吐芽猶嫩，冰臺已鏤津。","薄紅梅色冷，淺綠柳輕春。","送迎交兩節，暄寒變一辰。","（見上海圖書館藏明抄本宋蒲積中《古今歲時雜詠》卷四一）（按：《全唐詩》卷二收本詩有缺文，今重錄。","）。"]', '["今宵冬律尽，来朝丽景新。","花餘凝地雪，條含煖吹分。","綬吐芽猶嫩，冰台已鏤津。","薄紅梅色冷，淺綠柳轻春。","送迎交兩節，暄寒变一辰。","（见上海圖书館藏明抄本宋蒲積中《古今歲时杂詠》卷四一）（按：《全唐诗》卷二收本诗有缺文，今重錄。","）。"]', '诗', 'shi', '', NULL, '守歲 高宗皇帝李治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a059b7c-3c50-4992-8f61-2f555b96b3d6', '湖州精舍寺詩', '湖州精舍寺诗', 'e972b423-dee6-4280-9a0b-2e77f67a51e9', '唐', '["院古□□□。","（見宋談鑰《嘉泰吳興志》卷二十）（按：余所據《吳興志》爲嘉業堂刊本，適有殘缺，俟得善本補足之。","）。"]', '["院古□□□。","（见宋談鑰《嘉泰吳兴志》卷二十）（按：余所據《吳兴志》爲嘉業堂刊本，適有殘缺，俟得善本補足之。","）。"]', '诗', 'shi', '', NULL, '湖州精舍寺詩 高智周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8002d7-a944-497b-b565-9ece5b1cf053', '', '', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68810af6-995c-41c0-81c3-c930bf4b2a6a', '修西方十二時 一', '修西方十二时 一', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["平旦寅，被衣出戶整心神。","合掌焚香請極樂，慇懃遙禮紫金身。"]', '["平旦寅，被衣出戶整心神。","合掌焚香請極乐，慇懃遙禮紫金身。"]', '诗', 'shi', '', NULL, '修西方十二時 一 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('483b3a72-7ffb-41ca-a969-94236057fd84', '修西方十二時 二', '修西方十二时 二', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["日出卯，不應念佛論多少。","安在專心擊一緣，勿爲妄境相侵擾。"]', '["日出卯，不應念佛論多少。","安在專心擊一緣，勿爲妄境相侵擾。"]', '诗', 'shi', '', NULL, '修西方十二時 二 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b7ff91-e617-4d76-bed8-3ff796a59ab1', '修西方十二時 三', '修西方十二时 三', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["食時辰，念佛先須伏我人。","若將念佛恃人我，何始何成淨土因。"]', '["食时辰，念佛先須伏我人。","若將念佛恃人我，何始何成淨土因。"]', '诗', 'shi', '', NULL, '修西方十二時 三 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a09d8d76-3cc4-4568-86e2-82e1babf6d57', '修西方十二時 四', '修西方十二时 四', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["禺中巳，進修淨土須決志。","如喰甘露自知甜，且莫謗人道不是。"]', '["禺中巳，進修淨土須決志。","如喰甘露自知甜，且莫謗人道不是。"]', '诗', 'shi', '', NULL, '修西方十二時 四 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a577677-e9c7-4395-a02c-f19be7d45828', '修西方十二時 五', '修西方十二时 五', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["正南午，想念吾師如目覩。","無邊業障自然消，豈要云爲枉辛苦。"]', '["正南午，想念吾師如目覩。","無邊業障自然消，豈要云爲枉辛苦。"]', '诗', 'shi', '', NULL, '修西方十二時 五 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e812fb4-619e-42eb-bfe5-30b892a60e33', '修西方十二時 六', '修西方十二时 六', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["日昳未，浩浩生死誠堪畏。","不取西方迷疾門，塵沙劫海須沉墜。"]', '["日昳未，浩浩生死誠堪畏。","不取西方迷疾门，塵沙劫海須沉墜。"]', '诗', 'shi', '', NULL, '修西方十二時 六 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf232da-7971-4d58-91ce-680d8df5ad7c', '修西方十二時 七', '修西方十二时 七', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["晡時申，急急須持淨土因。","闐健不能懃念佛，一朝虛作世間塵。"]', '["晡时申，急急須持淨土因。","闐健不能懃念佛，一朝虛作世间塵。"]', '诗', 'shi', '', NULL, '修西方十二時 七 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d836c99-b5e0-4280-aaad-e553063edbe5', '修西方十二時 八', '修西方十二时 八', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["日沒酉，想知光景何能久。","看看無常即到來，莫教佛字離心口。"]', '["日沒酉，想知光景何能久。","看看無常即到来，莫教佛字離心口。"]', '诗', 'shi', '', NULL, '修西方十二時 八 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fbe83a0-4c26-4cd2-9845-005a97a97b08', '修西方十二時 九', '修西方十二时 九', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["黃昏戌，勿使身心多過失。","十惡雖然亦往生，何如上品蓮開疾。"]', '["黄昏戌，勿使身心多過失。","十惡雖然亦往生，何如上品蓮开疾。"]', '诗', 'shi', '', NULL, '修西方十二時 九 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b568c72-236c-4273-a757-f6322023af40', '修西方十二時 十', '修西方十二时 十', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["人定亥，深心念佛真三昧。","十地高人尚爾修，將知不信寧非罪。"]', '["人定亥，深心念佛真三昧。","十地高人尚爾修，將知不信寧非罪。"]', '诗', 'shi', '', NULL, '修西方十二時 十 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49379a73-82d1-4369-abdb-9efb66f2df28', '修西方十二時 十一', '修西方十二时 十一', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["夜半子，朝朝念佛常如此。","皆乘蓮華一往生，從茲決定無生死。"]', '["夜半子，朝朝念佛常如此。","皆乘蓮华一往生，從茲決定無生死。"]', '诗', 'shi', '', NULL, '修西方十二時 十一 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508294de-77e4-438a-8dd4-2583ee0fde99', '修西方十二時 十二', '修西方十二时 十二', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["雞鳴丑，壯盛俄然即衰朽。","忙忙剎海更無親，唯有彌陀獨招手。","。"]', '["雞鳴丑，壯盛俄然即衰朽。","忙忙剎海更無親，唯有彌陀独招手。","。"]', '诗', 'shi', '', NULL, '修西方十二時 十二 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6d74da7-300d-4bdd-a6ca-d9e99e892cac', '修西方十勸 一', '修西方十勸 一', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君一，長時念佛須真實。","歸依佛語莫生疑，制護心猿無放逸。"]', '["勸君一，长时念佛須真實。","归依佛語莫生疑，制護心猿無放逸。"]', '诗', 'shi', '', NULL, '修西方十勸 一 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eef0e97c-1f02-4534-b60e-241c963c74c0', '修西方十勸 二', '修西方十勸 二', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君二，唯思念佛無餘事。","澄心決定願西方，臨終自見如來至。"]', '["勸君二，唯思念佛無餘事。","澄心決定願西方，臨終自见如来至。"]', '诗', 'shi', '', NULL, '修西方十勸 二 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a00c3e04-f8d2-43a6-b773-49e8b4f42c3d', '修西方十勸 三', '修西方十勸 三', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君三，念佛先須斷愛貪。","臨終心淨見如來，似月清光照碧潭。"]', '["勸君三，念佛先須斷愛貪。","臨終心淨见如来，似月清光照碧潭。"]', '诗', 'shi', '', NULL, '修西方十勸 三 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e5d406-c2ea-40f2-aafb-e72a175e5750', '修西方十勸 四', '修西方十勸 四', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君四，莫令念佛心移志。","臨終極樂寶華迎，觀音勢至俱來至。"]', '["勸君四，莫令念佛心移志。","臨終極乐寶华迎，观音勢至俱来至。"]', '诗', 'shi', '', NULL, '修西方十勸 四 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0820714-82a5-4af7-a802-dda6a634bf9e', '修西方十勸 五', '修西方十勸 五', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君五，莫辭念佛多辛苦。","思惟長劫生死輪，更向何人求出路。"]', '["勸君五，莫辞念佛多辛苦。","思惟长劫生死輪，更向何人求出路。"]', '诗', 'shi', '', NULL, '修西方十勸 五 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed0c640-54a7-48bd-8524-d3b9483a03f5', '修西方十勸 六', '修西方十勸 六', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君六，念佛時中恒相續。","假使不念順凡情，何日得離生死獄。"]', '["勸君六，念佛时中恒相續。","假使不念順凡情，何日得離生死獄。"]', '诗', 'shi', '', NULL, '修西方十勸 六 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb344d5b-02a3-496e-a4fa-e35369d262e7', '修西方十勸 七', '修西方十勸 七', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君七，念佛莫令三業失。","專專敬禮願西方，去見彌陀無上日。"]', '["勸君七，念佛莫令三業失。","專專敬禮願西方，去见彌陀無上日。"]', '诗', 'shi', '', NULL, '修西方十勸 七 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2001ce74-9233-45a3-a80d-b36b14d8a434', '修西方十勸 八', '修西方十勸 八', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君八，教修念佛牟尼法。","應須遵奉本師言，命盡得往彌陀剎。"]', '["勸君八，教修念佛牟尼法。","應須遵奉本師言，命尽得往彌陀剎。"]', '诗', 'shi', '', NULL, '修西方十勸 八 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efc60cd8-f27b-49b5-b16b-10c6ddfa544b', '修西方十勸 九', '修西方十勸 九', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君九，念佛真心爲上首。","臨終化佛共來迎，七寶蓮華隨願誘。"]', '["勸君九，念佛真心爲上首。","臨終化佛共来迎，七寶蓮华隨願誘。"]', '诗', 'shi', '', NULL, '修西方十勸 九 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ebeab23-41fe-47df-b637-f3592940e997', '修西方十勸 十', '修西方十勸 十', '9445574f-a563-4b7f-9af6-1418fca3b86b', '唐', '["勸君十，念佛常須心口急。","思量業海苦輪深，生死忙忙悔難及。","（以上二十二首均見《大正新修大藏經》第四十七冊唐道鏡、善導共集《念佛鏡》。","參《續藏經》本）。"]', '["勸君十，念佛常須心口急。","思量業海苦輪深，生死忙忙悔难及。","（以上二十二首均见《大正新修大藏經》第四十七冊唐道镜、善導共集《念佛镜》。","參《續藏經》本）。"]', '诗', 'shi', '', NULL, '修西方十勸 十 道鏡　善導 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705e7f88-732a-4847-9146-7e53257e1ac7', '', '', 'd7fd7ca1-55df-4507-a70d-39e88bb0d0fb', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 王拊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191b706b-36ca-4ce5-9752-7a8b0af6232b', '別故人賦得淩雲獨鶴', '別故人賦得淩云独鹤', 'd7fd7ca1-55df-4507-a70d-39e88bb0d0fb', '唐', '["單嘶淩碧霧，風颺入青雲。","九臯空顧侶，千里會離羣。","望海飛恒急，摩天影詎分？","欲知淒斷意，琴裏自當聞。","（《文苑英華》卷二八五）。"]', '["單嘶淩碧霧，风颺入青云。","九臯空顧侶，千里會離羣。","望海飞恒急，摩天影詎分？","欲知淒斷意，琴裏自當闻。","（《文苑英华》卷二八五）。"]', '诗', 'shi', '', NULL, '別故人賦得淩雲獨鶴 王拊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20603c1c-2d54-4d9b-8438-7b64909b1aac', '詠霜朝城上烏', '詠霜朝城上烏', 'd7fd7ca1-55df-4507-a70d-39e88bb0d0fb', '唐', '["霜旦早暉通，城烏漸颺空。","聲喧高疊（疑）外，曲韻楚琴中。","樓寒映曉日，竿迥噪朝風。","雖狎金墉上，獨（一作「猶」）畏虎賁弓。","（同書卷三二八）（按：王拊事跡不詳。","《英華》錄前詩於王胄詩後，駱賓王前，錄後詩於楊師道詩後，李嶠詩前，因知爲初唐人。","）。"]', '["霜旦早暉通，城烏漸颺空。","声喧高叠（疑）外，曲韻楚琴中。","楼寒映晓日，竿迥噪朝风。","雖狎金墉上，独（一作「猶」）畏虎賁弓。","（同书卷三二八）（按：王拊事跡不詳。","《英华》錄前诗於王胄诗後，駱賓王前，錄後诗於楊師道诗後，李嶠诗前，因知爲初唐人。","）。"]', '诗', 'shi', '', NULL, '詠霜朝城上烏 王拊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4066cf2c-a83b-4fee-b995-9a544c6cf2bc', '古意', '古意', '125633f0-a97c-4062-be41-123a333fdba1', '唐', '["逶迤臨雲雨，蛾眉戲瓊（一作「瑤」）臺。","對酒自嬌笑，君王肯下來。","擊鼓雷闐闐，選妓紛呈才。","錫宴池上子，精魄辭不迴。","指日窮所樂，豈知殷運開。","孤舟一遙放，曾構成塵埃。","（見《文苑英華》卷二○五）（按：《文苑英華》卷三○六收顏胄《適意》一首，《全唐詩》卷七七六收入。","疑胄、曹爲一人，惜其事跡無考，無以定奪。","）。"]', '["逶迤臨云雨，蛾眉戲瓊（一作「瑤」）台。","对酒自嬌笑，君王肯下来。","擊鼓雷闐闐，選妓紛呈才。","錫宴池上子，精魄辞不迴。","指日窮所乐，豈知殷運开。","孤舟一遙放，曾構成塵埃。","（见《文苑英华》卷二○五）（按：《文苑英华》卷三○六收顏胄《適意》一首，《全唐诗》卷七七六收入。","疑胄、曹爲一人，惜其事跡無考，無以定奪。","）。"]', '诗', 'shi', '', NULL, '古意 顏曹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f22b114-dc60-462d-9fdb-f7fb08406bf0', '讚觀音勢至二菩薩（題擬）', '讚观音勢至二菩薩（題擬）', '66a898b9-601a-4789-b58d-6091b1008853', '唐', '["觀音助遠接，勢至輔遙迎。","寶瓶冠上顯，化佛頂前明。","俱遊十方剎，持華候九生。","願以慈悲手，提獎共西行。","（《宋高僧傳》卷十八《唐岸禪師傳》，宋王日休《龍舒增廣淨土文集》卷五作「惟岸」）。"]', '["观音助远接，勢至輔遙迎。","寶瓶冠上显，化佛頂前明。","俱游十方剎，持华候九生。","願以慈悲手，提獎共西行。","（《宋高僧傳》卷十八《唐岸禪師傳》，宋王日休《龙舒增廣淨土文集》卷五作「惟岸」）。"]', '诗', 'shi', '', NULL, '讚觀音勢至二菩薩（題擬） 釋岸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bac0f8b9-ec86-4395-9229-d1f24ec15cab', '句', '句', 'f744ccd2-0a66-47a1-bbde-dceec77886fb', '唐', '["天將富外翁。","（《白氏長慶集》卷三四《自題酒庫》注引劉仁軌詩。","）。"]', '["天將富外翁。","（《白氏长慶集》卷三四《自題酒庫》注引劉仁軌诗。","）。"]', '诗', 'shi', '', NULL, '句 劉仁軌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35c0198e-af2b-4280-a573-7744de5a95d7', '', '', '230661e0-5c42-4a47-b050-ac56d3d4fad5', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 魏玄同 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c771914-d0a6-410a-b26e-888894b565e1', '流所贈張錫', '流所贈張錫', '230661e0-5c42-4a47-b050-ac56d3d4fad5', '唐', '["黃葉因風下，甘從洛浦隈。","白雲何所爲，還出帝鄉來。","（見《十萬卷樓叢書》本皎然《詩式》卷三）（按：此詩作者原署作「韋玄同」。","張錫，《舊唐書》卷八五有傳附其叔張文瓘傳後，則天時爲相，約卒於睿宗時。","檢初唐史傳，無韋玄同其人。","魏玄同曾配流嶺外，與張錫恰同時，「韋」、「魏」讀音又極相近，因知此詩應爲魏玄同作，作韋玄同爲音近而誤。","《全唐詩》卷九九誤作章玄同詩，今移正。","）。"]', '["黄葉因风下，甘從洛浦隈。","白云何所爲，還出帝乡来。","（见《十万卷楼叢书》本皎然《诗式》卷三）（按：此诗作者原署作「韋玄同」。","張錫，《旧唐书》卷八五有傳附其叔張文瓘傳後，則天时爲相，約卒於睿宗时。","檢初唐史傳，無韋玄同其人。","魏玄同曾配流嶺外，與張錫恰同时，「韋」、「魏」读音又極相近，因知此诗應爲魏玄同作，作韋玄同爲音近而誤。","《全唐诗》卷九九誤作章玄同诗，今移正。","）。"]', '诗', 'shi', '', NULL, '流所贈張錫 魏玄同 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43109872-b156-4191-a22c-c1a8929a0032', '幽蘭之歌', '幽蘭之歌', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["幽蘭生矣，于彼朝陽。","含雨露之津潤，吸日月之休光。","美人愁思兮，採芙蓉於南浦；公子忘憂兮，樹萱草於北堂。","雖處幽林與窮谷，不以無人而不芳。","（《楊盈川集》卷一《幽蘭賦》附）。"]', '["幽蘭生矣，于彼朝陽。","含雨露之津潤，吸日月之休光。","美人愁思兮，採芙蓉於南浦；公子忘憂兮，樹萱草於北堂。","雖处幽林與窮谷，不以無人而不芳。","（《楊盈川集》卷一《幽蘭賦》附）。"]', '诗', 'shi', '', NULL, '幽蘭之歌 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dddc2cb-7fae-4021-8e97-db43d5f361af', '竹（題擬）', '竹（題擬）', 'df46e9a6-93d8-4fe8-ab85-6936a9ad0fcd', '唐', '["森然幾竿竹，密密茂成林。","半室生清興，一窗餘午陰。","俗物不到眼，好書還上心。","底事忘覊旅，此君同此襟。","（見《全芳備祖後集》卷十六「竹韻」。","）。"]', '["森然幾竿竹，密密茂成林。","半室生清兴，一窗餘午陰。","俗物不到眼，好书還上心。","底事忘覊旅，此君同此襟。","（见《全芳備祖後集》卷十六「竹韻」。","）。"]', '诗', 'shi', '', NULL, '竹（題擬） 楊炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4e8b2da-26b6-4f8a-93fd-01ba373ec83c', '聞楊炯幽蘭之歌作（題擬）', '闻楊炯幽蘭之歌作（題擬）', '11f4a705-5cac-45d4-8871-32487e631084', '唐', '["昔聞蘭葉據龍圖，復道蘭林引鳳雛。","鴻歸燕去紫莖歇，露往霜來綠葉枯。","（《楊盈川集》卷一《幽蘭賦》附）。"]', '["昔闻蘭葉據龙圖，复道蘭林引鳳雛。","鴻归燕去紫莖歇，露往霜来綠葉枯。","（《楊盈川集》卷一《幽蘭賦》附）。"]', '诗', 'shi', '', NULL, '聞楊炯幽蘭之歌作（題擬） 趙元淑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e292b3e6-8da7-4dc2-8e69-780c22825ef9', '獨鶴篇', '独鹤篇', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["西山日沒人獨歸，東江月明鶴孤[飛]（非）。","秋風四起聲切切，邊心一聽淚[霏霏]（非非）。","嵩嶽靈泉搖玉羽，蓬丘仙霧下金衣。","自[憐]（拎）流落煩歲暮，唯有悲涼人事非。","（見伯二六八七卷）。"]', '["西山日沒人独归，东江月明鹤孤[飞]（非）。","秋风四起声切切，邊心一听泪[霏霏]（非非）。","嵩嶽靈泉搖玉羽，蓬丘仙霧下金衣。","自[怜]（拎）流落煩歲暮，唯有悲涼人事非。","（见伯二六八七卷）。"]', '诗', 'shi', '', NULL, '獨鶴篇 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f793d025-24c3-47f8-91d7-59d811eeaf8e', '初度嶺過韶州靈鷲廣果二寺其寺院相接故同詩一首', '初度嶺過韶州靈鷲廣果二寺其寺院相接故同诗一首', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["五嶺分鳶徼，三天峙鷲峰。","法堂因嶂起，香閣與巖重。","寒水千尋壑，禪林萬丈松。","日將輕影殿，風閑響傳鐘。","佛帳珠幡繞，經函寶印封。","野鳴初化鶴，岸上欲降龍。","北牖泉埃散，南階石癬濃。","淨花山木槿，真蒂水芙蓉。","古塔留奇制，殘碑紀勝蹤。","一音三界路，十善百靈恭。","流竄同飄蘀，登臨蹔杖笻。","攝衣趨福地，跪膝對真容。","忽似毗耶偈，還如舍衛逢。","宿心常懇懇，爾日更顒顒。","苦業暥前際，危光迫下舂。","已知空假色，猶念吉除凶。","覆護如無爽，歸飛庶可從。","。"]', '["五嶺分鳶徼，三天峙鷲峰。","法堂因嶂起，香閣與巖重。","寒水千尋壑，禪林万丈松。","日將轻影殿，风闲响傳鐘。","佛帳珠幡繞，經函寶印封。","野鳴初化鹤，岸上欲降龙。","北牖泉埃散，南階石癬濃。","淨花山木槿，真蒂水芙蓉。","古塔留奇制，殘碑紀勝蹤。","一音三界路，十善百靈恭。","流竄同飄蘀，登臨蹔杖笻。","攝衣趨福地，跪膝对真容。","忽似毗耶偈，還如舍衛逢。","宿心常懇懇，爾日更顒顒。","苦業暥前際，危光迫下舂。","已知空假色，猶念吉除凶。","覆護如無爽，归飞庶可從。","。"]', '诗', 'shi', '', NULL, '初度嶺過韶州靈鷲廣果二寺其寺院相接故同詩一首 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb3dbab-b836-4466-a675-480a36a8a48d', '江上覊情', '江上覊情', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["獨下三江路，飄如一葉浮。","臥查冲險洑，欹樹壓平流。","岸枝時冒挽，潬沙或礙舟。","出沒見帆影，遠近聞棹謳。","浦花春似雪，江氣曉如秋。","白雲乖帝里，舟徼（下缺。","以上二首均見伯二六七三卷）（按：以上二詩原收於劉希夷《北邙篇》之次，疑亦爲其所作，姑收希夷下，俟考。","）。"]', '["独下三江路，飄如一葉浮。","臥查冲險洑，欹樹壓平流。","岸枝时冒挽，潬沙或礙舟。","出沒见帆影，远近闻棹謳。","浦花春似雪，江氣晓如秋。","白云乖帝里，舟徼（下缺。","以上二首均见伯二六七三卷）（按：以上二诗原收於劉希夷《北邙篇》之次，疑亦爲其所作，姑收希夷下，俟考。","）。"]', '诗', 'shi', '', NULL, '江上覊情 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f7b0b26-2d1a-42e3-9b9e-fee9432c2549', '謁諸葛祠', '謁諸葛祠', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["孤雲何其高，明月不可繫。","灼灼抱此心，與世自涇渭。","釋來從所歡，感亂亦歔欷。","咨惟今之人，竊國未云耻。","白首入吳市，秋風恐燕水。","區區袁與曹，等是刺客耳。","而我於其間，秉義不敢墜。","袁音回衡飈，清義動幽邃。","天心固難亮，吾獨信所履。","溶溶日間雲，漠漠點寒砌。","饑鼯墮蒼瓦，澹薄公所憇。","靜然想英姿，孤懷亦差𢠢。","（《道藏輯要》本明諸葛曦基輯《漢丞相諸葛忠武侯集》卷十二。","）。"]', '["孤云何其高，明月不可繫。","灼灼抱此心，與世自涇渭。","釋来從所歡，感亂亦歔欷。","咨惟今之人，竊国未云耻。","白首入吳市，秋风恐燕水。","區區袁與曹，等是刺客耳。","而我於其间，秉義不敢墜。","袁音回衡飈，清義动幽邃。","天心固难亮，吾独信所履。","溶溶日间云，漠漠点寒砌。","饑鼯墮蒼瓦，澹薄公所憇。","静然想英姿，孤懷亦差𢠢。","（《道藏輯要》本明諸葛曦基輯《漢丞相諸葛忠武侯集》卷十二。","）。"]', '诗', 'shi', '', NULL, '謁諸葛祠 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e6baa50-aa11-4d5e-836c-40b59ada394c', '樂道歌（一作《了元歌》）', '乐道歌（一作《了元歌》）', 'd973ce2c-8f1a-4974-a67e-6be7dff101b1', '唐', '["[修]（問）（從《燈錄》改）道道無可修，問法法無可問。","違人不了性（一作「色」）空，智者本無違順（一作「悟者無逆順」）。","八萬四千法門，至理不離方寸。","不要（一作「用」）廣學多聞，不要辯才聰隽。","識取自家城郭，莫謾遊他州（一作「尋他鄉」）郡。","（《燈錄》二句在「不用」二句前）煩惱即是菩提，淨花（一作「華」）生於泥糞。","若有人求問答（一作「人來問我若爲」），誰（一作「不」）能共他講（一作「伊談」）論。","不知月之大小，亦不知（一無「亦」字，「知」作「管」）歲之餘閏。","（《燈錄》二句在「煩惱」二句前）辰時以（一作「寅期用」）粥充饑，仲（一作「齋」）時更飡（一作「飱」）一頓。","今日任運騰騰，明日騰騰任運。","心中了了總知，只沒（一作「且作」）佯癡縛鈍。","（見影印日本花園大學藏南唐靜、筠二僧撰《祖堂集》卷三。","注「一作」者，爲《四部叢刊三編》影宋本宋釋道原撰《景德傳燈錄》卷三十之異文。","）。"]', '["[修]（问）（從《灯錄》改）道道無可修，问法法無可问。","違人不了性（一作「色」）空，智者本無違順（一作「悟者無逆順」）。","八万四千法门，至理不離方寸。","不要（一作「用」）廣学多闻，不要辯才聰隽。","識取自家城郭，莫謾游他州（一作「尋他乡」）郡。","（《灯錄》二句在「不用」二句前）煩惱即是菩提，淨花（一作「华」）生於泥糞。","若有人求问答（一作「人来问我若爲」），誰（一作「不」）能共他講（一作「伊談」）論。","不知月之大小，亦不知（一無「亦」字，「知」作「管」）歲之餘閏。","（《灯錄》二句在「煩惱」二句前）辰时以（一作「寅期用」）粥充饑，仲（一作「斋」）时更飡（一作「飱」）一頓。","今日任運腾腾，明日腾腾任運。","心中了了總知，只沒（一作「且作」）佯癡縛鈍。","（见影印日本花园大学藏南唐静、筠二僧撰《祖堂集》卷三。","注「一作」者，爲《四部叢刊三編》影宋本宋釋道原撰《景德傳灯錄》卷三十之異文。","）。"]', '诗', 'shi', '', NULL, '樂道歌（一作《了元歌》） 仁儉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ede73ae1-5244-47d5-a675-b378cc2ce80a', '武三思席上詠綺娘（題擬）', '武三思席上詠綺娘（題擬）', '9f057e3a-2855-4f90-92a1-fcd96bd8b7be', '唐', '["傾國精神掌上身，天風驚雪上香裀。","須臾舞徹《霓裳曲》，騃卻高堂滿座人。","（《新編分門古今類事》卷二引《甘澤謠》）。"]', '["傾国精神掌上身，天风驚雪上香裀。","須臾舞徹《霓裳曲》，騃卻高堂满座人。","（《新編分门古今類事》卷二引《甘澤謠》）。"]', '诗', 'shi', '', NULL, '武三思席上詠綺娘（題擬） 魏元忠 shi');
